export type StorageMode = 'local' | 'session';

export interface OTPAccount {
  id: string;
  issuer: string;
  account: string;
  secret: string;
  period: number;
  notes?: string;
  algorithm?: string;
  digits?: number;
  createdAt: number;
}

export interface ImportCandidate {
  raw: string;
  issuer: string;
  account: string;
  secret: string;
  period: number;
  isValid: boolean;
  notes?: string;
}

import * as OTPAuth from 'otpauth';

// Wrapper to generate current token and remaining seconds
export const generateToken = (secret: string, period: number = 30) => {
  try {
    // Sanitize secret (remove spaces)
    const cleanSecret = secret.replace(/\s+/g, '');

    // Check if secret is base32 compatible roughly
    if (!/^[A-Z2-7=]+$/i.test(cleanSecret)) {
      // If it's hex, we might need conversion, but standard TOTP uses Base32.
      // We will assume Base32 for this implementation as per standard.
    }

    const totp = new OTPAuth.TOTP({
      secret: OTPAuth.Secret.fromBase32(cleanSecret),
      period: period,
      algorithm: 'SHA1',
      digits: 6,
    });

    const token = totp.generate();
    const seconds = period - (Math.floor(Date.now() / 1000) % period);
    const progress = (seconds / period) * 100;

    return { token, seconds, progress, valid: true };
  } catch (e) {
    return { token: 'ERROR', seconds: 0, progress: 0, valid: false };
  }
};

export const generateRandomSecret = (length: number = 16): string => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

export const parseOTPAuthURL = (url: string): Partial<import('../types').OTPAccount> | null => {
  try {
    const parsed = OTPAuth.URI.parse(url);
    if (parsed instanceof OTPAuth.TOTP) {
      return {
        issuer: parsed.issuer,
        account: parsed.label,
        secret: parsed.secret.base32,
        period: parsed.period,
        algorithm: parsed.algorithm,
        digits: parsed.digits,
      };
    }
  } catch (e) {
    console.error("Invalid OTP Auth URL", e);
  }
  return null;
};

// Simple text line parser
// Format: issuer, account, secret, period?
// OR: otpauth://...
export const parseLine = (line: string): import('../types').ImportCandidate => {
  const trimmed = line.trim();
  if (!trimmed) return { raw: line, issuer: '', account: '', secret: '', period: 30, isValid: false };

  // Try URI first
  if (trimmed.startsWith('otpauth://')) {
    const parsed = parseOTPAuthURL(trimmed);
    if (parsed && parsed.secret) {
      return {
        raw: line,
        issuer: parsed.issuer || 'Unknown',
        account: parsed.account || 'Unknown',
        secret: parsed.secret,
        period: parsed.period || 30,
        isValid: true
      };
    }
  }

  // Try CSV/Split
  // Expected: Issuer,Account,Secret,Period(opt),Notes(opt)
  const parts = trimmed.split(',').map(p => p.trim());
  if (parts.length >= 3) {
    return {
      raw: line,
      issuer: parts[0],
      account: parts[1],
      secret: parts[2],
      period: parts[3] ? parseInt(parts[3], 10) : 30,
      notes: parts[4] || '',
      isValid: true // Basic validation passed
    };
  }

  return { raw: line, issuer: '', account: '', secret: '', period: 30, isValid: false };
};

import React, { useRef, useState, useEffect } from 'react';
import jsQR from 'jsqr';
import { Camera, Upload, X } from 'lucide-react';

interface QRCodeScannerProps {
  onScan: (data: string) => void;
  onClose: () => void;
}

const QRCodeScanner: React.FC<QRCodeScannerProps> = ({ onScan, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [error, setError] = useState<string>('');

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
      setIsCameraActive(false);
    }
  };

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute('playsinline', 'true');
        videoRef.current.play();
        setIsCameraActive(true);
        requestAnimationFrame(tick);
      }
    } catch (err) {
      setError("Unable to access camera. Please allow permissions or use file upload.");
    }
  };

  const tick = () => {
    if (!videoRef.current || !canvasRef.current || !isCameraActive) return;

    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const code = jsQR(imageData.data, imageData.width, imageData.height, {
          inversionAttempts: "dontInvert",
        });

        if (code) {
          stopCamera();
          onScan(code.data);
          return;
        }
      }
    }
    requestAnimationFrame(tick);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height);
          if (code) {
            onScan(code.data);
          } else {
            setError("No QR code found in image.");
          }
        }
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  return (
    <div className="flex flex-col gap-4">
      {error && (
        <div className="bg-red-50 text-red-600 p-3 rounded-md text-sm mb-2">
          {error}
        </div>
      )}

      <div className="relative bg-black rounded-lg overflow-hidden aspect-square md:aspect-video flex items-center justify-center">
        {!isCameraActive && (
           <div className="text-gray-400 flex flex-col items-center">
             <Camera className="w-12 h-12 mb-2 opacity-50" />
             <p>Camera inactive</p>
           </div>
        )}
        <video ref={videoRef} className={`w-full h-full object-cover ${!isCameraActive ? 'hidden' : ''}`} />
        <canvas ref={canvasRef} className="hidden" />
      </div>

      <div className="flex gap-2">
        {!isCameraActive ? (
          <button
            onClick={startCamera}
            className="flex-1 flex items-center justify-center gap-2 bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition"
          >
            <Camera size={18} />
            Start Camera
          </button>
        ) : (
          <button
            onClick={stopCamera}
            className="flex-1 flex items-center justify-center gap-2 bg-red-600 text-white py-2 px-4 rounded-md hover:bg-red-700 transition"
          >
            <X size={18} />
            Stop Camera
          </button>
        )}

        <label className="flex-1 flex items-center justify-center gap-2 bg-gray-200 text-gray-800 py-2 px-4 rounded-md hover:bg-gray-300 transition cursor-pointer">
          <Upload size={18} />
          Upload Image
          <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
        </label>
      </div>
    </div>
  );
};

export default QRCodeScanner;

import React, { useState, useEffect } from 'react';
import { OTPAccount } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Copy, Share2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';

interface AccountCardProps {
  account: OTPAccount;
  onDelete: (id: string) => void;
}

const AccountCard: React.FC<AccountCardProps> = ({ account, onDelete }) => {
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);
  const [showQR, setShowQR] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));

    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);

    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();

  // Construct OTPAuth URI for export
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 hover:shadow-md transition-shadow duration-200 flex flex-col relative group">

      {/* Header */}
      <div className="flex justify-between items-start mb-4">
        <div className="overflow-hidden">
          <h3 className="font-bold text-gray-900 truncate" title={account.issuer}>
            {account.issuer || "Unknown Issuer"}
          </h3>
          <p className="text-sm text-gray-500 truncate" title={account.account}>
            {account.account}
          </p>
        </div>
        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
           <button 
             onClick={() => setShowQR(!showQR)}
             className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-full transition"
             title="Show QR Code"
           >
             <QrCode size={16} />
           </button>
           <button 
             onClick={() => onDelete(account.id)}
             className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-full transition"
             title="Delete"
           >
             <Trash2 size={16} />
           </button>
        </div>
      </div>

      {/* Code Display */}
      {showQR ? (
         <div className="flex flex-col items-center justify-center py-2 animate-in fade-in zoom-in duration-200">
            <div className="bg-white p-2 rounded border">
                <QRCodeSVG value={otpUri} size={120} />
            </div>
            <button onClick={() => setShowQR(false)} className="text-xs text-blue-500 mt-2 hover:underline">
                Back to Code
            </button>
         </div>
      ) : (
        <div className="flex-1 flex flex-col justify-center">
            <div 
                className="text-4xl font-mono font-semibold text-center tracking-wider text-gray-800 cursor-pointer hover:scale-105 transition-transform select-all"
                onClick={handleCopy}
            >
                {formattedToken}
            </div>
            {copied && <span className="text-xs text-center text-green-500 font-medium h-4 mt-1">Copied!</span>}
            {!copied && <span className="h-4 mt-1"></span>}
        </div>
      )}

      {/* Progress Bar */}
      <div className="mt-4">
        <div className="flex justify-between text-xs text-gray-400 mb-1">
          <span>{tokenData.seconds}s</span>
          {account.notes && <span className="truncate max-w-[100px]" title={account.notes}>{account.notes}</span>}
        </div>
        <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
          <div 
            className={`h-full transition-all duration-1000 ease-linear ${tokenData.seconds < 5 ? 'bg-red-500' : 'bg-blue-500'}`}
            style={{ width: `${tokenData.progress}%` }}
          />
        </div>
      </div>
    </div>
  );
};

export default AccountCard;

import React, { useState, useEffect } from 'react';
import { X, Upload, Download, Check, RefreshCw, Copy } from 'lucide-react';
import { ImportCandidate, OTPAccount } from '../types';
import { parseLine, generateRandomSecret } from '../utils/crypto';
import QRCodeScanner from './QRCodeScanner';

// --- Base Modal ---
const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-xl max-h-[90vh] overflow-auto flex flex-col">
      <div className="flex justify-between items-center p-5 border-b sticky top-0 bg-white z-10">
        <h2 className="text-xl font-bold text-gray-800">{title}</h2>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition"><X size={24} /></button>
      </div>
      <div className="p-5 flex-1 overflow-y-auto">
        {children}
      </div>
    </div>
  </div>
);

// --- Add Account Modal ---
interface AddAccountModalProps {
  onClose: () => void;
  onAdd: (account: Omit<OTPAccount, 'id' | 'createdAt'>) => void;
}

export const AddAccountModal: React.FC<AddAccountModalProps> = ({ onClose, onAdd }) => {
  const [mode, setMode] = useState<'manual' | 'scan'>('manual');
  const [formData, setFormData] = useState({
    issuer: '',
    account: '',
    secret: '',
    period: 30,
    notes: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.issuer && formData.account && formData.secret) {
      onAdd(formData);
      onClose();
    }
  };

  const handleScan = (data: string) => {
    // Attempt to parse the scanned data
    if (data.startsWith('otpauth://')) {
        const { parseOTPAuthURL } = require('../utils/crypto');
        const parsed = parseOTPAuthURL(data);
        if (parsed) {
             onAdd({
                issuer: parsed.issuer || 'Unknown',
                account: parsed.account || 'Unknown',
                secret: parsed.secret || '',
                period: parsed.period || 30,
                notes: 'Scanned via QR'
             });
             onClose();
             return;
        }
    }
    // If raw text
    alert('Invalid QR Code or format not supported yet. (Must be otpauth URI)');
  };

  const generateSecret = () => {
    setFormData(prev => ({ ...prev, secret: generateRandomSecret() }));
  };

  return (
    <Modal title="Add New Account" onClose={onClose}>
      <div className="flex gap-4 mb-6 border-b">
        <button 
          className={`pb-2 px-1 font-medium text-sm transition ${mode === 'manual' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}
          onClick={() => setMode('manual')}
        >
          Manual Entry / Create
        </button>
        <button 
          className={`pb-2 px-1 font-medium text-sm transition ${mode === 'scan' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}
          onClick={() => setMode('scan')}
        >
          Scan QR Code
        </button>
      </div>

      {mode === 'manual' ? (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Issuer</label>
                <input required type="text" placeholder="e.g. Google" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.issuer} onChange={e => setFormData({...formData, issuer: e.target.value})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Account Name</label>
                <input required type="text" placeholder="e.g. alice@example.com" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.account} onChange={e => setFormData({...formData, account: e.target.value})} />
             </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Secret Key</label>
            <div className="flex gap-2">
                <input required type="text" placeholder="Base32 Secret" className="flex-1 p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none font-mono" 
                value={formData.secret} onChange={e => setFormData({...formData, secret: e.target.value})} />
                <button type="button" onClick={generateSecret} className="px-3 py-2 bg-gray-100 text-gray-600 rounded-md hover:bg-gray-200" title="Generate Random Secret">
                    <RefreshCw size={18} />
                </button>
            </div>
            <p className="text-xs text-gray-500 mt-1">Leave as is if importing. Generate if creating a new service.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Refresh Period (sec)</label>
                <input type="number" min="15" step="1" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.period} onChange={e => setFormData({...formData, period: parseInt(e.target.value) || 30})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Notes (Optional)</label>
                <input type="text" placeholder="Tag or description" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
             </div>
          </div>

          <button type="submit" className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 font-medium mt-4">
            Save Account
          </button>
        </form>
      ) : (
        <QRCodeScanner onScan={handleScan} onClose={onClose} />
      )}
    </Modal>
  );
};

// --- Batch Import Modal ---
interface BatchImportModalProps {
  onClose: () => void;
  onImport: (accounts: Omit<OTPAccount, 'id' | 'createdAt'>[]) => void;
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onImport }) => {
  const [text, setText] = useState('');
  const [preview, setPreview] = useState<ImportCandidate[]>([]);
  const [step, setStep] = useState<1 | 2>(1);

  const handleParse = () => {
    const lines = text.split('\n');
    const parsed = lines.map(parseLine).filter(p => p.raw.trim() !== ''); // Filter empty lines
    setPreview(parsed);
    setStep(2);
  };

  const handleUpdatePeriod = (index: number, newPeriod: number) => {
    const updated = [...preview];
    updated[index].period = newPeriod;
    setPreview(updated);
  };

  const handleToggleValid = (index: number) => {
      const updated = [...preview];
      updated[index].isValid = !updated[index].isValid;
      setPreview(updated);
  };

  const confirmImport = () => {
    const validItems = preview.filter(p => p.isValid && p.secret).map(p => ({
      issuer: p.issuer || 'Batch Import',
      account: p.account || 'Unknown',
      secret: p.secret,
      period: p.period || 30,
      notes: p.notes
    }));
    onImport(validItems);
    onClose();
  };

  return (
    <Modal title="Batch Import" onClose={onClose}>
      {step === 1 ? (
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            Paste one entry per line. Supported formats:<br/>
            1. <code className="bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</code><br/>
            2. <code className="bg-gray-100 px-1 rounded">otpauth://totp/...</code>
          </p>
          <textarea 
            className="w-full h-64 p-3 border rounded-md font-mono text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\nAWS, bob@work, GEZDGNBVGY3TQOJQ, 60`}
            value={text}
            onChange={e => setText(e.target.value)}
          />
          <button 
            onClick={handleParse}
            disabled={!text.trim()}
            className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Preview Import
          </button>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex justify-between items-center mb-2">
             <h3 className="font-semibold text-gray-700">Confirm Details</h3>
             <button onClick={() => setStep(1)} className="text-sm text-blue-600 hover:underline">Edit Raw Text</button>
          </div>
          <div className="overflow-x-auto border rounded-lg">
            <table className="w-full text-sm text-left">
              <thead className="bg-gray-50 text-gray-600 font-medium">
                <tr>
                  <th className="p-3">Import?</th>
                  <th className="p-3">Issuer</th>
                  <th className="p-3">Account</th>
                  <th className="p-3">Secret</th>
                  <th className="p-3">Period(s)</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {preview.map((item, idx) => (
                  <tr key={idx} className={item.isValid ? 'bg-white' : 'bg-red-50'}>
                    <td className="p-3">
                       <input type="checkbox" checked={item.isValid} onChange={() => handleToggleValid(idx)} className="h-4 w-4 text-blue-600 rounded" />
                    </td>
                    <td className="p-3 max-w-[100px] truncate">{item.issuer}</td>
                    <td className="p-3 max-w-[150px] truncate">{item.account}</td>
                    <td className="p-3 font-mono text-xs max-w-[150px] truncate" title={item.secret}>{item.secret}</td>
                    <td className="p-3">
                      <input 
                        type="number" 
                        value={item.period} 
                        onChange={(e) => handleUpdatePeriod(idx, parseInt(e.target.value))}
                        className="w-16 p-1 border rounded text-center"
                        min="15"
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex justify-end gap-3 pt-2">
             <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg">Cancel</button>
             <button onClick={confirmImport} className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                Import {preview.filter(p => p.isValid).length} Accounts
             </button>
          </div>
        </div>
      )}
    </Modal>
  );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose }) => {
  const [format, setFormat] = useState<'csv' | 'uri'>('csv');

  const generateExportText = () => {
    if (format === 'uri') {
      return accounts.map(a => `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`).join('\n');
    }
    return accounts.map(a => `${a.issuer}, ${a.account}, ${a.secret}, ${a.period}, ${a.notes || ''}`).join('\n');
  };

  const text = generateExportText();

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    alert('Copied to clipboard');
  };

  return (
    <Modal title="Batch Export" onClose={onClose}>
       <div className="space-y-4">
