                <ShieldCheck className="text-white h-6 w-6" />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500 hidden sm:block">
                SecureAuth 2FA
              </h1>
            </div>

            {/* Tab Switcher */}
            <div className="flex p-1 bg-gray-100 rounded-lg">
              <button
                onClick={() => setActiveTab('local')}
                className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                  activeTab === 'local' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <HardDrive size={16} />
                <span className="hidden sm:inline">Local Storage</span>
                <span className="sm:hidden">Local</span>
              </button>
              <button
                onClick={() => setActiveTab('session')}
                className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                  activeTab === 'session' 
                    ? 'bg-white text-orange-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Zap size={16} />
                <span className="hidden sm:inline">Session / Temp</span>
                <span className="sm:hidden">Temp</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

