            </div>
            <div className="min-w-0">
                <h3 className="font-bold text-gray-900 truncate text-base leading-tight" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 truncate" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox (Always Visible or on Hover) */}
        <div className="absolute top-5 right-5 z-10">
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={() => onToggleSelect(account.id)}
                className={`w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-6 relative">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-2 rounded-lg border shadow-sm">
                    <QRCodeSVG value={otpUri} size={130} />
                 </div>
                 <button onClick={() => setShowQR(false)} className="text-xs text-gray-500 mt-3 hover:text-blue-600 font-medium">
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className="text-4xl sm:text-5xl font-mono font-semibold text-gray-800 tracking-wider cursor-pointer hover:scale-105 active:scale-95 transition-transform select-all"
                    onClick={handleCopy}
                >
                    {formattedToken}
