                         </div>
                      </div>
                    );
                 })}
              </div>
           </div>
         )}
       </div>
    </Modal>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageMode, OTPAccount } from './types';
import AccountCard from './components/AccountCard';
