// --- Add/Edit Account Modal ---
interface AccountFormModalProps {
  onClose: () => void;
  onSave: (account: Omit<OTPAccount, 'id' | 'createdAt'>) => void;
  initialData?: OTPAccount; // If present, we are editing
}

export const AccountFormModal: React.FC<AccountFormModalProps> = ({ onClose, onSave, initialData }) => {
  const { t } = useContext(LanguageContext);
  const [mode, setMode] = useState<'manual' | 'scan'>(initialData ? 'manual' : 'manual');
  const [formData, setFormData] = useState({
    issuer: '',
    account: '',
    secret: '',
    period: 30,
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
        setFormData({
            issuer: initialData.issuer,
            account: initialData.account,
            secret: initialData.secret,
            period: initialData.period,
            notes: initialData.notes || ''
        });
    }
  }, [initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.issuer && formData.account && formData.secret) {
      onSave(formData);
      onClose();
    }
  };

  const handleScan = (data: string) => {
    if (data.startsWith('otpauth://')) {
        const parsed = parseOTPAuthURL(data);
        if (parsed) {
             onSave({
                issuer: parsed.issuer || 'Unknown',
                account: parsed.account || 'Unknown',
                secret: parsed.secret || '',
                period: parsed.period || 30,
                notes: 'Scanned via QR'
             });
             onClose();
             return;
        }
    }
    alert('Invalid QR Code or format not supported yet. (Must be otpauth URI)');
  };

  const generateSecret = () => {
    setFormData(prev => ({ ...prev, secret: generateRandomSecret() }));
  };

  return (
    <Modal title={initialData ? t.modalEditTitle : t.modalAddTitle} onClose={onClose}>
      {!initialData && (
          <div className="flex gap-4 mb-6 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${mode === 'manual' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}
              onClick={() => setMode('manual')}
            >
              {t.tabManual}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${mode === 'scan' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}
              onClick={() => setMode('scan')}
            >
              {t.tabScan}
            </button>
          </div>
      )}

      {mode === 'manual' ? (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelIssuer}</label>
                <input required type="text" placeholder="e.g. Google" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.issuer} onChange={e => setFormData({...formData, issuer: e.target.value})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelAccount}</label>
                <input required type="text" placeholder="e.g. alice@example.com" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.account} onChange={e => setFormData({...formData, account: e.target.value})} />
             </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSecret}</label>
            <div className="flex gap-2">
                <input required type="text" placeholder="Base32 Secret" className="flex-1 p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none font-mono" 
                value={formData.secret} onChange={e => setFormData({...formData, secret: e.target.value})} />
                <button type="button" onClick={generateSecret} className="px-3 py-2 bg-gray-100 text-gray-600 rounded-md hover:bg-gray-200" title={t.btnGenerate}>
                    <RefreshCw size={18} />
                </button>
            </div>
            {!initialData && <p className="text-xs text-gray-500 mt-1">{t.msgLeaveBlank}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelPeriod}</label>
                <input type="number" min="15" step="1" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.period} onChange={e => setFormData({...formData, period: parseInt(e.target.value) || 30})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelNotes}</label>
                <input type="text" placeholder="Tag or description" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" 
                  value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
             </div>
          </div>

          <button type="submit" className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 font-medium mt-4">
            {t.btnSave}
          </button>
        </form>
      ) : (
        <QRCodeScanner onScan={handleScan} onClose={onClose} />
      )}
    </Modal>
  );
};

// --- Batch Import Modal (Step 1: Input) ---
interface BatchImportModalProps {
  onClose: () => void;
  onPreview: (candidates: ImportCandidate[]) => void;
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview }) => {
  const { t } = useContext(LanguageContext);
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleParseText = () => {
    const lines = text.split('\n');
    const parsed = lines.map(line => parseLine(line, separator)).filter(p => p.raw.trim() !== '');
    if (parsed.length > 0) {
        onPreview(parsed);
    } else {
        alert("No valid entries found.");
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files: File[] = Array.from(e.target.files);
      const newCandidates: ImportCandidate[] = [];

      for (const file of files) {
        const qrData = await decodeQRFromImage(file);
        if (qrData) {
            // Treat qrData as a line to parse (it should be an otpauth URI)
            const candidate = parseLine(qrData, separator);
            if(candidate.isValid) {
                candidate.raw = "QR Code Import";
                newCandidates.push(candidate);
            }
        }
      }

      if (newCandidates.length > 0) {
          onPreview(newCandidates);
      } else {
          alert('No valid QR codes found in selected images.');
      }
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            {t.textPaste}<br/>
            1. <code className="bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</code><br/>
            2. <code className="bg-gray-100 px-1 rounded">otpauth://totp/...</code>
          </p>

          <div className="flex gap-2 items-center bg-gray-50 p-2 rounded border">
            <label className="text-sm text-gray-700 font-medium whitespace-nowrap">{t.labelSeparator}:</label>
            <input 
                type="text" 
                value={separator} 
                onChange={e => setSeparator(e.target.value)} 
                className="w-12 text-center border rounded p-1"
                maxLength={1}
            />
            <span className="text-xs text-gray-400">(Default: comma)</span>
          </div>

          <textarea 
            className="w-full h-40 p-3 border rounded-md font-mono text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            placeholder={`Google${separator} alice@gmail.com${separator} JBSWY3DPEHPK3PXP${separator} 30`}
            value={text}
            onChange={e => setText(e.target.value)}
          />

          <div className="flex flex-col gap-3">
             <button 
                onClick={handleParseText}
                disabled={!text.trim()}
                className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
             >
                {t.btnPreview}
             </button>

             <div className="relative">
                 <div className="absolute inset-0 flex items-center">
                    <div className="w-full border-t border-gray-300"></div>
                 </div>
                 <div className="relative flex justify-center text-sm">
                    <span className="px-2 bg-white text-gray-500">OR</span>
                 </div>
             </div>

             <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-2.5 rounded-lg hover:bg-gray-200 border border-gray-300 transition"
             >
                <ImageIcon size={18} /> {t.btnUploadQR}
             </button>
             <input 
                type="file" 
                multiple 
                accept="image/*" 
                ref={fileInputRef} 
                className="hidden" 
                onChange={handleImageUpload} 
             />
          </div>
        </div>
    </Modal>
  );
};

// --- Import Preview Drawer (Step 2) ---
interface ImportPreviewDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    candidates: ImportCandidate[];
    onConfirm: (candidates: ImportCandidate[]) => void;
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ isOpen, onClose, candidates, onConfirm }) => {
    const { t } = useContext(LanguageContext);
    const [preview, setPreview] = useState<ImportCandidate[]>([]);

    useEffect(() => {
        setPreview(candidates);
    }, [candidates]);

    const handleUpdatePeriod = (index: number, newPeriod: number) => {
        const updated = [...preview];
        updated[index].period = newPeriod;
        setPreview(updated);
    };

    const handleToggleValid = (index: number) => {
        const updated = [...preview];
        updated[index].isValid = !updated[index].isValid;
        setPreview(updated);
    };

    const handleConfirm = () => {
        const validItems = preview.filter(p => p.isValid && p.secret);
        onConfirm(validItems);
    };

    return (
        <BottomDrawer isOpen={isOpen} onClose={onClose} title={`Preview Import (${preview.filter(p=>p.isValid).length})`}>
            <div className="space-y-4">
                <div className="overflow-x-auto border rounded-lg max-h-[60vh] overflow-y-auto">
                    <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 text-gray-600 font-medium sticky top-0 z-10 shadow-sm">
                        <tr>
                        <th className="p-3 w-10">{t.headerImport}</th>
                        <th className="p-3">{t.headerIssuer}</th>
                        <th className="p-3">{t.headerAccount}</th>
                        <th className="p-3">{t.headerSecret}</th>
                        <th className="p-3 w-20">{t.headerPeriod}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {preview.map((item, idx) => (
                        <tr key={idx} className={item.isValid ? 'bg-white hover:bg-gray-50' : 'bg-red-50 hover:bg-red-100'}>
                            <td className="p-3">
                                <input type="checkbox" checked={item.isValid} onChange={() => handleToggleValid(idx)} className="h-5 w-5 text-blue-600 rounded cursor-pointer" />
                            </td>
                            <td className="p-3 max-w-[120px] truncate font-medium">{item.issuer}</td>
                            <td className="p-3 max-w-[150px] truncate">{item.account}</td>
                            <td className="p-3 font-mono text-xs max-w-[150px] truncate text-gray-500" title={item.secret}>{item.secret}</td>
                            <td className="p-3">
                                <input 
                                    type="number" 
                                    value={item.period} 
                                    onChange={(e) => handleUpdatePeriod(idx, parseInt(e.target.value))}
                                    className="w-full p-1 border rounded text-center focus:ring-blue-500"
                                    min="15"
                                />
                            </td>
                        </tr>
                        ))}
                    </tbody>
                    </table>
                </div>

                <div className="flex justify-end gap-3 pt-2">
                    <button onClick={onClose} className="px-5 py-2.5 text-gray-600 hover:bg-gray-100 rounded-lg font-medium border border-gray-200">
                        {t.btnCancel}
                    </button>
                    <button onClick={handleConfirm} className="px-6 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium shadow-sm">
                        {t.btnImport}
                    </button>
                </div>
            </div>
        </BottomDrawer>
    );
};

