import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Edit2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import { LanguageContext } from '../utils/i18n';

interface AccountCardProps {
  account: OTPAccount;
  onDelete: (id: string) => void;
  onEdit: (account: OTPAccount) => void;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
}

const AccountCard: React.FC<AccountCardProps> = ({ account, onDelete, onEdit, isSelected, onToggleSelect }) => {
  const { t } = useContext(LanguageContext);
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);
  const [showQR, setShowQR] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));
    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);
    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  // Generate a soft background color based on issuer char
  const getAvatarColor = (name: string) => {
    const colors = ['bg-blue-100 text-blue-700', 'bg-emerald-100 text-emerald-700', 'bg-violet-100 text-violet-700', 'bg-amber-100 text-amber-700', 'bg-rose-100 text-rose-700', 'bg-cyan-100 text-cyan-700'];
    const index = name.length % colors.length;
    return colors[index];
  };

  const avatarClass = getAvatarColor(account.issuer || 'U');

  return (
    <div 
      className={`relative bg-white rounded-2xl transition-all duration-200 flex flex-col overflow-hidden group border ${isSelected ? 'border-blue-500 ring-1 ring-blue-500 shadow-md' : 'border-gray-100 shadow-sm hover:shadow-md'}`}
    >
      {/* Top Section: Issuer & Controls */}
      <div className="p-5 pb-2 flex justify-between items-start">
        <div className="flex items-center gap-3 overflow-hidden pr-2">
            <div 
              className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 ${avatarClass}`}
            >
                {(account.issuer || '?').charAt(0).toUpperCase()}
            </div>
            <div className="min-w-0">
                <h3 className="font-bold text-gray-900 truncate text-base leading-tight" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 truncate" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox (Always Visible or on Hover) */}
        <div className="absolute top-5 right-5 z-10">
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={(e) => { e.stopPropagation(); onToggleSelect(account.id); }}
                className={`w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-6 relative">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-2 rounded-lg border shadow-sm">
                    <QRCodeSVG value={otpUri} size={130} />
                 </div>
                 <button onClick={() => setShowQR(false)} className="text-xs text-gray-500 mt-3 hover:text-blue-600 font-medium">
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className="text-4xl sm:text-5xl font-mono font-semibold text-gray-800 tracking-wider cursor-pointer hover:scale-105 active:scale-95 transition-transform select-all"
                    onClick={handleCopy}
                >
                    {formattedToken}
                </div>
                <div className={`h-6 flex items-center mt-2 transition-opacity duration-300 ${copied ? 'opacity-100' : 'opacity-0'}`}>
                    <span className="text-xs font-semibold bg-green-100 text-green-700 px-2 py-0.5 rounded-full">
                        {t.copied}
                    </span>
                </div>
            </>
         )}
      </div>

      {/* Bottom Section: Progress & Actions */}
      <div className="bg-gray-50/50 p-4 border-t border-gray-100 mt-auto">
         {/* Action Buttons Row */}
         <div className="flex justify-between items-center mb-3">
            <div className="text-xs font-medium text-gray-400 font-mono">
                {tokenData.seconds}s
            </div>

            <div className="flex gap-1">
                 <button 
                    onClick={(e) => { e.stopPropagation(); setShowQR(!showQR); }} 
                    className="p-2 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition"
                    title="QR Code"
                >
                    <QrCode size={18} />
                 </button>
                 <button 
                    onClick={(e) => { e.stopPropagation(); onEdit(account); }} 
                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition"
                    title={t.edit}
                >
                    <Edit2 size={18} />
                </button>
                 <button 
                    onClick={(e) => { e.stopPropagation(); onDelete(account.id); }} 
                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
                    title={t.delete}
                >
                    <Trash2 size={18} />
                </button>
            </div>
         </div>

         {/* Progress Bar & Notes */}
         <div className="relative h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${tokenData.seconds < 5 ? 'bg-red-500' : 'bg-blue-500'}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
         {account.notes && (
             <p className="text-xs text-gray-400 mt-2 truncate" title={account.notes}>
                {account.notes}
             </p>
         )}
      </div>
    </div>
  );
};

