        </header>

        {/* Main Content */}
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          {/* Info Banner */}
          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${activeTab === 'local' ? 'bg-blue-50 border-blue-100 text-blue-800' : 'bg-orange-50 border-orange-100 text-orange-800'}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : <Zap size={18} />}
             </div>
             <div className="text-sm">
               <p className="font-semibold">{activeTab === 'local' ? t.bannerLocalTitle : t.bannerSessionTitle}</p>
               <p className="opacity-80">
                 {activeTab === 'local' ? t.bannerLocalDesc : t.bannerSessionDesc}
               </p>
             </div>
          </div>

          {/* Toolbar */}
          <div className="flex flex-col sm:flex-row gap-4 mb-8 justify-between items-start sm:items-center">
             <div className="flex flex-wrap gap-3">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg shadow-sm hover:shadow transition font-medium"
                >
                    <Plus size={18} /> {t.addAccount}
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium"
                >
                    <Upload size={18} /> {t.importBatch}
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium disabled:opacity-50"
                >
                    <Download size={18} /> {t.exportBatch}
                </button>
             </div>

             {filteredAccounts.length > 0 && (
                <button 
                   onClick={handleSelectAll}
                   className="text-sm font-medium text-gray-500 hover:text-blue-600 flex items-center gap-1"
                >
                   {selectedIds.size === filteredAccounts.length ? <CheckSquare size={16} /> : <Square size={16} />}
                   {selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                </button>
             )}
          </div>

          {/* Grid */}
          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
              <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                />
              ))}
            </div>
          )}
        </main>

        {/* Floating Bulk Actions Bar */}
        {selectedIds.size > 0 && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex justify-between items-center px-4">
                    <span className="font-semibold text-gray-700">
                        {selectedIds.size} {t.selected}
                    </span>
                    <div className="flex gap-3">
                        <button 
                           onClick={() => setShowExportModal(true)} // Reuse the export modal
                           className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg transition"
                        >
                            <Download size={18} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2 rounded-lg transition"
                        >
                            <Trash2 size={18} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Modals */}
        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
            />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview} 
          />
        )}

        {/* Drawers */}
        <ImportPreviewDrawer
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Edit2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import { LanguageContext } from '../utils/i18n';

interface AccountCardProps {
  account: OTPAccount;
  onDelete: (id: string) => void;
  onEdit: (account: OTPAccount) => void;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
}

const AccountCard: React.FC<AccountCardProps> = ({ account, onDelete, onEdit, isSelected, onToggleSelect }) => {
  const { t } = useContext(LanguageContext);
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);
  const [showQR, setShowQR] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));
    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);
    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  // Generate a soft background color based on issuer char
  const getAvatarColor = (name: string) => {
    const colors = ['bg-blue-100 text-blue-700', 'bg-emerald-100 text-emerald-700', 'bg-violet-100 text-violet-700', 'bg-amber-100 text-amber-700', 'bg-rose-100 text-rose-700', 'bg-cyan-100 text-cyan-700'];
    const index = name.length % colors.length;
    return colors[index];
  };

  const avatarClass = getAvatarColor(account.issuer || 'U');

  return (
    <div 
      className={`relative bg-white rounded-2xl transition-all duration-200 flex flex-col overflow-hidden group border ${isSelected ? 'border-blue-500 ring-1 ring-blue-500 shadow-md' : 'border-gray-100 shadow-sm hover:shadow-md'}`}
    >
      {/* Top Section: Issuer & Controls */}
      <div className="p-5 pb-2 flex justify-between items-start">
        <div className="flex items-center gap-3 overflow-hidden pr-2">
            <div 
              className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 ${avatarClass}`}
            >
                {(account.issuer || '?').charAt(0).toUpperCase()}
            </div>
            <div className="min-w-0">
                <h3 className="font-bold text-gray-900 truncate text-base leading-tight" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 truncate" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox (Always Visible or on Hover) */}
        <div className="absolute top-5 right-5 z-10">
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={(e) => { e.stopPropagation(); onToggleSelect(account.id); }}
                className={`w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-6 relative">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-2 rounded-lg border shadow-sm">
                    <QRCodeSVG value={otpUri} size={130} />
                 </div>
                 <button type="button" onClick={() => setShowQR(false)} className="text-xs text-gray-500 mt-3 hover:text-blue-600 font-medium">
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className="text-4xl sm:text-5xl font-mono font-semibold text-gray-800 tracking-wider cursor-pointer hover:scale-105 active:scale-95 transition-transform select-all"
                    onClick={handleCopy}
                >
                    {formattedToken}
                </div>
                <div className={`h-6 flex items-center mt-2 transition-opacity duration-300 ${copied ? 'opacity-100' : 'opacity-0'}`}>
                    <span className="text-xs font-semibold bg-green-100 text-green-700 px-2 py-0.5 rounded-full">
                        {t.copied}
                    </span>
                </div>
            </>
         )}
      </div>

      {/* Bottom Section: Progress & Actions */}
      <div className="bg-gray-50/50 p-4 border-t border-gray-100 mt-auto">
         {/* Action Buttons Row */}
         <div className="flex justify-between items-center mb-3">
            <div className="text-xs font-medium text-gray-400 font-mono">
                {tokenData.seconds}s
            </div>

            <div className="flex gap-1">
                 <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); setShowQR(!showQR); }} 
                    className="p-2 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition"
                    title="QR Code"
                >
                    <QrCode size={18} />
                 </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); onEdit(account); }} 
                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition"
                    title={t.edit}
                >
                    <Edit2 size={18} />
                </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); onDelete(account.id); }} 
                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
                    title={t.delete}
                >
                    <Trash2 size={18} />
                </button>
            </div>
         </div>

         {/* Progress Bar & Notes */}
         <div className="relative h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${tokenData.seconds < 5 ? 'bg-red-500' : 'bg-blue-500'}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
         {account.notes && (
             <p className="text-xs text-gray-400 mt-2 truncate" title={account.notes}>
                {account.notes}
             </p>
         )}
      </div>
    </div>
  );
};

export default AccountCard;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageMode, OTPAccount, ImportCandidate } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewDrawer } from './components/Modals';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);
  const [lang, setLang] = useState<Language>('en');

  // Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Load Data on Tab Change
  useEffect(() => {
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    try {
      const stored = storage.getItem(key);
      if (stored) {
        setAccounts(JSON.parse(stored));
      } else {
        setAccounts([]);
      }
    } catch (e) {
      console.error("Failed to load data", e);
      setAccounts([]);
    }
    // Clear selection when tab changes
    setSelectedIds(new Set());
    setSearchQuery('');
  }, [activeTab]);

  // Save Data helper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
    setAccounts(newAccounts);
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    storage.setItem(key, JSON.stringify(newAccounts));
  };

  // Add / Edit Logic
  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        // Update existing
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
    } else {
        // Add new
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
    }
    setEditingAccount(undefined); // Close edit mode
  };

  // Handle parsed candidates from Import Modal
  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  // Confirm import from Drawer
  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      // Direct filter on the current 'accounts' state
      const updatedAccounts = accounts.filter(a => a.id !== id);
      saveAccounts(updatedAccounts);

      // Update selection if necessary
      if (selectedIds.has(id)) {
          const newSelected = new Set(selectedIds);
          newSelected.delete(id);
          setSelectedIds(newSelected);
      }
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  // Selection Logic
  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          const updatedAccounts = accounts.filter(a => !selectedIds.has(a.id));
          saveAccounts(updatedAccounts);
          setSelectedIds(new Set());
      }
  };

  // Filter Logic
  const filteredAccounts = useMemo(() => {
    if (!searchQuery.trim()) return accounts;

    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);

    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      // Every keyword must exist in the search string (Intersection)
      return keywords.every(kw => searchString.includes(kw));
    });
  }, [accounts, searchQuery]);

  const t = translations[lang];

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-20">

        {/* Navbar / Header */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className="bg-blue-600 p-2 rounded-lg">
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500 hidden md:block">
                  {t.appTitle}
                </h1>
              </div>

              {/* Search Bar */}
              <div className="flex-1 max-w-md mx-auto">
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className="h-5 w-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
                    </div>
                    <input
                        type="text"
                        className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all sm:text-sm"
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                {/* Tab Switcher */}
                <div className="flex p-1 bg-gray-100 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? 'bg-white text-blue-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <HardDrive size={16} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? 'bg-white text-orange-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <Zap size={16} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Lang Switcher */}
                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className="ml-2 p-2 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded-full transition"
                  title="Switch Language"
                >
                  <Languages size={20} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          {/* Info Banner */}
          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${activeTab === 'local' ? 'bg-blue-50 border-blue-100 text-blue-800' : 'bg-orange-50 border-orange-100 text-orange-800'}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : <Zap size={18} />}
             </div>
             <div className="text-sm">
               <p className="font-semibold">{activeTab === 'local' ? t.bannerLocalTitle : t.bannerSessionTitle}</p>
               <p className="opacity-80">
                 {activeTab === 'local' ? t.bannerLocalDesc : t.bannerSessionDesc}
               </p>
             </div>
          </div>

          {/* Toolbar */}
          <div className="flex flex-col sm:flex-row gap-4 mb-8 justify-between items-start sm:items-center">
             <div className="flex flex-wrap gap-3">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg shadow-sm hover:shadow transition font-medium"
                >
                    <Plus size={18} /> {t.addAccount}
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium"
                >
                    <Upload size={18} /> {t.importBatch}
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium disabled:opacity-50"
                >
                    <Download size={18} /> {t.exportBatch}
                </button>
             </div>

             {filteredAccounts.length > 0 && (
                <button 
                   onClick={handleSelectAll}
                   className="text-sm font-medium text-gray-500 hover:text-blue-600 flex items-center gap-1"
                >
                   {selectedIds.size === filteredAccounts.length ? <CheckSquare size={16} /> : <Square size={16} />}
                   {selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                </button>
             )}
          </div>

          {/* Grid */}
          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
              <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                />
              ))}
            </div>
          )}
        </main>

        {/* Floating Bulk Actions Bar */}
        {selectedIds.size > 0 && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex justify-between items-center px-4">
                    <span className="font-semibold text-gray-700">
                        {selectedIds.size} {t.selected}
                    </span>
                    <div className="flex gap-3">
                        <button 
                           onClick={() => setShowExportModal(true)} // Reuse the export modal
                           className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg transition"
                        >
                            <Download size={18} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2 rounded-lg transition"
                        >
                            <Trash2 size={18} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Modals */}
        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
            />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview} 
          />
        )}

        {/* Drawers */}
        <ImportPreviewDrawer
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Edit2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import { LanguageContext } from '../utils/i18n';

interface AccountCardProps {
  account: OTPAccount;
  onDelete: (id: string) => void;
  onEdit: (account: OTPAccount) => void;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
}

const AccountCard: React.FC<AccountCardProps> = ({ account, onDelete, onEdit, isSelected, onToggleSelect }) => {
  const { t } = useContext(LanguageContext);
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);
  const [showQR, setShowQR] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));
    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);
    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  // Generate a soft background color based on issuer char
  const getAvatarColor = (name: string) => {
    const colors = ['bg-blue-100 text-blue-700', 'bg-emerald-100 text-emerald-700', 'bg-violet-100 text-violet-700', 'bg-amber-100 text-amber-700', 'bg-rose-100 text-rose-700', 'bg-cyan-100 text-cyan-700'];
    const index = name.length % colors.length;
    return colors[index];
  };

  const avatarClass = getAvatarColor(account.issuer || 'U');

  return (
    <div 
      className={`relative bg-white rounded-2xl transition-all duration-200 flex flex-col overflow-hidden group border ${isSelected ? 'border-blue-500 ring-1 ring-blue-500 shadow-md' : 'border-gray-100 shadow-sm hover:shadow-md'}`}
    >
      {/* Top Section: Issuer & Controls */}
      <div className="p-5 pb-2 flex justify-between items-start">
        <div className="flex items-center gap-3 overflow-hidden pr-2">
            <div 
              className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 ${avatarClass}`}
            >
                {(account.issuer || '?').charAt(0).toUpperCase()}
            </div>
            <div className="min-w-0">
                <h3 className="font-bold text-gray-900 truncate text-base leading-tight" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 truncate" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox (Always Visible or on Hover) */}
        <div className="absolute top-5 right-5 z-10">
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={(e) => { e.stopPropagation(); onToggleSelect(account.id); }}
                className={`w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-6 relative">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-2 rounded-lg border shadow-sm">
                    <QRCodeSVG value={otpUri} size={130} />
                 </div>
                 <button type="button" onClick={() => setShowQR(false)} className="text-xs text-gray-500 mt-3 hover:text-blue-600 font-medium">
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className="text-4xl sm:text-5xl font-mono font-semibold text-gray-800 tracking-wider cursor-pointer hover:scale-105 active:scale-95 transition-transform select-all"
                    onClick={handleCopy}
                >
                    {formattedToken}
                </div>
                <div className={`h-6 flex items-center mt-2 transition-opacity duration-300 ${copied ? 'opacity-100' : 'opacity-0'}`}>
                    <span className="text-xs font-semibold bg-green-100 text-green-700 px-2 py-0.5 rounded-full">
                        {t.copied}
                    </span>
                </div>
            </>
         )}
      </div>

      {/* Bottom Section: Progress & Actions */}
      <div className="bg-gray-50/50 p-4 border-t border-gray-100 mt-auto">
         {/* Action Buttons Row */}
         <div className="flex justify-between items-center mb-3">
            <div className="text-xs font-medium text-gray-400 font-mono">
                {tokenData.seconds}s
            </div>

            <div className="flex gap-1">
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); setShowQR(!showQR); }} 
                    className="p-2 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition"
                    title="QR Code"
                >
                    <QrCode size={18} className="pointer-events-none" />
                 </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onEdit(account); }} 
                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition"
                    title={t.edit}
                >
                    <Edit2 size={18} className="pointer-events-none" />
                </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(account.id); }} 
                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
                    title={t.delete}
                >
                    <Trash2 size={18} className="pointer-events-none" />
                </button>
            </div>
         </div>

         {/* Progress Bar & Notes */}
         <div className="relative h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${tokenData.seconds < 5 ? 'bg-red-500' : 'bg-blue-500'}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
         {account.notes && (
             <p className="text-xs text-gray-400 mt-2 truncate" title={account.notes}>
                {account.notes}
             </p>
         )}
      </div>
    </div>
  );
};

export default AccountCard;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageMode, OTPAccount, ImportCandidate } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewDrawer } from './components/Modals';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);
  const [lang, setLang] = useState<Language>('en');

  // Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Load Data on Tab Change
  useEffect(() => {
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    try {
      const stored = storage.getItem(key);
      if (stored) {
        setAccounts(JSON.parse(stored));
      } else {
        setAccounts([]);
      }
    } catch (e) {
      console.error("Failed to load data", e);
      setAccounts([]);
    }
    // Clear selection when tab changes
    setSelectedIds(new Set());
    setSearchQuery('');
  }, [activeTab]);

  // Save Data helper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
    setAccounts(newAccounts);
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    storage.setItem(key, JSON.stringify(newAccounts));
  };

  // Add / Edit Logic
  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        // Update existing
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
    } else {
        // Add new
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
    }
    setEditingAccount(undefined); // Close edit mode
  };

  // Handle parsed candidates from Import Modal
  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  // Confirm import from Drawer
  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      setAccounts(prevAccounts => {
        const updatedAccounts = prevAccounts.filter(a => a.id !== id);

        // Persist immediately using the current activeTab closure
        // Note: We use the closure's activeTab which matches the rendered view
        const key = STORAGE_KEYS[activeTab];
        const storage = activeTab === 'local' ? localStorage : sessionStorage;
        storage.setItem(key, JSON.stringify(updatedAccounts));

        return updatedAccounts;
      });

      // Update selection if necessary
      setSelectedIds(prev => {
        if (prev.has(id)) {
            const next = new Set(prev);
            next.delete(id);
            return next;
        }
        return prev;
      });
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  // Selection Logic
  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          setAccounts(prevAccounts => {
              const updatedAccounts = prevAccounts.filter(a => !selectedIds.has(a.id));

              const key = STORAGE_KEYS[activeTab];
              const storage = activeTab === 'local' ? localStorage : sessionStorage;
              storage.setItem(key, JSON.stringify(updatedAccounts));

              return updatedAccounts;
          });
          setSelectedIds(new Set());
      }
  };

  // Filter Logic
  const filteredAccounts = useMemo(() => {
    if (!searchQuery.trim()) return accounts;

    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);

    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      // Every keyword must exist in the search string (Intersection)
      return keywords.every(kw => searchString.includes(kw));
    });
  }, [accounts, searchQuery]);

  const t = translations[lang];

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-20">

        {/* Navbar / Header */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className="bg-blue-600 p-2 rounded-lg">
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500 hidden md:block">
                  {t.appTitle}
                </h1>
              </div>

              {/* Search Bar */}
              <div className="flex-1 max-w-md mx-auto">
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className="h-5 w-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
                    </div>
                    <input
                        type="text"
                        className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all sm:text-sm"
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                {/* Tab Switcher */}
                <div className="flex p-1 bg-gray-100 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? 'bg-white text-blue-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <HardDrive size={16} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? 'bg-white text-orange-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <Zap size={16} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Lang Switcher */}
                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className="ml-2 p-2 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded-full transition"
                  title="Switch Language"
                >
                  <Languages size={20} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          {/* Info Banner */}
          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${activeTab === 'local' ? 'bg-blue-50 border-blue-100 text-blue-800' : 'bg-orange-50 border-orange-100 text-orange-800'}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : <Zap size={18} />}
             </div>
             <div className="text-sm">
               <p className="font-semibold">{activeTab === 'local' ? t.bannerLocalTitle : t.bannerSessionTitle}</p>
               <p className="opacity-80">
                 {activeTab === 'local' ? t.bannerLocalDesc : t.bannerSessionDesc}
               </p>
             </div>
          </div>

          {/* Toolbar */}
          <div className="flex flex-col sm:flex-row gap-4 mb-8 justify-between items-start sm:items-center">
             <div className="flex flex-wrap gap-3">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg shadow-sm hover:shadow transition font-medium"
                >
                    <Plus size={18} /> {t.addAccount}
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium"
                >
                    <Upload size={18} /> {t.importBatch}
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium disabled:opacity-50"
                >
                    <Download size={18} /> {t.exportBatch}
                </button>
             </div>

             {filteredAccounts.length > 0 && (
                <button 
                   onClick={handleSelectAll}
                   className="text-sm font-medium text-gray-500 hover:text-blue-600 flex items-center gap-1"
                >
                   {selectedIds.size === filteredAccounts.length ? <CheckSquare size={16} /> : <Square size={16} />}
                   {selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                </button>
             )}
          </div>

          {/* Grid */}
          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
              <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                />
              ))}
            </div>
          )}
        </main>

        {/* Floating Bulk Actions Bar */}
        {selectedIds.size > 0 && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex justify-between items-center px-4">
                    <span className="font-semibold text-gray-700">
                        {selectedIds.size} {t.selected}
                    </span>
                    <div className="flex gap-3">
                        <button 
                           onClick={() => setShowExportModal(true)} // Reuse the export modal
                           className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg transition"
                        >
                            <Download size={18} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2 rounded-lg transition"
                        >
                            <Trash2 size={18} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Modals */}
        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
            />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview} 
          />
        )}

        {/* Drawers */}
        <ImportPreviewDrawer
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

export default App;

export type StorageMode = 'local' | 'session';

export interface AppLogo {
  id: string; // Unique identifier (integer string or uuid)
  name: string;
  data: string; // Base64 or URL
  isDefault?: boolean;
}

export interface OTPAccount {
  id: string;
  issuer: string;
  account: string;
  secret: string;
  period: number;
  notes?: string;
  logoId?: string; // Reference to AppLogo.id
  algorithm?: string;
  digits?: number;
  createdAt: number;
}

export interface ImportCandidate {
  raw: string;
  issuer: string;
  account: string;
  secret: string;
  period: number;
  isValid: boolean;
  notes?: string;
  logoId?: string;
}

export interface DefaultLogo {
  id: number;
  name: string;
  data: string;
}

import * as OTPAuth from 'otpauth';

// Wrapper to generate current token and remaining seconds
export const generateToken = (secret: string, period: number = 30) => {
  try {
    // Sanitize secret (remove spaces)
    const cleanSecret = secret.replace(/\s+/g, '');

    // Check if secret is base32 compatible roughly
    if (!/^[A-Z2-7=]+$/i.test(cleanSecret)) {
      // If it's hex, we might need conversion, but standard TOTP uses Base32.
      // We will assume Base32 for this implementation as per standard.
    }

    const totp = new OTPAuth.TOTP({
      secret: OTPAuth.Secret.fromBase32(cleanSecret),
      period: period,
      algorithm: 'SHA1',
      digits: 6,
    });

    const token = totp.generate();
    const seconds = period - (Math.floor(Date.now() / 1000) % period);
    const progress = (seconds / period) * 100;

    return { token, seconds, progress, valid: true };
  } catch (e) {
    return { token: 'ERROR', seconds: 0, progress: 0, valid: false };
  }
};

export const generateRandomSecret = (length: number = 16): string => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

export const parseOTPAuthURL = (url: string): Partial<import('../types').OTPAccount> | null => {
  try {
    const parsed = OTPAuth.URI.parse(url);
    if (parsed instanceof OTPAuth.TOTP) {
      return {
        issuer: parsed.issuer,
        account: parsed.label,
        secret: parsed.secret.base32,
        period: parsed.period,
        algorithm: parsed.algorithm,
        digits: parsed.digits,
      };
    }
  } catch (e) {
    console.error("Invalid OTP Auth URL", e);
  }
  return null;
};

// Simple text line parser
// Format: issuer, account, secret, period?, notes?, logoId?
// OR: otpauth://...
export const parseLine = (line: string, separator: string = ','): import('../types').ImportCandidate => {
  const trimmed = line.trim();
  if (!trimmed) return { raw: line, issuer: '', account: '', secret: '', period: 30, isValid: false };

  // Try URI first
  if (trimmed.startsWith('otpauth://')) {
    const parsed = parseOTPAuthURL(trimmed);
    if (parsed && parsed.secret) {
      return {
        raw: line,
        issuer: parsed.issuer || 'Unknown',
        account: parsed.account || 'Unknown',
        secret: parsed.secret,
        period: parsed.period || 30,
        isValid: true
      };
    }
  }

  // Try CSV/Split with custom separator
  const parts = trimmed.split(separator).map(p => p.trim());
  if (parts.length >= 3) {
    return {
      raw: line,
      issuer: parts[0],
      account: parts[1],
      secret: parts[2],
      period: parts[3] ? parseInt(parts[3], 10) : 30,
      notes: parts[4] || '',
      logoId: parts[5] || undefined,
      isValid: true // Basic validation passed
    };
  }

  return { raw: line, issuer: '', account: '', secret: '', period: 30, isValid: false };
};

import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount, AppLogo } from '../types';
import { generateToken } from '../utils/crypto';
