                    title={t.edit}
                >
                    <Edit2 size={18} className="pointer-events-none" />
                </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(account.id); }} 
                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
                    title={t.delete}
                >
                    <Trash2 size={18} className="pointer-events-none" />
                </button>
            </div>
         </div>

         {/* Progress Bar & Notes */}
         <div className="relative h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${tokenData.seconds < 5 ? 'bg-red-500' : 'bg-blue-500'}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
         {account.notes && (
             <p className="text-xs text-gray-400 mt-2 truncate" title={account.notes}>
                {account.notes}
             </p>
         )}
      </div>
    </div>
  );
};

