import * as OTPAuth from 'otpauth';

// Wrapper to generate current token and remaining seconds
export const generateToken = (secret: string, period: number = 30) => {
  try {
    // Sanitize secret (remove spaces)
    const cleanSecret = secret.replace(/\s+/g, '');

    // Check if secret is base32 compatible roughly
    if (!/^[A-Z2-7=]+$/i.test(cleanSecret)) {
      // If it's hex, we might need conversion, but standard TOTP uses Base32.
      // We will assume Base32 for this implementation as per standard.
    }

    const totp = new OTPAuth.TOTP({
      secret: OTPAuth.Secret.fromBase32(cleanSecret),
      period: period,
      algorithm: 'SHA1',
      digits: 6,
    });

    const token = totp.generate();
    const seconds = period - (Math.floor(Date.now() / 1000) % period);
    const progress = (seconds / period) * 100;

    return { token, seconds, progress, valid: true };
  } catch (e) {
    return { token: 'ERROR', seconds: 0, progress: 0, valid: false };
  }
};

export const generateRandomSecret = (length: number = 16): string => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

export const generateShortId = (): string => {
  return Math.random().toString(36).substring(2, 10);
};

export const parseOTPAuthURL = (url: string): Partial<import('../types').OTPAccount> | null => {
  try {
    const parsed = OTPAuth.URI.parse(url);
    if (parsed instanceof OTPAuth.TOTP) {
      return {
        issuer: parsed.issuer,
        account: parsed.label,
        secret: parsed.secret.base32,
        period: parsed.period,
        algorithm: parsed.algorithm,
        digits: parsed.digits,
      };
    }
  } catch (e) {
    console.error("Invalid OTP Auth URL", e);
  }
  return null;
};

// Simple text line parser
// Format: issuer, account, secret, period?, notes?, logoId?
// OR: otpauth://...
export const parseLine = (line: string, separator: string = ','): import('../types').ImportCandidate => {
  const trimmed = line.trim();
  if (!trimmed) return { raw: line, issuer: '', account: '', secret: '', period: 30, isValid: false };

  // Try URI first
  if (trimmed.startsWith('otpauth://')) {
    const parsed = parseOTPAuthURL(trimmed);
    if (parsed && parsed.secret) {
      return {
        raw: line,
        issuer: parsed.issuer || 'Unknown',
        account: parsed.account || 'Unknown',
        secret: parsed.secret,
        period: parsed.period || 30,
        isValid: true
      };
    }
  }

  // Try CSV/Split with custom separator
  const parts = trimmed.split(separator).map(p => p.trim());
  if (parts.length >= 3) {
    return {
      raw: line,
      issuer: parts[0],
      account: parts[1],
      secret: parts[2],
      period: parts[3] ? parseInt(parts[3], 10) : 30,
      notes: parts[4] || '',
      logoId: parts[5] || undefined,
      isValid: true // Basic validation passed
    };
  }

  return { raw: line, issuer: '', account: '', secret: '', period: 30, isValid: false };
};

import React, { useState, useEffect, useMemo } from 'react';
import { StorageMode, OTPAccount, ImportCandidate, AppLogo } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewDrawer, LogoManagerModal } from './components/Modals';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search, Image as ImageIcon } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';
import { DEFAULT_LOGOS } from './utils/defaultLogos';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data',
  customLogos: 'secure_auth_custom_logos'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);
  const [lang, setLang] = useState<Language>('en');

  // Logo State
  const [customLogos, setCustomLogos] = useState<AppLogo[]>([]);
  const [showLogoManager, setShowLogoManager] = useState(false);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Load Custom Logos on Mount
  useEffect(() => {
      try {
          const storedLogos = localStorage.getItem(STORAGE_KEYS.customLogos);
          if (storedLogos) {
              setCustomLogos(JSON.parse(storedLogos));
          }
      } catch (e) {
          console.error("Failed to load custom logos", e);
      }
  }, []);

  // Combined Logos (Default + Custom)
  const allLogos = useMemo(() => {
      // Mark defaults as default
      const defaults = DEFAULT_LOGOS.map(l => ({...l, isDefault: true}));
      return [...defaults, ...customLogos];
  }, [customLogos]);

  // Load Data on Tab Change
  useEffect(() => {
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    try {
      const stored = storage.getItem(key);
      if (stored) {
        setAccounts(JSON.parse(stored));
      } else {
        setAccounts([]);
      }
    } catch (e) {
      console.error("Failed to load data", e);
      setAccounts([]);
    }
    // Clear selection when tab changes
    setSelectedIds(new Set());
    setSearchQuery('');
  }, [activeTab]);

  // Save Data helper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
    setAccounts(newAccounts);
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    storage.setItem(key, JSON.stringify(newAccounts));
  };

  // Logo Helpers
  const saveCustomLogos = (logos: AppLogo[]) => {
      setCustomLogos(logos);
      localStorage.setItem(STORAGE_KEYS.customLogos, JSON.stringify(logos));
  };

  const handleAddLogo = (logo: AppLogo) => {
      saveCustomLogos([...customLogos, logo]);
  };

  const handleDeleteLogo = (id: string) => {
      saveCustomLogos(customLogos.filter(l => l.id !== id));
  };

  const handleImportLogos = (newLogos: AppLogo[]) => {
      // Merge unique IDs
      const existingIds = new Set(customLogos.map(l => l.id));
      const filteredNew = newLogos.filter(l => !existingIds.has(l.id));
      saveCustomLogos([...customLogos, ...filteredNew]);
  };

  // Add / Edit Logic
  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        // Update existing
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
    } else {
        // Add new
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
    }
    setEditingAccount(undefined); // Close edit mode
  };

  // Handle parsed candidates from Import Modal
  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  // Confirm import from Drawer
  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      logoId: item.logoId,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      setAccounts(prevAccounts => {
        const updatedAccounts = prevAccounts.filter(a => a.id !== id);

        // Persist immediately using the current activeTab closure
        // Note: We use the closure's activeTab which matches the rendered view
        const key = STORAGE_KEYS[activeTab];
        const storage = activeTab === 'local' ? localStorage : sessionStorage;
        storage.setItem(key, JSON.stringify(updatedAccounts));

        return updatedAccounts;
      });

      // Update selection if necessary
      setSelectedIds(prev => {
        if (prev.has(id)) {
            const next = new Set(prev);
            next.delete(id);
            return next;
        }
        return prev;
      });
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  // Selection Logic
  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          setAccounts(prevAccounts => {
              const updatedAccounts = prevAccounts.filter(a => !selectedIds.has(a.id));

              const key = STORAGE_KEYS[activeTab];
              const storage = activeTab === 'local' ? localStorage : sessionStorage;
              storage.setItem(key, JSON.stringify(updatedAccounts));

              return updatedAccounts;
          });
          setSelectedIds(new Set());
      }
  };

  // Filter Logic
  const filteredAccounts = useMemo(() => {
    if (!searchQuery.trim()) return accounts;

    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);

    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      // Every keyword must exist in the search string (Intersection)
      return keywords.every(kw => searchString.includes(kw));
    });
  }, [accounts, searchQuery]);

  const t = translations[lang];

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-20">

        {/* Navbar / Header */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className="bg-blue-600 p-2 rounded-lg">
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500 hidden md:block">
                  {t.appTitle}
                </h1>
              </div>

              {/* Search Bar */}
              <div className="flex-1 max-w-md mx-auto">
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className="h-5 w-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
                    </div>
                    <input
                        type="text"
                        className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all sm:text-sm"
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                {/* Tab Switcher */}
                <div className="flex p-1 bg-gray-100 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? 'bg-white text-blue-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <HardDrive size={16} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? 'bg-white text-orange-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <Zap size={16} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Lang Switcher */}
                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className="ml-2 p-2 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded-full transition"
                  title="Switch Language"
                >
                  <Languages size={20} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
