import React, { useState, useRef, useEffect } from 'react';
import { AppLogo } from '../types';
import { ChevronDown, Search } from 'lucide-react';

interface LogoSelectProps {
  logos: AppLogo[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
}

const LogoSelect: React.FC<LogoSelectProps> = ({ logos, value, onChange, placeholder = "Select Logo", className = "" }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");
  const dropdownRef = useRef<HTMLDivElement>(null);

  const selectedLogo = logos.find(l => l.id === value);
  const filteredLogos = logos.filter(l => l.name.toLowerCase().includes(search.toLowerCase()));

  // Close when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className={`relative ${className}`} ref={dropdownRef}>
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between border rounded-md p-2 bg-white text-left focus:ring-2 focus:ring-blue-500 focus:outline-none"
      >
        {selectedLogo ? (
            <div className="flex items-center gap-2">
                <div className="w-6 h-6 shrink-0 bg-gray-50 border rounded p-0.5 flex items-center justify-center">
                   <img src={selectedLogo.data} alt={selectedLogo.name} className="max-w-full max-h-full object-contain" />
                </div>
                <span className="truncate">{selectedLogo.name}</span>
            </div>
        ) : (
            <span className="text-gray-500">{placeholder}</span>
        )}
        <ChevronDown size={16} className="text-gray-400" />
      </button>

      {isOpen && (
        <div className="absolute z-50 mt-1 w-full bg-white border border-gray-200 rounded-md shadow-lg max-h-60 overflow-hidden flex flex-col">
          <div className="p-2 border-b sticky top-0 bg-white">
            <div className="relative">
                <Search size={14} className="absolute left-2 top-2.5 text-gray-400" />
                <input
                    type="text"
                    className="w-full pl-8 pr-2 py-1.5 border rounded text-sm focus:outline-none focus:border-blue-500"
                    placeholder="Search..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    autoFocus
                />
            </div>
          </div>
          <div className="overflow-y-auto flex-1 p-1">
             <div 
                className="flex items-center gap-2 p-2 hover:bg-gray-50 cursor-pointer rounded text-gray-500 text-sm"
                onClick={() => { onChange(""); setIsOpen(false); }}
             >
                <span>No Logo</span>
             </div>
             {filteredLogos.map(logo => (
                 <div
                    key={logo.id}
                    className={`flex items-center gap-2 p-2 hover:bg-gray-50 cursor-pointer rounded ${value === logo.id ? 'bg-blue-50 text-blue-700' : 'text-gray-800'}`}
                    onClick={() => { onChange(logo.id); setIsOpen(false); }}
                 >
                    <div className="w-8 h-8 shrink-0 bg-white border rounded p-0.5 flex items-center justify-center">
                        <img src={logo.data} alt={logo.name} className="max-w-full max-h-full object-contain" />
                    </div>
                    <span className="text-sm truncate">{logo.name}</span>
                 </div>
             ))}
             {filteredLogos.length === 0 && (
                 <div className="p-4 text-center text-sm text-gray-500">No logos found</div>
             )}
          </div>
        </div>
      )}
    </div>
  );
};

