                    {t.tabAddLogo}
                </button>
                <button 
                  className={`pb-2 px-1 font-medium text-sm ${tab === 'import' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`} 
                  onClick={() => setTab('import')}
                >
                    {t.tabImportLogos}
                </button>
            </div>

            {tab === 'list' && (
                <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-4 max-h-[60vh] overflow-y-auto p-1">
                    {logos.map(logo => (
                        <div key={logo.id} className="flex flex-col items-center group relative border rounded-lg p-2 hover:shadow-md transition aspect-square">
                            <div className="flex-1 w-full flex items-center justify-center mb-1">
                                <img src={logo.data} alt={logo.name} className="max-w-full max-h-full object-contain" />
                            </div>
                            <span className="text-[10px] text-center truncate w-full text-gray-600" title={logo.name}>{logo.name}</span>
                            {!logo.isDefault && (
                                <button 
                                    onClick={() => { if(confirm(t.confirmDeleteLogo)) onDeleteLogo(logo.id); }}
                                    className="absolute top-1 right-1 p-1 bg-white/90 text-red-500 rounded-full opacity-0 group-hover:opacity-100 transition shadow-sm hover:bg-red-50"
                                >
                                    <Trash2 size={12} />
                                </button>
                            )}
                        </div>
                    ))}
