            )}

            {tab === 'add' && (
                <form onSubmit={handleAddSubmit} className="space-y-4 max-w-lg mx-auto">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                        <input required type="text" className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none" value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
