                            {t.btnImportLogos}
                        </button>
                    </div>
                </div>
            )}
        </>
    );

    if (inline) {
        return <div className="h-full">{Content}</div>;
    }

    return (
        <Modal title={t.modalLogoManagerTitle} onClose={onClose}>
            {Content}
        </Modal>
    );
};


// --- Batch Import Modal (Step 1: Input) ---
interface BatchImportModalProps {
  onClose: () => void;
  onPreview: (candidates: ImportCandidate[]) => void;
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview }) => {
  const { t } = useContext(LanguageContext);
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleParseText = () => {
    const lines = text.split('\n');
    const parsed = lines.map(line => parseLine(line, separator)).filter(p => p.raw.trim() !== '');
    if (parsed.length > 0) {
        onPreview(parsed);
    } else {
        alert("No valid entries found.");
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files: File[] = Array.from(e.target.files);
      const newCandidates: ImportCandidate[] = [];

      for (const file of files) {
        const qrData = await decodeQRFromImage(file);
        if (qrData) {
            // Treat qrData as a line to parse (it should be an otpauth URI)
            const candidate = parseLine(qrData, separator);
            if(candidate.isValid) {
                candidate.raw = "QR Code Import";
                newCandidates.push(candidate);
            }
        }
      }

      if (newCandidates.length > 0) {
          onPreview(newCandidates);
      } else {
          alert('No valid QR codes found in selected images.');
      }
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            {t.textPaste}<br/>
            1. <code className="bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period, Notes, LogoID</code><br/>
            2. <code className="bg-gray-100 px-1 rounded">otpauth://totp/...</code>
          </p>

          <div className="flex gap-2 items-center bg-gray-50 p-2 rounded border">
            <label className="text-sm text-gray-700 font-medium whitespace-nowrap">{t.labelSeparator}:</label>
            <input 
                type="text" 
                value={separator} 
                onChange={e => setSeparator(e.target.value)} 
                className="w-12 text-center border rounded p-1"
                maxLength={1}
            />
            <span className="text-xs text-gray-400">(Default: comma)</span>
          </div>

          <textarea 
            className="w-full h-40 p-3 border rounded-md font-mono text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            placeholder={`Google${separator} alice@gmail.com${separator} JBSWY3DPEHPK3PXP${separator} 30${separator} Work Account${separator} 33`}
            value={text}
            onChange={e => setText(e.target.value)}
          />

          <div className="flex flex-col gap-3">
             <button 
                onClick={handleParseText}
                disabled={!text.trim()}
                className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium"
             >
                {t.btnPreview}
             </button>

             <div className="relative">
                 <div className="absolute inset-0 flex items-center">
                    <div className="w-full border-t border-gray-300"></div>
                 </div>
                 <div className="relative flex justify-center text-sm">
                    <span className="px-2 bg-white text-gray-500">OR</span>
                 </div>
             </div>

             <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-2.5 rounded-lg hover:bg-gray-200 border border-gray-300 transition font-medium"
             >
                <ImageIcon size={18} /> {t.btnUploadQR}
             </button>
             <input 
                type="file" 
                multiple 
                accept="image/*" 
                ref={fileInputRef} 
                className="hidden" 
                onChange={handleImageUpload} 
             />
          </div>
        </div>
    </Modal>
  );
};

// --- Import Preview Drawer (Step 2) ---
interface ImportPreviewDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    candidates: ImportCandidate[];
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ isOpen, onClose, candidates, onConfirm, logos }) => {
    const { t } = useContext(LanguageContext);
    const [preview, setPreview] = useState<ImportCandidate[]>([]);

    useEffect(() => {
        setPreview(candidates);
    }, [candidates]);

    const handleUpdatePeriod = (index: number, newPeriod: number) => {
        const updated = [...preview];
        updated[index].period = newPeriod;
        setPreview(updated);
    };

    const handleUpdateLogo = (index: number, newLogoId: string) => {
        const updated = [...preview];
        updated[index].logoId = newLogoId;
        setPreview(updated);
    };

    const handleToggleValid = (index: number) => {
        const updated = [...preview];
        updated[index].isValid = !updated[index].isValid;
        setPreview(updated);
    };

    const handleConfirm = () => {
        const validItems = preview.filter(p => p.isValid && p.secret);
        onConfirm(validItems);
    };

    return (
        <BottomDrawer isOpen={isOpen} onClose={onClose} title={`Preview Import (${preview.filter(p=>p.isValid).length})`}>
            <div className="space-y-4">
                <div className="overflow-x-auto border rounded-lg max-h-[60vh] overflow-y-auto">
                    <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 text-gray-600 font-medium sticky top-0 z-10 shadow-sm">
                        <tr>
                        <th className="p-3 w-10">{t.headerImport}</th>
                        <th className="p-3">{t.headerIssuer}</th>
                        <th className="p-3">{t.headerAccount}</th>
                        <th className="p-3">{t.headerSecret}</th>
                        <th className="p-3 w-20">{t.headerPeriod}</th>
                        <th className="p-3 w-40">Logo</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {preview.map((item, idx) => (
                        <tr key={idx} className={item.isValid ? 'bg-white hover:bg-gray-50' : 'bg-red-50 hover:bg-red-100'}>
                            <td className="p-3">
                                <input type="checkbox" checked={item.isValid} onChange={() => handleToggleValid(idx)} className="h-5 w-5 text-blue-600 rounded cursor-pointer" />
                            </td>
                            <td className="p-3 max-w-[120px] truncate font-medium">{item.issuer}</td>
                            <td className="p-3 max-w-[150px] truncate">{item.account}</td>
                            <td className="p-3 font-mono text-xs max-w-[150px] truncate text-gray-500" title={item.secret}>{item.secret}</td>
                            <td className="p-3">
                                <input 
                                    type="number" 
                                    value={item.period} 
                                    onChange={(e) => handleUpdatePeriod(idx, parseInt(e.target.value))}
                                    className="w-full p-1 border rounded text-center focus:ring-blue-500"
                                    min="15"
                                />
                            </td>
                            <td className="p-3">
                                <LogoSelect 
                                    logos={logos}
                                    value={item.logoId || ''}
                                    onChange={(val) => handleUpdateLogo(idx, val)}
                                    placeholder="Logo..."
                                    className="min-w-[140px]"
                                />
                            </td>
                        </tr>
                        ))}
                    </tbody>
                    </table>
                </div>

                <div className="flex justify-end gap-3 pt-2">
                    <button onClick={onClose} className="px-5 py-2.5 text-gray-600 hover:bg-gray-100 rounded-lg font-medium border border-gray-200">
                        {t.btnCancel}
                    </button>
                    <button onClick={handleConfirm} className="px-6 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium shadow-sm">
                        {t.btnImport}
                    </button>
                </div>
            </div>
        </BottomDrawer>
    );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose }) => {
  const { t } = useContext(LanguageContext);
  const [format, setFormat] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(false);

  const generateExportText = () => {
    if (format === 'uri') {
      return accounts.map(a => `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`).join('\n');
    }
    // CSV
    return accounts.map(a => {
        let line = `${a.issuer}, ${a.account}, ${a.secret}, ${a.period}, ${a.notes || ''}`;
        if (includeLogo && a.logoId) {
            line += `, ${a.logoId}`;
        }
        return line;
    }).join('\n');
  };

  const text = generateExportText();

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    alert(t.copied);
  };

  return (
    <Modal title={t.modalExportTitle} onClose={onClose}>
       <div className="space-y-4">
         <div className="flex gap-4 border-b pb-2">
            <button 
              className={`text-sm font-medium ${format === 'csv' ? 'text-blue-600' : 'text-gray-500'}`}
              onClick={() => setFormat('csv')}
            >
              {t.tabCSV}
            </button>
            <button 
              className={`text-sm font-medium ${format === 'uri' ? 'text-blue-600' : 'text-gray-500'}`}
              onClick={() => setFormat('uri')}
            >
              {t.tabURI}
            </button>
            <button 
              className={`text-sm font-medium ${format === 'qr' ? 'text-blue-600' : 'text-gray-500'}`}
              onClick={() => setFormat('qr')}
            >
              {t.tabQR}
            </button>
         </div>

         {format !== 'qr' ? (
           <>
            <div className="flex justify-between items-center">
                <p className="text-sm text-gray-500">
                    {format === 'csv' ? t.descCSV : t.descURI}
                </p>
                {format === 'csv' && (
                    <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                        <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className="rounded text-blue-600" />
                        {t.labelIncludeLogo}
                    </label>
                )}
            </div>
            <textarea 
                readOnly
                className="w-full h-64 p-3 border rounded-md font-mono text-xs bg-gray-50 focus:outline-none"
                value={text}
              />
              <div className="flex gap-3">
                 <button onClick={handleCopy} className="flex-1 flex items-center justify-center gap-2 bg-gray-800 text-white py-2.5 rounded-lg hover:bg-gray-900 font-medium">
                    <Copy size={18} /> {t.btnCopy}
                 </button>
              </div>
           </>
         ) : (
           <div className="space-y-4">
              <p className="text-sm text-gray-500">{t.descQR}</p>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-6 max-h-[60vh] overflow-y-auto p-2">
                 {accounts.map(acc => {
                    const uri = `otpauth://totp/${encodeURIComponent(acc.issuer)}:${encodeURIComponent(acc.account)}?secret=${acc.secret}&issuer=${encodeURIComponent(acc.issuer)}&period=${acc.period}`;
                    return (
                      <div key={acc.id} className="flex flex-col items-center border p-3 rounded-lg shadow-sm">
                         <div className="bg-white p-1">
                             <QRCodeSVG value={uri} size={100} />
                         </div>
                         <div className="mt-2 text-center w-full">
                            <p className="text-xs font-bold truncate" title={acc.issuer}>{acc.issuer}</p>
                            <p className="text-[10px] text-gray-500 truncate" title={acc.account}>{acc.account}</p>
                         </div>
                      </div>
                    );
                 })}
              </div>
           </div>
         )}
       </div>
    </Modal>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageMode, OTPAccount, ImportCandidate, AppLogo } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewDrawer, LogoManagerModal } from './components/Modals';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search, Image as ImageIcon } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data',
  customLogos: 'secure_auth_custom_logos',
  lang: 'secure_auth_lang'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);

  // Initialize Lang from Storage
  const [lang, setLang] = useState<Language>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.lang) as Language) || 'en';
      } catch {
          return 'en';
      }
  });

  // Logo State
  const [customLogos, setCustomLogos] = useState<AppLogo[]>([]);
  const [showLogoManager, setShowLogoManager] = useState(false);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Persist Language
  useEffect(() => {
      localStorage.setItem(STORAGE_KEYS.lang, lang);
  }, [lang]);

  // Load Custom Logos on Mount
  useEffect(() => {
      try {
          const storedLogos = localStorage.getItem(STORAGE_KEYS.customLogos);
          if (storedLogos) {
              setCustomLogos(JSON.parse(storedLogos));
          }
      } catch (e) {
          console.error("Failed to load custom logos", e);
      }
  }, []);

  // Load Data on Tab Change
  useEffect(() => {
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    try {
      const stored = storage.getItem(key);
      if (stored) {
        setAccounts(JSON.parse(stored));
      } else {
        setAccounts([]);
      }
    } catch (e) {
      console.error("Failed to load data", e);
      setAccounts([]);
    }
    // Clear selection when tab changes
    setSelectedIds(new Set());
    setSearchQuery('');
  }, [activeTab]);

  // Save Data helper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
    setAccounts(newAccounts);
    const key = STORAGE_KEYS[activeTab];
    const storage = activeTab === 'local' ? localStorage : sessionStorage;
    storage.setItem(key, JSON.stringify(newAccounts));
  };

  // Logo Helpers
  const saveCustomLogos = (logos: AppLogo[]) => {
      setCustomLogos(logos);
      localStorage.setItem(STORAGE_KEYS.customLogos, JSON.stringify(logos));
  };

  const handleAddLogo = (logo: AppLogo) => {
      saveCustomLogos([...customLogos, logo]);
  };

  const handleDeleteLogo = (id: string) => {
      saveCustomLogos(customLogos.filter(l => l.id !== id));
  };

  const handleBatchDeleteLogos = (ids: string[]) => {
      const idSet = new Set(ids);
      saveCustomLogos(customLogos.filter(l => !idSet.has(l.id)));
  };

  const handleImportLogos = (newLogos: AppLogo[]) => {
      // Merge unique IDs
      const existingIds = new Set(customLogos.map(l => l.id));
      const filteredNew = newLogos.filter(l => !existingIds.has(l.id));
      saveCustomLogos([...customLogos, ...filteredNew]);
  };

  // Add / Edit Logic
  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        // Update existing
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
    } else {
        // Add new
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
    }
    setEditingAccount(undefined); // Close edit mode
  };

  // Handle parsed candidates from Import Modal
  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  // Confirm import from Drawer
  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      logoId: item.logoId,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      setAccounts(prevAccounts => {
        const updatedAccounts = prevAccounts.filter(a => a.id !== id);

        // Persist immediately using the current activeTab closure
        // Note: We use the closure's activeTab which matches the rendered view
        const key = STORAGE_KEYS[activeTab];
        const storage = activeTab === 'local' ? localStorage : sessionStorage;
        storage.setItem(key, JSON.stringify(updatedAccounts));

        return updatedAccounts;
      });

      // Update selection if necessary
      setSelectedIds(prev => {
        if (prev.has(id)) {
            const next = new Set(prev);
            next.delete(id);
            return next;
        }
        return prev;
      });
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  // Selection Logic
  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          setAccounts(prevAccounts => {
              const updatedAccounts = prevAccounts.filter(a => !selectedIds.has(a.id));

              const key = STORAGE_KEYS[activeTab];
              const storage = activeTab === 'local' ? localStorage : sessionStorage;
              storage.setItem(key, JSON.stringify(updatedAccounts));

              return updatedAccounts;
          });
          setSelectedIds(new Set());
      }
  };

  // Filter Logic
  const filteredAccounts = (function() {
    if (!searchQuery.trim()) return accounts;

    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);

    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      // Every keyword must exist in the search string (Intersection)
      return keywords.every(kw => searchString.includes(kw));
    });
  })();

  const t = translations[lang];

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-20">

        {/* Navbar / Header */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className="bg-blue-600 p-2 rounded-lg">
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500 hidden md:block">
                  {t.appTitle}
                </h1>
              </div>

              {/* Search Bar */}
              <div className="flex-1 max-w-md mx-auto">
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className="h-5 w-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
                    </div>
                    <input
                        type="text"
                        className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all sm:text-sm"
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                {/* Tab Switcher */}
                <div className="flex p-1 bg-gray-100 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? 'bg-white text-blue-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <HardDrive size={16} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? 'bg-white text-orange-600 shadow-sm' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <Zap size={16} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Lang Switcher */}
                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className="ml-2 p-2 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded-full transition"
                  title="Switch Language"
                >
                  <Languages size={20} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
                    <button 
                        onClick={() => setShowLogoManager(false)}
                        className="text-gray-500 hover:text-gray-700 font-medium text-sm flex items-center gap-1"
                    >
                        &larr; Back to Accounts
                    </button>
                    <h2 className="text-2xl font-bold text-gray-800 ml-2">{t.manageLogos}</h2>
                 </div>
                 <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6">
                    {/* Inline Logo Manager Content */}
                     <LogoManagerModal 
                        onClose={() => setShowLogoManager(false)}
                        logos={customLogos}
                        onAddLogo={handleAddLogo}
                        onDeleteLogo={handleDeleteLogo}
                        onBatchDeleteLogo={handleBatchDeleteLogos}
                        onImportLogos={handleImportLogos}
                        inline={true} 
                    />
                 </div>
            </main>
        ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          {/* Info Banner */}
          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${activeTab === 'local' ? 'bg-blue-50 border-blue-100 text-blue-800' : 'bg-orange-50 border-orange-100 text-orange-800'}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : <Zap size={18} />}
             </div>
             <div className="text-sm">
               <p className="font-semibold">{activeTab === 'local' ? t.bannerLocalTitle : t.bannerSessionTitle}</p>
               <p className="opacity-80">
                 {activeTab === 'local' ? t.bannerLocalDesc : t.bannerSessionDesc}
               </p>
             </div>
          </div>

          {/* Toolbar */}
          <div className="flex flex-col xl:flex-row gap-4 mb-8 justify-between items-start xl:items-center">
             <div className="flex flex-wrap gap-3 w-full sm:w-auto flex-nowrap overflow-x-auto pb-1 sm:pb-0">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-lg shadow-sm hover:shadow transition font-medium whitespace-nowrap"
                    title={t.addAccount}
                >
                    <Plus size={18} /> <span className="hidden sm:inline">{t.addAccount}</span>
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap"
                    title={t.importBatch}
                >
                    <Upload size={18} /> <span className="hidden sm:inline">{t.importBatch}</span>
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium disabled:opacity-50 whitespace-nowrap"
                    title={t.exportBatch}
                >
                    <Download size={18} /> <span className="hidden sm:inline">{t.exportBatch}</span>
                </button>
                <button 
                    onClick={() => setShowLogoManager(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap"
                    title={t.manageLogos}
                >
                    <ImageIcon size={18} /> <span className="hidden sm:inline">{t.manageLogos}</span>
                </button>

                 {filteredAccounts.length > 0 && (
                    <button 
                       onClick={handleSelectAll}
                       className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap ml-auto sm:ml-0"
                       title={selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                    >
                       {selectedIds.size === filteredAccounts.length ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                 )}
             </div>
          </div>

          {/* Grid */}
          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
              <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    logo={customLogos.find(l => l.id === acc.logoId)}
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                />
              ))}
            </div>
          )}
        </main>
        )}

        {/* Floating Bulk Actions Bar */}
        {selectedIds.size > 0 && !showLogoManager && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex justify-between items-center px-4">
                    <span className="font-semibold text-gray-700">
                        {selectedIds.size} {t.selected}
                    </span>
                    <div className="flex gap-3">
                        <button 
                           onClick={() => setShowExportModal(true)} // Reuse the export modal
                           className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg transition"
                        >
                            <Download size={18} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2 rounded-lg transition"
                        >
                            <Trash2 size={18} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Modals */}
        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
                logos={customLogos}
            />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview} 
          />
        )}

        {/* Drawers */}
        <ImportPreviewDrawer
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
           logos={customLogos}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

