         <div className="flex-1 overflow-y-auto p-6">
            {children}
         </div>
      </div>
    </>
  );
};


// --- Add/Edit Account Modal ---
interface AccountFormModalProps {
  onClose: () => void;
  onSave: (account: Omit<OTPAccount, 'id' | 'createdAt'>) => void;
  initialData?: OTPAccount;
  logos: AppLogo[];
  color?: 'blue' | 'orange';
}

export const AccountFormModal: React.FC<AccountFormModalProps> = ({ onClose, onSave, initialData, logos, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [mode, setMode] = useState<'manual' | 'scan'>(initialData ? 'manual' : 'manual');
  const [formData, setFormData] = useState({
    issuer: '',
    account: '',
    secret: '',
    period: 30,
    notes: '',
    logoId: ''
  });

  useEffect(() => {
    if (initialData) {
        setFormData({
            issuer: initialData.issuer,
            account: initialData.account,
            secret: initialData.secret,
            period: initialData.period,
            notes: initialData.notes || '',
            logoId: initialData.logoId || ''
        });
    }
  }, [initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.issuer && formData.account && formData.secret) {
      onSave(formData);
      onClose();
    }
  };

  const handleScan = (data: string) => {
    if (data.startsWith('otpauth://')) {
        const parsed = parseOTPAuthURL(data);
        if (parsed) {
             onSave({
                issuer: parsed.issuer || 'Unknown',
                account: parsed.account || 'Unknown',
                secret: parsed.secret || '',
                period: parsed.period || 30,
                notes: 'Scanned via QR',
                logoId: ''
             });
             onClose();
             return;
        }
    }
    alert('Invalid QR Code or format not supported yet. (Must be otpauth URI)');
  };

  const generateSecret = () => {
    setFormData(prev => ({ ...prev, secret: generateRandomSecret() }));
  };

  return (
    <Modal title={initialData ? t.modalEditTitle : t.modalAddTitle} onClose={onClose}>
      {!initialData && (
          <div className="flex gap-4 mb-6 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${mode === 'manual' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setMode('manual')}
            >
              {t.tabManual}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${mode === 'scan' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setMode('scan')}
            >
              {t.tabScan}
            </button>
          </div>
      )}

      {mode === 'manual' ? (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelIssuer}</label>
                <input required type="text" placeholder="e.g. Google" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.issuer} onChange={e => setFormData({...formData, issuer: e.target.value})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelAccount}</label>
                <input required type="text" placeholder="e.g. alice@example.com" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.account} onChange={e => setFormData({...formData, account: e.target.value})} />
             </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSecret}</label>
            <div className="flex gap-2">
                <input required type="text" placeholder="Base32 Secret" className={`flex-1 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono`} 
                value={formData.secret} onChange={e => setFormData({...formData, secret: e.target.value})} />
                <button type="button" onClick={generateSecret} className="px-3 py-2 bg-gray-100 text-gray-600 rounded-md hover:bg-gray-200" title={t.btnGenerate}>
                    <RefreshCw size={18} />
                </button>
            </div>
            {!initialData && <p className="text-xs text-gray-500 mt-1">{t.msgLeaveBlank}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelPeriod}</label>
                <input type="number" min="15" step="1" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.period} onChange={e => setFormData({...formData, period: parseInt(e.target.value) || 30})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelNotes}</label>
                <input type="text" placeholder="Tag or description" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
             </div>
          </div>

          <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogo}</label>
              <LogoSelect 
                 logos={logos}
                 value={formData.logoId}
                 onChange={(val) => setFormData({...formData, logoId: val})}
              />
          </div>

          <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4`}>
            {t.btnSave}
          </button>
        </form>
      ) : (
        <QRCodeScanner onScan={handleScan} onClose={onClose} />
      )}
    </Modal>
  );
};

// --- Logo Manager Modal ---
interface LogoManagerModalProps {
    onClose: () => void;
    logos: AppLogo[];
    onAddLogo: (logo: AppLogo) => void;
    onDeleteLogo: (id: string) => void;
    onBatchDeleteLogo: (ids: string[]) => void;
    onImportLogos: (logos: AppLogo[]) => void;
    inline?: boolean;
    color?: 'blue' | 'orange';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color='blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');

    // Selection State
    const [selectedLogoIds, setSelectedLogoIds] = useState<Set<string>>(new Set());

    // Add Logo State
    const [newLogoName, setNewLogoName] = useState('');
    const [newLogoUrl, setNewLogoUrl] = useState('');
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Import/Export State
    const [importText, setImportText] = useState('');
    const [dragActive, setDragActive] = useState(false);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                setNewLogoUrl(ev.target?.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleAddSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (newLogoName && newLogoUrl) {
            const newLogo: AppLogo = {
                id: generateShortId(), 
                name: newLogoName,
                data: newLogoUrl,
                isDefault: false
            };
            onAddLogo(newLogo);
            setNewLogoName('');
            setNewLogoUrl('');
            setTab('list');
        }
    };

    const processJsonImport = (jsonString: string) => {
         try {
            const parsed = JSON.parse(jsonString);
            if (Array.isArray(parsed)) {
                const validLogos = parsed.filter((l: any) => l.id && l.name && l.data);
                if (validLogos.length > 0) {
                    onImportLogos(validLogos);
                    setImportText('');
                } else {
                    alert("No valid logos found in JSON.");
                }
            }
        } catch (e) {
            alert("Invalid JSON format.");
        }
    }

    const handleImportSubmit = () => {
       processJsonImport(importText);
    };

    const handleExport = () => {
        // Export selected or all
        const subset = selectedLogoIds.size > 0 
            ? logos.filter(l => selectedLogoIds.has(l.id))
            : logos;

        const json = JSON.stringify(subset, null, 2);
        navigator.clipboard.writeText(json);
        alert(t.copied);
    };

    // Selection Logic
    const toggleSelection = (id: string) => {
        const next = new Set(selectedLogoIds);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        setSelectedLogoIds(next);
    };

    const handleSelectAll = () => {
        if (selectedLogoIds.size === logos.length) setSelectedLogoIds(new Set());
        else setSelectedLogoIds(new Set(logos.map(l => l.id)));
    };

    const handleBatchDelete = () => {
        if (selectedLogoIds.size === 0) return;
        if (confirm(`Delete ${selectedLogoIds.size} logos?`)) {
            onBatchDeleteLogo(Array.from(selectedLogoIds));
            setSelectedLogoIds(new Set());
        }
    };

    // Drag and Drop Logic
    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            const file = e.dataTransfer.files[0];
            if (file.type === "application/json" || file.name.endsWith('.json')) {
                const reader = new FileReader();
                reader.onload = (event) => {
                    const text = event.target?.result as string;
                    setImportText(text); // populate text area
                    processJsonImport(text); // auto-process
                };
                reader.readAsText(file);
            }
        }
    };

    const Content = (
        <div className="flex flex-col h-full relative">
            <div className="flex flex-col sm:flex-row gap-4 mb-4 border-b justify-between items-start sm:items-center shrink-0">
                <div className="flex gap-4">
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('list')}
                    >
                        {t.tabLogoList}
                    </button>
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('add')}
                    >
                        {t.tabAddLogo}
                    </button>
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('import')}
                    >
                        {t.tabImportLogos}
                    </button>
                </div>

                {tab === 'list' && (
                     <div className="flex gap-2">
                        <button 
                            onClick={handleSelectAll}
                            className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded text-sm transition"
                        >
                            {selectedLogoIds.size === logos.length ? <CheckSquare size={16}/> : <Square size={16}/>}
                            <span className="hidden sm:inline">{selectedLogoIds.size === logos.length ? t.deselectAll : t.selectAll}</span>
                        </button>
                     </div>
                )}
            </div>

            {tab === 'list' && (
                <>
                <div className="flex-1 min-h-0 overflow-y-auto pb-16">
                    <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-4 p-1">
                        {logos.map(logo => {
                            const isSelected = selectedLogoIds.has(logo.id);
                            return (
                                <div 
                                    key={logo.id} 
                                    className={`relative flex flex-col items-center group border rounded-lg p-3 transition cursor-pointer bg-white ${isSelected ? `${theme.border} ${theme.bgLight} ${theme.ring}` : 'border-gray-200 hover:shadow-md'}`}
                                    onClick={() => toggleSelection(logo.id)}
                                >
                                    {/* Checkbox (Same style as AccountCard) */}
                                    <div className="absolute top-2 right-2 z-10">
                                         <input 
                                            type="checkbox" 
                                            checked={isSelected}
                                            onChange={() => toggleSelection(logo.id)}
                                            className={`w-4 h-4 rounded border-gray-300 cursor-pointer transition-opacity ${theme.checkbox} ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                                         />
                                    </div>

                                    {/* Uniform Image Container (Smaller) */}
                                    <div className="w-12 h-12 mb-2 flex items-center justify-center bg-white rounded-md overflow-hidden">
                                        <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                                    </div>
                                    <span className="text-[10px] text-center truncate w-full text-gray-600 font-medium" title={logo.name}>{logo.name}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Floating Bottom Action Bar for Logos */}
                {selectedLogoIds.size > 0 && (
                     <div className="absolute bottom-0 left-0 right-0 bg-white/95 border-t backdrop-blur-sm p-3 flex justify-between items-center shadow-lg rounded-b-lg z-20 animate-in slide-in-from-bottom duration-300">
                         <span className="text-sm font-semibold text-gray-700 ml-2">{selectedLogoIds.size} {t.selected}</span>
                         <div className="flex gap-2">
                             <button 
                                onClick={handleExport}
                                className="flex items-center gap-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded-lg text-sm transition"
                             >
                                <Download size={14} /> Export
                             </button>
                             <button 
                                onClick={handleBatchDelete}
                                className="flex items-center gap-1.5 bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-sm transition"
                             >
                                <Trash2 size={14} /> Delete
                             </button>
                         </div>
                     </div>
                )}
                </>
            )}

            {tab === 'add' && (
                <form onSubmit={handleAddSubmit} className="space-y-4 max-w-lg mx-auto w-full">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                        <input required type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                        <input required type="text" className={`w-full p-2 border rounded-md mb-2 focus:ring-2 ${theme.ring} outline-none`} value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://... or data:image..." />

                        <div className="flex gap-2 items-center">
                            <span className="text-sm text-gray-500">OR</span>
                            <button type="button" onClick={() => fileInputRef.current?.click()} className="text-sm bg-gray-100 px-3 py-1 rounded hover:bg-gray-200 flex items-center gap-1 transition">
                                <Upload size={14} /> {t.btnUploadLogo}
                            </button>
                            <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleImageUpload} />
                        </div>
                    </div>
                    {newLogoUrl && (
                        <div className="w-24 h-24 border rounded-lg mx-auto flex items-center justify-center p-2 bg-gray-50">
                             <img src={newLogoUrl} alt="Preview" className="max-w-full max-h-full object-contain" />
                        </div>
                    )}
                    <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium`}>
                        {t.btnAddLogo}
                    </button>
                </form>
            )}

            {tab === 'import' && (
                <div className="space-y-4 max-w-2xl mx-auto w-full">
                    <button onClick={handleExport} className="w-full bg-gray-100 text-gray-800 py-3 rounded-lg hover:bg-gray-200 border border-gray-300 font-medium flex items-center justify-center gap-2">
                         <Copy size={18} /> {t.btnExportLogos}
                    </button>

                    <div className="border-t pt-4">
                        <label className="block text-sm font-medium text-gray-700 mb-2">{t.textLogoImport}</label>

                        {/* Drop Zone */}
                        <div 
                            className={`relative border-2 border-dashed rounded-lg p-2 transition-colors ${dragActive ? `${theme.border} ${theme.bgLight}` : 'border-gray-300 bg-gray-50'}`}
                            onDragEnter={handleDrag}
                            onDragLeave={handleDrag}
                            onDragOver={handleDrag}
                            onDrop={handleDrop}
                        >
                            <textarea 
                                className="w-full h-40 p-3 bg-transparent border-none text-xs font-mono focus:ring-0 outline-none resize-none z-10 relative"
                                value={importText}
                                onChange={e => setImportText(e.target.value)}
                                placeholder='[{"id":"uuid","name":"My Logo","data":"..."}]'
                            />
                             {!importText && (
                                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 pointer-events-none">
                                    <FileJson className="w-8 h-8 mb-2" />
                                    <span className="text-xs">Drag & Drop JSON file here</span>
                                </div>
                             )}
                        </div>

                        <button onClick={handleImportSubmit} disabled={!importText} className={`w-full mt-2 ${theme.btn} text-white py-2.5 rounded-lg disabled:opacity-50 font-medium`}>
                            {t.btnImportLogos}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );

    if (inline) {
        return <div className="h-full">{Content}</div>;
    }

    return (
        <Modal title={t.modalLogoManagerTitle} onClose={onClose}>
            {Content}
        </Modal>
    );
};


// --- Batch Import Modal (Step 1: Input) ---
interface BatchImportModalProps {
  onClose: () => void;
  onPreview: (candidates: ImportCandidate[]) => void;
  color?: 'blue' | 'orange';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color='blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleParseText = () => {
    const lines = text.split('\n');
    const parsed = lines.map(line => parseLine(line, separator)).filter(p => p.raw.trim() !== '');
    if (parsed.length > 0) {
        onPreview(parsed);
    } else {
        alert("No valid entries found.");
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files: File[] = Array.from(e.target.files);
      const newCandidates: ImportCandidate[] = [];

      for (const file of files) {
        const qrData = await decodeQRFromImage(file);
        if (qrData) {
            // Treat qrData as a line to parse (it should be an otpauth URI)
            const candidate = parseLine(qrData, separator);
            if(candidate.isValid) {
                candidate.raw = "QR Code Import";
                newCandidates.push(candidate);
            }
        }
      }

      if (newCandidates.length > 0) {
          onPreview(newCandidates);
      } else {
          alert('No valid QR codes found in selected images.');
      }
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            {t.textPaste}<br/>
            1. <code className="bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period, Notes, LogoID</code><br/>
            2. <code className="bg-gray-100 px-1 rounded">otpauth://totp/...</code>
          </p>

          <div className="flex gap-2 items-center bg-gray-50 p-2 rounded border">
            <label className="text-sm text-gray-700 font-medium whitespace-nowrap">{t.labelSeparator}:</label>
            <input 
                type="text" 
                value={separator} 
                onChange={e => setSeparator(e.target.value)} 
                className="w-12 text-center border rounded p-1"
                maxLength={1}
            />
            <span className="text-xs text-gray-400">(Default: comma)</span>
          </div>

          <textarea 
            className={`w-full h-40 p-3 border rounded-md font-mono text-sm focus:ring-2 ${theme.ring} outline-none`}
            placeholder={`Google${separator} alice@gmail.com${separator} JBSWY3DPEHPK3PXP${separator} 30${separator} Work Account${separator} 33`}
            value={text}
            onChange={e => setText(e.target.value)}
          />

          <div className="flex flex-col gap-3">
             <button 
                onClick={handleParseText}
                disabled={!text.trim()}
                className={`w-full ${theme.btn} text-white py-2.5 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed font-medium`}
             >
                {t.btnPreview}
             </button>

             <div className="relative">
                 <div className="absolute inset-0 flex items-center">
                    <div className="w-full border-t border-gray-300"></div>
                 </div>
                 <div className="relative flex justify-center text-sm">
                    <span className="px-2 bg-white text-gray-500">OR</span>
                 </div>
             </div>

             <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-2.5 rounded-lg hover:bg-gray-200 border border-gray-300 transition font-medium"
             >
                <ImageIcon size={18} /> {t.btnUploadQR}
             </button>
             <input 
                type="file" 
                multiple 
                accept="image/*" 
                ref={fileInputRef} 
                className="hidden" 
                onChange={handleImageUpload} 
             />
          </div>
        </div>
    </Modal>
  );
};

// --- Import Preview Drawer (Step 2) ---
interface ImportPreviewDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    candidates: ImportCandidate[];
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange';
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ isOpen, onClose, candidates, onConfirm, logos, color='blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [preview, setPreview] = useState<ImportCandidate[]>([]);

    useEffect(() => {
        setPreview(candidates);
    }, [candidates]);

    const handleUpdatePeriod = (index: number, newPeriod: number) => {
        const updated = [...preview];
        updated[index].period = newPeriod;
        setPreview(updated);
    };

    const handleUpdateLogo = (index: number, newLogoId: string) => {
        const updated = [...preview];
        updated[index].logoId = newLogoId;
        setPreview(updated);
    };

    const handleToggleValid = (index: number) => {
        const updated = [...preview];
        updated[index].isValid = !updated[index].isValid;
        setPreview(updated);
    };

    const handleConfirm = () => {
        const validItems = preview.filter(p => p.isValid && p.secret);
        onConfirm(validItems);
    };

    return (
        <BottomDrawer isOpen={isOpen} onClose={onClose} title={`Preview Import (${preview.filter(p=>p.isValid).length})`}>
            <div className="space-y-4">
                <div className="overflow-x-auto border rounded-lg max-h-[60vh] overflow-y-auto">
                    <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 text-gray-600 font-medium sticky top-0 z-10 shadow-sm">
                        <tr>
                        <th className="p-3 w-10">{t.headerImport}</th>
                        <th className="p-3">{t.headerIssuer}</th>
                        <th className="p-3">{t.headerAccount}</th>
                        <th className="p-3">{t.headerSecret}</th>
                        <th className="p-3 w-20">{t.headerPeriod}</th>
                        <th className="p-3 w-40">Logo</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {preview.map((item, idx) => (
                        <tr key={idx} className={item.isValid ? 'bg-white hover:bg-gray-50' : 'bg-red-50 hover:bg-red-100'}>
                            <td className="p-3">
                                <input type="checkbox" checked={item.isValid} onChange={() => handleToggleValid(idx)} className={`h-5 w-5 ${theme.checkbox} rounded cursor-pointer`} />
                            </td>
                            <td className="p-3 max-w-[120px] truncate font-medium">{item.issuer}</td>
                            <td className="p-3 max-w-[150px] truncate">{item.account}</td>
                            <td className="p-3 font-mono text-xs max-w-[150px] truncate text-gray-500" title={item.secret}>{item.secret}</td>
                            <td className="p-3">
                                <input 
                                    type="number" 
                                    value={item.period} 
                                    onChange={(e) => handleUpdatePeriod(idx, parseInt(e.target.value))}
                                    className={`w-full p-1 border rounded text-center focus:ring-2 ${theme.ring} outline-none`}
                                    min="15"
                                />
                            </td>
                            <td className="p-3">
                                <LogoSelect 
                                    logos={logos}
                                    value={item.logoId || ''}
                                    onChange={(val) => handleUpdateLogo(idx, val)}
                                    placeholder="Logo..."
                                    className="min-w-[140px]"
                                />
                            </td>
                        </tr>
                        ))}
                    </tbody>
                    </table>
                </div>

                <div className="flex justify-end gap-3 pt-2">
                    <button onClick={onClose} className="px-5 py-2.5 text-gray-600 hover:bg-gray-100 rounded-lg font-medium border border-gray-200">
                        {t.btnCancel}
                    </button>
                    <button onClick={handleConfirm} className={`px-6 py-2.5 ${theme.btn} text-white rounded-lg font-medium shadow-sm`}>
                        {t.btnImport}
                    </button>
                </div>
            </div>
        </BottomDrawer>
    );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color='blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [format, setFormat] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(false);

  const generateExportText = () => {
    if (format === 'uri') {
      return accounts.map(a => `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`).join('\n');
    }
    // CSV
    return accounts.map(a => {
        let line = `${a.issuer}, ${a.account}, ${a.secret}, ${a.period}, ${a.notes || ''}`;
        if (includeLogo && a.logoId) {
            line += `, ${a.logoId}`;
        }
        return line;
    }).join('\n');
  };

  const text = generateExportText();

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    alert(t.copied);
  };

  return (
    <Modal title={t.modalExportTitle} onClose={onClose}>
       <div className="space-y-4">
         <div className="flex gap-4 border-b pb-2">
            <button 
              className={`text-sm font-medium ${format === 'csv' ? theme.text : 'text-gray-500'}`}
              onClick={() => setFormat('csv')}
            >
              {t.tabCSV}
            </button>
            <button 
              className={`text-sm font-medium ${format === 'uri' ? theme.text : 'text-gray-500'}`}
              onClick={() => setFormat('uri')}
            >
              {t.tabURI}
            </button>
            <button 
              className={`text-sm font-medium ${format === 'qr' ? theme.text : 'text-gray-500'}`}
              onClick={() => setFormat('qr')}
            >
              {t.tabQR}
            </button>
         </div>

         {format !== 'qr' ? (
           <>
            <div className="flex justify-between items-center">
                <p className="text-sm text-gray-500">
                    {format === 'csv' ? t.descCSV : t.descURI}
                </p>
                {format === 'csv' && (
                    <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                        <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                        {t.labelIncludeLogo}
                    </label>
                )}
            </div>
            <textarea 
                readOnly
                className="w-full h-64 p-3 border rounded-md font-mono text-xs bg-gray-50 focus:outline-none"
                value={text}
              />
              <div className="flex gap-3">
                 <button onClick={handleCopy} className="flex-1 flex items-center justify-center gap-2 bg-gray-800 text-white py-2.5 rounded-lg hover:bg-gray-900 font-medium">
                    <Copy size={18} /> {t.btnCopy}
                 </button>
              </div>
           </>
         ) : (
           <div className="space-y-4">
              <p className="text-sm text-gray-500">{t.descQR}</p>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-6 max-h-[60vh] overflow-y-auto p-2">
                 {accounts.map(acc => {
                    const uri = `otpauth://totp/${encodeURIComponent(acc.issuer)}:${encodeURIComponent(acc.account)}?secret=${acc.secret}&issuer=${encodeURIComponent(acc.issuer)}&period=${acc.period}`;
                    return (
                      <div key={acc.id} className="flex flex-col items-center border p-3 rounded-lg shadow-sm">
                         <div className="bg-white p-1">
                             <QRCodeSVG value={uri} size={100} />
