    const [importText, setImportText] = useState('');
    const [dragActive, setDragActive] = useState(false);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                setNewLogoUrl(ev.target?.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleAddSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (newLogoName && newLogoUrl) {
            const newLogo: AppLogo = {
                id: generateShortId(), 
                name: newLogoName,
                data: newLogoUrl,
                isDefault: false
            };
            onAddLogo(newLogo);
            setNewLogoName('');
            setNewLogoUrl('');
            setTab('list');
        }
    };

    const processJsonImport = (jsonString: string) => {
         try {
            const parsed = JSON.parse(jsonString);
            if (Array.isArray(parsed)) {
                const validLogos = parsed.filter((l: any) => l.id && l.name && l.data);
                if (validLogos.length > 0) {
                    onImportLogos(validLogos);
                    setImportText('');
                } else {
                    alert("No valid logos found in JSON.");
                }
            }
        } catch (e) {
            alert("Invalid JSON format.");
        }
    }

    const handleImportSubmit = () => {
       processJsonImport(importText);
    };

    const handleExport = () => {
        // Export selected or all
        const subset = selectedLogoIds.size > 0 
            ? logos.filter(l => selectedLogoIds.has(l.id))
            : logos;

        const json = JSON.stringify(subset, null, 2);
        navigator.clipboard.writeText(json);
        alert(t.copied);
    };

    // Selection Logic
    const toggleSelection = (id: string) => {
        const next = new Set(selectedLogoIds);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        setSelectedLogoIds(next);
    };

    const handleSelectAll = () => {
        if (selectedLogoIds.size === logos.length) setSelectedLogoIds(new Set());
        else setSelectedLogoIds(new Set(logos.map(l => l.id)));
    };

    const handleBatchDelete = () => {
        if (selectedLogoIds.size === 0) return;
        if (confirm(`Delete ${selectedLogoIds.size} logos?`)) {
            onBatchDeleteLogo(Array.from(selectedLogoIds));
            setSelectedLogoIds(new Set());
        }
    };

    // Drag and Drop Logic
    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            const file = e.dataTransfer.files[0];
            if (file.type === "application/json" || file.name.endsWith('.json')) {
                const reader = new FileReader();
                reader.onload = (event) => {
                    const text = event.target?.result as string;
                    setImportText(text); // populate text area
                    processJsonImport(text); // auto-process
                };
                reader.readAsText(file);
            }
        }
    };

    const Content = (
        <div className="flex flex-col h-full relative">
            <div className="flex flex-col sm:flex-row gap-4 mb-4 border-b justify-between items-start sm:items-center shrink-0">
                <div className="flex gap-4">
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('list')}
                    >
                        {t.tabLogoList}
                    </button>
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('add')}
                    >
                        {t.tabAddLogo}
                    </button>
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('import')}
                    >
                        {t.tabImportLogos}
                    </button>
                </div>

                {tab === 'list' && (
                     <div className="flex gap-2">
                        <button 
                            onClick={handleSelectAll}
                            className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded text-sm transition"
                        >
                            {selectedLogoIds.size === logos.length ? <CheckSquare size={16}/> : <Square size={16}/>}
                            <span className="hidden sm:inline">{selectedLogoIds.size === logos.length ? t.deselectAll : t.selectAll}</span>
                        </button>
                     </div>
                )}
            </div>

            {tab === 'list' && (
                <>
                <div className="flex-1 min-h-0 overflow-y-auto pb-16">
                    <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-4 p-1">
                        {logos.map(logo => {
                            const isSelected = selectedLogoIds.has(logo.id);
                            return (
                                <div 
                                    key={logo.id} 
                                    className={`relative flex flex-col items-center group border rounded-lg p-3 transition cursor-pointer bg-white ${isSelected ? `${theme.border} ${theme.bgLight} ${theme.ring}` : 'border-gray-200 hover:shadow-md'}`}
                                    onClick={() => toggleSelection(logo.id)}
                                >
                                    {/* Checkbox (Same style as AccountCard) */}
                                    <div className="absolute top-2 right-2 z-10">
                                         <input 
                                            type="checkbox" 
                                            checked={isSelected}
                                            onChange={() => toggleSelection(logo.id)}
                                            className={`w-4 h-4 rounded border-gray-300 cursor-pointer transition-opacity ${theme.checkbox} ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                                         />
                                    </div>

                                    {/* Uniform Image Container (Smaller) */}
                                    <div className="w-12 h-12 mb-2 flex items-center justify-center bg-white rounded-md overflow-hidden">
                                        <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                                    </div>
                                    <span className="text-[10px] text-center truncate w-full text-gray-600 font-medium" title={logo.name}>{logo.name}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Floating Bottom Action Bar for Logos */}
                {selectedLogoIds.size > 0 && (
                     <div className="absolute bottom-0 left-0 right-0 bg-white/95 border-t backdrop-blur-sm p-3 flex justify-between items-center shadow-lg rounded-b-lg z-20 animate-in slide-in-from-bottom duration-300">
                         <span className="text-sm font-semibold text-gray-700 ml-2">{selectedLogoIds.size} {t.selected}</span>
                         <div className="flex gap-2">
                             <button 
                                onClick={handleExport}
                                className="flex items-center gap-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded-lg text-sm transition"
                             >
                                <Download size={14} /> {t.exportSelected}
                             </button>
                             <button 
                                onClick={handleBatchDelete}
                                className="flex items-center gap-1.5 bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-sm transition"
                             >
                                <Trash2 size={14} /> {t.deleteSelected}
                             </button>
                         </div>
                     </div>
                )}
                </>
            )}

            {tab === 'add' && (
                <form onSubmit={handleAddSubmit} className="space-y-4 max-w-lg mx-auto w-full">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                        <input required type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                        <input required type="text" className={`w-full p-2 border rounded-md mb-2 focus:ring-2 ${theme.ring} outline-none`} value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://... or data:image..." />

                        <div className="flex gap-2 items-center">
                            <span className="text-sm text-gray-500">OR</span>
                            <button type="button" onClick={() => fileInputRef.current?.click()} className="text-sm bg-gray-100 px-3 py-1 rounded hover:bg-gray-200 flex items-center gap-1 transition">
                                <Upload size={14} /> {t.btnUploadLogo}
                            </button>
                            <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleImageUpload} />
                        </div>
                    </div>
                    {newLogoUrl && (
                        <div className="w-24 h-24 border rounded-lg mx-auto flex items-center justify-center p-2 bg-gray-50">
                             <img src={newLogoUrl} alt="Preview" className="max-w-full max-h-full object-contain" />
                        </div>
                    )}
                    <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium`}>
                        {t.btnAddLogo}
                    </button>
                </form>
            )}

            {tab === 'import' && (
                <div className="space-y-4 max-w-2xl mx-auto w-full">
                    <button onClick={handleExport} className="w-full bg-gray-100 text-gray-800 py-3 rounded-lg hover:bg-gray-200 border border-gray-300 font-medium flex items-center justify-center gap-2">
                         <Copy size={18} /> {t.btnExportLogos}
                    </button>

                    <div className="border-t pt-4">
                        <label className="block text-sm font-medium text-gray-700 mb-2">{t.textLogoImport}</label>

                        {/* Drop Zone */}
                        <div 
                            className={`relative border-2 border-dashed rounded-lg p-2 transition-colors ${dragActive ? `${theme.border} ${theme.bgLight}` : 'border-gray-300 bg-gray-50'}`}
                            onDragEnter={handleDrag}
                            onDragLeave={handleDrag}
                            onDragOver={handleDrag}
                            onDrop={handleDrop}
                        >
                            <textarea 
                                className="w-full h-40 p-3 bg-transparent border-none text-xs font-mono focus:ring-0 outline-none resize-none z-10 relative"
                                value={importText}
                                onChange={e => setImportText(e.target.value)}
                                placeholder='[{"id":"uuid","name":"My Logo","data":"..."}]'
                            />
                             {!importText && (
                                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 pointer-events-none">
                                    <FileJson className="w-8 h-8 mb-2" />
                                    <span className="text-xs">Drag & Drop JSON file here</span>
                                </div>
                             )}
                        </div>

                        <button onClick={handleImportSubmit} disabled={!importText} className={`w-full mt-2 ${theme.btn} text-white py-2.5 rounded-lg disabled:opacity-50 font-medium`}>
                            {t.btnImportLogos}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );

    if (inline) {
        return <div className="h-full">{Content}</div>;
    }

    return (
        <Modal title={t.modalLogoManagerTitle} onClose={onClose}>
            {Content}
        </Modal>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { StorageMode, OTPAccount, ImportCandidate, AppLogo } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewDrawer, LogoManagerModal, BatchEditModal, PasswordSettingsModal } from './components/Modals';
import LockScreen from './components/LockScreen';
import { ToastContainer, ToastMessage, ToastType } from './components/Toast';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search, Image as ImageIcon, Edit2, ShieldAlert } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';
import { encryptData, decryptData, hashPassword, generateSalt } from './utils/crypto';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data',
  customLogos: 'secure_auth_custom_logos',
  lang: 'secure_auth_lang',
  passwordHash: 'secure_auth_password_hash',
  salt: 'secure_auth_salt'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);

  // Security State
  const [isLocked, setIsLocked] = useState(false);
  const [hasPassword, setHasPassword] = useState(false);
  const [sessionKey, setSessionKey] = useState<string | null>(null); // To store password temporarily in memory
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // Theme Color derived from activeTab
  const themeColor = activeTab === 'local' ? 'blue' : 'orange';

  // Notification State
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  const showToast = (message: string, type: ToastType = 'info') => {
      const id = uuidv4();
      setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
      setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Initialize Lang from Storage
  const [lang, setLang] = useState<Language>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.lang) as Language) || 'en';
      } catch {
          return 'en';
      }
  });

  // Logo State
  const [customLogos, setCustomLogos] = useState<AppLogo[]>([]);
  const [showLogoManager, setShowLogoManager] = useState(false);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showBatchEditModal, setShowBatchEditModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Persist Language
  useEffect(() => {
      localStorage.setItem(STORAGE_KEYS.lang, lang);
  }, [lang]);

  // Load Custom Logos on Mount
  useEffect(() => {
      try {
          const storedLogos = localStorage.getItem(STORAGE_KEYS.customLogos);
          if (storedLogos) {
              setCustomLogos(JSON.parse(storedLogos));
          }
      } catch (e) {
          console.error("Failed to load custom logos", e);
      }
  }, []);

  // Check Lock Status on Mount
  useEffect(() => {
    const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
    const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);

    if (storedHash && storedSalt) {
        setHasPassword(true);
        setIsLocked(true);
    } else {
        setHasPassword(false);
        setIsLocked(false);
        loadData('local', null); // Initial load without password
    }
  }, []);

  // Load Data helper function
  const loadData = async (mode: StorageMode, password: string | null) => {
      const key = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const stored = storage.getItem(key);

      if (!stored) {
          setAccounts([]);
          return;
      }

      // If persistent storage and we have a password, try decrypt
      // Session storage is usually ephemeral, but if we want to secure it too, we could.
      // Current design: Only Local Storage is encrypted persistently. 
      // Session storage is assumed temporary and plaintext in session (or cleared).

      if (mode === 'local' && password) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const decrypted = await decryptData(stored, password, salt);
              if (decrypted) {
                  setAccounts(JSON.parse(decrypted));
              } else {
                  console.error("Failed to decrypt local data");
                  setAccounts([]); // Or handle error
              }
          }
      } else {
          // Assume plaintext if no password or session storage
          try {
              // Check if it looks encrypted (Base64) but we expected plaintext?
              // Simple check: JSON starts with [ or {
              if (stored.trim().startsWith('[') || stored.trim().startsWith('{')) {
                   setAccounts(JSON.parse(stored));
              } else if (mode === 'local' && hasPassword && !password) {
                   // This shouldn't happen if flow is correct (locked)
                   console.log("Data is encrypted, waiting for unlock");
              } else {
                   // Fallback
                   setAccounts(JSON.parse(stored)); 
              }
          } catch (e) {
              console.error("Error parsing data", e);
              setAccounts([]);
          }
      }
  };

  // Reload data when Tab changes (if unlocked)
  useEffect(() => {
      if (!isLocked) {
          loadData(activeTab, sessionKey);
          setSelectedIds(new Set());
          setSearchQuery('');
      }
  }, [activeTab, isLocked]);


  // Unlock Handler
  const handleUnlock = async (password: string) => {
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);

      if (!storedHash || !storedSalt) return false;

      // Verify Password
      const inputHash = await hashPassword(password, storedSalt);
      if (inputHash === storedHash) {
          setSessionKey(password);
          setIsLocked(false);
          await loadData('local', password); // Load decrypted data
          return true;
      }
      return false;
  };

  // Lock Reset (Forgot Password)
  const handleResetLock = () => {
      localStorage.removeItem(STORAGE_KEYS.passwordHash);
      localStorage.removeItem(STORAGE_KEYS.salt);
      localStorage.removeItem(STORAGE_KEYS.local); // Clear Encrypted Data
      setHasPassword(false);
      setIsLocked(false);
      setSessionKey(null);
      setAccounts([]);
      showToast('App reset. All local data cleared.', 'info');
  };

  // Set Password Handler
  const handleSetPassword = async (password: string) => {
      const salt = generateSalt();
      const hash = await hashPassword(password, salt);

      localStorage.setItem(STORAGE_KEYS.salt, salt);
      localStorage.setItem(STORAGE_KEYS.passwordHash, hash);
      setSessionKey(password);
      setHasPassword(true);

      // Re-save current accounts with encryption
      await saveAccountsInternal(accounts, password, 'local');
      showToast(translations[lang].passwordSet, 'success');
  };

  // Remove Password Handler
  const handleRemovePassword = async (currentPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);

      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(currentPassword, storedSalt);
          if (inputHash === storedHash) {
               localStorage.removeItem(STORAGE_KEYS.passwordHash);
               localStorage.removeItem(STORAGE_KEYS.salt);
               setHasPassword(false);
               setSessionKey(null);

               // Save as plaintext
               await saveAccountsInternal(accounts, null, 'local');
               showToast(translations[lang].passwordRemoved, 'success');
               return true;
          }
      }
      return false;
  };


  // Save Data Internal Helper
  const saveAccountsInternal = async (newAccounts: OTPAccount[], key: string | null, mode: StorageMode) => {
      const storageKey = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const json = JSON.stringify(newAccounts);

      if (mode === 'local' && key) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const encrypted = await encryptData(json, key, salt);
              storage.setItem(storageKey, encrypted);
          }
      } else {
          storage.setItem(storageKey, json);
      }
  };

  // Public Save Wrapper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
      setAccounts(newAccounts);
      saveAccountsInternal(newAccounts, sessionKey, activeTab);
  };


  // ... Existing Handlers ...

  const handleAddLogo = (logo: AppLogo) => {
      saveCustomLogos([...customLogos, logo]);
      showToast(translations[lang].logoAdded, 'success');
  };
  const saveCustomLogos = (logos: AppLogo[]) => {
      setCustomLogos(logos);
      localStorage.setItem(STORAGE_KEYS.customLogos, JSON.stringify(logos));
  };
  const handleDeleteLogo = (id: string) => {
      saveCustomLogos(customLogos.filter(l => l.id !== id));
      showToast('Logo deleted', 'success');
  };
  const handleBatchDeleteLogos = (ids: string[]) => {
      const idSet = new Set(ids);
      saveCustomLogos(customLogos.filter(l => !idSet.has(l.id)));
      showToast(`${ids.length} logos deleted`, 'success');
  };
  const handleImportLogos = (newLogos: AppLogo[]) => {
      const existingIds = new Set(customLogos.map(l => l.id));
      const filteredNew = newLogos.filter(l => !existingIds.has(l.id));
      if (filteredNew.length === 0) {
          showToast('No new logos to import (all exist)', 'info');
          return;
      }
      saveCustomLogos([...customLogos, ...filteredNew]);
      showToast(`${filteredNew.length} logos imported`, 'success');
  };

  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
        showToast('Account updated successfully', 'success');
    } else {
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
        showToast('Account created successfully', 'success');
    }
    setEditingAccount(undefined);
  };

  const handleBatchSave = (updates: Partial<OTPAccount>) => {
      if (Object.keys(updates).length === 0) {
          setShowBatchEditModal(false);
          return;
      }
      const updatedAccounts = accounts.map(acc => {
          if (selectedIds.has(acc.id)) {
              return { ...acc, ...updates };
          }
          return acc;
      });
      saveAccounts(updatedAccounts);
      showToast(`Updated ${selectedIds.size} accounts`, 'success');
      setShowBatchEditModal(false);
      setSelectedIds(new Set());
  };

  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      logoId: item.logoId,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
    showToast(`${newItems.length} accounts imported`, 'success');
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      setAccounts(prevAccounts => {
        const updatedAccounts = prevAccounts.filter(a => a.id !== id);
        saveAccountsInternal(updatedAccounts, sessionKey, activeTab);
        return updatedAccounts;
      });
      setSelectedIds(prev => {
        if (prev.has(id)) {
            const next = new Set(prev);
            next.delete(id);
            return next;
        }
        return prev;
      });
      showToast('Account deleted', 'success');
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          setAccounts(prevAccounts => {
              const updatedAccounts = prevAccounts.filter(a => !selectedIds.has(a.id));
              saveAccountsInternal(updatedAccounts, sessionKey, activeTab);
              return updatedAccounts;
          });
          showToast(`Deleted ${selectedIds.size} accounts`, 'success');
          setSelectedIds(new Set());
      }
  };

  const filteredAccounts = (function() {
    if (!searchQuery.trim()) return accounts;
    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);
    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      return keywords.every(kw => searchString.includes(kw));
    });
  })();

  const t = translations[lang];
  const theme = getThemeClasses();

  // Helper for theme classes
  function getThemeClasses() {
     if (activeTab === 'local') {
         return {
             primaryBg: 'bg-blue-600',
             primaryHover: 'hover:bg-blue-700',
             textGradient: 'from-blue-700 to-blue-500',
             focusRing: 'focus:ring-blue-500',
             checkboxText: 'text-blue-600',
             iconBg: 'bg-blue-600',
             tabActive: 'bg-white text-blue-600 shadow-sm'
         };
     } else {
         return {
             primaryBg: 'bg-orange-600',
             primaryHover: 'hover:bg-orange-700',
             textGradient: 'from-orange-700 to-orange-500',
             focusRing: 'focus:ring-orange-500',
             checkboxText: 'text-orange-600',
             iconBg: 'bg-orange-600',
             tabActive: 'bg-white text-orange-600 shadow-sm'
         };
     }
  }

  // --- Render ---

  if (isLocked) {
      return (
        <LanguageContext.Provider value={{ lang, t, setLang }}>
            <LockScreen onUnlock={handleUnlock} onReset={handleResetLock} />
        </LanguageContext.Provider>
      );
  }

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <ToastContainer toasts={toasts} onClose={removeToast} />
      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-20">

        {/* Navbar */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className={`${theme.iconBg} p-2 rounded-lg transition-colors duration-300`}>
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className={`text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r ${theme.textGradient} hidden md:block transition-all duration-300`}>
                  {t.appTitle}
                </h1>
              </div>

              <div className="flex-1 max-w-md mx-auto">
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className={`h-5 w-5 text-gray-400 group-focus-within:${theme.checkboxText} transition-colors`} />
                    </div>
                    <input
                        type="text"
                        className={`block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 ${theme.focusRing} focus:border-transparent transition-all sm:text-sm`}
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                <div className="flex p-1 bg-gray-100 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? theme.tabActive 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <HardDrive size={16} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? theme.tabActive 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <Zap size={16} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Password / Security Settings */}
                <button 
                  onClick={() => setShowPasswordModal(true)}
                  className={`ml-1 p-2 ${hasPassword ? 'text-green-600' : 'text-gray-400'} hover:bg-gray-100 rounded-full transition relative group`}
                  title={t.securityTitle}
                >
                  <Lock size={20} />
                  {hasPassword && <span className="absolute top-1 right-1 w-2 h-2 bg-green-500 rounded-full ring-2 ring-white"></span>}
                </button>

                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className={`ml-1 p-2 text-gray-500 hover:${theme.checkboxText} hover:bg-gray-100 rounded-full transition`}
                  title="Switch Language"
                >
                  <Languages size={20} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
                    <button 
                        onClick={() => setShowLogoManager(false)}
                        className="text-gray-500 hover:text-gray-700 font-medium text-sm flex items-center gap-1"
                    >
                        &larr; Back to Accounts
                    </button>
                    <h2 className="text-2xl font-bold text-gray-800 ml-2">{t.manageLogos}</h2>
                 </div>
                 <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6">
                     <LogoManagerModal 
                        onClose={() => setShowLogoManager(false)}
                        logos={customLogos}
                        onAddLogo={handleAddLogo}
                        onDeleteLogo={handleDeleteLogo}
                        onBatchDeleteLogo={handleBatchDeleteLogos}
                        onImportLogos={handleImportLogos}
                        inline={true} 
                        color={themeColor}
                    />
                 </div>
            </main>
        ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${activeTab === 'local' ? 'bg-blue-50 border-blue-100 text-blue-800' : 'bg-orange-50 border-orange-100 text-orange-800'}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : <Zap size={18} />}
             </div>
             <div className="text-sm">
               <p className="font-semibold">{activeTab === 'local' ? t.bannerLocalTitle : t.bannerSessionTitle}</p>
               <p className="opacity-80">
                 {activeTab === 'local' ? t.bannerLocalDesc : t.bannerSessionDesc}
