import React, { useRef, useState, useEffect, useContext } from 'react';
import jsQR from 'jsqr';
import { Camera, Upload, X } from 'lucide-react';
import { LanguageContext } from '../utils/i18n';

interface QRCodeScannerProps {
  onScan: (data: string) => void;
  onClose: () => void;
}

const QRCodeScanner: React.FC<QRCodeScannerProps> = ({ onScan, onClose }) => {
  const { t } = useContext(LanguageContext);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [error, setError] = useState<string>('');
  const animationFrameRef = useRef<number>();

  const stopCamera = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
      setIsCameraActive(false);
    }
  };

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute('playsinline', 'true');
        await videoRef.current.play();
        setIsCameraActive(true);
        animationFrameRef.current = requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Camera Error:", err);
      setError(t.errCamAccess);
    }
  };

  const tick = () => {
    if (!videoRef.current || !canvasRef.current) return;

    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });

      if (ctx && video.videoWidth > 0 && video.videoHeight > 0) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        try {
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "attemptBoth",
          });

          if (code && code.data) {
            stopCamera();
            onScan(code.data);
            return;
          }
        } catch (e) {
          // Ignore processing errors (e.g. out of memory or corrupted frame)
        }
      }
    }
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "attemptBoth",
          });
          if (code) {
            onScan(code.data);
          } else {
            setError(t.errNoQR);
          }
        }
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  return (
    <div className="flex flex-col gap-4">
      {error && (
        <div className="bg-red-50 text-red-600 p-3 rounded-md text-sm mb-2">
          {error}
        </div>
      )}

      <div className="relative bg-black rounded-lg overflow-hidden aspect-square md:aspect-video flex items-center justify-center">
        {!isCameraActive && (
           <div className="text-gray-400 flex flex-col items-center">
             <Camera className="w-12 h-12 mb-2 opacity-50" />
             <p>{t.camInactive}</p>
           </div>
        )}
        <video ref={videoRef} className={`w-full h-full object-cover ${!isCameraActive ? 'hidden' : ''}`} muted playsInline />
        <canvas ref={canvasRef} className="hidden" />

        {/* Scan Line Overlay */}
        {isCameraActive && (
          <div className="absolute inset-0 pointer-events-none">
             <div className="w-full h-1 bg-blue-500/50 absolute top-1/2 -translate-y-1/2 shadow-[0_0_15px_rgba(59,130,246,0.5)] animate-pulse"></div>
          </div>
        )}
      </div>

      <div className="flex gap-2">
        {!isCameraActive ? (
          <button
            onClick={startCamera}
            className="flex-1 flex items-center justify-center gap-2 bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition"
          >
            <Camera size={18} />
            {t.btnStartCam}
          </button>
        ) : (
          <button
            onClick={stopCamera}
            className="flex-1 flex items-center justify-center gap-2 bg-red-600 text-white py-2 px-4 rounded-md hover:bg-red-700 transition"
          >
            <X size={18} />
            {t.btnStopCam}
          </button>
        )}

        <label className="flex-1 flex items-center justify-center gap-2 bg-gray-200 text-gray-800 py-2 px-4 rounded-md hover:bg-gray-300 transition cursor-pointer">
          <Upload size={18} />
          {t.btnUploadImg}
          <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
        </label>
      </div>
    </div>
  );
};

export default QRCodeScanner;

import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount, AppLogo } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Edit2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import { LanguageContext } from '../utils/i18n';

interface AccountCardProps {
  account: OTPAccount;
  logo?: AppLogo;
  onDelete: (id: string) => void;
  onEdit: (account: OTPAccount) => void;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
  showQR: boolean;
  onToggleQR: (id: string) => void;
  color?: 'blue' | 'orange';
}

const AccountCard: React.FC<AccountCardProps> = ({ account, logo, onDelete, onEdit, isSelected, onToggleSelect, showQR, onToggleQR, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));
    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);
    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  // Theme based styles
  const borderColor = color === 'blue' ? 'border-blue-500 ring-1 ring-blue-500' : 'border-orange-500 ring-1 ring-orange-500';
  const checkboxColor = color === 'blue' ? 'text-blue-600 focus:ring-blue-500' : 'text-orange-600 focus:ring-orange-500';
  const progressBarColor = tokenData.seconds < 5 ? 'bg-red-500' : (color === 'blue' ? 'bg-blue-500' : 'bg-orange-500');
  const hoverText = color === 'blue' ? 'hover:text-blue-600' : 'hover:text-orange-600';
  const hoverBg = color === 'blue' ? 'hover:bg-blue-50' : 'hover:bg-orange-50';
  const qrActiveBg = showQR ? (color === 'blue' ? 'bg-blue-50 text-blue-600' : 'bg-orange-50 text-orange-600') : 'text-gray-400 hover:bg-gray-100';

  // Generate a soft background color based on issuer char
  const getAvatarColor = (name: string) => {
    const colors = ['bg-blue-100 text-blue-700', 'bg-emerald-100 text-emerald-700', 'bg-violet-100 text-violet-700', 'bg-amber-100 text-amber-700', 'bg-rose-100 text-rose-700', 'bg-cyan-100 text-cyan-700'];
    const index = name.length % colors.length;
    return colors[index];
  };

  const avatarClass = getAvatarColor(account.issuer || 'U');

  return (
    <div 
      className={`relative bg-white rounded-2xl transition-all duration-200 flex flex-col overflow-hidden group border ${isSelected ? `${borderColor} shadow-md` : 'border-gray-100 shadow-sm hover:shadow-md'}`}
      onClick={(e) => {
          // Prevent accidental copy when selecting logic might change later
      }}
    >
      {/* Top Section: Issuer & Controls */}
      <div className="p-5 pb-2 flex justify-between items-start">
        <div className="flex items-center gap-3 overflow-hidden pr-2 min-w-0 flex-1">
            {logo ? (
                // Custom Logo: No border, no background, just the image
                <div className="w-10 h-10 shrink-0 flex items-center justify-center">
                    <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                </div>
            ) : (
                // Default Avatar: Colored background
                <div 
                  className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 ${avatarClass}`}
                >
                    {(account.issuer || '?').charAt(0).toUpperCase()}
                </div>
            )}
            <div className="min-w-0 flex-1">
                <h3 className="font-bold text-gray-900 truncate text-base leading-tight w-full" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 truncate w-full" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox (Always Visible or on Hover) */}
        <div className="shrink-0 ml-2 z-10" onClick={(e) => e.stopPropagation()}>
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={() => onToggleSelect(account.id)}
                className={`w-5 h-5 rounded border-gray-300 cursor-pointer transition-opacity ${checkboxColor} ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-4 relative px-4">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-2 rounded-lg border shadow-sm">
                    <QRCodeSVG value={otpUri} size={130} />
                 </div>
                 <button type="button" onClick={() => onToggleQR(account.id)} className={`text-xs text-gray-500 mt-3 ${hoverText} font-medium`}>
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className="text-4xl sm:text-5xl font-mono font-semibold text-gray-800 tracking-wider cursor-pointer hover:scale-105 active:scale-95 transition-transform select-all text-center w-full truncate"
                    onClick={handleCopy}
                    title="Click to copy"
                >
                    {formattedToken}
                </div>

                <div className={`h-6 flex items-center mt-2 transition-opacity duration-300 ${copied ? 'opacity-100' : 'opacity-0'}`}>
                    <span className="text-xs font-semibold bg-green-100 text-green-700 px-2 py-0.5 rounded-full">
                        {t.copied}
                    </span>
                </div>

                {/* Notes centered below code - Fixed Height to prevent layout shift */}
                <div className="mt-2 w-full px-2 text-center h-4 min-h-[1rem]">
                     {account.notes && (
                        <p className="text-xs text-gray-400 truncate w-full leading-4" title={account.notes}>
                           {account.notes}
                        </p>
                     )}
                </div>
            </>
         )}
      </div>

      {/* Bottom Section: Progress & Actions */}
      <div className="bg-gray-50/50 p-4 border-t border-gray-100 mt-auto">
         {/* Action Buttons Row */}
         <div className="flex justify-between items-center mb-3">
            <div className="text-xs font-medium text-gray-400 font-mono">
                {tokenData.seconds}s
            </div>

            <div className="flex gap-1">
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleQR(account.id); }} 
                    className={`p-2 rounded-lg transition ${qrActiveBg}`}
                    title="QR Code"
                >
                    <QrCode size={18} className="pointer-events-none" />
                 </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onEdit(account); }} 
                    className={`p-2 text-gray-400 ${hoverText} ${hoverBg} rounded-lg transition`}
                    title={t.edit}
                >
                    <Edit2 size={18} className="pointer-events-none" />
                </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(account.id); }} 
                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
                    title={t.delete}
                >
                    <Trash2 size={18} className="pointer-events-none" />
                </button>
            </div>
         </div>

         {/* Progress Bar */}
         <div className="relative h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${progressBarColor}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
      </div>
    </div>
  );
};

