// Theme Helper
const getTheme = (color: 'blue' | 'orange' | 'emerald') => {
    switch(color) {
        case 'emerald':
             return {
                btn: 'bg-emerald-600 hover:bg-emerald-700',
                text: 'text-emerald-600',
                border: 'border-emerald-500',
                ring: 'ring-emerald-500',
                bgLight: 'bg-emerald-50',
                checkbox: 'text-emerald-600 focus:ring-emerald-500',
            };
        case 'orange':
            return {
                btn: 'bg-orange-600 hover:bg-orange-700',
                text: 'text-orange-600',
                border: 'border-orange-500',
                ring: 'ring-orange-500',
                bgLight: 'bg-orange-50',
                checkbox: 'text-orange-600 focus:ring-orange-500',
            };
        case 'blue':
        default:
            return {
                btn: 'bg-blue-600 hover:bg-blue-700',
                text: 'text-blue-600',
                border: 'border-blue-500',
                ring: 'ring-blue-500',
                bgLight: 'bg-blue-50',
                checkbox: 'text-blue-600 focus:ring-blue-500',
            };
    }
};


// --- Base Modal ---
const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode; className?: string }> = ({ title, onClose, children, className="" }) => (
  <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200 ${className}`}>
    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-xl max-h-[90vh] overflow-hidden flex flex-col">
      <div className="flex justify-between items-center p-5 border-b sticky top-0 bg-white z-10 shrink-0">
