               {/* Account */}
              <div className="flex gap-2 items-end">
                  <div className="flex-1">
                      <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2 cursor-pointer w-fit">
                          <input type="checkbox" checked={updateAccount} onChange={e => setUpdateAccount(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                          {t.labelAccount}
