// --- Batch Import Modal ---
interface BatchImportModalProps {
  onClose: () => void;
  onPreview: (candidates: ImportCandidate[]) => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files);
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            const parsed = parseLine(qrData);
            if (parsed.isValid) {
                 candidates.push(parsed);
            } else {
                 candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500">{t.textPaste} <span className="font-mono bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</span></p>
                <textarea 
                    className={`w-full h-40 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-sm`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\nGitHub, bob, KZSVS43UOJ62E3T3, 30\notpauth://totp/...`}
                />
                 <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-center font-mono`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                     <ImageIcon size={32} className="text-gray-400" />
                 </div>
                 <div>
                     <p className="text-gray-600 mb-4">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-6 py-3 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition`}>
                         <Upload size={18} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-xs text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

// --- Import Preview Drawer ---
interface ImportPreviewDrawerProps {
  isOpen: boolean;
  candidates: ImportCandidate[];
  onClose: () => void;
  onConfirm: (selected: ImportCandidate[]) => void;
  logos: AppLogo[];
  color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
    const [editedCandidates, setEditedCandidates] = useState<ImportCandidate[]>([]);

    useEffect(() => {
        if (isOpen) {
            setEditedCandidates([...candidates]);
            // Select valid ones by default
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    const handleConfirm = () => {
        const selected = editedCandidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(selected);
    };

    // Update individual candidate field
    const updateCandidate = (index: number, field: keyof ImportCandidate, value: any) => {
        const updated = [...editedCandidates];
        updated[index] = { ...updated[index], [field]: value };
        setEditedCandidates(updated);
    };

    return (
        <BottomDrawer isOpen={isOpen} onClose={onClose} title={`${t.headerImport} (${selectedIndices.size})`}>
            <div className="flex flex-col h-full max-h-[60vh]">
                 <div className="flex-1 overflow-y-auto mb-4 border rounded-lg">
                      <table className="w-full text-left border-collapse">
                          <thead className="bg-gray-50 text-xs text-gray-500 uppercase sticky top-0 z-10">
                              <tr>
                                  <th className="p-3 border-b w-10">
                                      <input 
                                        type="checkbox" 
                                        checked={selectedIndices.size === editedCandidates.length && editedCandidates.length > 0} 
                                        onChange={() => {
                                            if (selectedIndices.size === editedCandidates.length) setSelectedIndices(new Set());
                                            else setSelectedIndices(new Set(editedCandidates.map((_, i) => i)));
                                        }}
                                        className={`rounded ${theme.checkbox}`}
                                      />
                                  </th>
                                  <th className="p-3 border-b">{t.headerIssuer}</th>
                                  <th className="p-3 border-b">{t.headerAccount}</th>
                                  <th className="p-3 border-b hidden sm:table-cell">{t.headerSecret}</th>
                                  <th className="p-3 border-b w-24">Logo</th> 
                              </tr>
                          </thead>
                          <tbody className="text-sm divide-y divide-gray-100">
                              {editedCandidates.map((c, i) => (
                                  <tr key={i} className={!c.isValid ? 'bg-red-50' : 'hover:bg-gray-50'}>
                                      <td className="p-3">
                                          <input type="checkbox" checked={selectedIndices.has(i)} onChange={() => toggleSelect(i)} className={`rounded ${theme.checkbox}`} />
                                      </td>
                                      <td className="p-3">
                                          <input 
                                            type="text" 
                                            className="w-full bg-transparent border-b border-transparent focus:border-gray-300 outline-none" 
                                            value={c.issuer} 
                                            onChange={e => updateCandidate(i, 'issuer', e.target.value)}
                                            placeholder="Issuer"
                                          />
                                      </td>
                                      <td className="p-3">
                                          <input 
                                            type="text" 
                                            className="w-full bg-transparent border-b border-transparent focus:border-gray-300 outline-none" 
                                            value={c.account} 
                                            onChange={e => updateCandidate(i, 'account', e.target.value)}
                                            placeholder="Account"
                                          />
                                      </td>
                                      <td className="p-3 hidden sm:table-cell">
                                          <div className="font-mono text-xs text-gray-500 truncate max-w-[150px]" title={c.secret}>
                                              {c.secret || 'INVALID'}
                                          </div>
                                      </td>
                                      <td className="p-3">
                                          <div className="w-24">
                                            <LogoSelect logos={logos} value={c.logoId || ''} onChange={(val) => updateCandidate(i, 'logoId', val)} placeholder="-" />
                                          </div>
                                      </td>
                                  </tr>
                              ))}
                          </tbody>
                      </table>
                 </div>

                 <div className="flex justify-end gap-3 pt-4 border-t shrink-0 bg-white">
                      <button onClick={onClose} className="px-5 py-2 text-gray-600 hover:bg-gray-100 rounded-lg transition">{t.btnCancel}</button>
                      <button onClick={handleConfirm} disabled={selectedIndices.size === 0} className={`px-6 py-2 ${theme.btn} text-white rounded-lg font-medium disabled:opacity-50`}>
                          {t.btnImport}
                      </button>
                 </div>
            </div>
        </BottomDrawer>
    );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [format, setFormat] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(false);

  const getExportData = () => {
      if (format === 'csv') {
          // Format: Issuer, Account, Secret, Period, Notes, LogoId
          return accounts.map(a => {
              const parts = [a.issuer, a.account, a.secret, a.period, a.notes || ''];
              if (includeLogo) parts.push(a.logoId || '');
              return parts.join(',');
          }).join('\n');
      } else if (format === 'uri') {
          return accounts.map(a => {
               return `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
          }).join('\n');
      }
      return '';
  };

  const handleCopy = () => {
      navigator.clipboard.writeText(getExportData());
      alert(t.copied);
  };

  return (
    <Modal title={t.modalExportTitle} onClose={onClose} className="max-w-3xl">
         <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${format === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setFormat('csv')}
            >
              {t.tabCSV}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${format === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setFormat('uri')}
            >
              {t.tabURI}
            </button>
             <button 
              className={`pb-2 px-1 font-medium text-sm transition ${format === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setFormat('qr')}
            >
              {t.tabQR}
            </button>
        </div>

        <div className="mb-4">
             {format === 'csv' && <p className="text-sm text-gray-600 mb-2">{t.descCSV}</p>}
             {format === 'uri' && <p className="text-sm text-gray-600 mb-2">{t.descURI}</p>}
             {format === 'qr' && <p className="text-sm text-gray-600 mb-2">{t.descQR}</p>}

             {format === 'csv' && (
                 <label className="flex items-center gap-2 text-sm text-gray-700">
                     <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                     {t.labelIncludeLogo}
                 </label>
             )}
        </div>

        {format !== 'qr' ? (
            <>
                <textarea 
                    readOnly
                    className={`w-full h-64 p-3 bg-gray-50 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-xs`}
                    value={getExportData()}
                />
                <button onClick={handleCopy} className={`w-full mt-4 ${theme.btn} text-white py-2.5 rounded-lg font-medium flex items-center justify-center gap-2`}>
                    <Copy size={18} /> {t.btnCopy}
                </button>
            </>
        ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 gap-6 overflow-y-auto max-h-[60vh] p-2">
                 {accounts.map(a => {
                     const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                     return (
                         <div key={a.id} className="border rounded-lg p-4 flex flex-col items-center bg-white">
                             <QRCodeSVG value={uri} size={120} />
                             <p className="mt-3 font-bold text-sm text-center truncate w-full">{a.issuer}</p>
                             <p className="text-xs text-gray-500 text-center truncate w-full">{a.account}</p>
                         </div>
                     );
                 })}
            </div>
        )}
    </Modal>
  );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
    onClose: () => void;
    hasPassword: boolean;
    onSetPassword: (password: string) => void;
    onRemovePassword: (currentPassword: string) => Promise<boolean> | boolean;
    color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ onClose, hasPassword, onSetPassword, onRemovePassword, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [password, setPassword] = useState('');
    const [confirm, setConfirm] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        if (hasPassword) {
            // Remove Password Mode
            try {
                const success = await onRemovePassword(password);
                if (success) {
                    onClose();
                } else {
                    setError(t.wrongPassword);
                }
            } catch (err) {
                setError("Error occurred");
            }
        } else {
            // Set Password Mode
            if (password.length < 4) {
                setError("Password too short");
                setLoading(false);
                return;
            }
            if (password !== confirm) {
                setError(t.passwordsNoMatch);
                setLoading(false);
                return;
            }
            await onSetPassword(password);
            onClose();
        }
        setLoading(false);
    };

    return (
        <Modal title={t.securityTitle} onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="bg-yellow-50 p-3 rounded-lg flex gap-3 border border-yellow-200 text-yellow-800 text-sm">
                    <AlertTriangle className="shrink-0" size={20} />
                    <p>{hasPassword ? t.passwordRemoved : t.passwordSet}</p>
                </div>

                {hasPassword ? (
                    <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword}</label>
                         <input 
                            type="password" 
                            className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            autoFocus
                         />
                         <p className="text-xs text-gray-500 mt-2">Enter current password to disable protection.</p>
                    </div>
                ) : (
                    <>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.setPassword}</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={confirm}
                                onChange={e => setConfirm(e.target.value)}
                            />
                        </div>
                    </>
                )}

                {error && <p className="text-red-500 text-sm">{error}</p>}

                <button 
                    type="submit" 
                    disabled={!password || loading}
                    className={`w-full py-2.5 rounded-lg font-medium text-white ${hasPassword ? 'bg-red-500 hover:bg-red-600' : theme.btn} disabled:opacity-50`}
                >
                    {loading ? 'Processing...' : (hasPassword ? t.removePassword : t.setPassword)}
                </button>
            </form>
        </Modal>
    );
};


// --- Logo Manager Modal ---
interface LogoManagerModalProps {
    onClose: () => void;
    logos: AppLogo[];
    onAddLogo: (logo: AppLogo) => void;
    onDeleteLogo: (id: string) => void;
    onBatchDeleteLogo: (ids: string[]) => void;
    onImportLogos: (logos: AppLogo[]) => void;
    inline?: boolean;
    color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color='blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');

    // Selection State
    const [selectedLogoIds, setSelectedLogoIds] = useState<Set<string>>(new Set());

    // Add Logo State
    const [newLogoName, setNewLogoName] = useState('');
    const [newLogoUrl, setNewLogoUrl] = useState('');
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Import/Export State
    const [importText, setImportText] = useState('');
    const [dragActive, setDragActive] = useState(false);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                setNewLogoUrl(ev.target?.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleAddSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (newLogoName && newLogoUrl) {
            const newLogo: AppLogo = {
                id: generateShortId(), 
                name: newLogoName,
                data: newLogoUrl,
                isDefault: false
            };
            onAddLogo(newLogo);
            setNewLogoName('');
            setNewLogoUrl('');
            setTab('list');
        }
    };

    const processJsonImport = (jsonString: string) => {
         try {
            const parsed = JSON.parse(jsonString);
            if (Array.isArray(parsed)) {
                const validLogos = parsed.filter((l: any) => l.id && l.name && l.data);
                if (validLogos.length > 0) {
                    onImportLogos(validLogos);
                    setImportText('');
                } else {
                    alert("No valid logos found in JSON.");
                }
            }
        } catch (e) {
            alert("Invalid JSON format.");
        }
    }

    const handleImportSubmit = () => {
       processJsonImport(importText);
    };

    const handleExport = () => {
        // Export selected or all
        const subset = selectedLogoIds.size > 0 
            ? logos.filter(l => selectedLogoIds.has(l.id))
            : logos;

        const json = JSON.stringify(subset, null, 2);
        navigator.clipboard.writeText(json);
        alert(t.copied);
    };

    // Selection Logic
    const toggleSelection = (id: string) => {
        const next = new Set(selectedLogoIds);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        setSelectedLogoIds(next);
    };

    const handleSelectAll = () => {
        if (selectedLogoIds.size === logos.length) setSelectedLogoIds(new Set());
        else setSelectedLogoIds(new Set(logos.map(l => l.id)));
    };

    const handleBatchDelete = () => {
        if (selectedLogoIds.size === 0) return;
        if (confirm(`Delete ${selectedLogoIds.size} logos?`)) {
            onBatchDeleteLogo(Array.from(selectedLogoIds));
            setSelectedLogoIds(new Set());
        }
    };

    // Drag and Drop Logic
    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            const file = e.dataTransfer.files[0];
            if (file.type === "application/json" || file.name.endsWith('.json')) {
                const reader = new FileReader();
                reader.onload = (event) => {
                    const text = event.target?.result as string;
                    setImportText(text); // populate text area
                    processJsonImport(text); // auto-process
                };
                reader.readAsText(file);
            }
        }
    };

    const Content = (
        <div className="flex flex-col h-full relative">
            <div className="flex flex-col sm:flex-row gap-4 mb-4 border-b justify-between items-start sm:items-center shrink-0">
                <div className="flex gap-4">
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('list')}
                    >
                        {t.tabLogoList}
                    </button>
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('add')}
                    >
                        {t.tabAddLogo}
                    </button>
                    <button 
                    className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} 
                    onClick={() => setTab('import')}
                    >
                        {t.tabImportLogos}
                    </button>
                </div>

                {tab === 'list' && (
                     <div className="flex gap-2">
                        <button 
                            onClick={handleSelectAll}
                            className="flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded text-sm transition"
                        >
                            {selectedLogoIds.size === logos.length ? <CheckSquare size={16}/> : <Square size={16}/>}
                            <span className="hidden sm:inline">{selectedLogoIds.size === logos.length ? t.deselectAll : t.selectAll}</span>
                        </button>
                     </div>
                )}
            </div>

            {tab === 'list' && (
                <>
                <div className="flex-1 min-h-0 overflow-y-auto pb-16">
                    <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-4 p-1">
                        {logos.map(logo => {
                            const isSelected = selectedLogoIds.has(logo.id);
                            return (
                                <div 
                                    key={logo.id} 
                                    className={`relative flex flex-col items-center group border rounded-lg p-3 transition cursor-pointer bg-white ${isSelected ? `${theme.border} ${theme.bgLight} ${theme.ring}` : 'border-gray-200 hover:shadow-md'}`}
                                    onClick={() => toggleSelection(logo.id)}
                                >
                                    {/* Checkbox (Same style as AccountCard) */}
                                    <div className="absolute top-2 right-2 z-10">
                                         <input 
                                            type="checkbox" 
                                            checked={isSelected}
                                            onChange={() => toggleSelection(logo.id)}
                                            className={`w-4 h-4 rounded border-gray-300 cursor-pointer transition-opacity ${theme.checkbox} ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                                         />
                                    </div>

                                    {/* Uniform Image Container (Smaller) */}
                                    <div className="w-12 h-12 mb-2 flex items-center justify-center bg-white rounded-md overflow-hidden">
                                        <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                                    </div>
                                    <span className="text-[10px] text-center truncate w-full text-gray-600 font-medium" title={logo.name}>{logo.name}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Floating Bottom Action Bar for Logos */}
                {selectedLogoIds.size > 0 && (
                     <div className="absolute bottom-0 left-0 right-0 bg-white/95 border-t backdrop-blur-sm p-3 flex justify-between items-center shadow-lg rounded-b-lg z-20 animate-in slide-in-from-bottom duration-300">
                         <span className="text-sm font-semibold text-gray-700 ml-2">{selectedLogoIds.size} {t.selected}</span>
                         <div className="flex gap-2">
                             <button 
                                onClick={handleExport}
                                className="flex items-center gap-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded-lg text-sm transition"
                             >
                                <Download size={14} /> {t.exportSelected}
                             </button>
                             <button 
                                onClick={handleBatchDelete}
                                className="flex items-center gap-1.5 bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-sm transition"
                             >
                                <Trash2 size={14} /> {t.deleteSelected}
                             </button>
                         </div>
                     </div>
                )}
                </>
            )}

            {tab === 'add' && (
                <form onSubmit={handleAddSubmit} className="space-y-4 max-w-lg mx-auto w-full">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                        <input required type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                        <input required type="text" className={`w-full p-2 border rounded-md mb-2 focus:ring-2 ${theme.ring} outline-none`} value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://... or data:image..." />

                        <div className="flex gap-2 items-center">
                            <span className="text-sm text-gray-500">OR</span>
                            <button type="button" onClick={() => fileInputRef.current?.click()} className="text-sm bg-gray-100 px-3 py-1 rounded hover:bg-gray-200 flex items-center gap-1 transition">
                                <Upload size={14} /> {t.btnUploadLogo}
                            </button>
                            <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleImageUpload} />
                        </div>
                    </div>
                    {newLogoUrl && (
                        <div className="w-24 h-24 border rounded-lg mx-auto flex items-center justify-center p-2 bg-gray-50">
                             <img src={newLogoUrl} alt="Preview" className="max-w-full max-h-full object-contain" />
                        </div>
                    )}
                    <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium`}>
                        {t.btnAddLogo}
                    </button>
                </form>
            )}

            {tab === 'import' && (
                <div className="space-y-4 max-w-2xl mx-auto w-full">
                    <button onClick={handleExport} className="w-full bg-gray-100 text-gray-800 py-3 rounded-lg hover:bg-gray-200 border border-gray-300 font-medium flex items-center justify-center gap-2">
                         <Copy size={18} /> {t.btnExportLogos}
                    </button>

                    <div className="border-t pt-4">
                        <label className="block text-sm font-medium text-gray-700 mb-2">{t.textLogoImport}</label>

                        {/* Drop Zone */}
                        <div 
                            className={`relative border-2 border-dashed rounded-lg p-2 transition-colors ${dragActive ? `${theme.border} ${theme.bgLight}` : 'border-gray-300 bg-gray-50'}`}
                            onDragEnter={handleDrag}
                            onDragLeave={handleDrag}
                            onDragOver={handleDrag}
                            onDrop={handleDrop}
                        >
                            <textarea 
                                className="w-full h-40 p-3 bg-transparent border-none text-xs font-mono focus:ring-0 outline-none resize-none z-10 relative"
                                value={importText}
                                onChange={e => setImportText(e.target.value)}
                                placeholder='[{"id":"uuid","name":"My Logo","data":"..."}]'
                            />
                             {!importText && (
                                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 pointer-events-none">
                                    <FileJson className="w-8 h-8 mb-2" />
                                    <span className="text-xs">Drag & Drop JSON file here</span>
                                </div>
                             )}
                        </div>

                        <button onClick={handleImportSubmit} disabled={!importText} className={`w-full mt-2 ${theme.btn} text-white py-2.5 rounded-lg disabled:opacity-50 font-medium`}>
                            {t.btnImportLogos}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );

    if (inline) {
        return <div className="h-full">{Content}</div>;
    }

    return (
        <Modal title={t.modalLogoManagerTitle} onClose={onClose}>
            {Content}
        </Modal>
    );
};

