          <div className="flex-1 overflow-y-auto min-h-[300px]">
              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                          {logos.map(l => (
                              <div key={l.id} className="border rounded-lg p-2 relative group hover:shadow-md transition bg-white">
                                  <div className="aspect-square flex items-center justify-center bg-gray-50 rounded mb-2 overflow-hidden">
