// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
    onClose: () => void;
    hasPassword: boolean;
    onSetPassword: (password: string) => Promise<void>; // Set
    onRemovePassword: (currentPassword: string) => Promise<boolean> | boolean; // Remove
    onChangePassword?: (oldPassword: string, newPassword: string) => Promise<boolean>; // Change (Optional)
    isUnlock?: boolean; // NEW: Unlock mode for specific files
    color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, isUnlock = false, color = 'blue' 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);

    // Modes: 'set' (initial), 'menu' (if hasPassword), 'change', 'remove', 'unlock'
    const [mode, setMode] = useState<'set' | 'menu' | 'change' | 'remove' | 'unlock'>(() => {
        if (isUnlock) return 'unlock';
        return hasPassword ? 'menu' : 'set';
    });

    const [password, setPassword] = useState(''); // Used as "New Password" in change, or "Current Password" in remove/unlock
    const [oldPassword, setOldPassword] = useState(''); // Used as "Old Password" in change
    const [confirm, setConfirm] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    // If hasPassword changes (e.g. from parent prop), reset mode
    useEffect(() => {
        if (isUnlock) {
            setMode('unlock');
        } else {
            if (hasPassword && mode === 'set') setMode('menu');
            if (!hasPassword && mode !== 'set') setMode('set');
        }
    }, [hasPassword, isUnlock]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (mode === 'unlock') {
                // Reuse onSetPassword as the generic "success" callback for unlocking with password
                await onSetPassword(password);
                onClose();
            }
            else if (mode === 'remove') {
                const success = await onRemovePassword(password);
                if (success) {
                    onClose();
                } else {
                    setError(t.wrongPassword);
                }
            } 
            else if (mode === 'change') {
                if (password.length < 4) {
                    setError("New password too short");
                } else if (password !== confirm) {
                    setError(t.passwordsNoMatch);
                } else if (onChangePassword) {
                     const success = await onChangePassword(oldPassword, password);
                     if (success) {
                         onClose();
                     } else {
                         setError("Incorrect old password");
                     }
                } else {
                    setError("Change password not supported in this context");
                }
            }
            else if (mode === 'set') {
                if (password.length < 4) {
                    setError("Password too short");
                } else if (password !== confirm) {
                    setError(t.passwordsNoMatch);
                } else {
                    await onSetPassword(password);
                    onClose();
                }
            }
        } catch (err) {
            console.error(err);
            if (mode === 'unlock') {
                setError("Wrong Password");
            } else {
                setError("Error occurred");
            }
        }
        setLoading(false);
    };

    // Render Menu when locked
    if (mode === 'menu') {
        return (
             <Modal title={t.securityTitle} onClose={onClose}>
                 <div className="space-y-4 py-4">
                     <div className="bg-green-50 p-4 rounded-lg flex gap-3 border border-green-200 text-green-800 text-sm mb-6">
                        <CheckCircle size={20} className="shrink-0" />
                        <p>{t.passwordSet}</p>
                     </div>

                     <button 
                        onClick={() => { setMode('change'); setError(''); setPassword(''); setConfirm(''); setOldPassword(''); }}
                        className={`w-full flex items-center justify-between p-4 border rounded-xl hover:bg-gray-50 transition group`}
                     >
                         <div className="flex items-center gap-3">
                             <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                                 <RefreshCw size={20} />
                             </div>
                             <span className="font-medium text-gray-700">{t.changePassword}</span>
                         </div>
                         <ArrowRight size={18} className="text-gray-400 group-hover:text-gray-600" />
                     </button>

                     <button 
                        onClick={() => { setMode('remove'); setError(''); setPassword(''); }}
                        className={`w-full flex items-center justify-between p-4 border rounded-xl hover:bg-red-50 hover:border-red-100 transition group`}
                     >
                         <div className="flex items-center gap-3">
                             <div className="bg-red-100 p-2 rounded-lg text-red-600">
                                 <ShieldOff size={20} />
                             </div>
                             <span className="font-medium text-gray-700">{t.removePassword}</span>
                         </div>
                         <ArrowRight size={18} className="text-gray-400 group-hover:text-red-600" />
                     </button>
                 </div>
             </Modal>
        );
    }

    const getTitle = () => {
        if (mode === 'unlock') return t.unlockFile;
        if (mode === 'change') return t.changePassword;
        if (mode === 'remove') return t.removePassword;
        return t.securityTitle;
    }

    return (
        <Modal title={getTitle()} onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">

                {/* Mode: Unlock (Single Input) */}
                {mode === 'unlock' && (
                     <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterFilePassword}</label>
                         <input 
                            type="password" 
                            className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            autoFocus
                         />
                    </div>
                )}

                {/* Mode: Remove */}
                {mode === 'remove' && (
                    <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword} (Current)</label>
                         <input 
                            type="password" 
                            className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            autoFocus
                         />
                         <p className="text-xs text-gray-500 mt-2">Enter current password to verify identity and remove protection.</p>
                    </div>
                )}

                {/* Mode: Change */}
                {mode === 'change' && (
                    <>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword} (Old)</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={oldPassword}
                                onChange={e => setOldPassword(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div className="border-t pt-4 mt-2">
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.setPassword} (New)</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword} (New)</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={confirm}
                                onChange={e => setConfirm(e.target.value)}
                            />
                        </div>
                    </>
                )}

                {/* Mode: Set (Initial) */}
                {mode === 'set' && (
                    <>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.setPassword}</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={confirm}
                                onChange={e => setConfirm(e.target.value)}
                            />
                        </div>
                    </>
                )}

                {error && <p className="text-red-500 text-sm">{error}</p>}

                <div className="flex gap-3 mt-6">
                    {mode !== 'set' && mode !== 'unlock' && (
                        <button 
                            type="button" 
                            onClick={() => setMode('menu')}
                            className="px-4 py-2 text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-lg font-medium"
                        >
                            Back
                        </button>
                    )}
                    <button 
                        type="submit" 
                        disabled={(!password && mode !== 'remove' && mode !== 'change') || loading}
                        className={`flex-1 py-2.5 rounded-lg font-medium text-white ${mode === 'remove' ? 'bg-red-500 hover:bg-red-600' : theme.btn} disabled:opacity-50`}
                    >
                        {loading ? 'Processing...' : (mode === 'remove' ? t.removePassword : (mode === 'unlock' ? t.unlockFile : t.btnSave))}
                    </button>
                </div>
            </form>
        </Modal>
    );
};

