interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files);
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            const parsed = parseLine(qrData);
            if (parsed.isValid) {
                 candidates.push(parsed);
            } else {
                 candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500">{t.textPaste} <span className="font-mono bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</span></p>
                <textarea 
                    className={`w-full h-40 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-sm`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\nGitHub, bob, KZSVS43UOJ62E3T3, 30\notpauth://totp/...`}
                />
                 <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-center font-mono`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                     <ImageIcon size={32} className="text-gray-400" />
                 </div>
                 <div>
                     <p className="text-gray-600 mb-4">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-6 py-3 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition`}>
                         <Upload size={18} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-xs text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

interface ImportPreviewDrawerProps {
    isOpen: boolean;
    candidates: ImportCandidate[];
    onClose: () => void;
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
    const [editedCandidates, setEditedCandidates] = useState<ImportCandidate[]>([]);

    useEffect(() => {
        if (isOpen) {
            setEditedCandidates([...candidates]);
            // Select valid ones by default
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    const handleConfirm = () => {
        const selected = editedCandidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(selected);
    };

    // Update individual candidate field
    const updateCandidate = (index: number, field: keyof ImportCandidate, value: any) => {
        const updated = [...editedCandidates];
        updated[index] = { ...updated[index], [field]: value };
        setEditedCandidates(updated);
    };

    return (
        <BottomDrawer isOpen={isOpen} onClose={onClose} title={`${t.headerImport} (${selectedIndices.size})`}>
            <div className="flex flex-col h-full max-h-[60vh]">
                 <div className="flex-1 overflow-y-auto mb-4 border rounded-lg">
                      <table className="w-full text-left border-collapse">
                          <thead className="bg-gray-50 text-xs text-gray-500 uppercase sticky top-0 z-10">
                              <tr>
                                  <th className="p-3 border-b w-10">
                                      <input 
                                        type="checkbox" 
                                        checked={selectedIndices.size === editedCandidates.length && editedCandidates.length > 0} 
                                        onChange={() => {
                                            if (selectedIndices.size === editedCandidates.length) setSelectedIndices(new Set());
                                            else setSelectedIndices(new Set(editedCandidates.map((_, i) => i)));
                                        }}
                                        className={`rounded ${theme.checkbox}`}
                                      />
                                  </th>
                                  <th className="p-3 border-b">{t.headerIssuer}</th>
                                  <th className="p-3 border-b">{t.headerAccount}</th>
                                  <th className="p-3 border-b hidden sm:table-cell">{t.headerSecret}</th>
                                  <th className="p-3 border-b w-24">Logo</th> 
                              </tr>
                          </thead>
                          <tbody className="text-sm divide-y divide-gray-100">
                              {editedCandidates.map((c, i) => (
                                  <tr key={i} className={!c.isValid ? 'bg-red-50' : 'hover:bg-gray-50'}>
                                      <td className="p-3">
                                          <input type="checkbox" checked={selectedIndices.has(i)} onChange={() => toggleSelect(i)} className={`rounded ${theme.checkbox}`} />
                                      </td>
                                      <td className="p-3">
                                          <input 
                                            type="text" 
                                            className="w-full bg-transparent border-b border-transparent focus:border-gray-300 outline-none" 
                                            value={c.issuer} 
                                            onChange={e => updateCandidate(i, 'issuer', e.target.value)}
                                            placeholder="Issuer"
                                          />
                                      </td>
                                      <td className="p-3">
                                          <input 
                                            type="text" 
                                            className="w-full bg-transparent border-b border-transparent focus:border-gray-300 outline-none" 
                                            value={c.account} 
                                            onChange={e => updateCandidate(i, 'account', e.target.value)}
                                            placeholder="Account"
                                          />
                                      </td>
                                      <td className="p-3 hidden sm:table-cell">
                                          <div className="font-mono text-xs text-gray-500 truncate max-w-[150px]" title={c.secret}>
                                              {c.secret || 'INVALID'}
                                          </div>
                                      </td>
                                      <td className="p-3">
                                          <div className="w-24">
                                            <LogoSelect logos={logos} value={c.logoId || ''} onChange={(val) => updateCandidate(i, 'logoId', val)} placeholder="-" />
                                          </div>
                                      </td>
                                  </tr>
                              ))}
                          </tbody>
                      </table>
                 </div>

                 <div className="flex justify-end gap-3 pt-4 border-t shrink-0 bg-white">
                      <button onClick={onClose} className="px-5 py-2 text-gray-600 hover:bg-gray-100 rounded-lg transition">{t.btnCancel}</button>
                      <button onClick={handleConfirm} disabled={selectedIndices.size === 0} className={`px-6 py-2 ${theme.btn} text-white rounded-lg font-medium disabled:opacity-50`}>
                          {t.btnImport}
                      </button>
                 </div>
            </div>
        </BottomDrawer>
    );
};

interface BatchExportModalProps {
    accounts: OTPAccount[];
    onClose: () => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [format, setFormat] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(false);

  const getExportData = () => {
      if (format === 'csv') {
          // Format: Issuer, Account, Secret, Period, Notes, LogoId
          return accounts.map(a => {
              const parts = [a.issuer, a.account, a.secret, a.period, a.notes || ''];
              if (includeLogo) parts.push(a.logoId || '');
              return parts.join(',');
          }).join('\n');
      } else if (format === 'uri') {
          return accounts.map(a => {
               return `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
          }).join('\n');
      }
      return '';
  };

  const handleCopy = () => {
      navigator.clipboard.writeText(getExportData());
      alert(t.copied);
  };

  return (
    <Modal title={t.modalExportTitle} onClose={onClose} className="max-w-3xl">
         <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${format === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setFormat('csv')}
            >
              {t.tabCSV}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${format === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setFormat('uri')}
            >
              {t.tabURI}
            </button>
             <button 
              className={`pb-2 px-1 font-medium text-sm transition ${format === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setFormat('qr')}
            >
              {t.tabQR}
            </button>
        </div>

        <div className="mb-4">
             {format === 'csv' && <p className="text-sm text-gray-600 mb-2">{t.descCSV}</p>}
             {format === 'uri' && <p className="text-sm text-gray-600 mb-2">{t.descURI}</p>}
             {format === 'qr' && <p className="text-sm text-gray-600 mb-2">{t.descQR}</p>}

             {format === 'csv' && (
                 <label className="flex items-center gap-2 text-sm text-gray-700">
                     <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                     {t.labelIncludeLogo}
                 </label>
             )}
        </div>

        {format !== 'qr' ? (
            <>
                <textarea 
                    readOnly
                    className={`w-full h-64 p-3 bg-gray-50 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-xs`}
                    value={getExportData()}
                />
                <button onClick={handleCopy} className={`w-full mt-4 ${theme.btn} text-white py-2.5 rounded-lg font-medium flex items-center justify-center gap-2`}>
                    <Copy size={18} /> {t.btnCopy}
                </button>
            </>
        ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 gap-6 overflow-y-auto max-h-[60vh] p-2">
                 {accounts.map(a => {
                     const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                     return (
                         <div key={a.id} className="border rounded-lg p-4 flex flex-col items-center bg-white">
                             <QRCodeSVG value={uri} size={120} />
                             <p className="mt-3 font-bold text-sm text-center truncate w-full">{a.issuer}</p>
                             <p className="text-xs text-gray-500 text-center truncate w-full">{a.account}</p>
                         </div>
                     );
                 })}
            </div>
        )}
    </Modal>
  );
};

// --- Logo Manager Modal ---
interface LogoManagerModalProps {
  onClose: () => void;
  logos: AppLogo[];
  onAddLogo: (logo: AppLogo) => void;
  onDeleteLogo: (id: string) => void;
  onBatchDeleteLogo: (ids: string[]) => void;
  onImportLogos: (logos: AppLogo[]) => void;
  inline?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ 
    onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');
  const [newLogoName, setNewLogoName] = useState('');
  const [newLogoUrl, setNewLogoUrl] = useState('');
  const [importJson, setImportJson] = useState('');
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Reset selection when switching tabs
  useEffect(() => {
      setSelectedIds(new Set());
  }, [tab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setNewLogoUrl(ev.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAdd = () => {
      if (newLogoName && newLogoUrl) {
          onAddLogo({
              id: uuidv4(),
              name: newLogoName,
              data: newLogoUrl
          });
          setNewLogoName('');
          setNewLogoUrl('');
          setTab('list');
      }
  };

  const handleImport = () => {
      try {
          const parsed = JSON.parse(importJson);
          if (Array.isArray(parsed)) {
              onImportLogos(parsed);
              setImportJson('');
              setTab('list');
          }
      } catch (e) {
          alert("Invalid JSON");
      }
  };

  const handleExportSelected = () => {
      if (selectedIds.size === 0) return;
      const selectedLogos = logos.filter(l => selectedIds.has(l.id));
      const json = JSON.stringify(selectedLogos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos-selected.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Selected logos exported to file");
  };

  const handleExportAll = () => {
      const json = JSON.stringify(logos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Logos exported to file");
  };

  const handleDrop = (e: React.DragEvent<HTMLLabelElement>) => {
      e.preventDefault();
      const file = e.dataTransfer.files[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setImportJson(ev.target.result as string);
              }
          };
          reader.readAsText(file);
      }
  };

  const handleImportFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (ev.target?.result) {
                setImportJson(ev.target.result as string);
            }
        };
        reader.readAsText(file);
        e.target.value = ''; // Reset so same file can be selected again
    }
  };

  const toggleSelect = (id: string) => {
      const next = new Set(selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedIds(next);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === logos.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(logos.map(l => l.id)));
      }
  };

  const handleDeleteSelected = () => {
      if (confirm(`Delete ${selectedIds.size} selected logos?`)) {
          onBatchDeleteLogo(Array.from(selectedIds));
          setSelectedIds(new Set());
      }
  };

  const content = (
      <div className="h-full flex flex-col relative">
          <div className="flex gap-4 mb-4 border-b shrink-0 items-center justify-between">
            <div className="flex gap-4">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('list')}>
                  {t.tabLogoList}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('add')}>
                  {t.tabAddLogo}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('import')}>
                  {t.tabImportLogos}
                </button>
            </div>
            {tab === 'list' && logos.length > 0 && (
                 <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedIds.size === logos.length} onChange={toggleSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
          </div>

          <div className="flex-1 overflow-y-auto min-h-[300px] pb-16">
              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                          {logos.map(l => {
                              const isSelected = selectedIds.has(l.id);
                              return (
                                  <div 
                                    key={l.id} 
                                    onClick={() => toggleSelect(l.id)}
                                    className={`border rounded-lg p-4 relative group cursor-pointer transition flex flex-col items-center bg-white ${isSelected ? 'ring-2 ring-orange-400 border-orange-400' : 'hover:shadow-md'}`}
                                  >
                                      {/* Selection Checkbox (Top Right) */}
                                      <div className={`absolute top-2 right-2 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                           <div className={`w-5 h-5 rounded flex items-center justify-center ${isSelected ? 'bg-blue-600 text-white' : 'border border-gray-300 bg-white'}`}>
                                                {isSelected && <Check size={14} />}
                                           </div>
                                      </div>

                                      <div className="w-12 h-12 flex items-center justify-center mb-3">
                                          <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                      </div>
                                      <p className="text-xs text-center font-medium truncate w-full" title={l.name}>{l.name}</p>
                                  </div>
                              );
                          })}
                      </div>
                  </div>
              )}

              {tab === 'add' && (
                  <div className="space-y-4 max-w-md mx-auto py-4">
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                       </div>
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://..." />
                       </div>
                       <div className="text-center text-sm text-gray-500 py-2">- OR -</div>
                       <div>
                           <label className={`flex items-center justify-center gap-2 border-2 border-dashed border-gray-300 rounded-lg p-6 cursor-pointer hover:border-gray-400 hover:bg-gray-50 transition`}>
                               <Upload size={20} className="text-gray-400" />
                               <span className="text-gray-600">{t.btnUploadLogo}</span>
                               <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                           </label>
                       </div>
                       {newLogoUrl && (
                           <div className="mt-4 flex justify-center">
                               <img src={newLogoUrl} alt="Preview" className="h-20 object-contain border rounded p-1" />
                           </div>
                       )}
                       <button onClick={handleAdd} disabled={!newLogoName || !newLogoUrl} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4 disabled:opacity-50`}>
                           {t.btnAddLogo}
                       </button>
                  </div>
              )}

              {tab === 'import' && (
                  <div className="space-y-4">
                      <div className="flex gap-4">
                          <button onClick={handleExportAll} className="flex-1 border border-gray-300 hover:bg-gray-50 text-gray-700 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2">
                              <Download size={16} /> {t.btnExportLogos}
                          </button>
                      </div>

                      <label 
                          onDrop={handleDrop} 
                          onDragOver={e => e.preventDefault()}
                          className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center text-gray-500 hover:bg-gray-50 transition cursor-pointer block"
                      >
                          <FileJson className="mx-auto h-8 w-8 text-gray-400 mb-2" />
                          <p className="text-sm">Drag & Drop JSON file here</p>
                          <p className="text-xs text-gray-400 mt-1">or click to select file</p>
                          <input type="file" accept=".json,application/json" className="hidden" onChange={handleImportFileSelect} />
                      </label>

                      <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">{t.textLogoImport}</label>
                          <textarea 
                              className={`w-full h-40 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-xs font-mono`}
                              value={importJson}
                              onChange={e => setImportJson(e.target.value)}
                              placeholder='[{"id":"...", "name":"...", "data":"..."}]'
                          />
                      </div>
                      <button onClick={handleImport} disabled={!importJson} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2 disabled:opacity-50`}>
                           {t.btnImportLogos}
                       </button>
                  </div>
              )}
          </div>

          {/* Bottom Action Bar for Selection */}
          {selectedIds.size > 0 && tab === 'list' && (
              <div className="absolute bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-10 animate-in slide-in-from-bottom duration-300">
                   <div className="flex justify-between items-center gap-4">
                       <span className="font-semibold text-gray-700 ml-1">{selectedIds.size} {t.selected}</span>
                       <div className="flex gap-3">
                            <button onClick={handleExportSelected} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Download size={16} /> {t.exportSelected}
                            </button>
                            <button onClick={handleDeleteSelected} className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Trash2 size={16} /> {t.deleteSelected}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
    onClose: () => void;
    hasPassword: boolean;
    onSetPassword: (password: string) => Promise<void>; // Set
    onRemovePassword: (currentPassword: string) => Promise<boolean> | boolean; // Remove
    onChangePassword?: (oldPassword: string, newPassword: string) => Promise<boolean>; // Change (Optional)
    isUnlock?: boolean; // NEW: Unlock mode for specific files
    color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, isUnlock = false, color = 'blue' 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);

    // Modes: 'set' (initial), 'menu' (if hasPassword), 'change', 'remove', 'unlock'
    const [mode, setMode] = useState<'set' | 'menu' | 'change' | 'remove' | 'unlock'>(() => {
        if (isUnlock) return 'unlock';
        return hasPassword ? 'menu' : 'set';
    });

    const [password, setPassword] = useState(''); // Used as "New Password" in change, or "Current Password" in remove/unlock
    const [oldPassword, setOldPassword] = useState(''); // Used as "Old Password" in change
    const [confirm, setConfirm] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    // If hasPassword changes (e.g. from parent prop), reset mode
    useEffect(() => {
        if (isUnlock) {
            setMode('unlock');
        } else {
            if (hasPassword && mode === 'set') setMode('menu');
            if (!hasPassword && mode !== 'set') setMode('set');
        }
    }, [hasPassword, isUnlock]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (mode === 'unlock') {
                // Reuse onSetPassword as the generic "success" callback for unlocking with password
                await onSetPassword(password);
                onClose();
            }
            else if (mode === 'remove') {
                const success = await onRemovePassword(password);
                if (success) {
                    onClose();
                } else {
                    setError(t.wrongPassword);
                }
            } 
            else if (mode === 'change') {
                if (password.length < 4) {
                    setError("New password too short");
                } else if (password !== confirm) {
                    setError(t.passwordsNoMatch);
                } else if (onChangePassword) {
                     const success = await onChangePassword(oldPassword, password);
                     if (success) {
                         onClose();
                     } else {
                         setError("Incorrect old password");
                     }
                } else {
                    setError("Change password not supported in this context");
                }
            }
            else if (mode === 'set') {
                if (password.length < 4) {
                    setError("Password too short");
                } else if (password !== confirm) {
                    setError(t.passwordsNoMatch);
                } else {
                    await onSetPassword(password);
                    onClose();
                }
            }
        } catch (err) {
            console.error(err);
            if (mode === 'unlock') {
                setError("Wrong Password");
            } else {
                setError("Error occurred");
            }
        }
        setLoading(false);
    };

    // Render Menu when locked
    if (mode === 'menu') {
        return (
             <Modal title={t.securityTitle} onClose={onClose}>
                 <div className="space-y-4 py-4">
                     <div className="bg-green-50 p-4 rounded-lg flex gap-3 border border-green-200 text-green-800 text-sm mb-6">
                        <CheckCircle size={20} className="shrink-0" />
                        <p>{t.passwordSet}</p>
                     </div>

                     <button 
                        onClick={() => { setMode('change'); setError(''); setPassword(''); setConfirm(''); setOldPassword(''); }}
                        className={`w-full flex items-center justify-between p-4 border rounded-xl hover:bg-gray-50 transition group`}
                     >
                         <div className="flex items-center gap-3">
                             <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                                 <RefreshCw size={20} />
                             </div>
                             <span className="font-medium text-gray-700">{t.changePassword}</span>
                         </div>
                         <ArrowRight size={18} className="text-gray-400 group-hover:text-gray-600" />
                     </button>

                     <button 
                        onClick={() => { setMode('remove'); setError(''); setPassword(''); }}
                        className={`w-full flex items-center justify-between p-4 border rounded-xl hover:bg-red-50 hover:border-red-100 transition group`}
                     >
                         <div className="flex items-center gap-3">
                             <div className="bg-red-100 p-2 rounded-lg text-red-600">
                                 <ShieldOff size={20} />
                             </div>
                             <span className="font-medium text-gray-700">{t.removePassword}</span>
                         </div>
                         <ArrowRight size={18} className="text-gray-400 group-hover:text-red-600" />
                     </button>
                 </div>
             </Modal>
        );
    }

    const getTitle = () => {
        if (mode === 'unlock') return t.unlockFile;
        if (mode === 'change') return t.changePassword;
        if (mode === 'remove') return t.removePassword;
        return t.securityTitle;
    }

    return (
        <Modal title={getTitle()} onClose={onClose}>
            <form onSubmit={handleSubmit} className="space-y-4">

                {/* Mode: Unlock (Single Input) */}
                {mode === 'unlock' && (
                     <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterFilePassword}</label>
                         <input 
                            type="password" 
                            className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            autoFocus
                         />
                    </div>
                )}

                {/* Mode: Remove */}
                {mode === 'remove' && (
                    <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword} (Current)</label>
                         <input 
                            type="password" 
                            className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            autoFocus
                         />
                         <p className="text-xs text-gray-500 mt-2">Enter current password to verify identity and remove protection.</p>
                    </div>
                )}

                {/* Mode: Change */}
                {mode === 'change' && (
                    <>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword} (Old)</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={oldPassword}
                                onChange={e => setOldPassword(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div className="border-t pt-4 mt-2">
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.setPassword} (New)</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword} (New)</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={confirm}
                                onChange={e => setConfirm(e.target.value)}
                            />
                        </div>
                    </>
                )}

                {/* Mode: Set (Initial) */}
                {mode === 'set' && (
                    <>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.setPassword}</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                            <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={confirm}
                                onChange={e => setConfirm(e.target.value)}
                            />
                        </div>
                    </>
                )}

                {error && <p className="text-red-500 text-sm">{error}</p>}

                <div className="flex gap-3 mt-6">
                    {mode !== 'set' && mode !== 'unlock' && (
                        <button 
                            type="button" 
                            onClick={() => setMode('menu')}
                            className="px-4 py-2 text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-lg font-medium"
                        >
                            Back
                        </button>
                    )}
                    <button 
                        type="submit" 
                        disabled={(!password && mode !== 'remove' && mode !== 'change') || loading}
                        className={`flex-1 py-2.5 rounded-lg font-medium text-white ${mode === 'remove' ? 'bg-red-500 hover:bg-red-600' : theme.btn} disabled:opacity-50`}
                    >
                        {loading ? 'Processing...' : (mode === 'remove' ? t.removePassword : (mode === 'unlock' ? t.unlockFile : t.btnSave))}
                    </button>
                </div>
            </form>
        </Modal>
    );
};

