          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
      });
  };

  // Smart Toggle for Selection
  const handleToggleSelectedQR = () => {
      const selectedArray = Array.from(selectedIds);
      const allSelectedVisible = selectedArray.every(id => visibleQRIds.has(id));

      setVisibleQRIds(prev => {
          const next = new Set(prev);
          if (allSelectedVisible) {
              // Hide all selected
              selectedArray.forEach(id => next.delete(id));
          } else {
              // Show all selected
              selectedArray.forEach(id => next.add(id));
          }
          return next;
      });
  };

  const filteredAccounts = (function() {
    if (!searchQuery.trim()) return accounts;
    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);
    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      return keywords.every(kw => searchString.includes(kw));
    });
  })();

  const t = translations[lang];
  const theme = getThemeClasses();

  const selectedAreAllVisible = selectedIds.size > 0 && Array.from(selectedIds).every(id => visibleQRIds.has(id));

  // Helper for theme classes
  function getThemeClasses() {
     const common = {
         tabActive: 'bg-white shadow-sm'
     };
     if (activeTab === 'local') {
         return {
             ...common,
             primaryBg: 'bg-blue-600',
             primaryHover: 'hover:bg-blue-700',
             textGradient: 'from-blue-700 to-blue-500',
             focusRing: 'focus:ring-blue-500',
             checkboxText: 'text-blue-600',
             iconBg: 'bg-blue-600',
             tabActive: `${common.tabActive} text-blue-600`,
             lightBg: 'bg-blue-50',
             borderColor: 'border-blue-100'
         };
     } else if (activeTab === 'file') {
         return {
             ...common,
             primaryBg: 'bg-emerald-600',
             primaryHover: 'hover:bg-emerald-700',
             textGradient: 'from-emerald-700 to-emerald-500',
             focusRing: 'focus:ring-emerald-500',
             checkboxText: 'text-emerald-600',
             iconBg: 'bg-emerald-600',
             tabActive: `${common.tabActive} text-emerald-600`,
             lightBg: 'bg-emerald-50',
             borderColor: 'border-emerald-100'
         };
     } else {
         return {
             ...common,
             primaryBg: 'bg-orange-600',
             primaryHover: 'hover:bg-orange-700',
             textGradient: 'from-orange-700 to-orange-500',
             focusRing: 'focus:ring-orange-500',
             checkboxText: 'text-orange-600',
             iconBg: 'bg-orange-600',
             tabActive: `${common.tabActive} text-orange-600`,
             lightBg: 'bg-orange-50',
             borderColor: 'border-orange-100'
         };
     }
  }

  // --- Render ---

  if (isLocked) {
      return (
        <LanguageContext.Provider value={{ lang, t, setLang }}>
            <LockScreen onUnlock={handleUnlock} onReset={handleResetLock} />
        </LanguageContext.Provider>
      );
  }

  // Active File Reference
  const currentFile = openFiles.find(f => f.id === currentFileId);

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <ToastContainer toasts={toasts} onClose={removeToast} />
      {/* Hidden input for fallback file loading */}
      <input type="file" ref={fileInputRef} className="hidden" accept=".json,application/json" onChange={handleLegacyFileSelect} />

      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-40 sm:pb-24">

        {/* Navbar */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className={`${theme.iconBg} p-2 rounded-lg transition-colors duration-300`}>
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className={`text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r ${theme.textGradient} hidden md:block transition-all duration-300`}>
                  {t.appTitle}
                </h1>
              </div>

              <div className={`flex-1 transition-all duration-300 ${isSearchFocused ? 'max-w-full' : 'max-w-md mx-auto'}`}>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className={`h-5 w-5 text-gray-400 group-focus-within:${theme.checkboxText} transition-colors`} />
                    </div>
                    <input
                        type="text"
                        className={`block w-full pl-10 pr-10 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 ${theme.focusRing} focus:border-transparent transition-all sm:text-sm`}
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onFocus={() => setIsSearchFocused(true)}
                        onBlur={() => setIsSearchFocused(false)}
                    />
                    {searchQuery && (
                      <button 
                        onMouseDown={(e) => { e.preventDefault(); setSearchQuery(''); }}
