              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
                    <button 
                        onClick={() => setShowLogoManager(false)}
                        className="text-gray-500 hover:text-gray-700 font-medium text-sm flex items-center gap-1"
                    >
                        &larr; Back to Accounts
                    </button>
                    <h2 className="text-2xl font-bold text-gray-800 ml-2">{t.manageLogos}</h2>
                 </div>
                 <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6">
                     <LogoManagerModal 
                        onClose={() => setShowLogoManager(false)}
                        logos={customLogos}
                        onAddLogo={handleAddLogo}
                        onDeleteLogo={handleDeleteLogo}
                        onBatchDeleteLogo={handleBatchDeleteLogos}
                        onImportLogos={handleImportLogos}
                        inline={true} 
                        color={themeColor}
                    />
                 </div>
            </main>
        ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${theme.lightBg} ${theme.borderColor}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : (activeTab === 'file' ? <FolderOpen size={18} /> : <Zap size={18} />)}
             </div>
             <div className="text-sm">
               <p className="font-semibold text-gray-800">
                  {activeTab === 'local' ? t.bannerLocalTitle : (activeTab === 'file' ? t.bannerFileTitle : t.bannerSessionTitle)}
               </p>
               <p className="opacity-80 text-gray-600">
                 {activeTab === 'local' ? t.bannerLocalDesc : (activeTab === 'file' ? t.bannerFileDesc : t.bannerSessionDesc)}
               </p>
             </div>
          </div>

          {/* File Space Manager (Only for File Mode) */}
          {activeTab === 'file' && (
              <div className="mb-6 bg-white p-4 rounded-lg border shadow-sm space-y-4">
                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
                      <div className="flex gap-2 shrink-0">
                          <button onClick={handleOpenFile} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap">
                              <FolderOpen size={16} /> {t.btnOpenFile}
                          </button>
                          <button onClick={handleOpenFolder} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap">
                              <FolderOpen size={16} /> {t.btnOpenFolder}
                          </button>
                      </div>
                      <button onClick={handleCreateFile} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap">
                          <FilePlus size={16} /> {t.btnCreateFile}
                      </button>

                      <div className="h-px w-full sm:h-6 sm:w-px bg-gray-300 mx-0 sm:mx-2"></div>

                      <div className="flex gap-2 overflow-x-auto pb-1 sm:pb-0 w-full no-scrollbar">
                          {openFiles.length === 0 && <span className="text-sm text-gray-400 self-center italic">No files open</span>}
                          {openFiles.map(f => (
                              <button 
                                key={f.id}
                                onClick={() => handleSwitchFile(f.id)}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-md border text-sm whitespace-nowrap transition shrink-0 ${currentFileId === f.id ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                              >
                                  {f.isEncrypted ? <Lock size={12} className={f.password ? "text-green-500" : "text-gray-400"}/> : <FileJson size={12} className="opacity-50"/>}
                                  {f.displayName}
                                  {f.isVirtual && <AlertTriangle size={10} className="text-orange-400" />}
                              </button>
                          ))}
                      </div>
                  </div>

                  {/* Active File Actions */}
                  {currentFile && (
                      <div className="flex flex-col gap-3 pt-3 border-t border-gray-100">
                           <div className="flex flex-wrap items-center justify-between gap-2">
                               <div className="flex items-center gap-3">
                                    <span className="text-sm font-semibold text-gray-700 truncate max-w-[200px]">{currentFile.displayName}</span>
                                    <span className={`text-xs px-2 py-0.5 rounded-full border ${currentFile.isEncrypted ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-500 border-gray-200'}`}>
                                        {currentFile.isEncrypted ? t.fileEncrypted : t.filePlain}
                                    </span>
                                    {currentFile.isVirtual && (
                                        <span className="text-xs px-2 py-0.5 rounded-full border bg-orange-50 text-orange-700 border-orange-200 flex items-center gap-1">
                                            <AlertTriangle size={10} /> Read-Only
                                        </span>
                                    )}
                               </div>
                               <div className="flex gap-2">
                                    <button onClick={() => handleFileRename(currentFile.id)} className="p-1.5 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded" title={t.labelRenameFile}>
                                        <PenLine size={16} />
                                    </button>
                                    <button onClick={() => handleCloseFile(currentFile.id)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded" title={t.btnCloseFile}>
                                        <XCircle size={16} />
                                    </button>
                               </div>
                           </div>

                           {/* Warning banner for Virtual Files */}
                           {currentFile.isVirtual && (
                               <div className="flex items-start gap-2 text-xs text-orange-700 bg-orange-50 p-2 rounded border border-orange-100">
                                   <AlertTriangle size={14} className="mt-0.5 shrink-0" />
                                   <p>{t.virtualFileWarning}</p>
                               </div>
                           )}

                           {/* Manual Save Button for Virtual Files */}
                           {currentFile.isVirtual && (
                               <button 
                                 onClick={() => saveToFile(currentFile, accounts)}
                                 className="self-start flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition shadow-sm"
                               >
                                   <Download size={16} /> {t.btnDownloadManual}
                               </button>
                           )}
                      </div>
                  )}
              </div>
          )}

          <div className="flex flex-col xl:flex-row gap-4 mb-8 justify-between items-start xl:items-center">
             <div className="flex flex-wrap gap-3 w-full sm:w-auto flex-nowrap overflow-x-auto pb-1 sm:pb-0">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    disabled={activeTab === 'file' && (!currentFileId || (currentFile?.isEncrypted && !currentFile?.password))}
                    className={`flex items-center gap-2 ${theme.primaryBg} ${theme.primaryHover} text-white px-4 py-2.5 rounded-lg shadow-sm hover:shadow transition font-medium whitespace-nowrap disabled:opacity-50 disabled:cursor-not-allowed`}
                    title={t.addAccount}
                >
                    <Plus size={18} /> <span className="hidden sm:inline">{t.addAccount}</span>
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    disabled={activeTab === 'file' && (!currentFileId || (currentFile?.isEncrypted && !currentFile?.password))}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap disabled:opacity-50"
                    title={t.importBatch}
                >
                    <Upload size={18} /> <span className="hidden sm:inline">{t.importBatch}</span>
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium disabled:opacity-50 whitespace-nowrap"
                    title={t.exportBatch}
                >
                    <Download size={18} /> <span className="hidden sm:inline">{t.exportBatch}</span>
                </button>
                <button 
                    onClick={() => setShowLogoManager(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap"
                    title={t.manageLogos}
                >
                    <ImageIcon size={18} /> <span className="hidden sm:inline">{t.manageLogos}</span>
                </button>

                 {filteredAccounts.length > 0 && (
                    <button 
                       onClick={handleSelectAll}
                       className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap ml-auto sm:ml-0"
                       title={selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                    >
                       {selectedIds.size === filteredAccounts.length ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                 )}
             </div>
          </div>

          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
              <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    logo={customLogos.find(l => l.id === acc.logoId)}
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                    showQR={visibleQRIds.has(acc.id)}
                    onToggleQR={handleToggleQR}
                    color={themeColor}
                />
              ))}
            </div>
          )}
        </main>
        )}

        {selectedIds.size > 0 && !showLogoManager && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4 px-0 sm:px-4">
                    <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                        <span className="font-semibold text-gray-700">
                            {selectedIds.size} {t.selected}
                        </span>
                    </div>

                    <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                        <button 
                           onClick={() => setShowBatchEditModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Edit2 size={16} /> {t.btnBatchEdit}
                        </button>
                        <button 
                           onClick={() => setShowExportModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Download size={16} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleToggleSelectedQR}
                           className={`flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg transition text-sm font-medium ${selectedAreAllVisible ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
                        >
                            <QrCode size={16} /> {selectedAreAllVisible ? t.hideQR : t.showQR}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Trash2 size={16} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
                logos={customLogos}
                color={themeColor}
            />
        )}
        {showBatchEditModal && (
          <BatchEditModal 
             onClose={() => setShowBatchEditModal(false)}
             onSave={handleBatchSave}
             logos={customLogos}
             color={themeColor}
          />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview}
            color={themeColor} 
          />
        )}

        {/* App Security Modal */}
        {showPasswordModal && (
            <PasswordSettingsModal 
                onClose={() => setShowPasswordModal(false)}
                hasPassword={activeTab === 'file' ? (currentFile?.isEncrypted || false) : hasPassword}
                onSetPassword={activeTab === 'file' ? handleSetFilePassword : handleSetPassword}
                onRemovePassword={activeTab === 'file' ? handleRemoveFilePassword : handleRemovePassword}
                onChangePassword={activeTab === 'file' ? handleChangeFilePassword : handleChangePassword}
                color={themeColor}
            />
        )}

        {/* File Unlock Modal (For Pending Files) */}
        {showFileUnlockModal && pendingFile && (
             <PasswordSettingsModal 
                onClose={handleCancelUnlock}
                hasPassword={false} // Mode: Unlock (Similar to set but verify against file)
                isUnlock={true} // Force Unlock Mode
                onSetPassword={handleUnlockFile} // Reusing setPassword prop for unlock submission
                onRemovePassword={() => true}
                color={themeColor}
             />
        )}

        <ImportPreviewDrawer
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
           logos={customLogos}
           color={themeColor}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
                color={themeColor}
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

export default App;

