// Theme Helper
const getTheme = (color: string = 'blue') => {
    switch(color) {
        case 'emerald':
             return {
                btn: 'bg-emerald-600 hover:bg-emerald-700',
                text: 'text-emerald-600',
                border: 'border-emerald-500',
                ring: 'ring-emerald-500',
                bgLight: 'bg-emerald-50',
                checkbox: 'text-emerald-600 focus:ring-emerald-500',
                selectionBorder: 'border-emerald-500',
                selectionRing: 'ring-emerald-500',
                checkBg: 'bg-emerald-600'
            };
        case 'orange':
            return {
                btn: 'bg-orange-600 hover:bg-orange-700',
                text: 'text-orange-600',
                border: 'border-orange-500',
                ring: 'ring-orange-500',
                bgLight: 'bg-orange-50',
                checkbox: 'text-orange-600 focus:ring-orange-500',
                selectionBorder: 'border-orange-500',
                selectionRing: 'ring-orange-500',
                checkBg: 'bg-orange-600'
            };
        case 'blue':
        default:
            return {
                btn: 'bg-blue-600 hover:bg-blue-700',
                text: 'text-blue-600',
                border: 'border-blue-500',
                ring: 'ring-blue-500',
                bgLight: 'bg-blue-50',
                checkbox: 'text-blue-600 focus:ring-blue-500',
                selectionBorder: 'border-blue-500',
                selectionRing: 'ring-blue-500',
                checkBg: 'bg-blue-600'
            };
    }
};


// --- Base Modal ---
