  <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200 ${className}`}>
    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-xl max-h-[90vh] overflow-hidden flex flex-col">
      <div className="flex justify-between items-center p-5 border-b sticky top-0 bg-white z-10 shrink-0">
        <h2 className="text-xl font-bold text-gray-800">{title}</h2>
