  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [mode, setMode] = useState<'manual' | 'scan'>(initialData ? 'manual' : 'manual');
  const [formData, setFormData] = useState({
    issuer: '',
    account: '',
    secret: '',
    period: 30,
    notes: '',
    logoId: ''
  });

  useEffect(() => {
    if (initialData) {
        setFormData({
            issuer: initialData.issuer,
            account: initialData.account,
            secret: initialData.secret,
            period: initialData.period,
            notes: initialData.notes || '',
            logoId: initialData.logoId || ''
        });
    }
  }, [initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.issuer && formData.account && formData.secret) {
      onSave(formData);
      onClose();
    }
  };

  const handleScan = (data: string) => {
    if (data.startsWith('otpauth://')) {
        const parsed = parseOTPAuthURL(data);
        if (parsed) {
             onSave({
                issuer: parsed.issuer || 'Unknown',
                account: parsed.account || 'Unknown',
                secret: parsed.secret || '',
                period: parsed.period || 30,
                notes: 'Scanned via QR',
                logoId: ''
             });
             onClose();
             return;
        }
    }
    alert('Invalid QR Code or format not supported yet. (Must be otpauth URI)');
  };

  const generateSecret = () => {
    setFormData(prev => ({ ...prev, secret: generateRandomSecret() }));
  };

  return (
    <Modal title={initialData ? t.modalEditTitle : t.modalAddTitle} onClose={onClose}>
      {!initialData && (
          <div className="flex gap-4 mb-6 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${mode === 'manual' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setMode('manual')}
            >
              {t.tabManual}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${mode === 'scan' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setMode('scan')}
            >
              {t.tabScan}
            </button>
          </div>
      )}

      {mode === 'manual' ? (
        // Added pb-40 to allow scrolling space for the absolute dropdown at the bottom
        <form onSubmit={handleSubmit} className="space-y-4 pb-40">
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelIssuer}</label>
                <input required type="text" placeholder="e.g. Google" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.issuer} onChange={e => setFormData({...formData, issuer: e.target.value})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelAccount}</label>
                <input required type="text" placeholder="e.g. alice@example.com" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.account} onChange={e => setFormData({...formData, account: e.target.value})} />
             </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSecret}</label>
            <div className="flex gap-2">
                <input required type="text" placeholder="Base32 Secret" className={`flex-1 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono`} 
                value={formData.secret} onChange={e => setFormData({...formData, secret: e.target.value})} />
                <button type="button" onClick={generateSecret} className="px-3 py-2 bg-gray-100 text-gray-600 rounded-md hover:bg-gray-200" title={t.btnGenerate}>
                    <RefreshCw size={18} />
                </button>
            </div>
            {!initialData && <p className="text-xs text-gray-500 mt-1">{t.msgLeaveBlank}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelPeriod}</label>
                <input type="number" min="15" step="1" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.period} onChange={e => setFormData({...formData, period: parseInt(e.target.value) || 30})} />
             </div>
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelNotes}</label>
                <input type="text" placeholder="Tag or description" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
             </div>
          </div>

          <div className="relative">
              <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogo}</label>
              <LogoSelect 
                 logos={logos}
                 value={formData.logoId}
                 onChange={(val) => setFormData({...formData, logoId: val})}
              />
          </div>

          <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4`}>
            {t.btnSave}
          </button>
        </form>
      ) : (
        <QRCodeScanner onScan={handleScan} onClose={onClose} />
      )}
    </Modal>
  );
};

