        {selectedIds.size > 0 && !showLogoManager && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4 px-0 sm:px-4">
                    <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                        <span className="font-semibold text-gray-700">
                            {selectedIds.size} {t.selected}
                        </span>
                    </div>

                    <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                        <button 
                           onClick={() => setShowBatchEditModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Edit2 size={16} /> {t.btnBatchEdit}
                        </button>
                        <button 
                           onClick={() => setShowExportModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Download size={16} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleToggleSelectedQR}
                           className={`flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg transition text-sm font-medium ${selectedAreAllVisible ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
                        >
                            <QrCode size={16} /> {selectedAreAllVisible ? t.hideQR : t.showQR}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Trash2 size={16} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
                logos={customLogos}
                color={themeColor}
            />
        )}
        {showBatchEditModal && (
          <BatchEditModal 
             onClose={() => setShowBatchEditModal(false)}
             onSave={handleBatchSave}
             logos={customLogos}
             color={themeColor}
          />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview}
            color={themeColor} 
          />
        )}

        {/* App Security Modal */}
        {showPasswordModal && (
            <PasswordSettingsModal 
                onClose={() => setShowPasswordModal(false)}
                hasPassword={activeTab === 'file' ? (currentFile?.isEncrypted || false) : hasPassword}
                onSetPassword={activeTab === 'file' ? handleSetFilePassword : handleSetPassword}
                onRemovePassword={activeTab === 'file' ? handleRemoveFilePassword : handleRemovePassword}
                onChangePassword={activeTab === 'file' ? handleChangeFilePassword : handleChangePassword}
                color={themeColor}
            />
        )}

        {/* File Unlock Modal (For Pending Files) */}
        {showFileUnlockModal && pendingFile && (
             <PasswordSettingsModal 
                onClose={handleCancelUnlock}
                hasPassword={false} // Mode: Unlock (Similar to set but verify against file)
                isUnlock={true} // Force Unlock Mode
                onSetPassword={handleUnlockFile} // Reusing setPassword prop for unlock submission
                onRemovePassword={async () => true}
                color={themeColor}
             />
        )}

        <ImportPreviewDrawer
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
           logos={customLogos}
           color={themeColor}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
                color={themeColor}
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

