               {/* Logo */}
              <div className="flex gap-2 items-end">
                  <div className="flex-1">
                      <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2 cursor-pointer w-fit">
                          <input type="checkbox" checked={updateLogo} onChange={e => setUpdateLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                          {t.labelLogo}
                      </label>
                      <div className={!updateLogo ? 'opacity-50 pointer-events-none' : ''}>
                        <LogoSelect 
                            logos={logos}
                            value={logoId}
                            onChange={(val) => setLogoId(val)}
                            placeholder={!updateLogo ? "(No Change)" : "Select Logo"}
                        />
                      </div>
                  </div>
              </div>

             <button onClick={handleSave} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4`}>
                {t.btnSave}
             </button>
          </div>
      </Modal>
  )
};

interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            const parsed = parseLine(qrData);
            if (parsed.isValid) {
                 candidates.push(parsed);
            } else {
                 candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500">{t.textPaste} <span className="font-mono bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</span></p>
                <textarea 
                    className={`w-full h-40 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-sm`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\nGitHub, bob, KZSVS43UOJ62E3T3, 30\notpauth://totp/...`}
                />
                 <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-center font-mono`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                     <ImageIcon size={32} className="text-gray-400" />
                 </div>
                 <div>
                     <p className="text-gray-600 mb-4">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-6 py-3 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition`}>
                         <Upload size={18} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-xs text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

// --- Logo Manager Modal ---
interface LogoManagerModalProps {
  onClose: () => void;
  logos: AppLogo[];
  onAddLogo: (logo: AppLogo) => void;
  onDeleteLogo: (id: string) => void;
  onBatchDeleteLogo: (ids: string[]) => void;
  onImportLogos: (logos: AppLogo[]) => void;
  inline?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ 
    onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');
  const [newLogoName, setNewLogoName] = useState('');
  const [newLogoUrl, setNewLogoUrl] = useState('');
  const [importJson, setImportJson] = useState('');
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Reset selection when switching tabs
  useEffect(() => {
      setSelectedIds(new Set());
  }, [tab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setNewLogoUrl(ev.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAdd = () => {
      if (newLogoName && newLogoUrl) {
          onAddLogo({
              id: uuidv4(),
              name: newLogoName,
              data: newLogoUrl
          });
          setNewLogoName('');
          setNewLogoUrl('');
          setTab('list');
      }
  };

  const handleImport = () => {
      try {
          const parsed = JSON.parse(importJson);
          if (Array.isArray(parsed)) {
              onImportLogos(parsed);
              setImportJson('');
              setTab('list');
          }
      } catch (e) {
          alert("Invalid JSON");
      }
  };

  const handleExportSelected = () => {
      if (selectedIds.size === 0) return;
      const selectedLogos = logos.filter(l => selectedIds.has(l.id));
      const json = JSON.stringify(selectedLogos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos-selected.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Selected logos exported to file");
  };

  const handleExportAll = () => {
      const json = JSON.stringify(logos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Logos exported to file");
  };

  const handleDrop = (e: React.DragEvent<HTMLLabelElement>) => {
      e.preventDefault();
      const file = e.dataTransfer.files[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setImportJson(ev.target.result as string);
              }
          };
          reader.readAsText(file);
      }
  };

  const handleImportFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (ev.target?.result) {
                setImportJson(ev.target.result as string);
            }
        };
        reader.readAsText(file);
        e.target.value = ''; // Reset so same file can be selected again
    }
  };

  const toggleSelect = (id: string) => {
      const next = new Set(selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedIds(next);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === logos.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(logos.map(l => l.id)));
      }
  };

  const handleDeleteSelected = () => {
      if (confirm(`Delete ${selectedIds.size} selected logos?`)) {
          onBatchDeleteLogo(Array.from(selectedIds));
          setSelectedIds(new Set());
      }
  };

  const content = (
      <div className={`flex flex-col relative ${inline ? '' : 'h-full'}`}>
          <div className="flex gap-4 mb-4 border-b shrink-0 items-center justify-between">
            <div className="flex gap-4">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('list')}>
                  {t.tabLogoList}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('add')}>
                  {t.tabAddLogo}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('import')}>
                  {t.tabImportLogos}
                </button>
            </div>
            {tab === 'list' && logos.length > 0 && (
                 <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedIds.size === logos.length} onChange={toggleSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
          </div>

          <div className={`${inline ? '' : 'flex-1 overflow-y-auto min-h-[300px]'} ${selectedIds.size > 0 ? 'pb-24' : 'pb-4'}`}>
              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                          {logos.map(l => {
                              const isSelected = selectedIds.has(l.id);
                              return (
                                  <div 
                                    key={l.id} 
                                    onClick={() => toggleSelect(l.id)}
                                    // Use theme.selectionRing and theme.selectionBorder for active state
                                    className={`border rounded-lg p-4 relative group cursor-pointer transition flex flex-col items-center bg-white ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                  >
                                      {/* Selection Checkbox (Top Right) */}
                                      <div className={`absolute top-2 right-2 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                           {/* Use theme.checkBg */}
                                           <div className={`w-5 h-5 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 bg-white'}`}>
                                                {isSelected && <Check size={14} />}
                                           </div>
                                      </div>

                                      <div className="w-12 h-12 flex items-center justify-center mb-3">
                                          <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                      </div>
                                      <p className="text-xs text-center font-medium truncate w-full" title={l.name}>{l.name}</p>
                                  </div>
                              );
                          })}
                      </div>
                  </div>
              )}

              {tab === 'add' && (
                  <div className="space-y-4 max-w-md mx-auto py-4">
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                       </div>
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://..." />
                       </div>
                       <div className="text-center text-sm text-gray-500 py-2">- OR -</div>
                       <div>
                           <label className={`flex items-center justify-center gap-2 border-2 border-dashed border-gray-300 rounded-lg p-6 cursor-pointer hover:border-gray-400 hover:bg-gray-50 transition`}>
                               <Upload size={20} className="text-gray-400" />
                               <span className="text-gray-600">{t.btnUploadLogo}</span>
                               <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                           </label>
                       </div>
                       {newLogoUrl && (
                           <div className="mt-4 flex justify-center">
                               <img src={newLogoUrl} alt="Preview" className="h-20 object-contain border rounded p-1" />
                           </div>
                       )}
                       <button onClick={handleAdd} disabled={!newLogoName || !newLogoUrl} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4 disabled:opacity-50`}>
                           {t.btnAddLogo}
                       </button>
                  </div>
              )}

              {tab === 'import' && (
                  <div className="space-y-4">
                      <div className="flex gap-4">
                          <button onClick={handleExportAll} className="flex-1 border border-gray-300 hover:bg-gray-50 text-gray-700 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2">
                              <Download size={16} /> {t.btnExportLogos}
                          </button>
                      </div>

                      <label 
                          onDrop={handleDrop} 
                          onDragOver={e => e.preventDefault()}
                          className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center text-gray-500 hover:bg-gray-50 transition cursor-pointer block"
                      >
                          <FileJson className="mx-auto h-8 w-8 text-gray-400 mb-2" />
                          <p className="text-sm">Drag & Drop JSON file here</p>
                          <p className="text-xs text-gray-400 mt-1">or click to select file</p>
                          <input type="file" accept=".json,application/json" className="hidden" onChange={handleImportFileSelect} />
                      </label>

                      <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">{t.textLogoImport}</label>
                          <textarea 
                              className={`w-full h-40 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-xs font-mono`}
                              value={importJson}
                              onChange={e => setImportJson(e.target.value)}
                              placeholder='[{"id":"...", "name":"...", "data":"..."}]'
                          />
                      </div>
                      <button onClick={handleImport} disabled={!importJson} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2 disabled:opacity-50`}>
                           {t.btnImportLogos}
                       </button>
                  </div>
              )}
          </div>

          {/* Bottom Action Bar for Selection */}
          {selectedIds.size > 0 && tab === 'list' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4 px-0 sm:px-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedIds.size} {t.selected}</span>
                       </div>
                       <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                            <button onClick={handleExportSelected} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Download size={16} /> {t.exportSelected}
                            </button>
                            <button onClick={handleDeleteSelected} className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Trash2 size={16} /> {t.deleteSelected}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
  onClose: () => void;
  hasPassword: boolean;
  onSetPassword: (password: string) => Promise<void | boolean>;
  onRemovePassword: (password: string) => Promise<boolean>;
  onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
  isUnlock?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, isUnlock = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'set' | 'remove' | 'change'>(isUnlock ? 'set' : (hasPassword ? 'change' : 'set'));
  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [oldPass, setOldPass] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');

      try {
          if (isUnlock) {
              await onSetPassword(pass1);
              onClose();
              return;
          }

          if (tab === 'set') {
              if (pass1 !== pass2) {
                  setError(t.passwordsNoMatch);
                  return;
              }
              await onSetPassword(pass1);
              onClose();
          } else if (tab === 'remove') {
              const success = await onRemovePassword(pass1);
              if (success) onClose();
              else setError(t.wrongPassword);
          } else if (tab === 'change') {
              if (pass1 !== pass2) {
                  setError(t.passwordsNoMatch);
                  return;
              }
              if (onChangePassword) {
                  const success = await onChangePassword(oldPass, pass1);
                  if (success) onClose();
                  else setError(t.wrongPassword);
              }
          }
      } catch (err) {
          setError(t.wrongPassword);
      }
  };

  return (
      <Modal title={isUnlock ? t.unlockFile : (hasPassword ? t.securityTitle : t.setPassword)} onClose={onClose}>
          <div className="space-y-4">
               {/* Tabs */}
               {!isUnlock && hasPassword && (
                    <div className="flex gap-4 mb-4 border-b">
                        <button 
                            className={`pb-2 px-1 font-medium text-sm transition ${tab === 'change' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
                            onClick={() => { setTab('change'); setError(''); setPass1(''); setPass2(''); setOldPass(''); }}
                        >
                            {t.changePassword}
                        </button>
                        <button 
                            className={`pb-2 px-1 font-medium text-sm transition ${tab === 'remove' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
                            onClick={() => { setTab('remove'); setError(''); setPass1(''); }}
                        >
                            {t.removePassword}
                        </button>
                    </div>
               )}

               <form onSubmit={handleSubmit} className="space-y-4">
                    {/* Old Password Field (for Change and Remove) */}
                    {(tab === 'remove' || tab === 'change') && (
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                {tab === 'remove' ? t.enterPassword : "Old Password"}
                            </label>
                            <div className="relative">
                                <Lock size={16} className="absolute left-3 top-3 text-gray-400" />
                                <input 
                                    type="password" 
                                    required 
                                    className={`w-full pl-9 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                    value={tab === 'remove' ? pass1 : oldPass}
                                    onChange={e => tab === 'remove' ? setPass1(e.target.value) : setOldPass(e.target.value)}
                                />
                            </div>
                        </div>
                    )}

                    {/* New Password Fields (Set, Change, Unlock) */}
                    {(tab === 'set' || tab === 'change') && (
                        <>
                             <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    {isUnlock ? t.enterPassword : (tab === 'change' ? "New Password" : t.setPassword)}
                                </label>
                                <div className="relative">
                                    <Lock size={16} className="absolute left-3 top-3 text-gray-400" />
                                    <input 
                                        type="password" 
                                        required 
                                        className={`w-full pl-9 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                        value={pass1}
                                        onChange={e => setPass1(e.target.value)}
                                    />
                                </div>
                             </div>

                             {!isUnlock && (
                                 <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                                    <div className="relative">
                                        <Check size={16} className="absolute left-3 top-3 text-gray-400" />
                                        <input 
                                            type="password" 
                                            required 
                                            className={`w-full pl-9 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                            value={pass2}
                                            onChange={e => setPass2(e.target.value)}
                                        />
                                    </div>
                                 </div>
                             )}
                        </>
                    )}

                    {error && (
                        <div className="bg-red-50 text-red-600 text-sm p-3 rounded flex items-center gap-2">
                             <AlertTriangle size={16} />
                             {error}
                        </div>
                    )}

                    <div className="flex gap-3 pt-2">
                        <button type="button" onClick={onClose} className="flex-1 px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition">
                            {t.btnCancel}
                        </button>
                        <button type="submit" className={`flex-1 ${theme.btn} text-white px-4 py-2 rounded-lg font-medium shadow-sm`}>
                            {isUnlock ? t.unlock : (tab === 'remove' ? t.removePassword : t.btnSave)}
                        </button>
                    </div>
               </form>
          </div>
      </Modal>
  );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(true);

  const getCSV = () => {
    return accounts.map(a => 
      `${a.issuer},${a.account},${a.secret},${a.period},${a.notes || ''},${includeLogo ? (a.logoId || '') : ''}`
    ).join('\n');
  };

  const getURIs = () => {
    return accounts.map(a => 
      `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`
    ).join('\n');
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert(t.copied);
  };

  return (
    <Modal title={t.modalExportTitle} onClose={onClose} className="max-w-4xl">
       <div className="flex gap-4 mb-4 border-b">
          <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('csv')}>{t.tabCSV}</button>
          <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('uri')}>{t.tabURI}</button>
          <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('qr')}>{t.tabQR}</button>
       </div>

       <div className="min-h-[300px] flex flex-col">
          {tab === 'csv' && (
             <>
                <p className="text-sm text-gray-500 mb-2">{t.descCSV}</p>
                <div className="mb-2">
                     <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                         <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                         {t.labelIncludeLogo}
                     </label>
                </div>
                <textarea 
                    readOnly 
                    className={`flex-1 w-full p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-xs mb-4`}
                    value={getCSV()}
                />
                <button onClick={() => copyToClipboard(getCSV())} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium`}>
                    {t.btnCopy}
                </button>
             </>
          )}

          {tab === 'uri' && (
              <>
                 <p className="text-sm text-gray-500 mb-2">{t.descURI}</p>
                 <textarea 
                     readOnly 
                     className={`flex-1 w-full p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-xs mb-4`}
                     value={getURIs()}
                 />
                 <button onClick={() => copyToClipboard(getURIs())} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium`}>
                     {t.btnCopy}
                 </button>
              </>
          )}

          {tab === 'qr' && (
               <div className="flex-1 overflow-y-auto">
                   <p className="text-sm text-gray-500 mb-4">{t.descQR}</p>
                   <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 p-2">
                       {accounts.map(acc => (
                           <div key={acc.id} className="flex flex-col items-center border rounded-lg p-3 bg-gray-50 text-center">
                               <div className="bg-white p-2 rounded shadow-sm mb-2">
                                  <QRCodeSVG 
                                     value={`otpauth://totp/${encodeURIComponent(acc.issuer)}:${encodeURIComponent(acc.account)}?secret=${acc.secret}&issuer=${encodeURIComponent(acc.issuer)}&period=${acc.period}`}
                                     size={100}
                                  />
                               </div>
                               <div className="w-full">
                                   <p className="font-bold text-xs truncate" title={acc.issuer}>{acc.issuer}</p>
                                   <p className="text-xs text-gray-500 truncate" title={acc.account}>{acc.account}</p>
                               </div>
                           </div>
                       ))}
                   </div>
               </div>
          )}
       </div>
    </Modal>
  );
};

// --- Import Preview Drawer ---
interface ImportPreviewDrawerProps {
  isOpen: boolean;
  candidates: ImportCandidate[];
  onClose: () => void;
  onConfirm: (selected: ImportCandidate[]) => void;
  logos: AppLogo[];
  color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

  // Initialize selection when candidates change
  useEffect(() => {
     if (candidates.length > 0) {
         // Select all valid by default
         const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
         setSelectedIndices(new Set(validIndices));
     }
  }, [candidates]);

  const toggleSelect = (index: number) => {
      const next = new Set(selectedIndices);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      setSelectedIndices(next);
  };

  const handleImport = () => {
      const selected = candidates.filter((_, i) => selectedIndices.has(i));
      onConfirm(selected);
  };

  return (
    <BottomDrawer isOpen={isOpen} onClose={onClose} title={`${t.headerImport} (${candidates.length})`}>
        <div className="flex flex-col h-full max-h-[70vh]">
             <div className="overflow-y-auto flex-1 -mx-2 px-2">
                 <table className="w-full text-left text-sm border-collapse">
                     <thead className="bg-gray-50 sticky top-0 z-10 text-xs font-semibold text-gray-500 uppercase">
                         <tr>
                             <th className="p-2 w-10">
                                 <input 
                                     type="checkbox" 
                                     checked={selectedIndices.size === candidates.filter(c=>c.isValid).length && candidates.some(c=>c.isValid)}
                                     onChange={(e) => {
                                         if (e.target.checked) setSelectedIndices(new Set(candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1)));
                                         else setSelectedIndices(new Set());
                                     }}
                                     className={`rounded ${theme.checkbox}`}
                                 />
                             </th>
                             <th className="p-2">{t.headerIssuer}</th>
                             <th className="p-2">{t.headerAccount}</th>
                             <th className="p-2 hidden sm:table-cell">{t.headerSecret}</th>
                             <th className="p-2 w-20">{t.headerPeriod}</th>
                             <th className="p-2 w-10">Logo</th>
                         </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-100">
                         {candidates.map((c, i) => {
                             const isSelected = selectedIndices.has(i);
                             const logo = logos.find(l => l.id === c.logoId);
                             return (
                                 <tr key={i} className={`hover:bg-gray-50 ${!c.isValid ? 'bg-red-50' : ''}`} onClick={() => c.isValid && toggleSelect(i)}>
                                     <td className="p-2" onClick={e => e.stopPropagation()}>
                                         <input 
                                             type="checkbox" 
                                             checked={isSelected}
                                             disabled={!c.isValid}
                                             onChange={() => toggleSelect(i)}
                                             className={`rounded ${theme.checkbox} disabled:opacity-50`}
                                         />
                                     </td>
                                     <td className="p-2 font-medium">
                                         {c.issuer || (c.isValid ? '-' : <span className="text-red-500 text-xs">Invalid</span>)}
                                     </td>
                                     <td className="p-2 text-gray-600 truncate max-w-[150px]">{c.account}</td>
                                     <td className="p-2 font-mono text-xs text-gray-400 hidden sm:table-cell truncate max-w-[150px]">
                                         {c.secret}
                                     </td>
                                     <td className="p-2 text-gray-500">{c.period}</td>
                                     <td className="p-2">
                                         {logo ? <img src={logo.data} className="w-6 h-6 object-contain" /> : (c.logoId ? '?' : '')}
                                     </td>
                                 </tr>
                             );
                         })}
                     </tbody>
                 </table>
             </div>

             <div className="pt-4 mt-4 border-t flex justify-end gap-3 sticky bottom-0 bg-white">
                 <button onClick={onClose} className="px-4 py-2 border rounded-lg text-gray-600 hover:bg-gray-50 font-medium">
                     {t.btnCancel}
                 </button>
                 <button 
                     onClick={handleImport} 
                     disabled={selectedIndices.size === 0}
                     className={`${theme.btn} text-white px-6 py-2 rounded-lg font-medium shadow-sm disabled:opacity-50`}
                 >
                     {t.btnImport} ({selectedIndices.size})
                 </button>
             </div>
        </div>
    </BottomDrawer>
  );
};

