                                              </div>
                                              <p className="text-xs text-center font-medium truncate w-full">{l.name}</p>
                                          </div>
                                      );
                                  })}
                              </div>
                          </div>
                      )}
                  </div>
              )}
          </div>

          {/* Bottom Action Bar for List Selection */}
          {selectedIds.size > 0 && tab === 'list' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300 rounded-t-xl sm:rounded-none">
                   <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4 px-0 sm:px-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedIds.size} {t.selected}</span>
                       </div>
                       <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                            <button onClick={handleExportSelected} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Download size={16} /> {t.exportSelected}
                            </button>
                            <button onClick={handleDeleteSelected} className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Trash2 size={16} /> {t.deleteSelected}
                            </button>
                       </div>
                   </div>
              </div>
          )}

          {/* Bottom Action Bar for Import Selection */}
          {importCandidates.length > 0 && tab === 'import' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300 rounded-t-xl sm:rounded-none">
                   <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4 px-0 sm:px-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedImportIds.size} {t.selected}</span>
                       </div>
                       <div className="flex gap-2 w-full sm:w-auto">
                            <button onClick={handleClearImport} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 {t.btnCancel}
                            </button>
                            <button onClick={handleConfirmImport} disabled={selectedImportIds.size === 0} className={`flex-[2] sm:flex-none flex items-center justify-center gap-2 ${theme.btn} text-white px-6 py-2.5 rounded-lg transition text-sm font-medium disabled:opacity-50`}>
                                 <Download size={16} /> {t.btnImportLogos}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
  onClose: () => void;
  hasPassword: boolean;
  onSetPassword: (password: string) => Promise<void | boolean>;
  onRemovePassword: (password: string) => Promise<boolean>;
  onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
  isUnlock?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, isUnlock = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'set' | 'remove' | 'change'>(isUnlock ? 'set' : (hasPassword ? 'change' : 'set'));
  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [oldPass, setOldPass] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');

      try {
          if (isUnlock) {
              await onSetPassword(pass1);
              onClose();
              return;
          }

          if (tab === 'set') {
              if (pass1 !== pass2) {
                  setError(t.passwordsNoMatch);
                  return;
              }
              await onSetPassword(pass1);
              onClose();
          } else if (tab === 'remove') {
              const success = await onRemovePassword(pass1);
              if (success) onClose();
              else setError(t.wrongPassword);
          } else if (tab === 'change') {
              if (pass1 !== pass2) {
                  setError(t.passwordsNoMatch);
                  return;
              }
              if (onChangePassword) {
                  const success = await onChangePassword(oldPass, pass1);
                  if (success) onClose();
                  else setError(t.wrongPassword);
              }
          }
      } catch (err) {
          setError(t.wrongPassword);
      }
  };

  return (
      <Modal title={isUnlock ? t.unlockFile : (hasPassword ? t.securityTitle : t.setPassword)} onClose={onClose}>
          <div className="space-y-4">
               {/* Tabs */}
               {!isUnlock && hasPassword && (
                    <div className="flex gap-4 mb-4 border-b">
                        <button 
                            className={`pb-2 px-1 font-medium text-sm transition ${tab === 'change' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
                            onClick={() => { setTab('change'); setError(''); setPass1(''); setPass2(''); setOldPass(''); }}
                        >
                            {t.changePassword}
                        </button>
                        <button 
                            className={`pb-2 px-1 font-medium text-sm transition ${tab === 'remove' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
                            onClick={() => { setTab('remove'); setError(''); setPass1(''); }}
                        >
                            {t.removePassword}
                        </button>
                    </div>
               )}

               <form onSubmit={handleSubmit} className="space-y-4">
                    {/* Old Password Field (for Change and Remove) */}
                    {(tab === 'remove' || tab === 'change') && (
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                {tab === 'remove' ? t.enterPassword : "Old Password"}
                            </label>
                            <div className="relative">
                                <Lock size={16} className="absolute left-3 top-3 text-gray-400" />
                                <input 
                                    type="password" 
                                    required 
                                    className={`w-full pl-9 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                    value={tab === 'remove' ? pass1 : oldPass}
                                    onChange={e => tab === 'remove' ? setPass1(e.target.value) : setOldPass(e.target.value)}
                                />
                            </div>
                        </div>
                    )}

                    {/* New Password Fields (Set, Change, Unlock) */}
                    {(tab === 'set' || tab === 'change') && (
                        <>
                             <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    {isUnlock ? t.enterPassword : (tab === 'change' ? "New Password" : t.setPassword)}
                                </label>
                                <div className="relative">
                                    <Lock size={16} className="absolute left-3 top-3 text-gray-400" />
                                    <input 
                                        type="password" 
                                        required 
                                        className={`w-full pl-9 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                        value={pass1}
                                        onChange={e => setPass1(e.target.value)}
                                    />
                                </div>
                             </div>

                             {!isUnlock && (
                                 <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                                    <div className="relative">
                                        <Check size={16} className="absolute left-3 top-3 text-gray-400" />
                                        <input 
                                            type="password" 
                                            required 
                                            className={`w-full pl-9 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                            value={pass2}
                                            onChange={e => setPass2(e.target.value)}
                                        />
                                    </div>
                                 </div>
                             )}
                        </>
                    )}

                    {error && (
                        <div className="bg-red-50 text-red-600 text-sm p-3 rounded flex items-center gap-2">
                             <AlertTriangle size={16} />
                             {error}
                        </div>
                    )}

                    <div className="flex gap-3 pt-2">
                        <button type="button" onClick={onClose} className="flex-1 px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition">
                            {t.btnCancel}
                        </button>
                        <button type="submit" className={`flex-1 ${theme.btn} text-white px-4 py-2 rounded-lg font-medium shadow-sm`}>
                            {isUnlock ? t.unlock : (tab === 'remove' ? t.removePassword : t.btnSave)}
                        </button>
                    </div>
               </form>
          </div>
      </Modal>
  );
};

// --- Import Preview Drawer ---
interface ImportPreviewDrawerProps {
  isOpen: boolean;
  candidates: ImportCandidate[];
  onClose: () => void;
  onConfirm: (candidates: ImportCandidate[]) => void;
  logos: AppLogo[];
  color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewDrawer: React.FC<ImportPreviewDrawerProps> = ({ 
    isOpen, candidates, onClose, onConfirm, logos, color = 'blue' 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

    useEffect(() => {
        if (isOpen && candidates.length > 0) {
            // Select all valid candidates by default
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        const toImport = candidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(toImport);
    };

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    return (
        <div className="fixed inset-0 z-[60] flex justify-center items-end sm:items-end pointer-events-none">
             <div className="absolute inset-0 bg-black/50 backdrop-blur-sm pointer-events-auto transition-opacity" onClick={onClose} />
             <div className="pointer-events-auto relative w-full max-w-2xl bg-white rounded-t-2xl shadow-2xl max-h-[90vh] flex flex-col animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-center pt-3 pb-1 shrink-0" onClick={onClose}>
                     <div className="w-12 h-1.5 bg-gray-300 rounded-full cursor-pointer hover:bg-gray-400 transition" />
                </div>
                <div className="flex justify-between items-center px-6 py-4 border-b shrink-0">
                    <div>
                        <h2 className="text-xl font-bold text-gray-800">{t.headerImport}</h2>
                        <p className="text-sm text-gray-500">{selectedIndices.size} / {candidates.length} selected</p>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition text-gray-600">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-0 overflow-y-auto flex-1 bg-gray-50">
                    {candidates.map((c, i) => {
                         const logo = c.logoId ? logos.find(l => l.id === c.logoId) : null;
                         return (
                            <div key={i} className={`flex items-start gap-3 p-4 border-b bg-white ${!c.isValid ? 'opacity-50' : ''}`} onClick={() => c.isValid && toggleSelect(i)}>
                                <div className="pt-1">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedIndices.has(i)} 
                                        onChange={() => {}} 
                                        disabled={!c.isValid}
                                        className={`w-5 h-5 rounded border-gray-300 ${theme.checkbox}`}
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between">
                                        <div className="flex items-center gap-2">
                                           {logo && <img src={logo.data} alt="logo" className="w-5 h-5 object-contain" />}
                                           <h4 className="font-bold text-gray-900 truncate">{c.issuer || 'Unknown'}</h4>
                                        </div>
                                        <span className="text-xs text-gray-400 font-mono shrink-0">{c.period}s</span>
                                    </div>
                                    <p className="text-sm text-gray-600 truncate">{c.account}</p>
                                    <p className="text-xs text-gray-400 font-mono truncate mt-1" title={c.secret}>
                                        {c.secret ? c.secret.substring(0, 4) + '...' + c.secret.substring(c.secret.length-4) : 'NO SECRET'}
                                    </p>
                                    {!c.isValid && <p className="text-xs text-red-500 mt-1">Invalid Format</p>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="p-4 border-t bg-white shrink-0 safe-area-bottom">
                     <button 
                        onClick={handleConfirm}
                        disabled={selectedIndices.size === 0}
                        className={`w-full ${theme.btn} text-white py-3 rounded-xl font-bold text-lg shadow-lg disabled:opacity-50`}
                     >
                        {t.btnImport} ({selectedIndices.size})
                     </button>
                </div>
             </div>
        </div>
    )
}

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [tab, setTab] = useState<'csv' | 'uri' | 'qr'>('csv');
    const [includeLogo, setIncludeLogo] = useState(true);

    const getCSV = () => {
        return accounts.map(a => `${a.issuer}, ${a.account}, ${a.secret}, ${a.period}, ${a.notes || ''}, ${includeLogo ? (a.logoId || '') : ''}`).join('\n');
    };

    const getURIs = () => {
         return accounts.map(a => `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`).join('\n');
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        alert(t.copied);
    };

    return (
        <Modal title={t.modalExportTitle} onClose={onClose}>
             <div className="flex gap-4 mb-4 border-b">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('csv')}>{t.tabCSV}</button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('uri')}>{t.tabURI}</button>
