const LogoSelect: React.FC<LogoSelectProps> = ({ logos, value, onChange, placeholder = "Select Logo", className = "", color = 'blue' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");

  const selectedLogo = logos.find(l => l.id === value);
  const filteredLogos = logos.filter(l => l.name.toLowerCase().includes(search.toLowerCase()));

  // Theme styles
  const getThemeColor = () => {
      switch(color) {
          case 'emerald': return 'text-emerald-600 bg-emerald-50 border-emerald-200 ring-emerald-500';
          case 'orange': return 'text-orange-600 bg-orange-50 border-orange-200 ring-orange-500';
          default: return 'text-blue-600 bg-blue-50 border-blue-200 ring-blue-500';
      }
  };
  const activeClass = getThemeColor();

  return (
    <>
      {/* Trigger Button */}
      <div className={`relative ${className}`}>
        <button
          type="button"
          onClick={() => setIsOpen(true)}
          className="w-full flex items-center justify-between border border-gray-300 rounded-lg p-2.5 bg-white text-left focus:ring-2 focus:ring-opacity-50 outline-none transition hover:border-gray-400"
          style={{ borderColor: isOpen ? 'transparent' : '' }}
        >
          {selectedLogo ? (
              <div className="flex items-center gap-3">
                  <div className="w-6 h-6 shrink-0 bg-gray-50 border rounded p-0.5 flex items-center justify-center">
