                  </div>
                  <span className="truncate font-medium text-gray-700">{selectedLogo.name}</span>
              </div>
          ) : (
              <span className="text-gray-500">{placeholder}</span>
          )}
          <ChevronDown size={18} className="text-gray-400" />
        </button>
      </div>

      {/* Drawer Portal (Fixed Overlay) */}
      {isOpen && (
        <div className="fixed inset-0 z-[70] flex justify-center items-end sm:items-end">
          {/* Backdrop */}
          <div 
            className="absolute inset-0 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200"
            onClick={() => setIsOpen(false)}
          />

          {/* Drawer Content */}
          <div className="relative w-full max-w-xl bg-white rounded-t-2xl shadow-2xl max-h-[70vh] flex flex-col animate-in slide-in-from-bottom duration-300">
            {/* Handle */}
            <div className="flex justify-center pt-3 pb-1 shrink-0 cursor-pointer" onClick={() => setIsOpen(false)}>
                <div className="w-12 h-1.5 bg-gray-300 rounded-full hover:bg-gray-400 transition" />
            </div>

            {/* Header with Search */}
            <div className="p-4 border-b shrink-0 flex gap-3 items-center">
                <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-3 text-gray-400" />
                    <input
                        type="text"
                        className={`w-full pl-9 pr-4 py-2.5 bg-gray-100 border-transparent focus:bg-white border focus:ring-2 rounded-lg text-sm outline-none transition ${color === 'orange' ? 'focus:border-orange-500 focus:ring-orange-200' : (color === 'emerald' ? 'focus:border-emerald-500 focus:ring-emerald-200' : 'focus:border-blue-500 focus:ring-blue-200')}`}
                        placeholder="Search logos..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        autoFocus
                    />
                </div>
                <button onClick={() => setIsOpen(false)} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 text-gray-600">
