               <div 
                  className={`flex items-center justify-between p-3 cursor-pointer rounded-lg transition ${!value ? activeClass : 'hover:bg-gray-50 text-gray-600'}`}
                  onClick={() => { onChange(""); setIsOpen(false); }}
               >
                  <span className="font-medium">No Logo (Default)</span>
                  {!value && <Check size={18} />}
               </div>

               {filteredLogos.map(logo => (
                   <div
                      key={logo.id}
                      className={`flex items-center justify-between p-3 cursor-pointer rounded-lg transition ${value === logo.id ? activeClass : 'hover:bg-gray-50 text-gray-700'}`}
                      onClick={() => { onChange(logo.id); setIsOpen(false); }}
