               {filteredLogos.length === 0 && (
                   <div className="p-8 text-center text-gray-400 flex flex-col items-center">
                       <Search size={32} className="mb-2 opacity-20" />
                       <p className="text-sm">No logos found</p>
                   </div>
               )}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default LogoSelect;

