interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            const parsed = parseLine(qrData);
            if (parsed.isValid) {
                 candidates.push(parsed);
            } else {
                 candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500">{t.textPaste} <span className="font-mono bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</span></p>
                <textarea 
                    className={`w-full h-40 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-sm`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\nGitHub, bob, KZSVS43UOJ62E3T3, 30\notpauth://totp/...`}
                />
                 <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-center font-mono`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                     <ImageIcon size={32} className="text-gray-400" />
                 </div>
                 <div>
                     <p className="text-gray-600 mb-4">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-6 py-3 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition`}>
                         <Upload size={18} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-xs text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

// --- Import Preview Drawer (Bottom Up) ---
interface ImportPreviewModalProps {
    isOpen: boolean;
    candidates: ImportCandidate[];
    onClose: () => void;
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewModal: React.FC<ImportPreviewModalProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

    useEffect(() => {
        if (isOpen && candidates.length > 0) {
            // Select all valid candidates by default
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        const toImport = candidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(toImport);
    };

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    return (
        <div className="fixed inset-0 z-[60] flex justify-center items-end sm:items-end">
             <div className="absolute inset-0 bg-black/50 backdrop-blur-sm transition-opacity" onClick={onClose} />
             <div className="relative w-full max-w-2xl bg-white rounded-t-2xl shadow-2xl max-h-[90vh] flex flex-col animate-in slide-in-from-bottom duration-300">

                {/* Drag Handle / Close */}
                <div className="flex justify-center pt-3 pb-1 shrink-0 cursor-pointer" onClick={onClose}>
                     <div className="w-12 h-1.5 bg-gray-300 rounded-full hover:bg-gray-400 transition" />
                </div>

                <div className="flex justify-between items-center px-6 py-4 border-b shrink-0">
                    <div>
                        <h2 className="text-xl font-bold text-gray-800">{t.headerImport} ({candidates.length})</h2>
                        <p className="text-sm text-gray-500">{selectedIndices.size} selected</p>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition text-gray-600">
                        <X size={20} />
                    </button>
                </div>

                <div className="overflow-y-auto flex-1 bg-gray-50">
                    {candidates.map((c, i) => {
                         const logo = c.logoId ? logos.find(l => l.id === c.logoId) : null;
                         const period = c.period || 30; // Default to 30s visually
                         return (
                            <div key={i} className={`flex items-start gap-4 p-4 border-b bg-white ${!c.isValid ? 'opacity-50' : 'hover:bg-gray-50 cursor-pointer'}`} onClick={() => c.isValid && toggleSelect(i)}>
                                <div className="pt-1 shrink-0">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedIndices.has(i)} 
                                        onChange={() => {}} 
                                        disabled={!c.isValid}
                                        className={`w-5 h-5 rounded border-gray-300 ${theme.checkbox}`}
                                    />
                                </div>

                                <div className="flex-1 min-w-0 flex flex-col gap-1">
                                    <div className="flex items-center gap-2">
                                        {logo ? (
                                            <div className="w-5 h-5 flex items-center justify-center shrink-0">
                                                <img src={logo.data} alt="logo" className="w-full h-full object-contain" />
                                            </div>
                                        ) : (
                                            <div className="w-5 h-5 rounded-md bg-gray-100 flex items-center justify-center text-xs font-bold text-gray-500 shrink-0">
                                                {(c.issuer || '?').charAt(0).toUpperCase()}
                                            </div>
                                        )}
                                        <span className="font-bold text-gray-900 truncate text-sm">{c.issuer || 'Unknown'}</span>
                                    </div>
                                    <div className="text-xs text-gray-600 truncate">{c.account || 'Unknown Account'}</div>
                                    {c.notes && (
                                        <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-gray-100 text-gray-600 w-fit">
                                            {c.notes}
                                        </span>
                                    )}
                                </div>

                                <div className="text-right shrink-0 flex flex-col items-end gap-1">
                                    <span className="text-xs font-mono bg-gray-100 px-2 py-0.5 rounded text-gray-600">
                                        {period}s
                                    </span>
                                    <span className="text-[10px] text-gray-400 font-mono truncate max-w-[80px]" title={c.secret}>
                                        {c.secret ? '***' + c.secret.slice(-4) : 'NO KEY'}
                                    </span>
                                    {!c.isValid && <span className="text-[10px] text-red-500 font-medium">Invalid</span>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="p-4 border-t bg-white shrink-0 safe-area-bottom">
                     <button 
                        onClick={handleConfirm}
                        disabled={selectedIndices.size === 0}
                        className={`w-full ${theme.btn} text-white py-3 rounded-xl font-bold text-lg shadow-lg disabled:opacity-50`}
                     >
                        {t.btnImport} ({selectedIndices.size})
                     </button>
                </div>
             </div>
        </div>
    )
}

// --- Logo Manager Modal ---
interface LogoManagerModalProps {
  onClose: () => void;
  logos: AppLogo[];
  onAddLogo: (logo: AppLogo) => void;
  onDeleteLogo: (id: string) => void;
  onBatchDeleteLogo: (ids: string[]) => void;
  onImportLogos: (logos: AppLogo[]) => void;
  inline?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ 
    onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');
  const [newLogoName, setNewLogoName] = useState('');
  const [newLogoUrl, setNewLogoUrl] = useState('');

  // Selection states for 'list' tab
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Import Logic States
  const [importCandidates, setImportCandidates] = useState<AppLogo[]>([]);
  const [selectedImportIds, setSelectedImportIds] = useState<Set<string>>(new Set());

  // Reset selection when switching tabs
  useEffect(() => {
      setSelectedIds(new Set());
  }, [tab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setNewLogoUrl(ev.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAdd = () => {
      if (newLogoName && newLogoUrl) {
          onAddLogo({
              id: uuidv4(),
              name: newLogoName,
              data: newLogoUrl
          });
          setNewLogoName('');
          setNewLogoUrl('');
          setTab('list');
      }
  };

  const handleImportFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (ev.target?.result) {
                try {
                    const parsed = JSON.parse(ev.target.result as string);
                    if (Array.isArray(parsed)) {
                        // Filter basic validity
                        const valid = parsed.filter(item => item.name && item.data);
                        const candidates = valid.map((l: any) => ({...l, id: l.id || uuidv4() }));

                        setImportCandidates(candidates);
                        // Select all by default
                        setSelectedImportIds(new Set(candidates.map((c: any) => c.id)));
                    } else {
                        alert("Invalid JSON Format: Expected an array.");
                    }
                } catch (e) {
                    alert("Invalid JSON File.");
                }
            }
        };
        reader.readAsText(file);
        e.target.value = ''; 
    }
  };

  const handleConfirmImport = () => {
      const toImport = importCandidates.filter(c => selectedImportIds.has(c.id));
      if (toImport.length === 0) return;
      onImportLogos(toImport);
      setImportCandidates([]); // Clear after import
      setTab('list');
  };

  const handleClearImport = () => {
      setImportCandidates([]);
      setSelectedImportIds(new Set());
  };

  const toggleImportSelect = (id: string) => {
      const next = new Set(selectedImportIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedImportIds(next);
  };

  const toggleImportSelectAll = () => {
      if (selectedImportIds.size === importCandidates.length) {
          setSelectedImportIds(new Set());
      } else {
          setSelectedImportIds(new Set(importCandidates.map(c => c.id)));
      }
  };

  // List Management Logic
  const handleExportSelected = () => {
      if (selectedIds.size === 0) return;
      const selectedLogos = logos.filter(l => selectedIds.has(l.id));
      const json = JSON.stringify(selectedLogos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos-selected.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Selected logos exported to file");
  };

  const handleExportAll = () => {
      const json = JSON.stringify(logos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Logos exported to file");
  };

  const toggleSelect = (id: string) => {
      const next = new Set(selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedIds(next);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === logos.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(logos.map(l => l.id)));
      }
  };

  const handleDeleteSelected = () => {
      if (confirm(`Delete ${selectedIds.size} selected logos?`)) {
          onBatchDeleteLogo(Array.from(selectedIds));
          setSelectedIds(new Set());
      }
  };

  const content = (
      <div className={`flex flex-col relative ${inline ? '' : 'h-full'}`}>
          <div className="flex gap-4 mb-4 border-b shrink-0 items-center justify-between">
            <div className="flex gap-4">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('list')}>
                  {t.tabLogoList}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('add')}>
                  {t.tabAddLogo}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('import')}>
                  {t.tabImportLogos}
                </button>
            </div>

            {/* Context Actions for Header */}
            {tab === 'list' && logos.length > 0 && (
                 <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedIds.size === logos.length} onChange={toggleSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
            {tab === 'import' && importCandidates.length > 0 && (
                 <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedImportIds.size === importCandidates.length} onChange={toggleImportSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
          </div>

          <div className={`${inline ? '' : 'flex-1 overflow-y-auto min-h-[300px]'} ${(selectedIds.size > 0 && tab === 'list') || (importCandidates.length > 0 && tab === 'import') ? 'pb-24' : 'pb-4'}`}>

              {/* TAB: LIST (Compacted Grid) */}
              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-3">
                          {logos.map(l => {
                              const isSelected = selectedIds.has(l.id);
                              return (
                                  <div 
                                    key={l.id} 
                                    onClick={() => toggleSelect(l.id)}
                                    className={`border rounded-lg p-2 relative group cursor-pointer transition flex flex-col items-center bg-white ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                  >
                                      <div className={`absolute top-1 right-1 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                           <div className={`w-4 h-4 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 bg-white'}`}>
                                                {isSelected && <Check size={10} />}
                                           </div>
                                      </div>
                                      <div className="w-8 h-8 flex items-center justify-center mb-2">
                                          <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                      </div>
                                      <p className="text-[10px] text-center font-medium truncate w-full" title={l.name}>{l.name}</p>
                                  </div>
                              );
                          })}
                      </div>
                  </div>
              )}

              {/* TAB: ADD */}
              {tab === 'add' && (
                  <div className="space-y-4 max-w-md mx-auto py-4">
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                       </div>
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://..." />
                       </div>
                       <div className="text-center text-sm text-gray-500 py-2">- OR -</div>
                       <div>
                           <label className={`flex items-center justify-center gap-2 border-2 border-dashed border-gray-300 rounded-lg p-6 cursor-pointer hover:border-gray-400 hover:bg-gray-50 transition`}>
                               <Upload size={20} className="text-gray-400" />
                               <span className="text-gray-600">{t.btnUploadLogo}</span>
                               <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                           </label>
                       </div>
                       {newLogoUrl && (
                           <div className="mt-4 flex justify-center">
                               <img src={newLogoUrl} alt="Preview" className="h-20 object-contain border rounded p-1" />
                           </div>
                       )}
                       <button onClick={handleAdd} disabled={!newLogoName || !newLogoUrl} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4 disabled:opacity-50`}>
                           {t.btnAddLogo}
                       </button>
                  </div>
              )}

              {/* TAB: IMPORT / EXPORT */}
              {tab === 'import' && (
                  <div className="space-y-4">
                      {importCandidates.length === 0 ? (
                          <>
                              <div className="flex gap-4">
                                  <button onClick={handleExportAll} className="flex-1 border border-gray-300 hover:bg-gray-50 text-gray-700 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2">
                                      <Download size={16} /> {t.btnExportLogos}
                                  </button>
                              </div>

                              <div className="py-6">
                                  <label 
                                      onDragOver={e => e.preventDefault()}
                                      className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center text-gray-500 hover:bg-gray-50 transition cursor-pointer block"
                                  >
                                      <FileJson className="mx-auto h-10 w-10 text-gray-400 mb-3" />
                                      <p className="text-sm font-medium text-gray-700">Import Logos from JSON File</p>
                                      <p className="text-xs text-gray-400 mt-1">Click to browse or drag file here</p>
                                      <input type="file" accept=".json,application/json" className="hidden" onChange={handleImportFileSelect} />
                                  </label>
                              </div>
                          </>
                      ) : (
                          <div>
                              <div className="flex items-center justify-between mb-4">
                                  <p className="text-sm text-gray-600">Found <b>{importCandidates.length}</b> logos.</p>
                                  <button onClick={handleClearImport} className="text-xs text-red-500 hover:text-red-700 flex items-center gap-1">
                                      <Trash2 size={12} /> Clear Import
                                  </button>
                              </div>
                              {/* Compacted Import Grid */}
                              <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3">
                                  {importCandidates.map(l => {
                                      const isSelected = selectedImportIds.has(l.id);
                                      return (
                                          <div 
                                            key={l.id} 
                                            onClick={() => toggleImportSelect(l.id)}
                                            className={`border rounded-lg p-2 relative group cursor-pointer transition flex flex-col items-center bg-white ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                          >
                                              <div className={`absolute top-1 right-1`}>
                                                   <div className={`w-4 h-4 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 bg-white'}`}>
                                                        {isSelected && <Check size={10} />}
                                                   </div>
                                              </div>
                                              <div className="w-8 h-8 flex items-center justify-center mb-2">
                                                  <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                              </div>
                                              <p className="text-[10px] text-center font-medium truncate w-full">{l.name}</p>
                                          </div>
                                      );
                                  })}
                              </div>
                          </div>
                      )}
                  </div>
              )}
          </div>

          {/* Bottom Action Bar for List Selection */}
          {selectedIds.size > 0 && tab === 'list' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedIds.size} {t.selected}</span>
                       </div>
                       <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                            <button onClick={handleExportSelected} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Download size={16} /> {t.exportSelected}
                            </button>
                            <button onClick={handleDeleteSelected} className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Trash2 size={16} /> {t.deleteSelected}
                            </button>
                       </div>
                   </div>
              </div>
          )}

          {/* Bottom Action Bar for Import Selection */}
          {importCandidates.length > 0 && tab === 'import' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedImportIds.size} {t.selected}</span>
                       </div>
                       <div className="flex gap-2 w-full sm:w-auto">
                            <button onClick={handleClearImport} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 {t.btnCancel}
                            </button>
                            <button onClick={handleConfirmImport} disabled={selectedImportIds.size === 0} className={`flex-[2] sm:flex-none flex items-center justify-center gap-2 ${theme.btn} text-white px-6 py-2.5 rounded-lg transition text-sm font-medium disabled:opacity-50`}>
                                 <Download size={16} /> {t.btnImportLogos}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(false);

  const getCSV = () => {
      const header = `Issuer,Account,Secret,Period,Notes${includeLogo ? ',LogoID' : ''}`;
      const rows = accounts.map(a => 
          `${a.issuer},${a.account},${a.secret},${a.period},${a.notes || ''}${includeLogo ? ',' + (a.logoId || '') : ''}`
      );
      return [header, ...rows].join('\n');
  };

  const getURIs = () => {
      return accounts.map(a => {
          const label = encodeURIComponent(a.issuer) + ':' + encodeURIComponent(a.account);
          return `otpauth://totp/${label}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
      }).join('\n');
  };

  const handleCopy = (text: string) => {
      navigator.clipboard.writeText(text);
      alert(t.copied);
  };

  return (
      <Modal title={t.modalExportTitle} onClose={onClose}>
          <div className="flex gap-4 mb-4 border-b">
               <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('csv')}>
                  <span className="flex items-center gap-2"><List size={16}/> {t.tabCSV}</span>
               </button>
               <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('uri')}>
                  <span className="flex items-center gap-2"><Link size={16}/> {t.tabURI}</span>
               </button>
               <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('qr')}>
                  <span className="flex items-center gap-2"><Grid size={16}/> {t.tabQR}</span>
               </button>
          </div>

          <div className="mb-4">
               {tab === 'csv' && (
                   <>
                      <p className="text-sm text-gray-500 mb-2">{t.descCSV}</p>
                      <div className="mb-2">
                           <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                               <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                               {t.labelIncludeLogo}
                           </label>
                      </div>
                      <textarea readOnly className="w-full h-60 p-3 bg-gray-50 border rounded-md font-mono text-xs outline-none" value={getCSV()} />
                      <button onClick={() => handleCopy(getCSV())} className={`mt-2 w-full ${theme.btn} text-white py-2 rounded-lg font-medium flex items-center justify-center gap-2`}>
                          <Copy size={16} /> {t.btnCopy}
                      </button>
                   </>
               )}
               {tab === 'uri' && (
                   <>
                      <p className="text-sm text-gray-500 mb-2">{t.descURI}</p>
                      <textarea readOnly className="w-full h-64 p-3 bg-gray-50 border rounded-md font-mono text-xs outline-none" value={getURIs()} />
                      <button onClick={() => handleCopy(getURIs())} className={`mt-2 w-full ${theme.btn} text-white py-2 rounded-lg font-medium flex items-center justify-center gap-2`}>
                          <Copy size={16} /> {t.btnCopy}
                      </button>
                   </>
               )}
               {tab === 'qr' && (
                   <>
                      <p className="text-sm text-gray-500 mb-4">{t.descQR}</p>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-h-[60vh] overflow-y-auto p-2">
                          {accounts.map(a => {
                              const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                              return (
                                  <div key={a.id} className="border rounded-lg p-4 flex flex-col items-center bg-gray-50">
                                      <div className="bg-white p-2 rounded shadow-sm border mb-2">
                                          <QRCodeSVG value={uri} size={120} />
                                      </div>
                                      <p className="font-bold text-sm text-center truncate w-full">{a.issuer}</p>
                                      <p className="text-xs text-gray-500 text-center truncate w-full">{a.account}</p>
                                  </div>
                              );
                          })}
                      </div>
                   </>
               )}
          </div>
      </Modal>
  );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
  onClose: () => void;
  hasPassword: boolean;
  onSetPassword: (pass: string) => Promise<any>;
  onRemovePassword: (pass: string) => Promise<boolean>;
  onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
  isUnlock?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
  onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, isUnlock = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);

  // View state: 'menu' (if hasPassword) | 'set' | 'change' | 'remove' | 'unlock'
  const [view, setView] = useState<'menu' | 'set' | 'change' | 'remove' | 'unlock'>(
      isUnlock ? 'unlock' : (hasPassword ? 'menu' : 'set')
  );

  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [oldPass, setOldPass] = useState('');
  const [error, setError] = useState('');

  const resetForm = () => {
      setPass1(''); setPass2(''); setOldPass(''); setError('');
  };

  const handleSet = async (e: React.FormEvent) => {
      e.preventDefault();
      if (pass1 !== pass2) {
          setError(t.passwordsNoMatch);
          return;
      }
      try {
          await onSetPassword(pass1);
          onClose();
      } catch (e) {
          setError('Error setting password');
      }
  };

  const handleUnlock = async (e: React.FormEvent) => {
      e.preventDefault();
      try {
          await onSetPassword(pass1); // Reusing onSetPassword as the "Submit" action for unlock
          onClose();
      } catch (e) {
          setError(t.wrongPassword);
      }
  }

  const handleChange = async (e: React.FormEvent) => {
      e.preventDefault();
      if (pass1 !== pass2) {
          setError(t.passwordsNoMatch);
          return;
      }
      if (onChangePassword) {
          const success = await onChangePassword(oldPass, pass1);
          if (success) {
              onClose();
          } else {
              setError(t.wrongPassword);
          }
      }
  };

  const handleRemove = async (e: React.FormEvent) => {
      e.preventDefault();
      const success = await onRemovePassword(pass1);
      if (success) {
          onClose();
      } else {
          setError(t.wrongPassword);
      }
  };

  const renderHeader = () => {
      if (view === 'unlock') return t.unlockFile;
      if (view === 'set') return t.setPassword;
      if (view === 'change') return t.changePassword;
      if (view === 'remove') return t.removePassword;
      return t.securityTitle;
  };

  return (
      <Modal title={renderHeader()} onClose={onClose} className="max-w-md">
           {view === 'menu' && (
               <div className="space-y-3 py-4">
                   <div className="bg-green-50 p-3 rounded-lg flex items-center gap-3 text-green-700 mb-6">
                       <ShieldCheck className="shrink-0" />
                       <span className="text-sm font-medium">{t.passwordSet}</span>
                   </div>
                   <button onClick={() => { setView('change'); resetForm(); }} className={`w-full bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 font-medium py-3 rounded-lg flex items-center justify-center gap-2`}>
                       <KeyRound size={18} /> {t.changePassword}
                   </button>
                   <button onClick={() => { setView('remove'); resetForm(); }} className={`w-full bg-white border border-red-200 hover:bg-red-50 text-red-600 font-medium py-3 rounded-lg flex items-center justify-center gap-2`}>
                       <ShieldOff size={18} /> {t.removePassword}
                   </button>
               </div>
           )}

           {view === 'set' && (
               <form onSubmit={handleSet} className="space-y-4 py-2">
                   <div className="bg-blue-50 p-3 rounded-lg flex items-start gap-3 text-blue-700 text-sm mb-2">
                       <Info className="shrink-0 mt-0.5" size={16} />
                       <span>Setting a password will encrypt your data. You must remember this password to access your accounts.</span>
                   </div>
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword}</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={pass1} onChange={e => setPass1(e.target.value)} autoFocus />
                   </div>
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={pass2} onChange={e => setPass2(e.target.value)} />
                   </div>
                   {error && <p className="text-red-500 text-sm">{error}</p>}
                   <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                       {t.btnSave}
                   </button>
               </form>
           )}

           {view === 'unlock' && (
               <form onSubmit={handleUnlock} className="space-y-4 py-2">
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">{t.enterPassword}</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={pass1} onChange={e => setPass1(e.target.value)} autoFocus />
                   </div>
                   {error && <p className="text-red-500 text-sm">{error}</p>}
                   <button type="submit" className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                       {t.unlock}
                   </button>
               </form>
           )}

           {view === 'change' && (
               <form onSubmit={handleChange} className="space-y-4 py-2">
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">Current Password</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={oldPass} onChange={e => setOldPass(e.target.value)} autoFocus />
                   </div>
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">New Password</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={pass1} onChange={e => setPass1(e.target.value)} />
                   </div>
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">Confirm New Password</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={pass2} onChange={e => setPass2(e.target.value)} />
                   </div>
                   {error && <p className="text-red-500 text-sm">{error}</p>}

                   <div className="flex gap-2 mt-4">
                       <button type="button" onClick={() => setView('menu')} className="flex-1 bg-gray-100 text-gray-700 py-2.5 rounded-lg font-medium">Cancel</button>
                       <button type="submit" className={`flex-1 ${theme.btn} text-white py-2.5 rounded-lg font-medium`}>Change</button>
                   </div>
               </form>
           )}

           {view === 'remove' && (
               <form onSubmit={handleRemove} className="space-y-4 py-2">
                   <div className="bg-red-50 p-3 rounded-lg flex items-start gap-3 text-red-700 text-sm mb-2">
                       <AlertTriangle className="shrink-0 mt-0.5" size={16} />
                       <span>Removing the password will decrypt your data and store it in plain text. Anyone with access to this device/file can see it.</span>
                   </div>
                   <div>
                       <label className="block text-sm font-medium text-gray-700 mb-1">Confirm Current Password</label>
                       <input type="password" required className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                          value={pass1} onChange={e => setPass1(e.target.value)} autoFocus />
                   </div>
                   {error && <p className="text-red-500 text-sm">{error}</p>}
                   <div className="flex gap-2 mt-4">
                       <button type="button" onClick={() => setView('menu')} className="flex-1 bg-gray-100 text-gray-700 py-2.5 rounded-lg font-medium">Cancel</button>
                       <button type="submit" className="flex-1 bg-red-600 hover:bg-red-700 text-white py-2.5 rounded-lg font-medium">Remove</button>
                   </div>
               </form>
           )}
      </Modal>
  );
};

import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount, AppLogo } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Edit2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import { LanguageContext } from '../utils/i18n';

interface AccountCardProps {
  account: OTPAccount;
  logo?: AppLogo;
  onDelete: (id: string) => void;
  onEdit: (account: OTPAccount) => void;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
  showQR: boolean;
  onToggleQR: (id: string) => void;
  color?: 'blue' | 'orange' | 'emerald';
}

const AccountCard: React.FC<AccountCardProps> = ({ account, logo, onDelete, onEdit, isSelected, onToggleSelect, showQR, onToggleQR, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));
    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);
    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  // Theme based styles
  const getThemeStyles = (c: string) => {
    switch (c) {
        case 'emerald':
            return {
                borderColor: 'border-emerald-500 ring-1 ring-emerald-500',
                checkboxColor: 'text-emerald-600 focus:ring-emerald-500',
                progressColor: 'bg-emerald-500',
                hoverText: 'hover:text-emerald-600',
                hoverBg: 'hover:bg-emerald-50',
                qrActiveBg: 'bg-emerald-50 text-emerald-600'
            };
        case 'orange':
            return {
                borderColor: 'border-orange-500 ring-1 ring-orange-500',
                checkboxColor: 'text-orange-600 focus:ring-orange-500',
                progressColor: 'bg-orange-500',
                hoverText: 'hover:text-orange-600',
                hoverBg: 'hover:bg-orange-50',
                qrActiveBg: 'bg-orange-50 text-orange-600'
            };
        case 'blue':
        default:
            return {
                borderColor: 'border-blue-500 ring-1 ring-blue-500',
                checkboxColor: 'text-blue-600 focus:ring-blue-500',
                progressColor: 'bg-blue-500',
                hoverText: 'hover:text-blue-600',
                hoverBg: 'hover:bg-blue-50',
                qrActiveBg: 'bg-blue-50 text-blue-600'
            };
    }
  }

  const styles = getThemeStyles(color);

  const borderColor = styles.borderColor;
  const checkboxColor = styles.checkboxColor;
  const progressBarColor = tokenData.seconds < 5 ? 'bg-red-500' : styles.progressColor;
  const hoverText = styles.hoverText;
  const hoverBg = styles.hoverBg;
  const qrActiveBg = showQR ? styles.qrActiveBg : 'text-gray-400 hover:bg-gray-100';

  // Generate a soft background color based on issuer char
  const getAvatarColor = (name: string) => {
    const colors = ['bg-blue-100 text-blue-700', 'bg-emerald-100 text-emerald-700', 'bg-violet-100 text-violet-700', 'bg-amber-100 text-amber-700', 'bg-rose-100 text-rose-700', 'bg-cyan-100 text-cyan-700'];
    const index = name.length % colors.length;
    return colors[index];
  };

  const avatarClass = getAvatarColor(account.issuer || 'U');

  return (
    <div 
      className={`relative bg-white rounded-2xl transition-all duration-200 flex flex-col overflow-hidden group border ${isSelected ? `${borderColor} shadow-md` : 'border-gray-200 shadow-sm hover:shadow-md'}`}
      onClick={(e) => {
          // Prevent accidental copy when selecting logic might change later
      }}
    >
      {/* Top Section: Issuer & Controls */}
      <div className="px-5 pt-4 pb-2 flex justify-between items-start">
        <div className="flex items-center gap-3 overflow-hidden pr-2 min-w-0 flex-1">
            {logo ? (
                // Custom Logo
                <div className="w-10 h-10 shrink-0 flex items-center justify-center">
                    <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                </div>
            ) : (
                // Default Avatar
                <div 
                  className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-xl shrink-0 ${avatarClass}`}
                >
                    {(account.issuer || '?').charAt(0).toUpperCase()}
                </div>
            )}
            <div className="min-w-0 flex-1">
                <h3 className="font-bold text-gray-900 truncate text-base" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 truncate" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox */}
        <div className="shrink-0 ml-2 z-10" onClick={(e) => e.stopPropagation()}>
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={() => onToggleSelect(account.id)}
                className={`w-5 h-5 rounded border-gray-300 cursor-pointer transition-opacity ${checkboxColor} ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-4 relative px-4 min-h-[110px]">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-2 rounded-xl border shadow-sm">
                    <QRCodeSVG value={otpUri} size={120} />
                 </div>
                 <button type="button" onClick={() => onToggleQR(account.id)} className={`text-xs text-gray-500 mt-2 ${hoverText} font-medium`}>
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className={`text-4xl sm:text-5xl font-mono font-semibold text-gray-800 tracking-widest cursor-pointer hover:scale-105 active:scale-95 transition-all select-all text-center w-full truncate ${account.notes ? 'mb-1' : 'mb-4'}`}
                    onClick={handleCopy}
                    title="Click to copy"
                >
                    {formattedToken}
                </div>

                {/* Notes centered below code */}
                {account.notes && (
                    <div className="w-full px-4 text-center mt-1 mb-2">
                         <p className="text-xs text-gray-400 truncate w-full bg-gray-50 rounded px-2 py-1 inline-block max-w-full" title={account.notes}>
                            {account.notes}
                         </p>
                    </div>
                )}

                {/* Copied Badge */}
                <div 
                    className={`absolute top-[60%] left-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-200 pointer-events-none ${copied ? 'opacity-100 scale-100' : 'opacity-0 scale-90'}`}
                >
                    <span className="text-sm font-semibold bg-green-100 text-green-700 px-3 py-1 rounded-full shadow-sm border border-green-200">
                        {t.copied}
                    </span>
                </div>
            </>
         )}
      </div>

      {/* Bottom Section: Progress & Actions */}
      <div className="bg-gray-50/50 px-4 py-3 border-t border-gray-100 mt-auto">
         <div className="flex justify-between items-center mb-2">
            <div className="text-xs font-medium text-gray-400 font-mono">
                {tokenData.seconds}s
            </div>

            <div className="flex gap-1">
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleQR(account.id); }} 
                    className={`p-2 rounded-lg transition ${qrActiveBg}`}
                    title="QR Code"
                >
                    <QrCode size={16} className="pointer-events-none" />
                 </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onEdit(account); }} 
                    className={`p-2 text-gray-400 ${hoverText} ${hoverBg} rounded-lg transition`}
                    title={t.edit}
                >
                    <Edit2 size={16} className="pointer-events-none" />
                </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(account.id); }} 
                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
                    title={t.delete}
                >
                    <Trash2 size={16} className="pointer-events-none" />
                </button>
            </div>
         </div>

         {/* Progress Bar */}
         <div className="relative h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${progressBarColor}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
      </div>
    </div>
  );
};

