                                    className={`aspect-square border rounded-lg p-2 relative group cursor-pointer transition flex flex-col items-center justify-center bg-white ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                  >
