                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedImportIds.size} {t.selected}</span>
                       </div>
                       <div className="flex gap-2 w-full sm:w-auto">
                            <button onClick={handleClearImport} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 {t.btnCancel}
                            </button>
                            <button onClick={handleConfirmImport} disabled={selectedImportIds.size === 0} className={`flex-[2] sm:flex-none flex items-center justify-center gap-2 ${theme.btn} text-white px-6 py-2.5 rounded-lg transition text-sm font-medium disabled:opacity-50`}>
                                 <Download size={16} /> {t.btnImportLogos}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(true);
  const [copied, setCopied] = useState(false);

  const getCSV = () => {
      const header = "Issuer,Account,Secret,Period,Notes" + (includeLogo ? ",LogoID" : "");
      const rows = accounts.map(a => {
          const base = `${a.issuer},${a.account},${a.secret},${a.period},${a.notes || ''}`;
          return includeLogo ? `${base},${a.logoId || ''}` : base;
      });
      return [header, ...rows].join('\n');
  };

  const getURIs = () => {
      return accounts.map(a => 
          `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`
      ).join('\n');
  };

  const handleCopy = () => {
      const content = tab === 'csv' ? getCSV() : getURIs();
      navigator.clipboard.writeText(content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Modal title={`${t.modalExportTitle} (${accounts.length})`} onClose={onClose} className="max-w-2xl">
         <div className="flex gap-4 mb-4 border-b overflow-x-auto">
            <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('csv')}>{t.tabCSV}</button>
            <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('uri')}>{t.tabURI}</button>
            <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('qr')}>{t.tabQR}</button>
         </div>

         <div className="mb-4 text-sm text-gray-500">
             {tab === 'csv' && <p>{t.descCSV}</p>}
             {tab === 'uri' && <p>{t.descURI}</p>}
             {tab === 'qr' && <p>{t.descQR}</p>}
         </div>

         {tab !== 'qr' ? (
             <div className="space-y-4">
                 {tab === 'csv' && (
                     <label className="flex items-center gap-2 text-sm text-gray-700">
                         <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                         {t.labelIncludeLogo}
                     </label>
                 )}
                 <textarea 
                    readOnly 
                    className={`w-full h-64 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-xs bg-gray-50`}
                    value={tab === 'csv' ? getCSV() : getURIs()}
                 />
                 <button onClick={handleCopy} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium flex items-center justify-center gap-2`}>
                     {copied ? <Check size={18} /> : <Copy size={18} />}
                     {copied ? t.copied : t.btnCopy}
                 </button>
             </div>
         ) : (
             <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 pb-4">
                 {accounts.map(a => {
                     const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                     return (
                         <div key={a.id} className="border rounded-lg p-4 flex flex-col items-center text-center bg-white shadow-sm">
                             <div className="mb-2 bg-white p-1">
                                 <QRCodeSVG value={uri} size={100} />
                             </div>
                             <p className="font-bold text-xs truncate w-full">{a.issuer}</p>
                             <p className="text-[10px] text-gray-500 truncate w-full">{a.account}</p>
                         </div>
                     )
                 })}
             </div>
         )}
    </Modal>
  );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
  onClose: () => void;
  hasPassword: boolean;
  onSetPassword: (password: string) => Promise<void>;
  onRemovePassword: (password: string) => Promise<boolean>;
  onChangePassword: (oldPass: string, newPass: string) => Promise<boolean>;
  color?: 'blue' | 'orange' | 'emerald';
  isUnlock?: boolean;
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, color = 'blue', isUnlock = false 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [mode, setMode] = useState<'set' | 'change' | 'remove'>(isUnlock ? 'set' : (hasPassword ? 'change' : 'set'));

    // Inputs
    const [currentPass, setCurrentPass] = useState('');
    const [newPass, setNewPass] = useState('');
    const [confirmPass, setConfirmPass] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (isUnlock) {
                // Unlock Mode (uses onSetPassword as handler)
                await onSetPassword(currentPass);
                // Parent handles close or success logic usually, but here onSetPassword might throw
            } else if (mode === 'set') {
                if (newPass !== confirmPass) throw new Error(t.passwordsNoMatch);
                if (!newPass) throw new Error("Password cannot be empty");
                await onSetPassword(newPass);
                onClose();
            } else if (mode === 'change') {
                if (newPass !== confirmPass) throw new Error(t.passwordsNoMatch);
                if (!newPass) throw new Error("Password cannot be empty");
                const success = await onChangePassword(currentPass, newPass);
                if (!success) throw new Error(t.wrongPassword);
                onClose();
            } else if (mode === 'remove') {
                const success = await onRemovePassword(currentPass);
                if (!success) throw new Error(t.wrongPassword);
                onClose();
            }
        } catch (err: any) {
            setError(err.message || "Operation failed");
            setLoading(false);
        }
    };

    const getTitle = () => {
        if (isUnlock) return t.unlockFile;
        if (hasPassword) return mode === 'change' ? t.changePassword : t.removePassword;
        return t.setPassword;
    };

    return (
        <Modal title={getTitle()} onClose={onClose} className="max-w-md">
            {!isUnlock && hasPassword && (
                <div className="flex gap-4 mb-6 border-b">
                    <button className={`pb-2 px-1 font-medium text-sm transition ${mode === 'change' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setMode('change')}>
                        {t.changePassword}
                    </button>
                    <button className={`pb-2 px-1 font-medium text-sm transition ${mode === 'remove' ? 'text-red-600 border-b-2 border-red-500' : 'text-gray-500'}`} onClick={() => setMode('remove')}>
                        {t.removePassword}
                    </button>
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
                {(isUnlock || mode === 'change' || mode === 'remove') && (
                    <div>
                         <label className="block text-sm font-medium text-gray-700 mb-1">
                             {isUnlock ? t.enterFilePassword : (mode === 'change' ? "Current Password" : "Enter Current Password")}
                         </label>
                         <input 
                            type="password" 
                            className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                            value={currentPass}
                            onChange={e => setCurrentPass(e.target.value)}
                            autoFocus={isUnlock || mode === 'remove'}
                         />
                    </div>
                )}

                {(mode === 'set' || mode === 'change') && !isUnlock && (
                    <>
                        <div>
                             <label className="block text-sm font-medium text-gray-700 mb-1">
                                 {mode === 'change' ? "New Password" : t.enterPassword}
                             </label>
                             <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={newPass}
                                onChange={e => setNewPass(e.target.value)}
                                autoFocus={mode === 'set'}
                             />
                        </div>
                        <div>
                             <label className="block text-sm font-medium text-gray-700 mb-1">
                                 {t.confirmPassword}
                             </label>
                             <input 
                                type="password" 
                                className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`}
                                value={confirmPass}
                                onChange={e => setConfirmPass(e.target.value)}
                             />
                        </div>
                    </>
                )}

                {error && (
                    <div className="text-red-600 text-sm bg-red-50 p-2 rounded flex items-center gap-2">
                        <AlertTriangle size={14} /> {error}
                    </div>
                )}

                <div className="pt-2">
                    <button 
                        type="submit" 
                        disabled={loading}
                        className={`w-full ${mode === 'remove' ? 'bg-red-600 hover:bg-red-700' : theme.btn} text-white py-2.5 rounded-lg font-medium shadow-sm disabled:opacity-50`}
                    >
                        {loading ? 'Processing...' : (
                            isUnlock ? t.unlock : (
                                mode === 'remove' ? t.removePassword : (mode === 'change' ? t.changePassword : t.setPassword)
                            )
                        )}
                    </button>
                    {mode === 'set' && !isUnlock && (
                         <p className="text-xs text-gray-500 mt-2 text-center">
                             Password is used to encrypt your data. If you lose it, data cannot be recovered.
                         </p>
                    )}
                </div>
            </form>
        </Modal>
    );
};

