interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            const parsed = parseLine(qrData);
            if (parsed.isValid) {
                 candidates.push(parsed);
            } else {
                 candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500">{t.textPaste} <span className="font-mono bg-gray-100 px-1 rounded">Issuer, Account, Secret, Period</span></p>
                <textarea 
                    className={`w-full h-40 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-sm`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\nGitHub, bob, KZSVS43UOJ62E3T3, 30\notpauth://totp/...`}
                />
                 <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none text-center font-mono`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-2`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center">
                     <ImageIcon size={32} className="text-gray-400" />
                 </div>
                 <div>
                     <p className="text-gray-600 mb-4">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-6 py-3 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition`}>
                         <Upload size={18} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-xs text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

// --- Import Preview Modal (Previously Drawer) ---
interface ImportPreviewModalProps {
    isOpen: boolean;
    candidates: ImportCandidate[];
    onClose: () => void;
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewModal: React.FC<ImportPreviewModalProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

    useEffect(() => {
        if (isOpen && candidates.length > 0) {
            // Select all valid candidates by default
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        const toImport = candidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(toImport);
    };

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    return (
        <Modal title={`${t.headerImport} (${candidates.length})`} onClose={onClose} className="max-w-2xl">
            <div className="flex flex-col h-full max-h-[70vh]">
                <div className="flex justify-between items-center mb-4 px-1">
                    <p className="text-sm text-gray-500">{selectedIndices.size} selected</p>
                </div>

                <div className="overflow-y-auto flex-1 bg-gray-50 rounded-lg border">
                    {candidates.map((c, i) => {
                         const logo = c.logoId ? logos.find(l => l.id === c.logoId) : null;
                         return (
                            <div key={i} className={`flex items-start gap-3 p-4 border-b bg-white last:border-b-0 ${!c.isValid ? 'opacity-50' : ''}`} onClick={() => c.isValid && toggleSelect(i)}>
                                <div className="pt-1">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedIndices.has(i)} 
                                        onChange={() => {}} 
                                        disabled={!c.isValid}
                                        className={`w-5 h-5 rounded border-gray-300 ${theme.checkbox}`}
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between">
                                        <div className="flex items-center gap-2">
                                           {logo && <img src={logo.data} alt="logo" className="w-5 h-5 object-contain" />}
                                           <span className="font-bold text-gray-900 truncate">{c.issuer || 'Unknown'}</span>
                                        </div>
                                        <span className="text-xs text-gray-400 font-mono shrink-0">{c.period}s</span>
                                    </div>
                                    <p className="text-sm text-gray-600 truncate mt-1">{c.account}</p>
                                    <div className="mt-1 flex items-center gap-2">
                                        <span className="text-xs text-gray-400 font-mono truncate max-w-[200px]" title={c.secret}>
                                            {c.secret ? c.secret.substring(0, 4) + '...' + c.secret.substring(c.secret.length-4) : 'NO SECRET'}
                                        </span>
                                        {!c.isValid && <span className="text-xs text-red-500 bg-red-50 px-1 rounded">Invalid</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="pt-4 mt-4 border-t flex justify-end gap-3">
                     <button onClick={onClose} className="px-4 py-2 border rounded-lg text-gray-600 hover:bg-gray-50 font-medium">
                         {t.btnCancel}
                     </button>
                     <button 
                        onClick={handleConfirm}
                        disabled={selectedIndices.size === 0}
                        className={`${theme.btn} text-white px-6 py-2 rounded-lg font-medium shadow-sm disabled:opacity-50`}
                     >
                        {t.btnImport} ({selectedIndices.size})
                     </button>
                </div>
            </div>
        </Modal>
    )
}

// --- Logo Manager Modal ---
interface LogoManagerModalProps {
  onClose: () => void;
  logos: AppLogo[];
  onAddLogo: (logo: AppLogo) => void;
  onDeleteLogo: (id: string) => void;
  onBatchDeleteLogo: (ids: string[]) => void;
  onImportLogos: (logos: AppLogo[]) => void;
  inline?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ 
    onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');
  const [newLogoName, setNewLogoName] = useState('');
  const [newLogoUrl, setNewLogoUrl] = useState('');

  // Selection states for 'list' tab
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Import Logic States
  const [importCandidates, setImportCandidates] = useState<AppLogo[]>([]);
  const [selectedImportIds, setSelectedImportIds] = useState<Set<string>>(new Set());

  // Reset selection when switching tabs
  useEffect(() => {
      setSelectedIds(new Set());
  }, [tab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setNewLogoUrl(ev.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAdd = () => {
      if (newLogoName && newLogoUrl) {
          onAddLogo({
              id: uuidv4(),
              name: newLogoName,
              data: newLogoUrl
          });
          setNewLogoName('');
          setNewLogoUrl('');
          setTab('list');
      }
  };

  const handleImportFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (ev.target?.result) {
                try {
                    const parsed = JSON.parse(ev.target.result as string);
                    if (Array.isArray(parsed)) {
                        // Filter basic validity
                        const valid = parsed.filter(item => item.name && item.data);
                        const candidates = valid.map((l: any) => ({...l, id: l.id || uuidv4() }));

                        setImportCandidates(candidates);
                        // Select all by default
                        setSelectedImportIds(new Set(candidates.map((c: any) => c.id)));
                    } else {
                        alert("Invalid JSON Format: Expected an array.");
                    }
                } catch (e) {
                    alert("Invalid JSON File.");
                }
            }
        };
        reader.readAsText(file);
        e.target.value = ''; 
    }
  };

  const handleConfirmImport = () => {
      const toImport = importCandidates.filter(c => selectedImportIds.has(c.id));
      if (toImport.length === 0) return;
      onImportLogos(toImport);
      setImportCandidates([]); // Clear after import
      setTab('list');
  };

  const handleClearImport = () => {
      setImportCandidates([]);
      setSelectedImportIds(new Set());
  };

  const toggleImportSelect = (id: string) => {
      const next = new Set(selectedImportIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedImportIds(next);
  };

  const toggleImportSelectAll = () => {
      if (selectedImportIds.size === importCandidates.length) {
          setSelectedImportIds(new Set());
      } else {
          setSelectedImportIds(new Set(importCandidates.map(c => c.id)));
      }
  };

  // List Management Logic
  const handleExportSelected = () => {
      if (selectedIds.size === 0) return;
      const selectedLogos = logos.filter(l => selectedIds.has(l.id));
      const json = JSON.stringify(selectedLogos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos-selected.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Selected logos exported to file");
  };

  const handleExportAll = () => {
      const json = JSON.stringify(logos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Logos exported to file");
  };

  const toggleSelect = (id: string) => {
      const next = new Set(selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedIds(next);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === logos.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(logos.map(l => l.id)));
      }
  };

  const handleDeleteSelected = () => {
      if (confirm(`Delete ${selectedIds.size} selected logos?`)) {
          onBatchDeleteLogo(Array.from(selectedIds));
          setSelectedIds(new Set());
      }
  };

  const content = (
      <div className={`flex flex-col relative ${inline ? '' : 'h-full'}`}>
          <div className="flex gap-4 mb-4 border-b shrink-0 items-center justify-between">
            <div className="flex gap-4">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('list')}>
                  {t.tabLogoList}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('add')}>
                  {t.tabAddLogo}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('import')}>
                  {t.tabImportLogos}
                </button>
            </div>

            {/* Context Actions for Header */}
            {tab === 'list' && logos.length > 0 && (
                 <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedIds.size === logos.length} onChange={toggleSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
            {tab === 'import' && importCandidates.length > 0 && (
                 <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedImportIds.size === importCandidates.length} onChange={toggleImportSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
          </div>

          <div className={`${inline ? '' : 'flex-1 overflow-y-auto min-h-[300px]'} ${(selectedIds.size > 0 && tab === 'list') || (importCandidates.length > 0 && tab === 'import') ? 'pb-24' : 'pb-4'}`}>

              {/* TAB: LIST */}
              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-2">
                          {logos.map(l => {
                              const isSelected = selectedIds.has(l.id);
                              return (
                                  <div 
                                    key={l.id} 
                                    onClick={() => toggleSelect(l.id)}
                                    className={`aspect-square border rounded-lg p-1 relative group cursor-pointer transition flex flex-col items-center justify-center bg-white ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                  >
                                      <div className={`absolute top-1 right-1 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                           <div className={`w-4 h-4 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 bg-white'}`}>
                                                {isSelected && <Check size={10} />}
                                           </div>
                                      </div>
                                      <div className="w-9 h-9 flex items-center justify-center mb-1">
                                          <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                      </div>
                                      <p className="text-[10px] text-center font-medium truncate w-full px-1" title={l.name}>{l.name}</p>
                                  </div>
                              );
                          })}
                      </div>
                  </div>
              )}

              {/* TAB: ADD */}
              {tab === 'add' && (
                  <div className="space-y-4 max-w-md mx-auto py-4">
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoName}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                       </div>
                       <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">{t.labelLogoUrl}</label>
                           <input type="text" className={`w-full p-2 border rounded-md focus:ring-2 ${theme.ring} outline-none`} 
                            value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://..." />
                       </div>
                       <div className="text-center text-sm text-gray-500 py-2">- OR -</div>
                       <div>
                           <label className={`flex items-center justify-center gap-2 border-2 border-dashed border-gray-300 rounded-lg p-6 cursor-pointer hover:border-gray-400 hover:bg-gray-50 transition`}>
                               <Upload size={20} className="text-gray-400" />
                               <span className="text-gray-600">{t.btnUploadLogo}</span>
                               <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                           </label>
                       </div>
                       {newLogoUrl && (
                           <div className="mt-4 flex justify-center">
                               <img src={newLogoUrl} alt="Preview" className="h-20 object-contain border rounded p-1" />
                           </div>
                       )}
                       <button onClick={handleAdd} disabled={!newLogoName || !newLogoUrl} className={`w-full ${theme.btn} text-white py-2.5 rounded-lg font-medium mt-4 disabled:opacity-50`}>
                           {t.btnAddLogo}
                       </button>
                  </div>
              )}

              {/* TAB: IMPORT / EXPORT */}
              {tab === 'import' && (
                  <div className="space-y-4">
                      {importCandidates.length === 0 ? (
                          <>
                              <div className="flex gap-4">
                                  <button onClick={handleExportAll} className="flex-1 border border-gray-300 hover:bg-gray-50 text-gray-700 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2">
                                      <Download size={16} /> {t.btnExportLogos}
                                  </button>
                              </div>

                              <div className="py-6">
                                  <label 
                                      onDragOver={e => e.preventDefault()}
                                      className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center text-gray-500 hover:bg-gray-50 transition cursor-pointer block"
                                  >
                                      <FileJson className="mx-auto h-10 w-10 text-gray-400 mb-3" />
                                      <p className="text-sm font-medium text-gray-700">Import Logos from JSON File</p>
                                      <p className="text-xs text-gray-400 mt-1">Click to browse or drag file here</p>
                                      <input type="file" accept=".json,application/json" className="hidden" onChange={handleImportFileSelect} />
                                  </label>
                              </div>
                          </>
                      ) : (
                          <div>
                              <div className="flex items-center justify-between mb-4">
                                  <p className="text-sm text-gray-600">Found <b>{importCandidates.length}</b> logos.</p>
                                  <button onClick={handleClearImport} className="text-xs text-red-500 hover:text-red-700 flex items-center gap-1">
                                      <Trash2 size={12} /> Clear Import
                                  </button>
                              </div>
                              <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-2">
                                  {importCandidates.map(l => {
                                      const isSelected = selectedImportIds.has(l.id);
                                      return (
                                          <div 
                                            key={l.id} 
                                            onClick={() => toggleImportSelect(l.id)}
                                            className={`aspect-square border rounded-lg p-1 relative group cursor-pointer transition flex flex-col items-center justify-center bg-white ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                          >
                                              <div className={`absolute top-1 right-1`}>
                                                   <div className={`w-4 h-4 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 bg-white'}`}>
                                                        {isSelected && <Check size={10} />}
                                                   </div>
                                              </div>
                                              <div className="w-9 h-9 flex items-center justify-center mb-1">
                                                  <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                              </div>
                                              <p className="text-[10px] text-center font-medium truncate w-full px-1">{l.name}</p>
                                          </div>
                                      );
                                  })}
                              </div>
                          </div>
                      )}
                  </div>
              )}
          </div>

          {/* Bottom Action Bar for List Selection */}
          {selectedIds.size > 0 && tab === 'list' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedIds.size} {t.selected}</span>
                       </div>
                       <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                            <button onClick={handleExportSelected} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Download size={16} /> {t.exportSelected}
                            </button>
                            <button onClick={handleDeleteSelected} className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 <Trash2 size={16} /> {t.deleteSelected}
                            </button>
                       </div>
                   </div>
              </div>
          )}

          {/* Bottom Action Bar for Import Selection */}
          {importCandidates.length > 0 && tab === 'import' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-4">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 ml-1">{selectedImportIds.size} {t.selected}</span>
                       </div>
                       <div className="flex gap-2 w-full sm:w-auto">
                            <button onClick={handleClearImport} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium">
                                 {t.btnCancel}
                            </button>
                            <button onClick={handleConfirmImport} disabled={selectedImportIds.size === 0} className={`flex-[2] sm:flex-none flex items-center justify-center gap-2 ${theme.btn} text-white px-6 py-2.5 rounded-lg transition text-sm font-medium disabled:opacity-50`}>
                                 <Download size={16} /> {t.btnImportLogos}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

// --- Batch Export Modal ---
interface BatchExportModalProps {
    accounts: OTPAccount[];
    onClose: () => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [tab, setTab] = useState<'csv' | 'uri' | 'qr'>('csv');
    const [includeLogo, setIncludeLogo] = useState(true);

    const getCSV = () => {
        const header = "Issuer,Account,Secret,Period,Notes,LogoID\n";
        const rows = accounts.map(a => 
            `${a.issuer},${a.account},${a.secret},${a.period},${a.notes || ''},${includeLogo ? (a.logoId || '') : ''}`
        ).join("\n");
        return header + rows;
    };

    const getURIs = () => {
        return accounts.map(a => 
            `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`
        ).join("\n");
    };

    const handleCopy = () => {
        const content = tab === 'csv' ? getCSV() : getURIs();
        navigator.clipboard.writeText(content);
        alert(t.copied);
    };

    const handleDownload = () => {
         const content = tab === 'csv' ? getCSV() : getURIs();
         const blob = new Blob([content], { type: 'text/plain' });
         const url = URL.createObjectURL(blob);
         const a = document.createElement('a');
         a.href = url;
         a.download = `secureauth-export-${Date.now()}.${tab === 'csv' ? 'csv' : 'txt'}`;
         a.click();
         URL.revokeObjectURL(url);
    };

    return (
        <Modal title={t.modalExportTitle} onClose={onClose} className="max-w-3xl">
            <div className="flex gap-4 mb-4 border-b">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('csv')}>{t.tabCSV}</button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('uri')}>{t.tabURI}</button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('qr')}>{t.tabQR}</button>
            </div>

            <div className="mb-4">
                 {tab === 'csv' && <p className="text-sm text-gray-500 mb-2">{t.descCSV}</p>}
                 {tab === 'uri' && <p className="text-sm text-gray-500 mb-2">{t.descURI}</p>}
                 {tab === 'qr' && <p className="text-sm text-gray-500 mb-2">{t.descQR}</p>}

                 {tab === 'csv' && (
                     <label className="flex items-center gap-2 text-sm text-gray-600 mb-2">
                         <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                         {t.labelIncludeLogo}
                     </label>
                 )}
            </div>

            {tab !== 'qr' ? (
                <div className="space-y-4">
                    <textarea 
                        readOnly 
                        className={`w-full h-64 p-3 border rounded-md focus:ring-2 ${theme.ring} outline-none font-mono text-xs whitespace-pre bg-gray-50`}
                        value={tab === 'csv' ? getCSV() : getURIs()}
                    />
                    <div className="flex gap-3">
                        <button onClick={handleCopy} className="flex-1 border border-gray-300 hover:bg-gray-50 text-gray-700 py-2.5 rounded-lg font-medium flex items-center justify-center gap-2">
                             <Copy size={18} /> {t.btnCopy}
                        </button>
                        <button onClick={handleDownload} className={`flex-1 ${theme.btn} text-white py-2.5 rounded-lg font-medium flex items-center justify-center gap-2`}>
                             <Download size={18} /> Download
                        </button>
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto p-2 bg-gray-50 rounded-lg border">
                    {accounts.map((a, i) => {
                         const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                         return (
                             <div key={i} className="bg-white p-3 rounded-lg border shadow-sm flex flex-col items-center text-center">
                                 <div className="bg-white p-1 rounded mb-2">
                                     <QRCodeSVG value={uri} size={100} />
                                 </div>
                                 <p className="font-bold text-xs truncate w-full">{a.issuer}</p>
                                 <p className="text-[10px] text-gray-500 truncate w-full">{a.account}</p>
                             </div>
                         );
                    })}
                </div>
            )}
        </Modal>
    );
};

// --- Password Settings Modal ---
interface PasswordSettingsModalProps {
    onClose: () => void;
    hasPassword?: boolean;
    isUnlock?: boolean; // If true, UI is for unlocking (e.g. file), not setting
    onSetPassword: (pass: string) => Promise<void>;
    onRemovePassword: (currPass: string) => Promise<boolean>;
    onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
    color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, isUnlock = false, onSetPassword, onRemovePassword, onChangePassword, color = 'blue' 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);

    // Modes: 'menu' | 'set' | 'change' | 'remove' | 'unlock'
    const [mode, setMode] = useState<'menu' | 'set' | 'change' | 'remove' | 'unlock'>(isUnlock ? 'unlock' : (hasPassword ? 'menu' : 'set'));

    // Inputs
    const [pass1, setPass1] = useState('');
    const [pass2, setPass2] = useState('');
    const [oldPass, setOldPass] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (mode === 'set' || mode === 'unlock') {
                if (mode === 'set' && pass1 !== pass2) {
                    setError(t.passwordsNoMatch);
                    setLoading(false);
                    return;
                }
                await onSetPassword(pass1);
                // If set/unlock succeeds, usually parent closes or we can close here
                onClose();
            } else if (mode === 'change') {
                if (pass1 !== pass2) {
                    setError(t.passwordsNoMatch);
                    setLoading(false);
                    return;
                }
                if (onChangePassword) {
                    const success = await onChangePassword(oldPass, pass1);
                    if (!success) setError(t.wrongPassword);
                    else onClose();
                }
            } else if (mode === 'remove') {
                const success = await onRemovePassword(oldPass);
                if (!success) setError(t.wrongPassword);
                else onClose();
            }
        } catch (err: any) {
             setError(err.message || "Operation failed");
        } finally {
            setLoading(false);
        }
    };

    const headerTitle = () => {
        if (mode === 'unlock') return t.unlockFile;
        if (mode === 'set') return t.setPassword;
        if (mode === 'change') return t.changePassword;
        if (mode === 'remove') return t.removePassword;
        return t.securityTitle;
    };

    return (
        <Modal title={headerTitle()} onClose={onClose} className="max-w-sm">
             {mode === 'menu' ? (
                 <div className="space-y-3 py-2">
                     <button onClick={() => setMode('change')} className="w-full flex items-center justify-between p-4 border rounded-xl hover:bg-gray-50 transition group">
                         <div className="flex items-center gap-3">
                             <div className="bg-blue-100 p-2 rounded-lg text-blue-600"><KeyRound size={20} /></div>
                             <span className="font-medium text-gray-700">{t.changePassword}</span>
                         </div>
                         <ArrowRight size={18} className="text-gray-300 group-hover:text-gray-500" />
                     </button>
                     <button onClick={() => setMode('remove')} className="w-full flex items-center justify-between p-4 border rounded-xl hover:bg-red-50 hover:border-red-100 transition group">
                         <div className="flex items-center gap-3">
                             <div className="bg-red-100 p-2 rounded-lg text-red-600"><ShieldOff size={20} /></div>
                             <span className="font-medium text-gray-700">{t.removePassword}</span>
                         </div>
                         <ArrowRight size={18} className="text-gray-300 group-hover:text-red-400" />
                     </button>
                 </div>
             ) : (
                 <form onSubmit={handleSubmit} className="space-y-4">
                     {error && <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-center gap-2"><AlertTriangle size={16}/> {error}</div>}

                     {(mode === 'change' || mode === 'remove') && (
                         <div>
                             <label className="block text-sm font-medium text-gray-700 mb-1">{mode === 'change' ? "Old Password" : t.enterPassword}</label>
                             <input type="password" required className={`w-full p-2.5 border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                                value={oldPass} onChange={e => setOldPass(e.target.value)} autoFocus />
                         </div>
                     )}

                     {(mode === 'set' || mode === 'change' || mode === 'unlock') && (
                         <div>
                             <label className="block text-sm font-medium text-gray-700 mb-1">
                                 {mode === 'change' ? "New Password" : (mode === 'unlock' ? t.enterFilePassword : t.enterPassword)}
                             </label>
                             <input type="password" required className={`w-full p-2.5 border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                                value={pass1} onChange={e => setPass1(e.target.value)} autoFocus={mode === 'set' || mode === 'unlock'} />
                         </div>
                     )}

                     {(mode === 'set' || mode === 'change') && (
                         <div>
                             <label className="block text-sm font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                             <input type="password" required className={`w-full p-2.5 border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                                value={pass2} onChange={e => setPass2(e.target.value)} />
                         </div>
                     )}

                     <div className="flex gap-3 mt-6">
                         {!isUnlock && hasPassword && mode !== 'menu' && (
                             <button type="button" onClick={() => setMode('menu')} className="px-4 py-2 text-gray-500 hover:bg-gray-100 rounded-lg">
                                 {t.btnCancel}
                             </button>
                         )}
                         <button type="submit" disabled={loading} className={`flex-1 ${theme.btn} text-white py-2.5 rounded-lg font-medium disabled:opacity-50`}>
                             {loading ? '...' : (mode === 'remove' ? t.removePassword : (mode === 'unlock' ? t.unlock : t.btnSave))}
                         </button>
                     </div>
                 </form>
             )}
        </Modal>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { StorageMode, OTPAccount, ImportCandidate, AppLogo, FileSpace } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewModal, LogoManagerModal, BatchEditModal, PasswordSettingsModal } from './components/Modals';
import LockScreen from './components/LockScreen';
import { ToastContainer, ToastMessage, ToastType } from './components/Toast';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search, Image as ImageIcon, Edit2, ShieldAlert, QrCode, X, FileJson, FolderOpen, Save, FilePlus, PenLine, XCircle, Unlock, AlertTriangle } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';
import { encryptData, decryptData, hashPassword, generateSalt } from './utils/crypto';
import fileSystemClient, { FileSystemFileHandle } from './service/FileSystemClient';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data',
  customLogos: 'secure_auth_custom_logos',
  lang: 'secure_auth_lang',
  passwordHash: 'secure_auth_password_hash',
  salt: 'secure_auth_salt'
};

interface PendingFile {
    space: FileSpace;
    rawEncryptedData: {
        isEncrypted: boolean;
        data: string;
        salt: string;
    }
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);

  // Security State (App Lock for LocalStorage)
  const [isLocked, setIsLocked] = useState(false);
  const [hasPassword, setHasPassword] = useState(false);
  const [sessionKey, setSessionKey] = useState<string | null>(null); // To store password temporarily in memory
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // File Storage State
  const [openFiles, setOpenFiles] = useState<FileSpace[]>([]);
  const [currentFileId, setCurrentFileId] = useState<string | null>(null);

  // Pending File State (Waiting for decryption)
  const [pendingFile, setPendingFile] = useState<PendingFile | null>(null);
  const [showFileUnlockModal, setShowFileUnlockModal] = useState(false);

  // Fallback for non-supported browsers
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Theme Color derived from activeTab
  const themeColor = activeTab === 'local' ? 'blue' : (activeTab === 'file' ? 'emerald' : 'orange');

  // Notification State
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  const showToast = (message: string, type: ToastType = 'info') => {
      const id = uuidv4();
      setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
      setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Initialize Lang from Storage
  const [lang, setLang] = useState<Language>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.lang) as Language) || 'en';
      } catch {
          return 'en';
      }
  });

  // Logo State
  const [customLogos, setCustomLogos] = useState<AppLogo[]>([]);
  const [showLogoManager, setShowLogoManager] = useState(false);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // QR Visibility State
  const [visibleQRIds, setVisibleQRIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showBatchEditModal, setShowBatchEditModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Persist Language
  useEffect(() => {
      localStorage.setItem(STORAGE_KEYS.lang, lang);
  }, [lang]);

  // Load Custom Logos on Mount
  useEffect(() => {
      try {
          const storedLogos = localStorage.getItem(STORAGE_KEYS.customLogos);
          if (storedLogos) {
              setCustomLogos(JSON.parse(storedLogos));
          }
      } catch (e) {
          console.error("Failed to load custom logos", e);
      }
  }, []);

  // Check Lock Status on Mount
  useEffect(() => {
    const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
    const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);

    if (storedHash && storedSalt) {
        setHasPassword(true);
        setIsLocked(true);
    } else {
        setHasPassword(false);
        setIsLocked(false);
        loadData('local', null); // Initial load without password
    }
  }, []);

  // Load Data helper function
  const loadData = async (mode: StorageMode, password: string | null) => {
      if (mode === 'file') {
          // File data loading is handled by handleFileSelection/Switching
          return;
      }

      const key = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const stored = storage.getItem(key);

      if (!stored) {
          setAccounts([]);
          return;
      }

      if (mode === 'local' && password) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const decrypted = await decryptData(stored, password, salt);
              if (decrypted) {
                  setAccounts(JSON.parse(decrypted));
              } else {
                  console.error("Failed to decrypt local data");
                  setAccounts([]); // Or handle error
              }
          }
      } else {
          try {
              if (stored.trim().startsWith('[') || stored.trim().startsWith('{')) {
                   setAccounts(JSON.parse(stored));
              } else if (mode === 'local' && hasPassword && !password) {
                   console.log("Data is encrypted, waiting for unlock");
              } else {
                   setAccounts(JSON.parse(stored)); 
              }
          } catch (e) {
              console.error("Error parsing data", e);
              setAccounts([]);
          }
      }
  };

  // Switching Files
  const handleSwitchFile = async (fileId: string) => {
      const file = openFiles.find(f => f.id === fileId);
      if (!file) return;

      // Handle locked file waiting in list
      if (file.isEncrypted && !file.password) {
          try {
              if (file.handle) {
                  // Re-read file to get encrypted blob
                  const { encryptedData } = await readFileRaw(file.handle as FileSystemFileHandle);
                  setPendingFile({ space: file, rawEncryptedData: encryptedData });
                  setShowFileUnlockModal(true);
              } else {
                  // Should not happen for virtual files as they are loaded into memory on start
                  console.error("Cannot re-read virtual file without data");
              }
          } catch (e) {
              console.error("Failed to read locked file to prep unlock", e);
              showToast("Failed to access file", 'error');
          }
          return;
      }

      // If already unlocked or plain
      setCurrentFileId(fileId);
      // Read content to update accounts view
      try {
          if (file.handle) {
              // Read from disk
              // @ts-ignore
              const fileObj = await file.handle.getFile();
              const text = await fileObj.text();
              const parsed = JSON.parse(text);

              if (file.isEncrypted && file.password) {
                 const decrypted = await decryptData(parsed.data, file.password, parsed.salt);
                 if (decrypted) {
                     setAccounts(JSON.parse(decrypted));
                 } else {
                     setAccounts([]); 
                 }
              } else {
                 setAccounts(Array.isArray(parsed) ? parsed : []);
              }
          } else if (file.isVirtual) {
              alert("Cannot switch back to memory-only file. Please re-open it.");
              setOpenFiles(prev => prev.filter(f => f.id !== fileId));
              return;
          }
      } catch (e) {
          console.error(e);
          setAccounts([]);
      }
  };

  // Reload data when Tab changes (if unlocked)
  useEffect(() => {
      if (!isLocked) {
          if (activeTab === 'file') {
              if (currentFileId) {
                  // Automatically focus/reload the file handle when returning to File tab
                  handleSwitchFile(currentFileId);
              } else {
                  setAccounts([]);
              }
          } else {
              loadData(activeTab, sessionKey);
          }
          setSelectedIds(new Set());
          setSearchQuery('');
          setIsSearchFocused(false);
          setVisibleQRIds(new Set()); // Hide QRs on tab switch
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, isLocked]);


  // Unlock Handler
  const handleUnlock = async (password: string) => {
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);

      if (!storedHash || !storedSalt) return false;

      // Verify Password
      const inputHash = await hashPassword(password, storedSalt);
      if (inputHash === storedHash) {
          setSessionKey(password);
          setIsLocked(false);
          await loadData('local', password); // Load decrypted data
          return true;
      }
      return false;
  };

  // Lock Reset (Forgot Password)
  const handleResetLock = () => {
      localStorage.removeItem(STORAGE_KEYS.passwordHash);
      localStorage.removeItem(STORAGE_KEYS.salt);
      localStorage.removeItem(STORAGE_KEYS.local); // Clear Encrypted Data
      setHasPassword(false);
      setIsLocked(false);
      setSessionKey(null);
      setAccounts([]);
      showToast('App reset. All local data cleared.', 'info');
  };

  // --- APP LOCK SECURITY HANDLERS ---

  // Set Password (App Lock)
  const handleSetPassword = async (password: string) => {
      const salt = generateSalt();
      const hash = await hashPassword(password, salt);

      localStorage.setItem(STORAGE_KEYS.salt, salt);
      localStorage.setItem(STORAGE_KEYS.passwordHash, hash);
      setSessionKey(password);
      setHasPassword(true);

      // Re-save current accounts with encryption
      await saveAccountsInternal(accounts, password, 'local');
      showToast(translations[lang].passwordSet, 'success');
  };

  // Remove Password (App Lock)
  const handleRemovePassword = async (currentPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);

      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(currentPassword, storedSalt);
          if (inputHash === storedHash) {
               localStorage.removeItem(STORAGE_KEYS.passwordHash);
               localStorage.removeItem(STORAGE_KEYS.salt);
               setHasPassword(false);
               setSessionKey(null);

               // Save as plaintext
               await saveAccountsInternal(accounts, null, 'local');
               showToast(translations[lang].passwordRemoved, 'success');
               return true;
          }
      }
      return false;
  };

  // Change Password (App Lock)
  const handleChangePassword = async (oldPassword: string, newPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);

      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(oldPassword, storedSalt);
          if (inputHash === storedHash) {
              // Verify old pass success, now set new
              const newSalt = generateSalt();
              const newHash = await hashPassword(newPassword, newSalt);

              localStorage.setItem(STORAGE_KEYS.salt, newSalt);
              localStorage.setItem(STORAGE_KEYS.passwordHash, newHash);
              setSessionKey(newPassword);

              // Re-save data with new key
              await saveAccountsInternal(accounts, newPassword, 'local');
              showToast("Password changed successfully", 'success');
              return true;
          }
      }
      return false;
  }


  // Save Data Internal Helper
  const saveAccountsInternal = async (newAccounts: OTPAccount[], key: string | null, mode: StorageMode) => {
      if (mode === 'file') {
          // File saving needs file handle, handled by saveToFile
          if (currentFileId) {
             const file = openFiles.find(f => f.id === currentFileId);
             if (file) {
                 await saveToFile(file, newAccounts);
             }
          }
          return;
      }

      const storageKey = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const json = JSON.stringify(newAccounts);

      if (mode === 'local' && key) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const encrypted = await encryptData(json, key, salt);
              storage.setItem(storageKey, encrypted);
          }
      } else {
          storage.setItem(storageKey, json);
      }
  };

  // --- FILE SYSTEM LOGIC ---

  const saveToFile = async (fileSpace: FileSpace, accountsData: OTPAccount[]) => {
      // Logic for File System Access API (supported browsers)
      if (fileSpace.handle) {
          try {
              // Cast handle to any for now to avoid TS errors with write
              const handle = fileSpace.handle as any;
              const writable = await handle.createWritable();
              const json = JSON.stringify(accountsData);

              if (fileSpace.isEncrypted && fileSpace.password) {
                  const salt = generateSalt();
                  const encrypted = await encryptData(json, fileSpace.password, salt);
                  const fileContent = JSON.stringify({
                      isEncrypted: true,
                      data: encrypted,
                      salt: salt
                  });
                  await writable.write(fileContent);
              } else {
                   await writable.write(json);
              }
              await writable.close();
          } catch (e) {
              console.error("Failed to save to file", e);
              showToast("Failed to save to file. Check permissions.", "error");
          }
      } 
      // Logic for fallback Virtual/Memory file (legacy browsers)
      else if (fileSpace.isVirtual) {
          const json = JSON.stringify(accountsData);
          let content = json;

          if (fileSpace.isEncrypted && fileSpace.password) {
              const salt = generateSalt();
              const encrypted = await encryptData(json, fileSpace.password, salt);
              content = JSON.stringify({
                  isEncrypted: true,
                  data: encrypted,
                  salt: salt
              });
          }

          // Trigger download
          const blob = new Blob([content], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = fileSpace.displayName || 'secureauth-accounts.json';
          a.click();
          URL.revokeObjectURL(url);
          showToast("File downloaded (Manual Save)", 'info');
      }
  };

  // Helper to read raw file data
  const readFileRaw = async (handle: FileSystemFileHandle) => {
      const fileData = await handle.getFile();
      const text = await fileData.text();
      return parseRawFileContent(text, handle.name, handle);
  };

  const parseRawFileContent = (text: string, name: string, handle: FileSystemFileHandle | null) => {
      let parsed;
      let isEncrypted = false;
      let encryptedData = { isEncrypted: false, data: '', salt: '' };

      try {
          parsed = JSON.parse(text);
          if (parsed && parsed.isEncrypted && parsed.data && parsed.salt) {
              isEncrypted = true;
              encryptedData = parsed;
          }
      } catch(e) {
           // Empty or invalid, treat as plain empty array
           parsed = [];
      }

      const newFileSpace: FileSpace = {
          id: uuidv4(),
          displayName: name,
          handle: handle,
          isEncrypted: isEncrypted,
          isVirtual: handle === null
      };

      return { newFileSpace, parsed, isEncrypted, encryptedData };
  }

  const handleOpenFile = async () => {
      if (!fileSystemClient.supported) {
          // Trigger hidden input for legacy open
          fileInputRef.current?.click();
          return;
      }
      try {
          const handles = await fileSystemClient.openFile({
              types: [{ description: 'JSON File', accept: { 'application/json': ['.json'] } }],
          });

          if (handles && handles.length > 0) {
              const handle = handles[0];
              const { newFileSpace, parsed, isEncrypted, encryptedData } = await readFileRaw(handle);

              if (isEncrypted) {
                  setPendingFile({
                      space: newFileSpace,
                      rawEncryptedData: encryptedData
                  });
                  setShowFileUnlockModal(true);
              } else {
                  setOpenFiles(prev => [...prev, newFileSpace]);
                  setCurrentFileId(newFileSpace.id);
                  setAccounts(Array.isArray(parsed) ? parsed : []);
              }
          }
      } catch (e: any) {
          if (e.name !== 'AbortError') {
              console.error(e);
              showToast("Error opening file", 'error');
          }
      }
  };

  const handleLegacyFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (ev) => {
          if (ev.target?.result) {
              const text = ev.target.result as string;
              const { newFileSpace, parsed, isEncrypted, encryptedData } = parseRawFileContent(text, file.name, null);

              if (isEncrypted) {
                  setPendingFile({
                      space: newFileSpace,
                      rawEncryptedData: encryptedData
                  });
                  setShowFileUnlockModal(true);
              } else {
                  setOpenFiles(prev => [...prev, newFileSpace]);
                  setCurrentFileId(newFileSpace.id);
                  setAccounts(Array.isArray(parsed) ? parsed : []);
                  showToast("File opened in Read-Only mode. Save manually.", 'info');
              }
          }
      };
      reader.readAsText(file);
      e.target.value = ''; // Reset input
  };

  const handleOpenFolder = async () => {
     if (!fileSystemClient.supported) {
         alert("Folder access requires a modern browser (Chrome, Edge, Opera). Please open individual files instead.");
         return;
     }
     try {
         const dirHandle = await fileSystemClient.openDirectory();
         const entries = await fileSystemClient.getDirectoryEntries(dirHandle);

         const jsonFiles = entries.filter(e => e.kind === 'file' && e.name.toLowerCase().endsWith('.json'));

         if (jsonFiles.length === 0) {
             showToast("No JSON files found in this folder.", 'info');
             return;
         }

         const newSpaces: FileSpace[] = [];
         let encryptedCount = 0;

         for (const entry of jsonFiles) {
             try {
                const fileHandle = entry.handle as FileSystemFileHandle;
                const { newFileSpace, isEncrypted } = await readFileRaw(fileHandle);

                // Avoid duplicates
                if (!openFiles.some(f => f.displayName === newFileSpace.displayName)) {
                    // We add it to the list even if encrypted, but without password.
                    // Accessing it will trigger unlock.
                    newSpaces.push(newFileSpace);
                    if (isEncrypted) encryptedCount++;
                }
             } catch (err) {
                 console.warn(`Skipping file ${entry.name}`, err);
             }
         }

         if (newSpaces.length > 0) {
             setOpenFiles(prev => [...prev, ...newSpaces]);
             showToast(`Added ${newSpaces.length} files (${encryptedCount} encrypted).`, 'success');
         } else {
             showToast("No new files added.", 'info');
         }

     } catch (e: any) {
         if (e.name !== 'AbortError') {
             console.error(e);
             showToast("Error opening folder", 'error');
         }
     }
  };

  const handleCreateFile = async () => {
      if (!fileSystemClient.supported) {
          // Fallback: Create virtual file
          const newFileId = uuidv4();
          const newFileSpace: FileSpace = {
              id: newFileId,
              displayName: 'Untitled.json',
              handle: null,
              isEncrypted: false,
              isVirtual: true
          };
          setOpenFiles(prev => [...prev, newFileSpace]);
          setCurrentFileId(newFileId);
          setAccounts([]);
          return;
      }

      try {
          const handle = await fileSystemClient.createFile({
              suggestedName: '2fa-accounts.json',
              types: [{ description: 'JSON File', accept: { 'application/json': ['.json'] } }],
          });

          const newFileId = uuidv4();
          const newFileSpace: FileSpace = {
              id: newFileId,
              displayName: handle.name,
              handle: handle,
              isEncrypted: false,
          };

          setOpenFiles(prev => [...prev, newFileSpace]);
          setCurrentFileId(newFileId);
          setAccounts([]);

          // Initialize empty file
          const writable = await handle.createWritable();
          await writable.write("[]");
          await writable.close();

      } catch (e: any) {
          if (e.name !== 'AbortError') console.error(e);
      }
  };

  // Unlock logic for Pending File
  const handleUnlockFile = async (password: string) => {
      if (!pendingFile) return;

      const { data, salt } = pendingFile.rawEncryptedData;

      const decrypted = await decryptData(data, password, salt);
      if (decrypted) {
          const accountsData = JSON.parse(decrypted);

          // If this was a pending NEW file not in list
          if (!openFiles.some(f => f.id === pendingFile.space.id)) {
             const unlockedSpace = { ...pendingFile.space, password: password };
             setOpenFiles(prev => [...prev, unlockedSpace]);
             setCurrentFileId(unlockedSpace.id);
             setAccounts(accountsData);
          } 
          // If this was an existing LOCKED file in list (folder view)
          else {
             setOpenFiles(prev => prev.map(f => f.id === pendingFile.space.id ? { ...f, password: password } : f));
             setCurrentFileId(pendingFile.space.id);
             setAccounts(accountsData);
          }

          setPendingFile(null);
          setShowFileUnlockModal(false);
      } else {
          // Keep modal open, show error (handled by modal component catch)
          throw new Error("Wrong Password");
      }
  };

  const handleCancelUnlock = () => {
      // If user cancels unlock
      if (pendingFile) {
          // If it was already in the list (folder view), remove it because user couldn't unlock
          if (openFiles.some(f => f.id === pendingFile.space.id)) {
              setOpenFiles(prev => prev.filter(f => f.id !== pendingFile.space.id));
          }
          // If it was new, just don't add it.
      }
      setPendingFile(null);
      setShowFileUnlockModal(false);
  };


  const handleFileRename = (id: string) => {
      const name = prompt(t.labelRenameFile);
      if (name) {
          setOpenFiles(prev => prev.map(f => f.id === id ? { ...f, displayName: name } : f));
      }
  };

  const handleCloseFile = (id: string) => {
      if (confirm(t.confirmCloseFile)) {
          setOpenFiles(prev => prev.filter(f => f.id !== id));
          if (currentFileId === id) {
              setCurrentFileId(null);
              setAccounts([]);
          }
      }
  };

  // --- FILE ENCRYPTION MANAGEMENT ---

  const handleSetFilePassword = async (password: string) => {
      if (!currentFileId) return;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file) {
          const updatedFile = { ...file, isEncrypted: true, password: password };
          await saveToFile(updatedFile, accounts);
          setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
          showToast(t.filePassSet, 'success');
      }
  };

  const handleRemoveFilePassword = async (currPass: string) => {
      if (!currentFileId) return false;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file && file.password === currPass) {
           const updatedFile = { ...file, isEncrypted: false, password: undefined };
           await saveToFile(updatedFile, accounts);
           setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
           showToast(t.filePassRemoved, 'success');
           return true;
      }
      return false;
  };

  const handleChangeFilePassword = async (oldPass: string, newPass: string) => {
      if (!currentFileId) return false;
      const file = openFiles.find(f => f.id === currentFileId);

      if (file && file.password === oldPass) {
          const updatedFile = { ...file, isEncrypted: true, password: newPass };
          await saveToFile(updatedFile, accounts);
          setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
          showToast("File password changed successfully", 'success');
          return true;
      }
      return false;
  };


  // Public Save Wrapper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
      setAccounts(newAccounts);
      saveAccountsInternal(newAccounts, sessionKey, activeTab);
  };

  // ... Existing Handlers ...
  const handleAddLogo = (logo: AppLogo) => {
      saveCustomLogos([...customLogos, logo]);
      showToast(translations[lang].logoAdded, 'success');
  };
  const saveCustomLogos = (logos: AppLogo[]) => {
      setCustomLogos(logos);
      localStorage.setItem(STORAGE_KEYS.customLogos, JSON.stringify(logos));
  };
  const handleDeleteLogo = (id: string) => {
      saveCustomLogos(customLogos.filter(l => l.id !== id));
      showToast('Logo deleted', 'success');
  };
  const handleBatchDeleteLogos = (ids: string[]) => {
      const idSet = new Set(ids);
      saveCustomLogos(customLogos.filter(l => !idSet.has(l.id)));
      showToast(`${ids.length} logos deleted`, 'success');
  };
  const handleImportLogos = (newLogos: AppLogo[]) => {
      const existingIds = new Set(customLogos.map(l => l.id));
      const filteredNew = newLogos.filter(l => !existingIds.has(l.id));
      if (filteredNew.length === 0) {
          showToast('No new logos to import (all exist)', 'info');
          return;
      }
      saveCustomLogos([...customLogos, ...filteredNew]);
      showToast(`${filteredNew.length} logos imported`, 'success');
  };

  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
        showToast('Account updated successfully', 'success');
    } else {
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
        showToast('Account created successfully', 'success');
    }
    setEditingAccount(undefined);
  };

  const handleBatchSave = (updates: Partial<OTPAccount>) => {
      if (Object.keys(updates).length === 0) {
          setShowBatchEditModal(false);
          return;
      }
      const updatedAccounts = accounts.map(acc => {
          if (selectedIds.has(acc.id)) {
              return { ...acc, ...updates };
          }
          return acc;
      });
      saveAccounts(updatedAccounts);
      showToast(`Updated ${selectedIds.size} accounts`, 'success');
      setShowBatchEditModal(false);
      setSelectedIds(new Set());
  };

  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      logoId: item.logoId,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
    showToast(`${newItems.length} accounts imported`, 'success');
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      setAccounts(prevAccounts => {
        const updatedAccounts = prevAccounts.filter(a => a.id !== id);
        saveAccountsInternal(updatedAccounts, sessionKey, activeTab);
        return updatedAccounts;
      });
      setSelectedIds(prev => {
        if (prev.has(id)) {
            const next = new Set(prev);
            next.delete(id);
            return next;
        }
        return prev;
      });
      setVisibleQRIds(prev => {
          if (prev.has(id)) {
              const next = new Set(prev);
              next.delete(id);
              return next;
          }
          return prev;
      });
      showToast('Account deleted', 'success');
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          setAccounts(prevAccounts => {
              const updatedAccounts = prevAccounts.filter(a => !selectedIds.has(a.id));
              saveAccountsInternal(updatedAccounts, sessionKey, activeTab);
              return updatedAccounts;
          });
          showToast(`Deleted ${selectedIds.size} accounts`, 'success');
          setSelectedIds(new Set());
          // Update QR visibility
          setVisibleQRIds(prev => {
             const next = new Set(prev);
             selectedIds.forEach(id => next.delete(id));
             return next;
          });
      }
  };

  // QR Visibility Handlers
  const handleToggleQR = (id: string) => {
      setVisibleQRIds(prev => {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
      });
  };

  // Smart Toggle for Selection
  const handleToggleSelectedQR = () => {
      const selectedArray = Array.from(selectedIds);
      const allSelectedVisible = selectedArray.every(id => visibleQRIds.has(id));

      setVisibleQRIds(prev => {
          const next = new Set(prev);
          if (allSelectedVisible) {
              // Hide all selected
              selectedArray.forEach(id => next.delete(id));
          } else {
              // Show all selected
              selectedArray.forEach(id => next.add(id));
          }
          return next;
      });
  };

  const filteredAccounts = (function() {
    if (!searchQuery.trim()) return accounts;
    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);
    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      return keywords.every(kw => searchString.includes(kw));
    });
  })();

  const t = translations[lang];
  const theme = getThemeClasses();

  const selectedAreAllVisible = selectedIds.size > 0 && Array.from(selectedIds).every(id => visibleQRIds.has(id));

  // Helper for theme classes
  function getThemeClasses() {
     const common = {
         tabActive: 'bg-white shadow-sm'
     };
     if (activeTab === 'local') {
         return {
             ...common,
             primaryBg: 'bg-blue-600',
             primaryHover: 'hover:bg-blue-700',
             textGradient: 'from-blue-700 to-blue-500',
             focusRing: 'focus:ring-blue-500',
             checkboxText: 'text-blue-600',
             iconBg: 'bg-blue-600',
             tabActive: `${common.tabActive} text-blue-600`,
             lightBg: 'bg-blue-50',
             borderColor: 'border-blue-100'
         };
     } else if (activeTab === 'file') {
         return {
             ...common,
             primaryBg: 'bg-emerald-600',
             primaryHover: 'hover:bg-emerald-700',
             textGradient: 'from-emerald-700 to-emerald-500',
             focusRing: 'focus:ring-emerald-500',
             checkboxText: 'text-emerald-600',
             iconBg: 'bg-emerald-600',
             tabActive: `${common.tabActive} text-emerald-600`,
             lightBg: 'bg-emerald-50',
             borderColor: 'border-emerald-100'
         };
     } else {
         return {
             ...common,
             primaryBg: 'bg-orange-600',
             primaryHover: 'hover:bg-orange-700',
             textGradient: 'from-orange-700 to-orange-500',
             focusRing: 'focus:ring-orange-500',
             checkboxText: 'text-orange-600',
             iconBg: 'bg-orange-600',
             tabActive: `${common.tabActive} text-orange-600`,
             lightBg: 'bg-orange-50',
             borderColor: 'border-orange-100'
         };
     }
  }

  // --- Render ---

  if (isLocked) {
      return (
        <LanguageContext.Provider value={{ lang, t, setLang }}>
            <LockScreen onUnlock={handleUnlock} onReset={handleResetLock} />
        </LanguageContext.Provider>
      );
  }

  // Active File Reference
  const currentFile = openFiles.find(f => f.id === currentFileId);

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <ToastContainer toasts={toasts} onClose={removeToast} />
      {/* Hidden input for fallback file loading */}
      <input type="file" ref={fileInputRef} className="hidden" accept=".json,application/json" onChange={handleLegacyFileSelect} />

      <div className="min-h-screen flex flex-col bg-gray-50 text-gray-800 font-sans pb-40 sm:pb-24">

        {/* Navbar */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className={`${theme.iconBg} p-2 rounded-lg transition-colors duration-300`}>
                  <ShieldCheck className="text-white h-6 w-6" />
                </div>
                <h1 className={`text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r ${theme.textGradient} hidden md:block transition-all duration-300`}>
                  {t.appTitle}
                </h1>
              </div>

              <div className={`flex-1 transition-all duration-300 ${isSearchFocused ? 'max-w-full' : 'max-w-md mx-auto'}`}>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className={`h-5 w-5 text-gray-400 group-focus-within:${theme.checkboxText} transition-colors`} />
                    </div>
                    <input
                        type="text"
                        className={`block w-full pl-10 pr-10 py-2 border border-gray-300 rounded-lg leading-5 bg-gray-50 text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 ${theme.focusRing} focus:border-transparent transition-all sm:text-sm`}
                        placeholder="Search issuer, account..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onFocus={() => setIsSearchFocused(true)}
                        onBlur={() => setIsSearchFocused(false)}
                    />
                    {searchQuery && (
                      <button 
                        onMouseDown={(e) => { e.preventDefault(); setSearchQuery(''); }}
                        className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600 cursor-pointer"
                      >
                         <X size={16} />
                      </button>
                    )}
                </div>
              </div>

              <div className={`flex items-center gap-2 shrink-0 transition-all duration-300 ${isSearchFocused ? 'w-0 opacity-0 overflow-hidden m-0 p-0' : 'w-auto opacity-100'}`}>
                <div className="flex p-1 bg-gray-100 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? theme.tabActive 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <HardDrive size={16} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('file')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'file' 
                        ? theme.tabActive 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <FolderOpen size={16} />
                    <span className="hidden sm:inline">{t.tabFile}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? theme.tabActive 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <Zap size={16} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Password / Security Settings */}
                <button 
                  onClick={() => setShowPasswordModal(true)}
                  className={`ml-1 p-2 ${hasPassword || (activeTab === 'file' && currentFile?.isEncrypted) ? 'text-green-600' : 'text-gray-400'} hover:bg-gray-100 rounded-full transition relative group`}
                  title={activeTab === 'file' ? t.fileSecurityTitle : t.securityTitle}
                  disabled={activeTab === 'file' && !currentFileId}
                >
                  <Lock size={20} />
                  {/* Indicator Dot */}
                  {((activeTab !== 'file' && hasPassword) || (activeTab === 'file' && currentFile?.isEncrypted)) && (
                      <span className="absolute top-1 right-1 w-2 h-2 bg-green-500 rounded-full ring-2 ring-white"></span>
                  )}
                </button>

                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className={`ml-1 p-2 text-gray-500 hover:${theme.checkboxText} hover:bg-gray-100 rounded-full transition`}
                  title="Switch Language"
                >
                  <Languages size={20} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
                    <button 
                        onClick={() => setShowLogoManager(false)}
                        className="text-gray-500 hover:text-gray-700 font-medium text-sm flex items-center gap-1"
                    >
                        &larr; Back to Accounts
                    </button>
                    <h2 className="text-2xl font-bold text-gray-800 ml-2">{t.manageLogos}</h2>
                 </div>
                 <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6">
                     <LogoManagerModal 
                        onClose={() => setShowLogoManager(false)}
                        logos={customLogos}
                        onAddLogo={handleAddLogo}
                        onDeleteLogo={handleDeleteLogo}
                        onBatchDeleteLogo={handleBatchDeleteLogos}
                        onImportLogos={handleImportLogos}
                        inline={true} 
                        color={themeColor}
                    />
                 </div>
            </main>
        ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

          <div className={`mb-6 p-4 rounded-lg border flex items-start gap-3 ${theme.lightBg} ${theme.borderColor}`}>
             <div className="mt-0.5">
               {activeTab === 'local' ? <Lock size={18} /> : (activeTab === 'file' ? <FolderOpen size={18} /> : <Zap size={18} />)}
             </div>
             <div className="text-sm">
               <p className="font-semibold text-gray-800">
                  {activeTab === 'local' ? t.bannerLocalTitle : (activeTab === 'file' ? t.bannerFileTitle : t.bannerSessionTitle)}
               </p>
               <p className="opacity-80 text-gray-600">
                 {activeTab === 'local' ? t.bannerLocalDesc : (activeTab === 'file' ? t.bannerFileDesc : t.bannerSessionDesc)}
               </p>
             </div>
          </div>

          {/* File Space Manager (Only for File Mode) */}
          {activeTab === 'file' && (
              <div className="mb-6 bg-white p-4 rounded-lg border shadow-sm space-y-4">
                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
                      <div className="flex gap-2 shrink-0">
                          <button onClick={handleOpenFile} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap">
                              <FolderOpen size={16} /> {t.btnOpenFile}
                          </button>
                          <button onClick={handleOpenFolder} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap">
                              <FolderOpen size={16} /> {t.btnOpenFolder}
                          </button>
                      </div>
                      <button onClick={handleCreateFile} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap">
                          <FilePlus size={16} /> {t.btnCreateFile}
                      </button>

                      <div className="h-px w-full sm:h-6 sm:w-px bg-gray-300 mx-0 sm:mx-2"></div>

                      <div className="flex gap-2 overflow-x-auto pb-1 sm:pb-0 w-full no-scrollbar">
                          {openFiles.length === 0 && <span className="text-sm text-gray-400 self-center italic">No files open</span>}
                          {openFiles.map(f => (
                              <button 
                                key={f.id}
                                onClick={() => handleSwitchFile(f.id)}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-md border text-sm whitespace-nowrap transition shrink-0 ${currentFileId === f.id ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                              >
                                  {f.isEncrypted ? <Lock size={12} className={f.password ? "text-green-500" : "text-gray-400"}/> : <FileJson size={12} className="opacity-50"/>}
                                  {f.displayName}
                                  {f.isVirtual && <AlertTriangle size={10} className="text-orange-400" />}
                              </button>
                          ))}
                      </div>
                  </div>

                  {/* Active File Actions */}
                  {currentFile && (
                      <div className="flex flex-col gap-3 pt-3 border-t border-gray-100">
                           <div className="flex flex-wrap items-center justify-between gap-2">
                               <div className="flex items-center gap-3">
                                    <span className="text-sm font-semibold text-gray-700 truncate max-w-[200px]">{currentFile.displayName}</span>
                                    <span className={`text-xs px-2 py-0.5 rounded-full border ${currentFile.isEncrypted ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-500 border-gray-200'}`}>
                                        {currentFile.isEncrypted ? t.fileEncrypted : t.filePlain}
                                    </span>
                                    {currentFile.isVirtual && (
                                        <span className="text-xs px-2 py-0.5 rounded-full border bg-orange-50 text-orange-700 border-orange-200 flex items-center gap-1">
                                            <AlertTriangle size={10} /> Read-Only
                                        </span>
                                    )}
                               </div>
                               <div className="flex gap-2">
                                    <button onClick={() => handleFileRename(currentFile.id)} className="p-1.5 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded" title={t.labelRenameFile}>
                                        <PenLine size={16} />
                                    </button>
                                    <button onClick={() => handleCloseFile(currentFile.id)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded" title={t.btnCloseFile}>
                                        <XCircle size={16} />
                                    </button>
                               </div>
                           </div>

                           {/* Warning banner for Virtual Files */}
                           {currentFile.isVirtual && (
                               <div className="flex items-start gap-2 text-xs text-orange-700 bg-orange-50 p-2 rounded border border-orange-100">
                                   <AlertTriangle size={14} className="mt-0.5 shrink-0" />
                                   <p>{t.virtualFileWarning}</p>
                               </div>
                           )}

                           {/* Manual Save Button for Virtual Files */}
                           {currentFile.isVirtual && (
                               <button 
                                 onClick={() => saveToFile(currentFile, accounts)}
                                 className="self-start flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition shadow-sm"
                               >
                                   <Download size={16} /> {t.btnDownloadManual}
                               </button>
                           )}
                      </div>
                  )}
              </div>
          )}

          <div className="flex flex-col xl:flex-row gap-4 mb-8 justify-between items-start xl:items-center">
             <div className="flex flex-wrap gap-3 w-full sm:w-auto flex-nowrap overflow-x-auto pb-1 sm:pb-0">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    disabled={activeTab === 'file' && (!currentFileId || (currentFile?.isEncrypted && !currentFile?.password))}
                    className={`flex items-center gap-2 ${theme.primaryBg} ${theme.primaryHover} text-white px-4 py-2.5 rounded-lg shadow-sm hover:shadow transition font-medium whitespace-nowrap disabled:opacity-50 disabled:cursor-not-allowed`}
                    title={t.addAccount}
                >
                    <Plus size={18} /> <span className="hidden sm:inline">{t.addAccount}</span>
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    disabled={activeTab === 'file' && (!currentFileId || (currentFile?.isEncrypted && !currentFile?.password))}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap disabled:opacity-50"
                    title={t.importBatch}
                >
                    <Upload size={18} /> <span className="hidden sm:inline">{t.importBatch}</span>
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium disabled:opacity-50 whitespace-nowrap"
                    title={t.exportBatch}
                >
                    <Download size={18} /> <span className="hidden sm:inline">{t.exportBatch}</span>
                </button>
                <button 
                    onClick={() => setShowLogoManager(true)}
                    className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap"
                    title={t.manageLogos}
                >
                    <ImageIcon size={18} /> <span className="hidden sm:inline">{t.manageLogos}</span>
                </button>

                 {filteredAccounts.length > 0 && (
                    <button 
                       onClick={handleSelectAll}
                       className="flex items-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2.5 rounded-lg transition font-medium whitespace-nowrap ml-auto sm:ml-0"
                       title={selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                    >
                       {selectedIds.size === filteredAccounts.length ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                 )}
             </div>
          </div>

          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
              <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    logo={customLogos.find(l => l.id === acc.logoId)}
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                    showQR={visibleQRIds.has(acc.id)}
                    onToggleQR={handleToggleQR}
                    color={themeColor}
                />
              ))}
            </div>
          )}
        </main>
        )}

        {selectedIds.size > 0 && !showLogoManager && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4 px-0 sm:px-4">
                    <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                        <span className="font-semibold text-gray-700">
                            {selectedIds.size} {t.selected}
                        </span>
                    </div>

                    <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-3">
                        <button 
                           onClick={() => setShowBatchEditModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Edit2 size={16} /> {t.btnBatchEdit}
                        </button>
                        <button 
                           onClick={() => setShowExportModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Download size={16} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleToggleSelectedQR}
                           className={`flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg transition text-sm font-medium ${selectedAreAllVisible ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
                        >
                            <QrCode size={16} /> {selectedAreAllVisible ? t.hideQR : t.showQR}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 text-red-600 px-4 py-2.5 rounded-lg transition text-sm font-medium"
                        >
                            <Trash2 size={16} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                initialData={editingAccount}
                logos={customLogos}
                color={themeColor}
            />
        )}
        {showBatchEditModal && (
          <BatchEditModal 
             onClose={() => setShowBatchEditModal(false)}
             onSave={handleBatchSave}
             logos={customLogos}
             color={themeColor}
          />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview}
            color={themeColor} 
          />
        )}

        {/* App Security Modal */}
        {showPasswordModal && (
            <PasswordSettingsModal 
                onClose={() => setShowPasswordModal(false)}
                hasPassword={activeTab === 'file' ? (currentFile?.isEncrypted || false) : hasPassword}
                onSetPassword={activeTab === 'file' ? handleSetFilePassword : handleSetPassword}
                onRemovePassword={activeTab === 'file' ? handleRemoveFilePassword : handleRemovePassword}
                onChangePassword={activeTab === 'file' ? handleChangeFilePassword : handleChangePassword}
                color={themeColor}
            />
        )}

        {/* File Unlock Modal (For Pending Files) */}
        {showFileUnlockModal && pendingFile && (
             <PasswordSettingsModal 
                onClose={handleCancelUnlock}
                hasPassword={false} // Mode: Unlock (Similar to set but verify against file)
                isUnlock={true} // Force Unlock Mode
                onSetPassword={handleUnlockFile} // Reusing setPassword prop for unlock submission
                onRemovePassword={async () => true}
                color={themeColor}
             />
        )}

        <ImportPreviewModal
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
           logos={customLogos}
           color={themeColor}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
                color={themeColor}
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

