             <div>
                <label className="block text-xs font-medium text-gray-700 mb-1">{t.labelAccount}</label>
                <input required type="text" placeholder="e.g. alice@example.com" className={`w-full p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.account} onChange={e => setFormData({...formData, account: e.target.value})} />
             </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">{t.labelSecret}</label>
            <div className="flex gap-2">
                <input required type="text" placeholder="Base32 Secret" className={`flex-1 p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono`} 
                value={formData.secret} onChange={e => setFormData({...formData, secret: e.target.value})} />
                <button type="button" onClick={generateSecret} className="px-3 py-2 bg-gray-100 text-gray-600 rounded-lg hover:bg-gray-200" title={t.btnGenerate}>
                    <RefreshCw size={16} />
                </button>
            </div>
            {!initialData && <p className="text-[10px] text-gray-500 mt-1">{t.msgLeaveBlank}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-xs font-medium text-gray-700 mb-1">{t.labelPeriod}</label>
                <input type="number" min="15" step="1" className={`w-full p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.period} onChange={e => setFormData({...formData, period: parseInt(e.target.value) || 30})} />
             </div>
             <div>
                <label className="block text-xs font-medium text-gray-700 mb-1">{t.labelNotes}</label>
                <input type="text" placeholder="Tag or description" className={`w-full p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                  value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
             </div>
          </div>

          <div className="relative">
              <label className="block text-xs font-medium text-gray-700 mb-1">{t.labelLogo}</label>
              <LogoSelect 
                 logos={logos}
                 value={formData.logoId}
                 onChange={(val) => setFormData({...formData, logoId: val})}
                 color={color}
              />
          </div>

          <button type="submit" className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-4 text-sm`}>
            {t.btnSave}
          </button>
        </form>
      ) : (
        <QRCodeScanner onScan={handleScan} onClose={onClose} />
      )}
    </Modal>
  );
};

