// --- Batch Export Modal ---
interface BatchExportModalProps {
    accounts: OTPAccount[];
    onClose: () => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [tab, setTab] = useState<'csv' | 'uri' | 'qr' | 'migration'>('csv');
    const [includeLogo, setIncludeLogo] = useState(true);

    // Chunking for Migration URI
    const [migrationChunkIndex, setMigrationChunkIndex] = useState(0);
    const CHUNK_SIZE = 10;

    const migrationChunks = React.useMemo(() => {
        const chunks = [];
        for (let i = 0; i < accounts.length; i += CHUNK_SIZE) {
            chunks.push(accounts.slice(i, i + CHUNK_SIZE));
        }
        return chunks.length > 0 ? chunks : [[]];
    }, [accounts]);

    const getCSV = () => {
        const header = "Issuer,Account,Secret,Period,Notes,LogoID\n";
        const rows = accounts.map(a => 
            `${a.issuer},${a.account},${a.secret},${a.period},${a.notes || ''},${includeLogo ? (a.logoId || '') : ''}`
        ).join("\n");
        return header + rows;
    };

    const getURIs = () => {
        return accounts.map(a => 
            `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`
        ).join("\n");
    };

    const getMigrationURI = (subset: OTPAccount[]) => {
        try {
            // Map internal OTPAccount to Migration OTPAccount
            const mappedAccounts = subset.map(acc => {
                let algo = Algorithm.SHA1;
                if (acc.algorithm?.toUpperCase() === 'SHA256') algo = Algorithm.SHA256;
                if (acc.algorithm?.toUpperCase() === 'SHA512') algo = Algorithm.SHA512;
                if (acc.algorithm?.toUpperCase() === 'MD5') algo = Algorithm.MD5;

                let digits = DigitCount.SIX;
                if (acc.digits === 8) digits = DigitCount.EIGHT;

                return {
                    secret: acc.secret,
                    name: acc.account,
                    issuer: acc.issuer,
                    algorithm: algo,
                    digits: digits,
                    type: OtpType.TOTP,
                    counter: 0
                };
            });
            return generateMigrationURI(mappedAccounts);
        } catch (e) {
            console.error(e);
            return "Error generating migration URI";
        }
    };

    const handleCopy = () => {
        let content = "";
        if (tab === 'csv') content = getCSV();
        else if (tab === 'uri') content = getURIs();
        else if (tab === 'migration') content = getMigrationURI(migrationChunks[migrationChunkIndex]);

        if (content) {
            navigator.clipboard.writeText(content);
            alert(t.copied);
        }
    };

    const handleDownload = () => {
         const content = tab === 'csv' ? getCSV() : getURIs(); // Migration download not typical as file
         const blob = new Blob([content], { type: 'text/plain' });
         const url = URL.createObjectURL(blob);
         const a = document.createElement('a');
         a.href = url;
         a.download = `secureauth-export-${Date.now()}.${tab === 'csv' ? 'csv' : 'txt'}`;
         a.click();
         URL.revokeObjectURL(url);
    };

    const currentMigrationUri = tab === 'migration' ? getMigrationURI(migrationChunks[migrationChunkIndex]) : '';

    return (
        <Modal title={t.modalExportTitle} onClose={onClose} className="max-w-3xl">
            <div className="flex gap-4 mb-4 border-b overflow-x-auto">
                <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('csv')}>{t.tabCSV}</button>
                <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('uri')}>{t.tabURI}</button>
                <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('qr')}>{t.tabQR}</button>
                <button className={`pb-2 px-1 font-medium text-sm transition whitespace-nowrap ${tab === 'migration' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500'}`} onClick={() => setTab('migration')}>Google Auth</button>
            </div>

            <div className="mb-4">
                 {tab === 'csv' && <p className="text-xs text-gray-500 mb-2">{t.descCSV}</p>}
                 {tab === 'uri' && <p className="text-xs text-gray-500 mb-2">{t.descURI}</p>}
                 {tab === 'qr' && <p className="text-xs text-gray-500 mb-2">{t.descQR}</p>}
                 {tab === 'migration' && <p className="text-xs text-gray-500 mb-2">Scan this with Google Authenticator (Import &gt; Scan QR).</p>}

                 {tab === 'csv' && (
                     <label className="flex items-center gap-2 text-sm text-gray-600 mb-2">
                         <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                         {t.labelIncludeLogo}
                     </label>
                 )}
            </div>

            {tab === 'migration' ? (
                <div className="flex flex-col items-center gap-4">
                    {/* Chunk Navigation */}
                    {migrationChunks.length > 1 && (
                        <div className="flex items-center gap-4 bg-gray-100 px-4 py-2 rounded-full">
                            <button 
                                onClick={() => setMigrationChunkIndex(prev => Math.max(0, prev - 1))}
                                disabled={migrationChunkIndex === 0}
                                className="p-1 hover:bg-white rounded-full disabled:opacity-30"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <span className="text-xs font-mono font-bold">
                                Part {migrationChunkIndex + 1} / {migrationChunks.length}
                            </span>
                            <button 
                                onClick={() => setMigrationChunkIndex(prev => Math.min(migrationChunks.length - 1, prev + 1))}
                                disabled={migrationChunkIndex === migrationChunks.length - 1}
                                className="p-1 hover:bg-white rounded-full disabled:opacity-30"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    )}

                    <div className="bg-white p-4 rounded-lg border shadow-sm">
                        {currentMigrationUri && !currentMigrationUri.startsWith("Error") ? (
                            <QRCodeSVG value={currentMigrationUri} size={200} />
                        ) : (
                            <div className="w-48 h-48 flex items-center justify-center text-red-500 text-xs">Error generating QR</div>
                        )}
                    </div>

                    {migrationChunks.length > 1 && (
                        <p className="text-xs text-orange-600 flex items-center gap-1">
                            <Info size={12} /> Scan each QR code sequentially.
                        </p>
                    )}

                    <div className="w-full">
                        <p className="text-[10px] text-gray-500 mb-1">Migration URI:</p>
                        <input type="text" readOnly value={currentMigrationUri} className="w-full p-2 border rounded bg-gray-50 text-[10px] font-mono" />
                    </div>
                    <button onClick={handleCopy} className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium flex items-center justify-center gap-2 text-sm`}>
                         <Copy size={16} /> {t.btnCopy}
                    </button>
                </div>
            ) : tab !== 'qr' ? (
                <div className="space-y-4">
                    <textarea 
                        readOnly 
                        className={`w-full h-64 p-3 border rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono text-[10px] whitespace-pre bg-gray-50`}
                        value={tab === 'csv' ? getCSV() : getURIs()}
                    />
                    <div className="flex gap-3">
                        <button onClick={handleCopy} className="flex-1 border border-gray-300 hover:bg-gray-50 text-gray-700 py-2 rounded-lg font-medium flex items-center justify-center gap-2 text-sm">
                             <Copy size={16} /> {t.btnCopy}
                        </button>
                        <button onClick={handleDownload} className={`flex-1 ${theme.btn} text-white py-2 rounded-lg font-medium flex items-center justify-center gap-2 text-sm`}>
                             <Download size={16} /> Download
                        </button>
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 max-h-[60vh] overflow-y-auto p-2 bg-gray-50 rounded-lg border">
                    {accounts.map((a, i) => {
                         const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                         return (
                             <div key={i} className="bg-white p-3 rounded-lg border shadow-sm flex flex-col items-center text-center">
                                 <div className="bg-white p-1 rounded mb-2">
                                     <QRCodeSVG value={uri} size={80} />
                                 </div>
                                 <p className="font-bold text-[10px] truncate w-full">{a.issuer}</p>
                                 <p className="text-[9px] text-gray-500 truncate w-full">{a.account}</p>
                             </div>
                         );
                    })}
                </div>
            )}
        </Modal>
    );
};

// ... PasswordSettingsModal remains unchanged ...
interface PasswordSettingsModalProps {
    onClose: () => void;
    hasPassword?: boolean;
    isUnlock?: boolean;
    onSetPassword: (pass: string) => Promise<void>;
    onRemovePassword: (currPass: string) => Promise<boolean>;
    onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
    color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, isUnlock = false, onSetPassword, onRemovePassword, onChangePassword, color = 'blue' 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [mode, setMode] = useState<'menu' | 'set' | 'change' | 'remove' | 'unlock'>(isUnlock ? 'unlock' : (hasPassword ? 'menu' : 'set'));

    // Inputs
    const [pass1, setPass1] = useState('');
    const [pass2, setPass2] = useState('');
    const [oldPass, setOldPass] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (mode === 'set' || mode === 'unlock') {
                if (mode === 'set' && pass1 !== pass2) {
                    setError(t.passwordsNoMatch);
                    setLoading(false);
                    return;
                }
                await onSetPassword(pass1);
                onClose();
            } else if (mode === 'change') {
                if (pass1 !== pass2) {
                    setError(t.passwordsNoMatch);
                    setLoading(false);
                    return;
                }
                if (onChangePassword) {
                    const success = await onChangePassword(oldPass, pass1);
                    if (!success) setError(t.wrongPassword);
                    else onClose();
                }
            } else if (mode === 'remove') {
                const success = await onRemovePassword(oldPass);
                if (!success) setError(t.wrongPassword);
                else onClose();
            }
        } catch (err: any) {
             setError(err.message || "Operation failed");
        } finally {
            setLoading(false);
        }
    };

    const headerTitle = () => {
        if (mode === 'unlock') return t.unlockFile;
        if (mode === 'set') return t.setPassword;
        if (mode === 'change') return t.changePassword;
        if (mode === 'remove') return t.removePassword;
        return t.securityTitle;
    };

    return (
        <Modal title={headerTitle()} onClose={onClose} className="max-w-sm">
             {mode === 'menu' ? (
                 <div className="space-y-3 py-2">
                     <button onClick={() => setMode('change')} className="w-full flex items-center justify-between p-3 border rounded-xl hover:bg-gray-50 transition group">
                         <div className="flex items-center gap-3">
                             <div className="bg-blue-100 p-1.5 rounded-lg text-blue-600"><KeyRound size={16} /></div>
                             <span className="font-medium text-gray-700 text-sm">{t.changePassword}</span>
                         </div>
                         <ArrowRight size={16} className="text-gray-300 group-hover:text-gray-500" />
                     </button>
                     <button onClick={() => setMode('remove')} className="w-full flex items-center justify-between p-3 border rounded-xl hover:bg-red-50 hover:border-red-100 transition group">
                         <div className="flex items-center gap-3">
                             <div className="bg-red-100 p-1.5 rounded-lg text-red-600"><ShieldOff size={16} /></div>
                             <span className="font-medium text-gray-700 text-sm">{t.removePassword}</span>
                         </div>
                         <ArrowRight size={16} className="text-gray-300 group-hover:text-red-400" />
                     </button>
                 </div>
             ) : (
                 <form onSubmit={handleSubmit} className="space-y-4">
                     {error && <div className="bg-red-50 text-red-600 p-2.5 rounded-lg text-xs flex items-center gap-2"><AlertTriangle size={14}/> {error}</div>}

                     {(mode === 'change' || mode === 'remove') && (
                         <div>
                             <label className="block text-xs font-medium text-gray-700 mb-1">{mode === 'change' ? "Old Password" : t.enterPassword}</label>
                             <input type="password" required className={`w-full p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                                value={oldPass} onChange={e => setOldPass(e.target.value)} autoFocus />
                         </div>
                     )}

                     {(mode === 'set' || mode === 'change' || mode === 'unlock') && (
                         <div>
                             <label className="block text-xs font-medium text-gray-700 mb-1">
                                 {mode === 'change' ? "New Password" : (mode === 'unlock' ? t.enterFilePassword : t.enterPassword)}
                             </label>
                             <input type="password" required className={`w-full p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                                value={pass1} onChange={e => setPass1(e.target.value)} autoFocus={mode === 'set' || mode === 'unlock'} />
                         </div>
                     )}

                     {(mode === 'set' || mode === 'change') && (
                         <div>
                             <label className="block text-xs font-medium text-gray-700 mb-1">{t.confirmPassword}</label>
                             <input type="password" required className={`w-full p-2 text-sm border rounded-lg focus:ring-2 ${theme.ring} outline-none`} 
                                value={pass2} onChange={e => setPass2(e.target.value)} />
                         </div>
                     )}

                     <div className="flex gap-3 mt-4">
                         {!isUnlock && hasPassword && (
                             <button type="button" onClick={() => setMode('menu')} className="px-3 py-2 text-gray-500 hover:bg-gray-100 rounded-lg text-sm">
                                 {t.btnCancel}
                             </button>
                         )}
                         <button type="submit" disabled={loading} className={`flex-1 ${theme.btn} text-white py-2 rounded-lg font-medium text-sm disabled:opacity-50`}>
                             {loading ? '...' : (mode === 'remove' ? t.removePassword : (mode === 'unlock' ? t.unlock : t.btnSave))}
                         </button>
                     </div>
                 </form>
             )}
        </Modal>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { AppLogo } from '../types';
import { ChevronDown, Search, X, Check } from 'lucide-react';

interface LogoSelectProps {
  logos: AppLogo[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  color?: 'blue' | 'orange' | 'emerald';
}

const LogoSelect: React.FC<LogoSelectProps> = ({ logos, value, onChange, placeholder = "Select Logo", className = "", color = 'blue' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const [lockedHeight, setLockedHeight] = useState<string | undefined>(undefined);

  const selectedLogo = logos.find(l => l.id === value);
  const filteredLogos = logos.filter(l => l.name.toLowerCase().includes(search.toLowerCase()));

  // Theme styles
  const getThemeColor = () => {
      switch(color) {
          case 'emerald': return 'text-emerald-600 bg-emerald-50 border-emerald-200 ring-emerald-500';
          case 'orange': return 'text-orange-600 bg-orange-50 border-orange-200 ring-orange-500';
          default: return 'text-blue-600 bg-blue-50 border-blue-200 ring-blue-500';
      }
  };
  const activeClass = getThemeColor();

  const handleOpen = () => {
      setSearch("");
      setLockedHeight(undefined);
      setIsOpen(true);
  };

  useEffect(() => {
      if (isOpen) {
          // Measure height after render to lock it
          const timer = setTimeout(() => {
              if (containerRef.current) {
                  setLockedHeight(`${containerRef.current.offsetHeight}px`);
              }
          }, 10);
          return () => clearTimeout(timer);
      }
  }, [isOpen]);

  return (
    <>
      {/* Trigger Button */}
      <div className={`relative ${className}`}>
        <button
          type="button"
          onClick={handleOpen}
          className="w-full flex items-center justify-between border border-gray-300 rounded-lg p-2 bg-white text-left focus:ring-2 focus:ring-opacity-50 outline-none transition hover:border-gray-400"
          style={{ borderColor: isOpen ? 'transparent' : '' }}
        >
          {selectedLogo ? (
              <div className="flex items-center gap-2">
                  <div className="w-5 h-5 shrink-0 bg-gray-50 border rounded p-0.5 flex items-center justify-center">
                     <img src={selectedLogo.data} alt={selectedLogo.name} className="max-w-full max-h-full object-contain" />
                  </div>
                  <span className="truncate font-medium text-gray-700 text-sm">{selectedLogo.name}</span>
              </div>
          ) : (
              <span className="text-gray-500 text-sm">{placeholder}</span>
          )}
          <ChevronDown size={16} className="text-gray-400" />
        </button>
      </div>

      {/* Drawer Portal (Fixed Overlay) */}
      {isOpen && (
        <div className="fixed inset-0 z-[70] flex justify-center items-end sm:items-end">
          {/* Backdrop */}
          <div 
            className="absolute inset-0 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200"
            onClick={() => setIsOpen(false)}
          />

          {/* Drawer Content */}
          <div 
            ref={containerRef}
            style={{ height: lockedHeight }}
            className="relative w-full max-w-lg bg-white rounded-t-xl shadow-2xl max-h-[70vh] flex flex-col animate-in slide-in-from-bottom duration-300"
          >
            {/* Handle */}
            <div className="flex justify-center pt-2 pb-1 shrink-0 cursor-pointer" onClick={() => setIsOpen(false)}>
                <div className="w-10 h-1 bg-gray-300 rounded-full hover:bg-gray-400 transition" />
            </div>

            {/* Header with Search */}
            <div className="p-3 border-b shrink-0 flex gap-2 items-center">
                <div className="relative flex-1">
                    <Search size={14} className="absolute left-3 top-2.5 text-gray-400" />
                    <input
                        type="text"
                        className={`w-full pl-9 pr-4 py-2 bg-gray-100 border-transparent focus:bg-white border focus:ring-2 rounded-lg text-sm outline-none transition ${color === 'orange' ? 'focus:border-orange-500 focus:ring-orange-200' : (color === 'emerald' ? 'focus:border-emerald-500 focus:ring-emerald-200' : 'focus:border-blue-500 focus:ring-blue-200')}`}
                        placeholder="Search logos..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        autoFocus
                    />
                </div>
                <button onClick={() => setIsOpen(false)} className="p-1.5 bg-gray-100 rounded-full hover:bg-gray-200 text-gray-600">
                    <X size={16} />
                </button>
            </div>

            {/* List */}
            <div className="overflow-y-auto flex-1 p-2 space-y-1">
               <div 
                  className={`flex items-center justify-between p-2 cursor-pointer rounded-lg transition ${!value ? activeClass : 'hover:bg-gray-50 text-gray-600'}`}
                  onClick={() => { onChange(""); setIsOpen(false); }}
               >
                  <span className="font-medium text-sm">No Logo (Default)</span>
                  {!value && <Check size={14} />}
               </div>

               {filteredLogos.map(logo => (
                   <div
                      key={logo.id}
                      className={`flex items-center justify-between p-2 cursor-pointer rounded-lg transition ${value === logo.id ? activeClass : 'hover:bg-gray-50 text-gray-700'}`}
                      onClick={() => { onChange(logo.id); setIsOpen(false); }}
                   >
                      <div className="flex items-center gap-2">
                          <div className="w-8 h-8 shrink-0 bg-white border rounded-lg p-0.5 flex items-center justify-center">
                              <img src={logo.data} alt={logo.name} className="max-w-full max-h-full object-contain" />
                          </div>
                          <span className="font-medium text-sm">{logo.name}</span>
                      </div>
                      {value === logo.id && <Check size={14} />}
                   </div>
               ))}

               {filteredLogos.length === 0 && (
                   <div className="p-6 text-center text-gray-400 flex flex-col items-center">
                       <Search size={24} className="mb-2 opacity-20" />
                       <p className="text-xs">No logos found</p>
                   </div>
               )}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

