import React, { useState, useEffect, useRef } from 'react';
import { StorageMode, OTPAccount, ImportCandidate, AppLogo, FileSpace } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewModal, LogoManagerModal, BatchEditModal, PasswordSettingsModal } from './components/Modals';
import LockScreen from './components/LockScreen';
import { ToastContainer, ToastMessage, ToastType } from './components/Toast';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search, Image as ImageIcon, Edit2, ShieldAlert, QrCode, X, FileJson, FolderOpen, Save, FilePlus, PenLine, XCircle, Unlock, AlertTriangle, Sun, Moon, Monitor } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';
import { encryptData, decryptData, hashPassword, generateSalt } from './utils/crypto';
import fileSystemClient, { FileSystemFileHandle } from './service/FileSystemClient';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data',
  customLogos: 'secure_auth_custom_logos',
  lang: 'secure_auth_lang',
  passwordHash: 'secure_auth_password_hash',
  salt: 'secure_auth_salt',
  theme: 'secure_auth_theme'
};

interface PendingFile {
    space: FileSpace;
    rawEncryptedData: {
        isEncrypted: boolean;
        data: string;
        salt: string;
    }
}

type Theme = 'light' | 'dark' | 'system';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<StorageMode>('local');
  const [accounts, setAccounts] = useState<OTPAccount[]>([]);

  // Security State (App Lock for LocalStorage)
  const [isLocked, setIsLocked] = useState(false);
  const [hasPassword, setHasPassword] = useState(false);
  const [sessionKey, setSessionKey] = useState<string | null>(null); // To store password temporarily in memory
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // File Storage State
  const [openFiles, setOpenFiles] = useState<FileSpace[]>([]);
  const [currentFileId, setCurrentFileId] = useState<string | null>(null);

  // Pending File State (Waiting for decryption)
  const [pendingFile, setPendingFile] = useState<PendingFile | null>(null);
  const [showFileUnlockModal, setShowFileUnlockModal] = useState(false);

  // Fallback for non-supported browsers
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Theme Color derived from activeTab
  const themeColor = activeTab === 'local' ? 'blue' : (activeTab === 'file' ? 'emerald' : 'orange');

  // Notification State
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  const showToast = (message: string, type: ToastType = 'info') => {
      const id = uuidv4();
      setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
      setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Initialize Lang from Storage
  const [lang, setLang] = useState<Language>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.lang) as Language) || 'en';
      } catch {
          return 'en';
      }
  });

  // Initialize Theme from Storage
  const [theme, setTheme] = useState<Theme>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.theme) as Theme) || 'system';
      } catch {
          return 'system';
      }
  });

  // Logo State
  const [customLogos, setCustomLogos] = useState<AppLogo[]>([]);
  const [showLogoManager, setShowLogoManager] = useState(false);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // QR Visibility State
  const [visibleQRIds, setVisibleQRIds] = useState<Set<string>>(new Set());

  // Modal States
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showBatchEditModal, setShowBatchEditModal] = useState(false);

  // Import Preview State
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);
  const [showImportPreview, setShowImportPreview] = useState(false);

  // Theme Effect
  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    const systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (theme === 'dark' || (theme === 'system' && systemDark)) {
        root.classList.add('dark');
    } else {
        root.classList.add('light');
    }
    localStorage.setItem(STORAGE_KEYS.theme, theme);
  }, [theme]);

  // Persist Language
  useEffect(() => {
      localStorage.setItem(STORAGE_KEYS.lang, lang);
  }, [lang]);

  // Load Custom Logos on Mount
  useEffect(() => {
      try {
          const storedLogos = localStorage.getItem(STORAGE_KEYS.customLogos);
          if (storedLogos) {
              setCustomLogos(JSON.parse(storedLogos));
          }
      } catch (e) {
          console.error("Failed to load custom logos", e);
      }
  }, []);

  // Check Lock Status on Mount
  useEffect(() => {
    const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
    const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);

    if (storedHash && storedSalt) {
        setHasPassword(true);
        setIsLocked(true);
    } else {
        setHasPassword(false);
        setIsLocked(false);
        loadData('local', null); // Initial load without password
    }
  }, []);

  // Load Data helper function
  const loadData = async (mode: StorageMode, password: string | null) => {
      if (mode === 'file') {
          // File data loading is handled by handleFileSelection/Switching
          return;
      }

      const key = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const stored = storage.getItem(key);

      if (!stored) {
          setAccounts([]);
          return;
      }

      if (mode === 'local' && password) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const decrypted = await decryptData(stored, password, salt);
              if (decrypted) {
                  setAccounts(JSON.parse(decrypted));
              } else {
                  console.error("Failed to decrypt local data");
                  setAccounts([]); // Or handle error
              }
          }
      } else {
          try {
              if (stored.trim().startsWith('[') || stored.trim().startsWith('{')) {
                   setAccounts(JSON.parse(stored));
              } else if (mode === 'local' && hasPassword && !password) {
                   console.log("Data is encrypted, waiting for unlock");
              } else {
                   setAccounts(JSON.parse(stored)); 
              }
          } catch (e) {
              console.error("Error parsing data", e);
              setAccounts([]);
          }
      }
  };

  // Switching Files
  const handleSwitchFile = async (fileId: string) => {
      const file = openFiles.find(f => f.id === fileId);
      if (!file) return;

      // Handle locked file waiting in list
      if (file.isEncrypted && !file.password) {
          try {
              if (file.handle) {
                  // Re-read file to get encrypted blob
                  const { encryptedData } = await readFileRaw(file.handle as FileSystemFileHandle);
                  setPendingFile({ space: file, rawEncryptedData: encryptedData });
                  setShowFileUnlockModal(true);
              } else {
                  // Should not happen for virtual files as they are loaded into memory on start
                  console.error("Cannot re-read virtual file without data");
              }
          } catch (e) {
              console.error("Failed to read locked file to prep unlock", e);
              showToast("Failed to access file", 'error');
          }
          return;
      }

      // If already unlocked or plain
      setCurrentFileId(fileId);
      // Read content to update accounts view
      try {
          if (file.handle) {
              // Read from disk
              // @ts-ignore
              const fileObj = await file.handle.getFile();
              const text = await fileObj.text();
              const parsed = JSON.parse(text);

              if (file.isEncrypted && file.password) {
                 const decrypted = await decryptData(parsed.data, file.password, parsed.salt);
                 if (decrypted) {
                     setAccounts(JSON.parse(decrypted));
                 } else {
                     setAccounts([]); 
                 }
              } else {
                 setAccounts(Array.isArray(parsed) ? parsed : []);
              }
          } else if (file.isVirtual) {
              alert("Cannot switch back to memory-only file. Please re-open it.");
              setOpenFiles(prev => prev.filter(f => f.id !== fileId));
              return;
          }
      } catch (e) {
          console.error(e);
          setAccounts([]);
      }
  };

  // Reload data when Tab changes (if unlocked)
  useEffect(() => {
      if (!isLocked) {
          if (activeTab === 'file') {
              if (currentFileId) {
                  // Automatically focus/reload the file handle when returning to File tab
                  handleSwitchFile(currentFileId);
              } else {
                  setAccounts([]);
              }
          } else {
              loadData(activeTab, sessionKey);
          }
          setSelectedIds(new Set());
          setSearchQuery('');
          setIsSearchFocused(false);
          setVisibleQRIds(new Set()); // Hide QRs on tab switch
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, isLocked]);


  // Unlock Handler
  const handleUnlock = async (password: string) => {
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);

      if (!storedHash || !storedSalt) return false;

      // Verify Password
      const inputHash = await hashPassword(password, storedSalt);
      if (inputHash === storedHash) {
          setSessionKey(password);
          setIsLocked(false);
          await loadData('local', password); // Load decrypted data
          return true;
      }
      return false;
  };

  // Lock Reset (Forgot Password)
  const handleResetLock = () => {
      localStorage.removeItem(STORAGE_KEYS.passwordHash);
      localStorage.removeItem(STORAGE_KEYS.salt);
      localStorage.removeItem(STORAGE_KEYS.local); // Clear Encrypted Data
      setHasPassword(false);
      setIsLocked(false);
      setSessionKey(null);
      setAccounts([]);
      showToast('App reset. All local data cleared.', 'info');
  };

  // --- APP LOCK SECURITY HANDLERS ---

  // Set Password (App Lock)
  const handleSetPassword = async (password: string) => {
      const salt = generateSalt();
      const hash = await hashPassword(password, salt);

      localStorage.setItem(STORAGE_KEYS.salt, salt);
      localStorage.setItem(STORAGE_KEYS.passwordHash, hash);
      setSessionKey(password);
      setHasPassword(true);

      // Re-save current accounts with encryption
      await saveAccountsInternal(accounts, password, 'local');
      showToast(translations[lang].passwordSet, 'success');
  };

  // Remove Password (App Lock)
  const handleRemovePassword = async (currentPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);

      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(currentPassword, storedSalt);
          if (inputHash === storedHash) {
               localStorage.removeItem(STORAGE_KEYS.passwordHash);
               localStorage.removeItem(STORAGE_KEYS.salt);
               setHasPassword(false);
               setSessionKey(null);

               // Save as plaintext
               await saveAccountsInternal(accounts, null, 'local');
               showToast(translations[lang].passwordRemoved, 'success');
               return true;
          }
      }
      return false;
  };

  // Change Password (App Lock)
  const handleChangePassword = async (oldPassword: string, newPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);

      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(oldPassword, storedSalt);
          if (inputHash === storedHash) {
              // Verify old pass success, now set new
              const newSalt = generateSalt();
              const newHash = await hashPassword(newPassword, newSalt);

              localStorage.setItem(STORAGE_KEYS.salt, newSalt);
              localStorage.setItem(STORAGE_KEYS.passwordHash, newHash);
              setSessionKey(newPassword);

              // Re-save data with new key
              await saveAccountsInternal(accounts, newPassword, 'local');
              showToast("Password changed successfully", 'success');
              return true;
          }
      }
      return false;
  }


  // Save Data Internal Helper
  const saveAccountsInternal = async (newAccounts: OTPAccount[], key: string | null, mode: StorageMode) => {
      if (mode === 'file') {
          // File saving needs file handle, handled by saveToFile
          if (currentFileId) {
             const file = openFiles.find(f => f.id === currentFileId);
             if (file) {
                 await saveToFile(file, newAccounts);
             }
          }
          return;
      }

      const storageKey = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const json = JSON.stringify(newAccounts);

      if (mode === 'local' && key) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const encrypted = await encryptData(json, key, salt);
              storage.setItem(storageKey, encrypted);
          }
      } else {
          storage.setItem(storageKey, json);
      }
  };

  // --- FILE SYSTEM LOGIC ---

  const saveToFile = async (fileSpace: FileSpace, accountsData: OTPAccount[]) => {
      // Logic for File System Access API (supported browsers)
      if (fileSpace.handle) {
          try {
              // Cast handle to any for now to avoid TS errors with write
              const handle = fileSpace.handle as any;
              const writable = await handle.createWritable();
              const json = JSON.stringify(accountsData);

              if (fileSpace.isEncrypted && fileSpace.password) {
                  const salt = generateSalt();
                  const encrypted = await encryptData(json, fileSpace.password, salt);
                  const fileContent = JSON.stringify({
                      isEncrypted: true,
                      data: encrypted,
                      salt: salt
                  });
                  await writable.write(fileContent);
              } else {
                   await writable.write(json);
              }
              await writable.close();
          } catch (e) {
              console.error("Failed to save to file", e);
              showToast("Failed to save to file. Check permissions.", "error");
          }
      } 
      // Logic for fallback Virtual/Memory file (legacy browsers)
      else if (fileSpace.isVirtual) {
          const json = JSON.stringify(accountsData);
          let content = json;

          if (fileSpace.isEncrypted && fileSpace.password) {
              const salt = generateSalt();
              const encrypted = await encryptData(json, fileSpace.password, salt);
              content = JSON.stringify({
                  isEncrypted: true,
                  data: encrypted,
                  salt: salt
              });
          }

          // Trigger download
          const blob = new Blob([content], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = fileSpace.displayName || 'secureauth-accounts.json';
          a.click();
          URL.revokeObjectURL(url);
          showToast("File downloaded (Manual Save)", 'info');
      }
  };

  // Helper to read raw file data
  const readFileRaw = async (handle: FileSystemFileHandle) => {
      const fileData = await handle.getFile();
      const text = await fileData.text();
      return parseRawFileContent(text, handle.name, handle);
  };

  const parseRawFileContent = (text: string, name: string, handle: FileSystemFileHandle | null) => {
      let parsed;
      let isEncrypted = false;
      let encryptedData = { isEncrypted: false, data: '', salt: '' };

      try {
          parsed = JSON.parse(text);
          if (parsed && parsed.isEncrypted && parsed.data && parsed.salt) {
              isEncrypted = true;
              encryptedData = parsed;
          }
      } catch(e) {
           // Empty or invalid, treat as plain empty array
           parsed = [];
      }

      const newFileSpace: FileSpace = {
          id: uuidv4(),
          displayName: name,
          handle: handle,
          isEncrypted: isEncrypted,
          isVirtual: handle === null
      };

      return { newFileSpace, parsed, isEncrypted, encryptedData };
  }

  const handleOpenFile = async () => {
      if (!fileSystemClient.supported) {
          // Trigger hidden input for legacy open
          fileInputRef.current?.click();
          return;
      }
      try {
          const handles = await fileSystemClient.openFile({
              types: [{ description: 'JSON File', accept: { 'application/json': ['.json'] } }],
          });

          if (handles && handles.length > 0) {
              const handle = handles[0];
              const { newFileSpace, parsed, isEncrypted, encryptedData } = await readFileRaw(handle);

              if (isEncrypted) {
                  setPendingFile({
                      space: newFileSpace,
                      rawEncryptedData: encryptedData
                  });
                  setShowFileUnlockModal(true);
              } else {
                  setOpenFiles(prev => [...prev, newFileSpace]);
                  setCurrentFileId(newFileSpace.id);
                  setAccounts(Array.isArray(parsed) ? parsed : []);
              }
          }
      } catch (e: any) {
          if (e.name !== 'AbortError') {
              console.error(e);
              showToast("Error opening file", 'error');
          }
      }
  };

  const handleLegacyFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (ev) => {
          if (ev.target?.result) {
              const text = ev.target.result as string;
              const { newFileSpace, parsed, isEncrypted, encryptedData } = parseRawFileContent(text, file.name, null);

              if (isEncrypted) {
                  setPendingFile({
                      space: newFileSpace,
                      rawEncryptedData: encryptedData
                  });
                  setShowFileUnlockModal(true);
              } else {
                  setOpenFiles(prev => [...prev, newFileSpace]);
                  setCurrentFileId(newFileSpace.id);
                  setAccounts(Array.isArray(parsed) ? parsed : []);
                  showToast("File opened in Read-Only mode. Save manually.", 'info');
              }
          }
      };
      reader.readAsText(file);
      e.target.value = ''; // Reset input
  };

  const handleOpenFolder = async () => {
     if (!fileSystemClient.supported) {
         alert("Folder access requires a modern browser (Chrome, Edge, Opera). Please open individual files instead.");
         return;
     }
     try {
         const dirHandle = await fileSystemClient.openDirectory();
         const entries = await fileSystemClient.getDirectoryEntries(dirHandle);

         const jsonFiles = entries.filter(e => e.kind === 'file' && e.name.toLowerCase().endsWith('.json'));

         if (jsonFiles.length === 0) {
             showToast("No JSON files found in this folder.", 'info');
             return;
         }

         const newSpaces: FileSpace[] = [];
         let encryptedCount = 0;

         for (const entry of jsonFiles) {
             try {
                const fileHandle = entry.handle as FileSystemFileHandle;
                const { newFileSpace, isEncrypted } = await readFileRaw(fileHandle);

                // Avoid duplicates
                if (!openFiles.some(f => f.displayName === newFileSpace.displayName)) {
                    // We add it to the list even if encrypted, but without password.
                    // Accessing it will trigger unlock.
                    newSpaces.push(newFileSpace);
                    if (isEncrypted) encryptedCount++;
                }
             } catch (err) {
                 console.warn(`Skipping file ${entry.name}`, err);
             }
         }

         if (newSpaces.length > 0) {
             setOpenFiles(prev => [...prev, ...newSpaces]);
             showToast(`Added ${newSpaces.length} files (${encryptedCount} encrypted).`, 'success');
         } else {
             showToast("No new files added.", 'info');
         }

     } catch (e: any) {
         if (e.name !== 'AbortError') {
             console.error(e);
             showToast("Error opening folder", 'error');
         }
     }
  };

  const handleCreateFile = async () => {
      if (!fileSystemClient.supported) {
          // Fallback: Create virtual file
          const newFileId = uuidv4();
          const newFileSpace: FileSpace = {
              id: newFileId,
              displayName: 'Untitled.json',
              handle: null,
              isEncrypted: false,
              isVirtual: true
          };
          setOpenFiles(prev => [...prev, newFileSpace]);
          setCurrentFileId(newFileId);
          setAccounts([]);
          return;
      }

      try {
          const handle = await fileSystemClient.createFile({
              suggestedName: '2fa-accounts.json',
              types: [{ description: 'JSON File', accept: { 'application/json': ['.json'] } }],
          });

          const newFileId = uuidv4();
          const newFileSpace: FileSpace = {
              id: newFileId,
              displayName: handle.name,
              handle: handle,
              isEncrypted: false,
          };

          setOpenFiles(prev => [...prev, newFileSpace]);
          setCurrentFileId(newFileId);
          setAccounts([]);

          // Initialize empty file
          const writable = await handle.createWritable();
          await writable.write("[]");
          await writable.close();

      } catch (e: any) {
          if (e.name !== 'AbortError') console.error(e);
      }
  };

  // Unlock logic for Pending File
  const handleUnlockFile = async (password: string) => {
      if (!pendingFile) return;

      const { data, salt } = pendingFile.rawEncryptedData;

      const decrypted = await decryptData(data, password, salt);
      if (decrypted) {
          const accountsData = JSON.parse(decrypted);

          // If this was a pending NEW file not in list
          if (!openFiles.some(f => f.id === pendingFile.space.id)) {
             const unlockedSpace = { ...pendingFile.space, password: password };
             setOpenFiles(prev => [...prev, unlockedSpace]);
             setCurrentFileId(unlockedSpace.id);
             setAccounts(accountsData);
          } 
          // If this was an existing LOCKED file in list (folder view)
          else {
             setOpenFiles(prev => prev.map(f => f.id === pendingFile.space.id ? { ...f, password: password } : f));
             setCurrentFileId(pendingFile.space.id);
             setAccounts(accountsData);
          }

          setPendingFile(null);
          setShowFileUnlockModal(false);
      } else {
          // Keep modal open, show error (handled by modal component catch)
          throw new Error("Wrong Password");
      }
  };

  const handleCancelUnlock = () => {
      // If user cancels unlock
      if (pendingFile) {
          // If it was already in the list (folder view), remove it because user couldn't unlock
          if (openFiles.some(f => f.id === pendingFile.space.id)) {
              setOpenFiles(prev => prev.filter(f => f.id !== pendingFile.space.id));
          }
          // If it was new, just don't add it.
      }
      setPendingFile(null);
      setShowFileUnlockModal(false);
  };


  const handleFileRename = (id: string) => {
      const name = prompt(t.labelRenameFile);
      if (name) {
          setOpenFiles(prev => prev.map(f => f.id === id ? { ...f, displayName: name } : f));
      }
  };

  const handleCloseFile = (id: string) => {
      if (confirm(t.confirmCloseFile)) {
          setOpenFiles(prev => prev.filter(f => f.id !== id));
          if (currentFileId === id) {
              setCurrentFileId(null);
              setAccounts([]);
          }
      }
  };

  // --- FILE ENCRYPTION MANAGEMENT ---

  const handleSetFilePassword = async (password: string) => {
      if (!currentFileId) return;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file) {
          const updatedFile = { ...file, isEncrypted: true, password: password };
          await saveToFile(updatedFile, accounts);
          setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
          showToast(t.filePassSet, 'success');
      }
  };

  const handleRemoveFilePassword = async (currPass: string) => {
      if (!currentFileId) return false;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file && file.password === currPass) {
           const updatedFile = { ...file, isEncrypted: false, password: undefined };
           await saveToFile(updatedFile, accounts);
           setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
           showToast(t.filePassRemoved, 'success');
           return true;
      }
      return false;
  };

  const handleChangeFilePassword = async (oldPass: string, newPass: string) => {
      if (!currentFileId) return false;
      const file = openFiles.find(f => f.id === currentFileId);

      if (file && file.password === oldPass) {
          const updatedFile = { ...file, isEncrypted: true, password: newPass };
          await saveToFile(updatedFile, accounts);
          setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
          showToast("File password changed successfully", 'success');
          return true;
      }
      return false;
  };


  // Public Save Wrapper
  const saveAccounts = (newAccounts: OTPAccount[]) => {
      setAccounts(newAccounts);
      saveAccountsInternal(newAccounts, sessionKey, activeTab);
  };

  // ... Existing Handlers ...
  const handleAddLogo = (logo: AppLogo) => {
      saveCustomLogos([...customLogos, logo]);
      showToast(translations[lang].logoAdded, 'success');
  };
  const saveCustomLogos = (logos: AppLogo[]) => {
      setCustomLogos(logos);
      localStorage.setItem(STORAGE_KEYS.customLogos, JSON.stringify(logos));
  };
  const handleDeleteLogo = (id: string) => {
      saveCustomLogos(customLogos.filter(l => l.id !== id));
      showToast('Logo deleted', 'success');
  };
  const handleBatchDeleteLogos = (ids: string[]) => {
      const idSet = new Set(ids);
      saveCustomLogos(customLogos.filter(l => !idSet.has(l.id)));
      showToast(`${ids.length} logos deleted`, 'success');
  };
  const handleImportLogos = (newLogos: AppLogo[]) => {
      const existingIds = new Set(customLogos.map(l => l.id));
      const filteredNew = newLogos.filter(l => !existingIds.has(l.id));
      if (filteredNew.length === 0) {
          showToast('No new logos to import (all exist)', 'info');
          return;
      }
      saveCustomLogos([...customLogos, ...filteredNew]);
      showToast(`${filteredNew.length} logos imported`, 'success');
  };

  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) {
        const updatedAccounts = accounts.map(acc => 
            acc.id === editingAccount.id ? { ...acc, ...data } : acc
        );
        saveAccounts(updatedAccounts);
        showToast('Account updated successfully', 'success');
    } else {
        const newAccount: OTPAccount = {
            ...data,
            id: uuidv4(),
            createdAt: Date.now()
        };
        saveAccounts([...accounts, newAccount]);
        showToast('Account created successfully', 'success');
    }
    setEditingAccount(undefined);
  };

  // Handle scanned batch accounts from AccountFormModal
  const handleBatchScan = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowAccountModal(false);
      setShowImportPreview(true);
  };

  const handleBatchSave = (updates: Partial<OTPAccount>) => {
      if (Object.keys(updates).length === 0) {
          setShowBatchEditModal(false);
          return;
      }
      const updatedAccounts = accounts.map(acc => {
          if (selectedIds.has(acc.id)) {
              return { ...acc, ...updates };
          }
          return acc;
      });
      saveAccounts(updatedAccounts);
      showToast(`Updated ${selectedIds.size} accounts`, 'success');
      setShowBatchEditModal(false);
      setSelectedIds(new Set());
  };

  const handleImportPreview = (candidates: ImportCandidate[]) => {
      setImportCandidates(candidates);
      setShowImportModal(false);
      setShowImportPreview(true);
  };

  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => {
    const newItems = selectedCandidates.map(item => ({
      issuer: item.issuer || 'Batch Import',
      account: item.account || 'Unknown',
      secret: item.secret,
      period: item.period || 30,
      notes: item.notes,
      logoId: item.logoId,
      id: uuidv4(),
      createdAt: Date.now()
    }));
    saveAccounts([...accounts, ...newItems]);
    setShowImportPreview(false);
    setImportCandidates([]);
    showToast(`${newItems.length} accounts imported`, 'success');
  };

  const handleDelete = (id: string) => {
    if (window.confirm(t.confirmDelete)) {
      setAccounts(prevAccounts => {
        const updatedAccounts = prevAccounts.filter(a => a.id !== id);
        saveAccountsInternal(updatedAccounts, sessionKey, activeTab);
        return updatedAccounts;
      });
      setSelectedIds(prev => {
        if (prev.has(id)) {
            const next = new Set(prev);
            next.delete(id);
            return next;
        }
        return prev;
      });
      setVisibleQRIds(prev => {
          if (prev.has(id)) {
              const next = new Set(prev);
              next.delete(id);
              return next;
          }
          return prev;
      });
      showToast('Account deleted', 'success');
    }
  };

  const handleEdit = (account: OTPAccount) => {
      setEditingAccount(account);
      setShowAccountModal(true);
  };

  const handleToggleSelect = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
      if (selectedIds.size === filteredAccounts.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(filteredAccounts.map(a => a.id)));
      }
  };

  const handleBulkDelete = () => {
      if (window.confirm(t.confirmBulkDelete)) {
          setAccounts(prevAccounts => {
              const updatedAccounts = prevAccounts.filter(a => !selectedIds.has(a.id));
              saveAccountsInternal(updatedAccounts, sessionKey, activeTab);
              return updatedAccounts;
          });
          showToast(`Deleted ${selectedIds.size} accounts`, 'success');
          setSelectedIds(new Set());
          // Update QR visibility
          setVisibleQRIds(prev => {
             const next = new Set(prev);
             selectedIds.forEach(id => next.delete(id));
             return next;
          });
      }
  };

  // QR Visibility Handlers
  const handleToggleQR = (id: string) => {
      setVisibleQRIds(prev => {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
      });
  };

  // Smart Toggle for Selection
  const handleToggleSelectedQR = () => {
      const selectedArray = Array.from(selectedIds);
      const allSelectedVisible = selectedArray.every(id => visibleQRIds.has(id));

      setVisibleQRIds(prev => {
          const next = new Set(prev);
          if (allSelectedVisible) {
              // Hide all selected
              selectedArray.forEach(id => next.delete(id));
          } else {
              // Show all selected
              selectedArray.forEach(id => next.add(id));
          }
          return next;
      });
  };

  const filteredAccounts = (function() {
    if (!searchQuery.trim()) return accounts;
    const lowerQuery = searchQuery.toLowerCase();
    const keywords = lowerQuery.split(/\s+/).filter(k => k.length > 0);
    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      return keywords.every(kw => searchString.includes(kw));
    });
  })();

  const t = translations[lang];
  const themeClasses = getThemeClasses();

  const selectedAreAllVisible = selectedIds.size > 0 && Array.from(selectedIds).every(id => visibleQRIds.has(id));

  // Helper for theme classes
  function getThemeClasses() {
     const common = {
         tabActive: 'bg-white dark:bg-gray-800 shadow-sm'
     };
     if (activeTab === 'local') {
         return {
             ...common,
             primaryBg: 'bg-blue-600',
             primaryHover: 'hover:bg-blue-700',
             textGradient: 'from-blue-700 to-blue-500 dark:from-blue-500 dark:to-blue-400',
             focusRing: 'focus:ring-blue-500',
             checkboxText: 'text-blue-600',
             iconBg: 'bg-blue-600',
             tabActive: `${common.tabActive} text-blue-600 dark:text-blue-400`,
             lightBg: 'bg-blue-50 dark:bg-blue-900/20',
             borderColor: 'border-blue-100 dark:border-blue-900/30'
         };
     } else if (activeTab === 'file') {
         return {
             ...common,
             primaryBg: 'bg-emerald-600',
             primaryHover: 'hover:bg-emerald-700',
             textGradient: 'from-emerald-700 to-emerald-500 dark:from-emerald-500 dark:to-emerald-400',
             focusRing: 'focus:ring-emerald-500',
             checkboxText: 'text-emerald-600',
             iconBg: 'bg-emerald-600',
             tabActive: `${common.tabActive} text-emerald-600 dark:text-emerald-400`,
             lightBg: 'bg-emerald-50 dark:bg-emerald-900/20',
             borderColor: 'border-emerald-100 dark:border-emerald-900/30'
         };
     } else {
         return {
             ...common,
             primaryBg: 'bg-orange-600',
             primaryHover: 'hover:bg-orange-700',
             textGradient: 'from-orange-700 to-orange-500 dark:from-orange-500 dark:to-orange-400',
             focusRing: 'focus:ring-orange-500',
             checkboxText: 'text-orange-600',
             iconBg: 'bg-orange-600',
             tabActive: `${common.tabActive} text-orange-600 dark:text-orange-400`,
             lightBg: 'bg-orange-50 dark:bg-orange-900/20',
             borderColor: 'border-orange-100 dark:border-orange-900/30'
         };
     }
  }

  // Handle Theme Toggle
  const toggleTheme = () => {
      if (theme === 'system') setTheme('light');
      else if (theme === 'light') setTheme('dark');
      else setTheme('system');
  };

  const getThemeIcon = () => {
      switch(theme) {
          case 'light': return <Sun size={18} />;
          case 'dark': return <Moon size={18} />;
          case 'system': return <Monitor size={18} />;
      }
  };

  // --- Render ---

  if (isLocked) {
      return (
        <LanguageContext.Provider value={{ lang, t, setLang }}>
            <LockScreen onUnlock={handleUnlock} onReset={handleResetLock} />
        </LanguageContext.Provider>
      );
  }

  // Active File Reference
  const currentFile = openFiles.find(f => f.id === currentFileId);

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <ToastContainer toasts={toasts} onClose={removeToast} />
      {/* Hidden input for fallback file loading */}
      <input type="file" ref={fileInputRef} className="hidden" accept=".json,application/json" onChange={handleLegacyFileSelect} />

      <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-gray-900 text-gray-800 dark:text-gray-100 font-sans pb-40 sm:pb-24 transition-colors duration-200">

        {/* Navbar */}
        <header className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-20 transition-colors duration-200">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-14 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className={`${themeClasses.iconBg} p-1.5 rounded-lg transition-colors duration-300`}>
                  <ShieldCheck className="text-white h-5 w-5" />
                </div>
                <h1 className={`text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r ${themeClasses.textGradient} hidden md:block transition-all duration-300`}>
                  {t.appTitle}
                </h1>
              </div>

              <div className={`flex-1 transition-all duration-300 ${isSearchFocused ? 'max-w-full' : 'max-w-md mx-auto'}`}>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className={`h-4 w-4 text-gray-400 group-focus-within:${themeClasses.checkboxText} transition-colors`} />
                    </div>
                    <input
                        type="text"
                        className={`block w-full pl-9 pr-9 py-1.5 border border-gray-300 dark:border-gray-600 rounded-lg leading-5 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:bg-white dark:focus:bg-gray-800 focus:ring-2 ${themeClasses.focusRing} focus:border-transparent transition-all text-sm`}
                        placeholder="Search..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onFocus={() => setIsSearchFocused(true)}
                        onBlur={() => setIsSearchFocused(false)}
                    />
                    {searchQuery && (
                      <button 
                        onMouseDown={(e) => { e.preventDefault(); setSearchQuery(''); }}
                        className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600 cursor-pointer"
                      >
                         <X size={14} />
                      </button>
                    )}
                </div>
              </div>

              <div className={`flex items-center gap-2 shrink-0 transition-all duration-300 ${isSearchFocused ? 'w-0 opacity-0 overflow-hidden m-0 p-0' : 'w-auto opacity-100'}`}>
                <div className="flex p-1 bg-gray-100 dark:bg-gray-700 rounded-lg">
                  <button
                    onClick={() => setActiveTab('local')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                      activeTab === 'local' 
                        ? themeClasses.tabActive 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                    }`}
                  >
                    <HardDrive size={14} />
                    <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('file')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                      activeTab === 'file' 
                        ? themeClasses.tabActive 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                    }`}
                  >
                    <FolderOpen size={14} />
                    <span className="hidden sm:inline">{t.tabFile}</span>
                  </button>
                  <button
                    onClick={() => setActiveTab('session')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                      activeTab === 'session' 
                        ? themeClasses.tabActive 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                    }`}
                  >
                    <Zap size={14} />
                    <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>
                </div>

                {/* Password / Security Settings */}
                <button 
                  onClick={() => setShowPasswordModal(true)}
                  className={`ml-1 p-1.5 ${hasPassword || (activeTab === 'file' && currentFile?.isEncrypted) ? 'text-green-600 dark:text-green-400' : 'text-gray-400 dark:text-gray-500'} hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition relative group`}
                  title={activeTab === 'file' ? t.fileSecurityTitle : t.securityTitle}
                  disabled={activeTab === 'file' && !currentFileId}
                >
                  <Lock size={18} />
                  {/* Indicator Dot */}
                  {((activeTab !== 'file' && hasPassword) || (activeTab === 'file' && currentFile?.isEncrypted)) && (
                      <span className="absolute top-1 right-1 w-1.5 h-1.5 bg-green-500 rounded-full ring-2 ring-white dark:ring-gray-800"></span>
                  )}
                </button>

                {/* Theme Switcher */}
                <button 
                  onClick={toggleTheme}
                  className={`ml-1 p-1.5 text-gray-500 dark:text-gray-400 hover:${themeClasses.checkboxText} hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition`}
                  title={`Theme: ${theme}`}
                >
                  {getThemeIcon()}
                </button>

                <button 
                  onClick={() => setLang(lang === 'en' ? 'zh' : 'en')}
                  className={`ml-1 p-1.5 text-gray-500 dark:text-gray-400 hover:${themeClasses.checkboxText} hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition`}
                  title="Switch Language"
                >
                  <Languages size={18} />
                </button>
              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
                    <button 
                        onClick={() => setShowLogoManager(false)}
                        className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 font-medium text-sm flex items-center gap-1"
                    >
                        &larr; Back to Accounts
                    </button>
                    <h2 className="text-2xl font-bold text-gray-800 dark:text-white ml-2">{t.manageLogos}</h2>
                 </div>
                 <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
                     <LogoManagerModal 
                        onClose={() => setShowLogoManager(false)}
                        logos={customLogos}
                        onAddLogo={handleAddLogo}
                        onDeleteLogo={handleDeleteLogo}
                        onBatchDeleteLogo={handleBatchDeleteLogos}
                        onImportLogos={handleImportLogos}
                        inline={true} 
                        color={themeColor}
                    />
                 </div>
            </main>
        ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">

          <div className={`mb-6 p-3 rounded-lg border flex items-center gap-3 ${themeClasses.lightBg} ${themeClasses.borderColor}`}>
             <div className="shrink-0">
               {activeTab === 'local' ? <Lock size={16} /> : (activeTab === 'file' ? <FolderOpen size={16} /> : <Zap size={16} />)}
             </div>
             <div className="text-xs sm:text-sm flex flex-col sm:flex-row sm:gap-2">
               <span className="font-semibold text-gray-800 dark:text-gray-200">
                  {activeTab === 'local' ? t.bannerLocalTitle : (activeTab === 'file' ? t.bannerFileTitle : t.bannerSessionTitle)}
               </span>
               <span className="hidden sm:inline text-gray-400 dark:text-gray-500">|</span>
               <span className="opacity-80 text-gray-600 dark:text-gray-400">
                 {activeTab === 'local' ? t.bannerLocalDesc : (activeTab === 'file' ? t.bannerFileDesc : t.bannerSessionDesc)}
               </span>
             </div>
          </div>

          {/* File Space Manager (Only for File Mode) */}
          {activeTab === 'file' && (
              <div className="mb-6 bg-white dark:bg-gray-800 p-3 rounded-lg border dark:border-gray-700 shadow-sm space-y-3">
                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
                      <div className="flex gap-2 shrink-0">
                          <button onClick={handleOpenFile} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition whitespace-nowrap">
                              <FolderOpen size={14} /> {t.btnOpenFile}
                          </button>
                          <button onClick={handleOpenFolder} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition whitespace-nowrap">
                              <FolderOpen size={14} /> {t.btnOpenFolder}
                          </button>
                      </div>
                      <button onClick={handleCreateFile} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition whitespace-nowrap">
                          <FilePlus size={14} /> {t.btnCreateFile}
                      </button>

                      <div className="h-px w-full sm:h-5 sm:w-px bg-gray-300 dark:bg-gray-600 mx-0 sm:mx-1"></div>

                      <div className="flex gap-2 overflow-x-auto pb-1 sm:pb-0 w-full no-scrollbar">
                          {openFiles.length === 0 && <span className="text-xs text-gray-400 dark:text-gray-500 self-center italic">No files open</span>}
                          {openFiles.map(f => (
                              <button 
                                key={f.id}
                                onClick={() => handleSwitchFile(f.id)}
                                className={`flex items-center gap-2 px-2.5 py-1 rounded-md border text-xs whitespace-nowrap transition shrink-0 ${currentFileId === f.id ? 'bg-emerald-50 border-emerald-200 text-emerald-700 dark:bg-emerald-900/30 dark:border-emerald-700 dark:text-emerald-400' : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'}`}
                              >
                                  {f.isEncrypted ? <Lock size={10} className={f.password ? "text-green-500" : "text-gray-400"}/> : <FileJson size={10} className="opacity-50"/>}
                                  {f.displayName}
                                  {f.isVirtual && <AlertTriangle size={10} className="text-orange-400" />}
                              </button>
                          ))}
                      </div>
                  </div>

                  {/* Active File Actions */}
                  {currentFile && (
                      <div className="flex flex-col gap-2 pt-2 border-t border-gray-100 dark:border-gray-700">
                           <div className="flex flex-wrap items-center justify-between gap-2">
                               <div className="flex items-center gap-3">
                                    <span className="text-xs sm:text-sm font-semibold text-gray-700 dark:text-gray-200 truncate max-w-[200px]">{currentFile.displayName}</span>
                                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full border ${currentFile.isEncrypted ? 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800' : 'bg-gray-50 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700'}`}>
                                        {currentFile.isEncrypted ? t.fileEncrypted : t.filePlain}
                                    </span>
                                    {currentFile.isVirtual && (
                                        <span className="text-[10px] px-1.5 py-0.5 rounded-full border bg-orange-50 text-orange-700 border-orange-200 flex items-center gap-1 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800">
                                            <AlertTriangle size={10} /> Read-Only
                                        </span>
                                    )}
                               </div>
                               <div className="flex gap-1">
                                    <button onClick={() => handleFileRename(currentFile.id)} className="p-1 text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded" title={t.labelRenameFile}>
                                        <PenLine size={14} />
                                    </button>
                                    <button onClick={() => handleCloseFile(currentFile.id)} className="p-1 text-gray-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded" title={t.btnCloseFile}>
                                        <XCircle size={14} />
                                    </button>
                               </div>
                           </div>

                           {/* Warning banner for Virtual Files */}
                           {currentFile.isVirtual && (
                               <div className="flex items-start gap-2 text-xs text-orange-700 bg-orange-50 dark:bg-orange-900/20 dark:text-orange-400 p-2 rounded border border-orange-100 dark:border-orange-900/30">
                                   <AlertTriangle size={12} className="mt-0.5 shrink-0" />
                                   <p>{t.virtualFileWarning}</p>
                               </div>
                           )}

                           {/* Manual Save Button for Virtual Files */}
                           {currentFile.isVirtual && (
                               <button 
                                 onClick={() => saveToFile(currentFile, accounts)}
                                 className="self-start flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-1.5 rounded-lg text-xs font-medium transition shadow-sm"
                               >
                                   <Download size={14} /> {t.btnDownloadManual}
                               </button>
                           )}
                      </div>
                  )}
              </div>
          )}

          <div className="flex flex-col xl:flex-row gap-4 mb-6 justify-between items-start xl:items-center">
             <div className="flex flex-wrap gap-2 w-full sm:w-auto flex-nowrap overflow-x-auto pb-1 sm:pb-0">
                <button 
                    onClick={() => { setEditingAccount(undefined); setShowAccountModal(true); }}
                    disabled={activeTab === 'file' && (!currentFileId || (currentFile?.isEncrypted && !currentFile?.password))}
                    className={`flex items-center gap-2 ${themeClasses.primaryBg} ${themeClasses.primaryHover} text-white px-3 py-2 rounded-lg shadow-sm hover:shadow transition text-sm font-medium whitespace-nowrap disabled:opacity-50 disabled:cursor-not-allowed`}
                    title={t.addAccount}
                >
                    <Plus size={16} /> <span className="hidden sm:inline">{t.addAccount}</span>
                </button>
                <button 
                    onClick={() => setShowImportModal(true)}
                    disabled={activeTab === 'file' && (!currentFileId || (currentFile?.isEncrypted && !currentFile?.password))}
                    className="flex items-center gap-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-sm font-medium whitespace-nowrap disabled:opacity-50"
                    title={t.importBatch}
                >
                    <Upload size={16} /> <span className="hidden sm:inline">{t.importBatch}</span>
                </button>
                <button 
                    onClick={() => setShowExportModal(true)}
                    disabled={accounts.length === 0}
                    className="flex items-center gap-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-sm font-medium disabled:opacity-50 whitespace-nowrap"
                    title={t.exportBatch}
                >
                    <Download size={16} /> <span className="hidden sm:inline">{t.exportBatch}</span>
                </button>
                <button 
                    onClick={() => setShowLogoManager(true)}
                    className="flex items-center gap-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-sm font-medium whitespace-nowrap"
                    title={t.manageLogos}
                >
                    <ImageIcon size={16} /> <span className="hidden sm:inline">{t.manageLogos}</span>
                </button>

                 {filteredAccounts.length > 0 && (
                    <button 
                       onClick={handleSelectAll}
                       className="flex items-center gap-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-sm font-medium whitespace-nowrap ml-auto sm:ml-0"
                       title={selectedIds.size === filteredAccounts.length ? t.deselectAll : t.selectAll}
                    >
                       {selectedIds.size === filteredAccounts.length ? <CheckSquare size={16} /> : <Square size={16} />}
                    </button>
                 )}
             </div>
          </div>

          {filteredAccounts.length === 0 ? (
            <div className="text-center py-20 bg-white dark:bg-gray-800 rounded-xl border border-dashed border-gray-300 dark:border-gray-700">
              <div className="bg-gray-50 dark:bg-gray-700 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                 <ShieldCheck className="text-gray-300 dark:text-gray-500 w-8 h-8" />
              </div>
              <h3 className="text-lg font-medium text-gray-900 dark:text-white">{searchQuery ? "No matching accounts" : t.noAccountsTitle}</h3>
              <p className="text-gray-500 dark:text-gray-400 mt-1 max-w-sm mx-auto">{searchQuery ? "Try refining your search terms." : t.noAccountsDesc}</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredAccounts.map(acc => (
                <AccountCard 
                    key={acc.id} 
                    account={acc} 
                    logo={customLogos.find(l => l.id === acc.logoId)}
                    onDelete={handleDelete} 
                    onEdit={handleEdit}
                    isSelected={selectedIds.has(acc.id)}
                    onToggleSelect={handleToggleSelect}
                    showQR={visibleQRIds.has(acc.id)}
                    onToggleQR={handleToggleQR}
                    color={themeColor}
                />
              ))}
            </div>
          )}
        </main>
        )}

        <footer className="w-full py-6 flex justify-center items-center pointer-events-none mb-4">
            <a 
                href="https://yubo.ltd" 
                target="_blank" 
                rel="noopener noreferrer" 
                className="flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-gray-800/50 backdrop-blur-sm rounded-full border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-md transition-all pointer-events-auto group no-underline"
            >
                <img src="/logo.png" alt="Logo" className="w-5 h-5 object-contain opacity-70 group-hover:opacity-100 transition-opacity" />
                <span className="text-xs font-medium text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200 transition-colors">
                Developed by <span className="font-bold">AnerYubo</span>
                </span>
            </a>
        </footer>

        {selectedIds.size > 0 && !showLogoManager && (
            <div className="fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-3 z-40 animate-in slide-in-from-bottom duration-300">
                <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-3 px-0 sm:px-4">
                    <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                        <span className="font-semibold text-gray-700 dark:text-gray-200 text-sm">
                            {selectedIds.size} {t.selected}
                        </span>
                    </div>

                    <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-2">
                        <button 
                           onClick={() => setShowBatchEditModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-xs font-medium"
                        >
                            <Edit2 size={14} /> {t.btnBatchEdit}
                        </button>
                        <button 
                           onClick={() => setShowExportModal(true)}
                           className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-xs font-medium"
                        >
                            <Download size={14} /> {t.exportSelected}
                        </button>
                        <button 
                           onClick={handleToggleSelectedQR}
                           className={`flex items-center justify-center gap-2 px-3 py-2 rounded-lg transition text-xs font-medium ${selectedAreAllVisible ? 'bg-blue-50 text-blue-600 border border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/30' : 'bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600'}`}
                        >
                            <QrCode size={14} /> {selectedAreAllVisible ? t.hideQR : t.showQR}
                        </button>
                        <button 
                           onClick={handleBulkDelete}
                           className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 dark:bg-red-900/20 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400 px-3 py-2 rounded-lg transition text-xs font-medium"
                        >
                            <Trash2 size={14} /> {t.deleteSelected}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {showAccountModal && (
            <AccountFormModal 
                onClose={() => { setShowAccountModal(false); setEditingAccount(undefined); }} 
                onSave={handleSaveAccount} 
                onBatchScan={handleBatchScan}
                initialData={editingAccount}
                logos={customLogos}
                color={themeColor}
            />
        )}
        {showBatchEditModal && (
          <BatchEditModal 
             onClose={() => setShowBatchEditModal(false)}
             onSave={handleBatchSave}
             logos={customLogos}
             color={themeColor}
          />
        )}
        {showImportModal && (
          <BatchImportModal 
            onClose={() => setShowImportModal(false)} 
            onPreview={handleImportPreview}
            color={themeColor} 
          />
        )}

        {/* App Security Modal */}
        {showPasswordModal && (
            <PasswordSettingsModal 
                onClose={() => setShowPasswordModal(false)}
                hasPassword={activeTab === 'file' ? (currentFile?.isEncrypted || false) : hasPassword}
                onSetPassword={activeTab === 'file' ? handleSetFilePassword : handleSetPassword}
                onRemovePassword={activeTab === 'file' ? handleRemoveFilePassword : handleRemovePassword}
                onChangePassword={activeTab === 'file' ? handleChangeFilePassword : handleChangePassword}
                color={themeColor}
            />
        )}

        {/* File Unlock Modal (For Pending Files) */}
        {showFileUnlockModal && pendingFile && (
             <PasswordSettingsModal 
                onClose={handleCancelUnlock}
                hasPassword={false} // Mode: Unlock (Similar to set but verify against file)
                isUnlock={true} // Force Unlock Mode
                onSetPassword={handleUnlockFile} // Reusing setPassword prop for unlock submission
                onRemovePassword={async () => true}
                color={themeColor}
             />
        )}

        <ImportPreviewModal
           isOpen={showImportPreview}
           candidates={importCandidates}
           onClose={() => { setShowImportPreview(false); setImportCandidates([]); }}
           onConfirm={handleConfirmImport}
           logos={customLogos}
           color={themeColor}
        />

        {showExportModal && (
            <BatchExportModal 
                accounts={selectedIds.size > 0 ? accounts.filter(a => selectedIds.has(a.id)) : accounts} 
                onClose={() => setShowExportModal(false)} 
                color={themeColor}
            />
        )}

      </div>
    </LanguageContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { OTPAccount, AppLogo } from '../types';
import { generateToken } from '../utils/crypto';
import { Trash2, Edit2, QrCode } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import { LanguageContext } from '../utils/i18n';

interface AccountCardProps {
  account: OTPAccount;
  logo?: AppLogo;
  onDelete: (id: string) => void;
  onEdit: (account: OTPAccount) => void;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
  showQR: boolean;
  onToggleQR: (id: string) => void;
  color?: 'blue' | 'orange' | 'emerald';
}

const AccountCard: React.FC<AccountCardProps> = ({ account, logo, onDelete, onEdit, isSelected, onToggleSelect, showQR, onToggleQR, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const [tokenData, setTokenData] = useState(generateToken(account.secret, account.period));
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    // Update immediately
    setTokenData(generateToken(account.secret, account.period));
    const interval = setInterval(() => {
      setTokenData(generateToken(account.secret, account.period));
    }, 1000);
    return () => clearInterval(interval);
  }, [account.secret, account.period]);

  const handleCopy = () => {
    navigator.clipboard.writeText(tokenData.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formattedToken = tokenData.token.replace(/(.{3})/g, "$1 ").trim();
  const otpUri = `otpauth://totp/${encodeURIComponent(account.issuer)}:${encodeURIComponent(account.account)}?secret=${account.secret}&issuer=${encodeURIComponent(account.issuer)}&period=${account.period}`;

  // Theme based styles
  const getThemeStyles = (c: string) => {
    switch (c) {
        case 'emerald':
            return {
                borderColor: 'border-emerald-500 ring-1 ring-emerald-500 dark:border-emerald-400 dark:ring-emerald-400',
                checkboxColor: 'text-emerald-600 focus:ring-emerald-500 dark:text-emerald-400',
                progressColor: 'bg-emerald-500 dark:bg-emerald-400',
                hoverText: 'hover:text-emerald-600 dark:hover:text-emerald-400',
                hoverBg: 'hover:bg-emerald-50 dark:hover:bg-emerald-900/30',
                qrActiveBg: 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400'
            };
        case 'orange':
            return {
                borderColor: 'border-orange-500 ring-1 ring-orange-500 dark:border-orange-400 dark:ring-orange-400',
                checkboxColor: 'text-orange-600 focus:ring-orange-500 dark:text-orange-400',
                progressColor: 'bg-orange-500 dark:bg-orange-400',
                hoverText: 'hover:text-orange-600 dark:hover:text-orange-400',
                hoverBg: 'hover:bg-orange-50 dark:hover:bg-orange-900/30',
                qrActiveBg: 'bg-orange-50 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400'
            };
        case 'blue':
        default:
            return {
                borderColor: 'border-blue-500 ring-1 ring-blue-500 dark:border-blue-400 dark:ring-blue-400',
                checkboxColor: 'text-blue-600 focus:ring-blue-500 dark:text-blue-400',
                progressColor: 'bg-blue-500 dark:bg-blue-400',
                hoverText: 'hover:text-blue-600 dark:hover:text-blue-400',
                hoverBg: 'hover:bg-blue-50 dark:hover:bg-blue-900/30',
                qrActiveBg: 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
            };
    }
  }

  const styles = getThemeStyles(color);

  const borderColor = styles.borderColor;
  const checkboxColor = styles.checkboxColor;
  const progressBarColor = tokenData.seconds < 5 ? 'bg-red-500 dark:bg-red-400' : styles.progressColor;
  const hoverText = styles.hoverText;
  const hoverBg = styles.hoverBg;
  const qrActiveBg = showQR ? styles.qrActiveBg : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700';

  // Generate a soft background color based on issuer char
  const getAvatarColor = (name: string) => {
    const colors = ['bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300', 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300', 'bg-violet-100 text-violet-700 dark:bg-violet-900 dark:text-violet-300', 'bg-amber-100 text-amber-700 dark:bg-amber-900 dark:text-amber-300', 'bg-rose-100 text-rose-700 dark:bg-rose-900 dark:text-rose-300', 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900 dark:text-cyan-300'];
    const index = name.length % colors.length;
    return colors[index];
  };

  const avatarClass = getAvatarColor(account.issuer || 'U');

  return (
    <div 
      className={`relative bg-white dark:bg-gray-800 rounded-xl transition-all duration-200 flex flex-col overflow-hidden group border ${isSelected ? `${borderColor} shadow-md` : 'border-gray-200 dark:border-gray-700 shadow-sm hover:shadow-md'}`}
      onClick={(e) => {
          // Prevent accidental copy when selecting logic might change later
      }}
    >
      {/* Top Section: Issuer & Controls */}
      <div className="px-4 pt-3 pb-2 flex justify-between items-start">
        <div className="flex items-center gap-2.5 overflow-hidden pr-2 min-w-0 flex-1">
            {logo ? (
                // Custom Logo
                <div className="w-8 h-8 shrink-0 flex items-center justify-center">
                    <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                </div>
            ) : (
                // Default Avatar
                <div 
                  className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-base shrink-0 ${avatarClass}`}
                >
                    {(account.issuer || '?').charAt(0).toUpperCase()}
                </div>
            )}
            <div className="min-w-0 flex-1">
                <h3 className="font-semibold text-gray-900 dark:text-white truncate text-sm leading-tight" title={account.issuer}>
                    {account.issuer || t.unknownIssuer}
                </h3>
                <p className="text-xs text-gray-500 dark:text-gray-400 truncate leading-tight" title={account.account}>
                    {account.account}
                </p>
            </div>
        </div>

        {/* Selection Checkbox */}
        <div className="shrink-0 ml-2 z-10" onClick={(e) => e.stopPropagation()}>
             <input 
                type="checkbox" 
                checked={isSelected}
                onChange={() => onToggleSelect(account.id)}
                className={`w-4 h-4 rounded border-gray-300 dark:border-gray-600 cursor-pointer transition-opacity ${checkboxColor} ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
             />
        </div>
      </div>

      {/* Main Content: Token */}
      <div className="flex-1 flex flex-col justify-center items-center py-2 relative px-3 min-h-[90px]">
         {showQR ? (
            <div className="animate-in fade-in zoom-in duration-200 flex flex-col items-center">
                 <div className="bg-white p-1.5 rounded-lg border shadow-sm">
                    <QRCodeSVG value={otpUri} size={100} />
                 </div>
                 <button type="button" onClick={() => onToggleQR(account.id)} className={`text-[10px] text-gray-500 dark:text-gray-400 mt-1 ${hoverText} font-medium`}>
                    {t.backToCode}
                 </button>
            </div>
         ) : (
            <>
                <div 
                    className={`text-4xl sm:text-5xl font-mono font-extrabold text-gray-800 dark:text-gray-100 tracking-widest cursor-pointer hover:scale-105 active:scale-95 transition-all text-center w-full truncate my-1 leading-none`}
                    onClick={handleCopy}
                    title="Click to copy"
                >
                    {formattedToken}
                </div>

                {/* Notes centered below code */}
                {account.notes && (
                    <div className="w-full px-2 text-center mt-1 mb-0.5">
                         <p className="text-[10px] text-gray-400 dark:text-gray-500 truncate w-full bg-gray-50 dark:bg-gray-700/50 rounded px-1.5 py-0.5 inline-block max-w-full" title={account.notes}>
                            {account.notes}
                         </p>
                    </div>
                )}

                {/* Copied Badge */}
                <div 
                    className={`absolute top-[60%] left-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-200 pointer-events-none ${copied ? 'opacity-100 scale-100' : 'opacity-0 scale-90'}`}
                >
                    <span className="text-xs font-semibold bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300 px-2 py-0.5 rounded-full shadow-sm border border-green-200 dark:border-green-800">
                        {t.copied}
                    </span>
                </div>
            </>
         )}
      </div>

      {/* Bottom Section: Progress & Actions */}
      <div className="bg-gray-50/50 dark:bg-gray-700/30 px-3 py-2 border-t border-gray-100 dark:border-gray-700 mt-auto">
         <div className="flex justify-between items-center mb-1.5">
            <div className="text-[10px] font-medium text-gray-400 font-mono">
                {tokenData.seconds}s
            </div>

            <div className="flex gap-1">
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleQR(account.id); }} 
                    className={`p-1.5 rounded-md transition ${qrActiveBg}`}
                    title="QR Code"
                >
                    <QrCode size={14} className="pointer-events-none" />
                 </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onEdit(account); }} 
                    className={`p-1.5 text-gray-400 dark:text-gray-500 ${hoverText} ${hoverBg} rounded-md transition`}
                    title={t.edit}
                >
                    <Edit2 size={14} className="pointer-events-none" />
                </button>
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(account.id); }} 
                    className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-md transition"
                    title={t.delete}
                >
                    <Trash2 size={14} className="pointer-events-none" />
                </button>
            </div>
         </div>

         {/* Progress Bar */}
         <div className="relative h-1 w-full bg-gray-200 dark:bg-gray-600 rounded-full overflow-hidden">
            <div 
                className={`absolute top-0 left-0 h-full transition-all duration-1000 ease-linear ${progressBarColor}`}
                style={{ width: `${tokenData.progress}%` }}
            />
         </div>
      </div>
    </div>
  );
};

export default AccountCard;

import React, { useState, useContext, useRef, useEffect } from 'react';
import { X, Upload, Download, Check, RefreshCw, Copy, Image as ImageIcon, ChevronUp, Grid, List, Trash2, ArrowRight, FileJson, CheckSquare, Square, KeyRound, AlertTriangle, Shield, ShieldOff, Save, CheckCircle, Lock, ArrowLeft, Link, Unlock, ShieldCheck, Info, ChevronLeft, ChevronRight } from 'lucide-react';
import { ImportCandidate, OTPAccount, AppLogo } from '../types';
