                        className={`w-full h-64 p-3 border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono text-[10px] whitespace-pre bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100`}
                        value={tab === 'csv' ? getCSV() : getURIs()}
