                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 max-h-[60vh] overflow-y-auto p-2 bg-gray-50 dark:bg-gray-900/50 rounded-lg border dark:border-gray-700">
                    {accounts.map((a, i) => {
                         const uri = `otpauth://totp/${encodeURIComponent(a.issuer)}:${encodeURIComponent(a.account)}?secret=${a.secret}&issuer=${encodeURIComponent(a.issuer)}&period=${a.period}`;
                         return (
                             <div key={i} className="bg-white dark:bg-gray-800 p-3 rounded-lg border dark:border-gray-700 shadow-sm flex flex-col items-center text-center">
