};

// ... PasswordSettingsModal remains unchanged ...
interface PasswordSettingsModalProps {
    onClose: () => void;
    hasPassword?: boolean;
    isUnlock?: boolean;
    onSetPassword: (pass: string) => Promise<void>;
    onRemovePassword: (currPass: string) => Promise<boolean>;
    onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
    color?: 'blue' | 'orange' | 'emerald';
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, isUnlock = false, onSetPassword, onRemovePassword, onChangePassword, color = 'blue' 
}) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [mode, setMode] = useState<'menu' | 'set' | 'change' | 'remove' | 'unlock'>(isUnlock ? 'unlock' : (hasPassword ? 'menu' : 'set'));

    // Inputs
    const [pass1, setPass1] = useState('');
    const [pass2, setPass2] = useState('');
    const [oldPass, setOldPass] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (mode === 'set' || mode === 'unlock') {
                if (mode === 'set' && pass1 !== pass2) {
                    setError(t.passwordsNoMatch);
                    setLoading(false);
                    return;
                }
                await onSetPassword(pass1);
                onClose();
            } else if (mode === 'change') {
                if (pass1 !== pass2) {
                    setError(t.passwordsNoMatch);
                    setLoading(false);
                    return;
                }
                if (onChangePassword) {
                    const success = await onChangePassword(oldPass, pass1);
                    if (!success) setError(t.wrongPassword);
                    else onClose();
                }
            } else if (mode === 'remove') {
                const success = await onRemovePassword(oldPass);
                if (!success) setError(t.wrongPassword);
                else onClose();
            }
        } catch (err: any) {
             setError(err.message || "Operation failed");
        } finally {
            setLoading(false);
        }
    };

    const headerTitle = () => {
        if (mode === 'unlock') return t.unlockFile;
        if (mode === 'set') return t.setPassword;
        if (mode === 'change') return t.changePassword;
        if (mode === 'remove') return t.removePassword;
        return t.securityTitle;
    };

    return (
        <Modal title={headerTitle()} onClose={onClose} className="max-w-sm">
             {mode === 'menu' ? (
                 <div className="space-y-3 py-2">
                     <button onClick={() => setMode('change')} className="w-full flex items-center justify-between p-3 border dark:border-gray-700 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-700 transition group">
                         <div className="flex items-center gap-3">
                             <div className="bg-blue-100 dark:bg-blue-900/30 p-1.5 rounded-lg text-blue-600 dark:text-blue-400"><KeyRound size={16} /></div>
                             <span className="font-medium text-gray-700 dark:text-gray-200 text-sm">{t.changePassword}</span>
                         </div>
                         <ArrowRight size={16} className="text-gray-300 group-hover:text-gray-500 dark:text-gray-600 dark:group-hover:text-gray-400" />
                     </button>
                     <button onClick={() => setMode('remove')} className="w-full flex items-center justify-between p-3 border dark:border-gray-700 rounded-xl hover:bg-red-50 dark:hover:bg-red-900/10 hover:border-red-100 dark:hover:border-red-900/30 transition group">
                         <div className="flex items-center gap-3">
                             <div className="bg-red-100 dark:bg-red-900/30 p-1.5 rounded-lg text-red-600 dark:text-red-400"><ShieldOff size={16} /></div>
                             <span className="font-medium text-gray-700 dark:text-gray-200 text-sm">{t.removePassword}</span>
                         </div>
                         <ArrowRight size={16} className="text-gray-300 group-hover:text-red-400 dark:text-gray-600 dark:group-hover:text-red-400" />
                     </button>
                 </div>
             ) : (
                 <form onSubmit={handleSubmit} className="space-y-4">
                     {error && <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-2.5 rounded-lg text-xs flex items-center gap-2"><AlertTriangle size={14}/> {error}</div>}

                     {(mode === 'change' || mode === 'remove') && (
                         <div>
                             <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{mode === 'change' ? "Old Password" : t.enterPassword}</label>
                             <input type="password" required className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                                value={oldPass} onChange={e => setOldPass(e.target.value)} autoFocus />
                         </div>
                     )}

                     {(mode === 'set' || mode === 'change' || mode === 'unlock') && (
                         <div>
                             <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">
                                 {mode === 'change' ? "New Password" : (mode === 'unlock' ? t.enterFilePassword : t.enterPassword)}
                             </label>
                             <input type="password" required className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                                value={pass1} onChange={e => setPass1(e.target.value)} autoFocus={mode === 'set' || mode === 'unlock'} />
                         </div>
                     )}

                     {(mode === 'set' || mode === 'change') && (
                         <div>
                             <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.confirmPassword}</label>
                             <input type="password" required className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                                value={pass2} onChange={e => setPass2(e.target.value)} />
                         </div>
                     )}

                     <div className="flex gap-3 mt-4">
                         {!isUnlock && hasPassword && (
                             <button type="button" onClick={() => setMode('menu')} className="px-3 py-2 text-gray-500 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700 rounded-lg text-sm">
                                 {t.btnCancel}
                             </button>
                         )}
                         <button type="submit" disabled={loading} className={`flex-1 ${theme.btn} text-white py-2 rounded-lg font-medium text-sm disabled:opacity-50`}>
                             {loading ? '...' : (mode === 'remove' ? t.removePassword : (mode === 'unlock' ? t.unlock : t.btnSave))}
                         </button>
                     </div>
                 </form>
             )}
        </Modal>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { AppLogo } from '../types';
import { ChevronDown, Search, X, Check } from 'lucide-react';

interface LogoSelectProps {
  logos: AppLogo[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  color?: 'blue' | 'orange' | 'emerald';
}

const LogoSelect: React.FC<LogoSelectProps> = ({ logos, value, onChange, placeholder = "Select Logo", className = "", color = 'blue' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const [lockedHeight, setLockedHeight] = useState<string | undefined>(undefined);

  const selectedLogo = logos.find(l => l.id === value);
  const filteredLogos = logos.filter(l => l.name.toLowerCase().includes(search.toLowerCase()));

  // Theme styles
  const getThemeColor = () => {
      switch(color) {
          case 'emerald': return 'text-emerald-600 bg-emerald-50 border-emerald-200 ring-emerald-500 dark:bg-emerald-900/30 dark:border-emerald-700 dark:text-emerald-400';
          case 'orange': return 'text-orange-600 bg-orange-50 border-orange-200 ring-orange-500 dark:bg-orange-900/30 dark:border-orange-700 dark:text-orange-400';
          default: return 'text-blue-600 bg-blue-50 border-blue-200 ring-blue-500 dark:bg-blue-900/30 dark:border-blue-700 dark:text-blue-400';
      }
  };
  const activeClass = getThemeColor();

  const handleOpen = () => {
      setSearch("");
      setLockedHeight(undefined);
      setIsOpen(true);
  };

  useEffect(() => {
      if (isOpen) {
          // Measure height after render to lock it
          const timer = setTimeout(() => {
              if (containerRef.current) {
                  setLockedHeight(`${containerRef.current.offsetHeight}px`);
              }
          }, 10);
          return () => clearTimeout(timer);
      }
  }, [isOpen]);

  return (
    <>
      {/* Trigger Button */}
      <div className={`relative ${className}`}>
        <button
          type="button"
          onClick={handleOpen}
          className="w-full flex items-center justify-between border border-gray-300 dark:border-gray-600 rounded-lg p-2 bg-white dark:bg-gray-700 text-left focus:ring-2 focus:ring-opacity-50 outline-none transition hover:border-gray-400 dark:hover:border-gray-500"
          style={{ borderColor: isOpen ? 'transparent' : '' }}
        >
          {selectedLogo ? (
              <div className="flex items-center gap-2">
                  <div className="w-5 h-5 shrink-0 bg-gray-50 dark:bg-gray-600 border dark:border-gray-500 rounded p-0.5 flex items-center justify-center">
                     <img src={selectedLogo.data} alt={selectedLogo.name} className="max-w-full max-h-full object-contain" />
                  </div>
                  <span className="truncate font-medium text-gray-700 dark:text-gray-200 text-sm">{selectedLogo.name}</span>
              </div>
          ) : (
              <span className="text-gray-500 dark:text-gray-400 text-sm">{placeholder}</span>
          )}
          <ChevronDown size={16} className="text-gray-400" />
        </button>
      </div>

      {/* Drawer Portal (Fixed Overlay) */}
      {isOpen && (
        <div className="fixed inset-0 z-[70] flex justify-center items-end sm:items-end">
          {/* Backdrop */}
          <div 
            className="absolute inset-0 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200"
            onClick={() => setIsOpen(false)}
          />

          {/* Drawer Content */}
          <div 
            ref={containerRef}
            style={{ height: lockedHeight }}
            className="relative w-full max-w-lg bg-white dark:bg-gray-800 rounded-t-xl shadow-2xl max-h-[70vh] flex flex-col animate-in slide-in-from-bottom duration-300"
          >
            {/* Handle */}
            <div className="flex justify-center pt-2 pb-1 shrink-0 cursor-pointer" onClick={() => setIsOpen(false)}>
                <div className="w-10 h-1 bg-gray-300 dark:bg-gray-600 rounded-full hover:bg-gray-400 transition" />
            </div>

            {/* Header with Search */}
            <div className="p-3 border-b dark:border-gray-700 shrink-0 flex gap-2 items-center">
                <div className="relative flex-1">
                    <Search size={14} className="absolute left-3 top-2.5 text-gray-400" />
                    <input
                        type="text"
                        className={`w-full pl-9 pr-4 py-2 bg-gray-100 dark:bg-gray-700 border-transparent focus:bg-white dark:focus:bg-gray-600 border focus:ring-2 rounded-lg text-sm outline-none transition text-gray-900 dark:text-white ${color === 'orange' ? 'focus:border-orange-500 focus:ring-orange-200' : (color === 'emerald' ? 'focus:border-emerald-500 focus:ring-emerald-200' : 'focus:border-blue-500 focus:ring-blue-200')}`}
                        placeholder="Search logos..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        autoFocus
                    />
                </div>
                <button onClick={() => setIsOpen(false)} className="p-1.5 bg-gray-100 dark:bg-gray-700 rounded-full hover:bg-gray-200 dark:hover:bg-gray-600 text-gray-600 dark:text-gray-300">
                    <X size={16} />
                </button>
            </div>

            {/* List */}
            <div className="overflow-y-auto flex-1 p-2 space-y-1">
               <div 
                  className={`flex items-center justify-between p-2 cursor-pointer rounded-lg transition ${!value ? activeClass : 'hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-300'}`}
                  onClick={() => { onChange(""); setIsOpen(false); }}
               >
                  <span className="font-medium text-sm">No Logo (Default)</span>
                  {!value && <Check size={14} />}
               </div>

               {filteredLogos.map(logo => (
                   <div
                      key={logo.id}
                      className={`flex items-center justify-between p-2 cursor-pointer rounded-lg transition ${value === logo.id ? activeClass : 'hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200'}`}
                      onClick={() => { onChange(logo.id); setIsOpen(false); }}
                   >
                      <div className="flex items-center gap-2">
                          <div className="w-8 h-8 shrink-0 bg-white dark:bg-gray-600 border dark:border-gray-500 rounded-lg p-0.5 flex items-center justify-center">
                              <img src={logo.data} alt={logo.name} className="max-w-full max-h-full object-contain" />
                          </div>
                          <span className="font-medium text-sm">{logo.name}</span>
                      </div>
                      {value === logo.id && <Check size={14} />}
                   </div>
               ))}

               {filteredLogos.length === 0 && (
                   <div className="p-6 text-center text-gray-400 flex flex-col items-center">
                       <Search size={24} className="mb-2 opacity-20" />
                       <p className="text-xs">No logos found</p>
                   </div>
               )}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default LogoSelect;

import React, { useState, useContext } from 'react';
import { Lock, AlertCircle, KeyRound, RefreshCcw } from 'lucide-react';
import { LanguageContext } from '../utils/i18n';

interface LockScreenProps {
  onUnlock: (password: string) => Promise<boolean>;
  onReset: () => void;
}

const LockScreen: React.FC<LockScreenProps> = ({ onUnlock, onReset }) => {
  const { t } = useContext(LanguageContext);
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);

  const handleUnlock = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!password) return;

    setLoading(true);
    setError(false);

    // Give UI a moment to update loading state before heavy crypto (though async usually handles it)
    setTimeout(async () => {
        const success = await onUnlock(password);
        if (!success) {
            setError(true);
            setLoading(false);
        } else {
            // Success logic handled by parent (unmounting this component)
        }
    }, 50);
  };

  const handleReset = () => {
      if (confirm(t.resetWarning)) {
          onReset();
      }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-gray-100 dark:bg-gray-900 flex flex-col items-center justify-center p-4">
       <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-8 w-full max-w-md text-center">
           <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 rounded-full flex items-center justify-center mx-auto mb-6 text-blue-600 dark:text-blue-400">
               <Lock size={32} />
           </div>

           <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">{t.lockScreenTitle}</h1>
           <p className="text-gray-500 dark:text-gray-400 mb-6">{t.enterPassword}</p>

           <form onSubmit={handleUnlock} className="space-y-4">
               <div>
                   <input 
                      type="password" 
                      className={`w-full p-3 border rounded-lg outline-none transition text-center text-lg bg-white dark:bg-gray-700 dark:text-white ${error ? 'border-red-500 bg-red-50 dark:bg-red-900/20' : 'border-gray-300 dark:border-gray-600 focus:border-blue-500 focus:ring-2 focus:ring-blue-100'}`}
                      placeholder="••••••"
                      value={password}
                      onChange={e => { setPassword(e.target.value); setError(false); }}
                      autoFocus
                   />
                   {error && <p className="text-red-500 text-sm mt-2 flex items-center justify-center gap-1"><AlertCircle size={14}/> {t.wrongPassword}</p>}
               </div>

               <button 
                  type="submit" 
                  disabled={loading || !password}
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-lg transition disabled:opacity-70 disabled:cursor-not-allowed"
               >
                   {loading ? '...' : t.unlock}
               </button>
           </form>

           <div className="mt-6 pt-6 border-t border-gray-100 dark:border-gray-700">
               {!showResetConfirm ? (
                   <button 
                        onClick={() => setShowResetConfirm(true)}
                        className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 text-sm font-medium flex items-center justify-center gap-1 mx-auto"
                   >
                        {t.forgotPassword}
                   </button>
               ) : (
                   <div className="animate-in fade-in slide-in-from-top-2">
                       <p className="text-xs text-red-500 mb-2">{t.resetWarning}</p>
                       <button 
                            onClick={handleReset}
                            className="text-white bg-red-500 hover:bg-red-600 px-4 py-2 rounded-lg text-sm font-medium w-full"
                       >
                            {t.resetConfirm}
                       </button>
                       <button 
                            onClick={() => setShowResetConfirm(false)}
                            className="text-gray-500 mt-2 text-xs hover:underline"
                       >
                            {t.btnCancel}
                       </button>
                   </div>
               )}
           </div>
       </div>
    </div>
  );
};

export default LockScreen;

import React, { useEffect } from 'react';
import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';

export type ToastType = 'success' | 'error' | 'info';

export interface ToastMessage {
  id: string;
  message: string;
  type: ToastType;
}

interface ToastProps {
  toast: ToastMessage;
  onClose: (id: string) => void;
}

const Toast: React.FC<ToastProps> = ({ toast, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(() => onClose(toast.id), 3000);
    return () => clearTimeout(timer);
  }, [toast.id, onClose]);

  const icons = {
    success: <CheckCircle size={20} className="text-green-500" />,
    error: <AlertCircle size={20} className="text-red-500" />,
    info: <Info size={20} className="text-blue-500" />
  };

  return (
    <div className={`flex items-center gap-3 p-4 rounded-lg shadow-lg border dark:border-gray-700 animate-in slide-in-from-top-2 duration-300 max-w-sm w-full bg-white dark:bg-gray-800 z-[110]`}>
       <div className="shrink-0">{icons[toast.type]}</div>
       <p className="flex-1 text-sm font-medium text-gray-800 dark:text-gray-200">{toast.message}</p>
       <button onClick={() => onClose(toast.id)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
         <X size={16} />
       </button>
    </div>
  );
};

