                  {error && <p className="text-red-500 text-xs flex items-center gap-1"><AlertTriangle size={12} /> {error}</p>}

                  <div className="flex gap-2">
                      <button type="button" onClick={() => setView('menu')} className="flex-1 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 py-2 rounded-lg text-sm font-medium">
                          {t.btnCancel}
                      </button>
                      <button type="submit" className={`flex-1 ${theme.btn} text-white py-2 rounded-lg font-medium text-sm`}>
