              </form>
          )}
      </Modal>
  );
};

export type StorageMode = 'local' | 'session' | 'file';

export interface AppLogo {
  id: string; // Unique identifier (integer string or uuid)
  name: string;
  data: string; // Base64 or URL
  isDefault?: boolean;
}

export interface OTPAccount {
  id: string;
  issuer: string;
  account: string;
  secret: string;
  period: number;
  notes?: string;
  logoId?: string; // Reference to AppLogo.id
  algorithm?: string;
  digits?: number;
  createdAt: number;
}

export interface ImportCandidate {
  raw: string;
  issuer: string;
  account: string;
  secret: string;
  period: number;
  isValid: boolean;
  notes?: string;
  logoId?: string;
}

export interface DefaultLogo {
  id: number;
  name: string;
  data: string;
}

export interface FileSpace {
  id: string;
  displayName: string;
  handle: FileSystemFileHandle | null; // Nullable for legacy browser support
  isEncrypted: boolean;
  password?: string; // Temporarily store password in memory for auto-saving
  isVirtual?: boolean; // True if using legacy <input type="file"> method (no auto-save)
  notes?: string; // Persistent remarks for this storage space
  needsPermission?: boolean; // UI state for persisted handles
}

/**
 * Simple IndexedDB wrapper to store FileSystemHandles
 */
const DB_NAME = 'SecureAuthFileStorage';
const STORE_NAME = 'handles';

export const handleStore = {
  getDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = () => {
        request.result.createObjectStore(STORE_NAME);
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  async save(id: string, handle: FileSystemHandle): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).put(handle, id);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  },

  async get(id: string): Promise<FileSystemHandle | null> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const request = tx.objectStore(STORE_NAME).get(id);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
    });
  },

  async remove(id: string): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).delete(id);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
};

import React, { useState, useEffect, useRef } from 'react';
