              {filteredAccounts.map(acc => <AccountCard key={acc.id} account={acc} logo={customLogos.find(l => l.id === acc.logoId)} onDelete={handleDelete} onEdit={handleEdit} isSelected={selectedIds.has(acc.id)} onToggleSelect={handleToggleSelect} showQR={visibleQRIds.has(acc.id)} onToggleQR={handleToggleQR} color={themeColor} />)}
            </div>
