                    {showInfo && (
                        <div className={`absolute top-full right-0 mt-2 w-64 p-3 bg-white dark:bg-gray-800 border rounded-lg shadow-xl z-[100] animate-in fade-in zoom-in duration-150 ${themeClasses.borderColor}`}>
