interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    // Check for Google Auth Migration URI
    if (text.trim().startsWith('otpauth-migration://')) {
        try {
            const migrationAccounts = parseMigrationURI(text.trim());
            const candidates: ImportCandidate[] = migrationAccounts.map(acc => ({
                raw: 'otpauth-migration import',
                issuer: acc.issuer,
                account: acc.name,
                secret: acc.secret,
                period: 30, // Google Auth Default
                isValid: true,
                notes: 'Imported via Google Migration'
            }));
            onPreview(candidates);
            return;
        } catch (e) {
            console.error(e);
            alert("Failed to parse migration URI");
            return;
        }
    }

    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            if (qrData.startsWith('otpauth-migration://')) {
                try {
                    const migrationAccounts = parseMigrationURI(qrData);
                    migrationAccounts.forEach(acc => {
                        candidates.push({
                            raw: 'otpauth-migration import',
                            issuer: acc.issuer,
                            account: acc.name,
                            secret: acc.secret,
                            period: 30,
                            isValid: true,
                            notes: 'Imported via Google Migration'
                        });
                    });
                } catch (e) {
                    candidates.push({ raw: file.name, issuer: 'Error', account: 'Migration Parse Error', secret: '', period: 0, isValid: false });
                }
            } else {
                const parsed = parseLine(qrData);
                if (parsed.isValid) {
                     candidates.push(parsed);
                } else {
                     candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
                }
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b dark:border-gray-700">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500 dark:text-gray-400">{t.textPaste} <span className="font-mono bg-gray-100 dark:bg-gray-700 px-1 rounded">Issuer, Account, Secret, Period</span></p>
                <textarea 
                    className={`w-full h-40 p-3 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30\notpauth-migration://offline?data=...`}
                />
                 <div>
                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none text-center font-mono bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-2 text-sm`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center">
                     <ImageIcon size={24} className="text-gray-400 dark:text-gray-300" />
                 </div>
                 <div>
                     <p className="text-gray-600 dark:text-gray-300 mb-4 text-sm">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-5 py-2.5 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition text-sm`}>
                         <Upload size={16} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-[10px] text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

interface ImportPreviewModalProps {
    isOpen: boolean;
    candidates: ImportCandidate[];
    onClose: () => void;
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewModal: React.FC<ImportPreviewModalProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

    useEffect(() => {
        if (isOpen && candidates.length > 0) {
            // Select all valid candidates by default
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        const toImport = candidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(toImport);
    };

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    const getAvatarColor = (name: string) => {
        const colors = ['bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300', 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300', 'bg-violet-100 text-violet-700 dark:bg-violet-900 dark:text-violet-300', 'bg-amber-100 text-amber-700 dark:bg-amber-900 dark:text-amber-300', 'bg-rose-100 text-rose-700 dark:bg-rose-900 dark:text-rose-300', 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900 dark:text-cyan-300'];
        const index = name.length % colors.length;
        return colors[index];
    };

    return (
        <Modal title={`${t.headerImport} (${candidates.length})`} onClose={onClose} className="max-w-2xl">
            <div className="flex flex-col h-full max-h-[70vh]">
                <div className="flex justify-between items-center mb-4 px-1">
                    <p className="text-xs text-gray-500 dark:text-gray-400">{selectedIndices.size} selected</p>
                </div>

                <div className="overflow-y-auto flex-1 bg-gray-50 dark:bg-gray-900/50 rounded-lg border dark:border-gray-700">
                    {candidates.map((c, i) => {
                         const logo = c.logoId ? logos.find(l => l.id === c.logoId) : null;
                         const avatarClass = getAvatarColor(c.issuer || 'U');
                         return (
                            <div key={i} className={`flex items-start gap-3 p-3 border-b dark:border-gray-700 bg-white dark:bg-gray-800 last:border-b-0 ${!c.isValid ? 'opacity-50' : 'cursor-pointer'}`} onClick={() => c.isValid && toggleSelect(i)}>
                                <div className="pt-1">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedIndices.has(i)} 
                                        onChange={() => {}} 
                                        disabled={!c.isValid}
                                        className={`w-4 h-4 rounded border-gray-300 ${theme.checkbox}`}
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center">
                                        <div className="flex items-center gap-2.5 overflow-hidden min-w-0">
                                            {logo ? (
                                                <div className="w-6 h-6 shrink-0 flex items-center justify-center">
                                                    <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                                                </div>
                                            ) : (
                                                <div className={`w-6 h-6 rounded flex items-center justify-center font-bold text-xs shrink-0 ${avatarClass}`}>
                                                    {(c.issuer || '?').charAt(0).toUpperCase()}
                                                </div>
                                            )}
                                           <span className="font-bold text-sm text-gray-900 dark:text-white truncate">{c.issuer || 'Unknown'}</span>
                                        </div>
                                        <span className="text-[10px] text-gray-400 font-mono shrink-0 ml-2">{c.period}s</span>
                                    </div>
                                    <p className="text-xs text-gray-600 dark:text-gray-400 truncate mt-0.5 ml-8.5">{c.account}</p>
                                    <div className="mt-1 flex items-center gap-2 ml-8.5">
                                        <span className="text-[10px] text-gray-400 font-mono truncate max-w-[200px]" title={c.secret}>
                                            {c.secret ? c.secret.substring(0, 4) + '...' + c.secret.substring(c.secret.length-4) : 'NO SECRET'}
                                        </span>
                                        {!c.isValid && <span className="text-[10px] text-red-500 bg-red-50 px-1 rounded">Invalid</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="pt-4 mt-4 border-t dark:border-gray-700 flex justify-end gap-3">
                     <button onClick={onClose} className="px-3 py-2 border dark:border-gray-600 rounded-lg text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 font-medium">
                         {t.btnCancel}
                     </button>
                     <button 
                        onClick={handleConfirm}
                        disabled={selectedIndices.size === 0}
                        className={`${theme.btn} text-white px-5 py-2 rounded-lg text-sm font-medium shadow-sm disabled:opacity-50`}
                     >
                        {t.btnImport} ({selectedIndices.size})
                     </button>
                </div>
            </div>
        </Modal>
    )
}

interface LogoManagerModalProps {
  onClose: () => void;
  logos: AppLogo[];
  onAddLogo: (logo: AppLogo) => void;
  onDeleteLogo: (id: string) => void;
  onBatchDeleteLogo: (ids: string[]) => void;
  onImportLogos: (logos: AppLogo[]) => void;
  inline?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ 
    onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');
  const [newLogoName, setNewLogoName] = useState('');
  const [newLogoUrl, setNewLogoUrl] = useState('');

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [importCandidates, setImportCandidates] = useState<AppLogo[]>([]);
  const [selectedImportIds, setSelectedImportIds] = useState<Set<string>>(new Set());

  useEffect(() => {
      setSelectedIds(new Set());
  }, [tab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setNewLogoUrl(ev.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAdd = () => {
      if (newLogoName && newLogoUrl) {
          onAddLogo({
              id: uuidv4(),
              name: newLogoName,
              data: newLogoUrl
          });
          setNewLogoName('');
          setNewLogoUrl('');
          setTab('list');
      }
  };

  const handleImportFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (ev.target?.result) {
                try {
                    const parsed = JSON.parse(ev.target.result as string);
                    if (Array.isArray(parsed)) {
                        const valid = parsed.filter(item => item.name && item.data);
                        const candidates = valid.map((l: any) => ({...l, id: l.id || uuidv4() }));
                        setImportCandidates(candidates);
                        setSelectedImportIds(new Set(candidates.map((c: any) => c.id)));
                    } else {
                        alert("Invalid JSON Format: Expected an array.");
                    }
                } catch (e) {
                    alert("Invalid JSON File.");
                }
            }
        };
        reader.readAsText(file);
        e.target.value = ''; 
    }
  };

  const handleConfirmImport = () => {
      const toImport = importCandidates.filter(c => selectedImportIds.has(c.id));
      if (toImport.length === 0) return;
      onImportLogos(toImport);
      setImportCandidates([]); 
      setTab('list');
  };

  const handleClearImport = () => {
      setImportCandidates([]);
      setSelectedImportIds(new Set());
  };

  const toggleImportSelect = (id: string) => {
      const next = new Set(selectedImportIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedImportIds(next);
  };

  const toggleImportSelectAll = () => {
      if (selectedImportIds.size === importCandidates.length) {
          setSelectedImportIds(new Set());
      } else {
          setSelectedImportIds(new Set(importCandidates.map(c => c.id)));
      }
  };

  const handleExportSelected = () => {
      if (selectedIds.size === 0) return;
      const selectedLogos = logos.filter(l => selectedIds.has(l.id));
      const json = JSON.stringify(selectedLogos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos-selected.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Selected logos exported to file");
  };

  const handleExportAll = () => {
      const json = JSON.stringify(logos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'secureauth-logos.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Logos exported to file");
  };

  const toggleSelect = (id: string) => {
      const next = new Set(selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedIds(next);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === logos.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(logos.map(l => l.id)));
      }
  };

  const handleDeleteSelected = () => {
      if (confirm(`Delete ${selectedIds.size} selected logos?`)) {
          onBatchDeleteLogo(Array.from(selectedIds));
          setSelectedIds(new Set());
      }
  };

  const content = (
      <div className={`flex flex-col relative ${inline ? '' : 'h-full'}`}>
          <div className="flex gap-4 mb-4 border-b dark:border-gray-700 shrink-0 items-center justify-between">
            <div className="flex gap-4">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`} onClick={() => setTab('list')}>
                  {t.tabLogoList}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`} onClick={() => setTab('add')}>
                  {t.tabAddLogo}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`} onClick={() => setTab('import')}>
                  {t.tabImportLogos}
                </button>
            </div>

            {tab === 'list' && logos.length > 0 && (
                 <label className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedIds.size === logos.length} onChange={toggleSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
            {tab === 'import' && importCandidates.length > 0 && (
                 <label className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedImportIds.size === importCandidates.length} onChange={toggleImportSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
          </div>

          <div className={`${inline ? '' : 'flex-1 overflow-y-auto min-h-[300px]'} ${(selectedIds.size > 0 && tab === 'list') || (importCandidates.length > 0 && tab === 'import') ? 'pb-20' : 'pb-4'}`}>

              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      {/* Denser grid: mobile 5 cols (was 4), large screen 10 cols (was 8) */}
                      <div className="grid grid-cols-5 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-2">
                          {logos.map(l => {
                              const isSelected = selectedIds.has(l.id);
                              return (
                                  <div 
                                    key={l.id} 
                                    onClick={() => toggleSelect(l.id)}
                                    className={`aspect-square border dark:border-gray-600 rounded-lg p-1 relative group cursor-pointer transition flex flex-col items-center justify-center bg-white dark:bg-gray-700 ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                  >
                                      <div className={`absolute top-1 right-1 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                           <div className={`w-3 h-3 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 dark:border-gray-500 bg-white dark:bg-gray-600'}`}>
                                                {isSelected && <Check size={8} />}
                                           </div>
                                      </div>
                                      <div className="w-6 h-6 sm:w-8 sm:h-8 flex items-center justify-center mb-1">
                                          <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                      </div>
                                      <p className="text-[8px] text-center font-medium truncate w-full px-1 text-gray-700 dark:text-gray-200" title={l.name}>{l.name}</p>
                                  </div>
                              );
                          })}
                      </div>
                  </div>
              )}

              {tab === 'add' && (
                  <div className="space-y-4 max-w-md mx-auto py-4">
                       <div>
                           <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.labelLogoName}</label>
                           <input type="text" className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                            value={newLogoName} onChange={e => setNewLogoName(e.target.value)} />
                       </div>
                       <div>
                           <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.labelLogoUrl}</label>
                           <input type="text" className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                            value={newLogoUrl} onChange={e => setNewLogoUrl(e.target.value)} placeholder="https://..." />
                       </div>
                       <div className="text-center text-xs text-gray-500 py-1">- OR -</div>
                       <div>
                           <label className={`flex items-center justify-center gap-2 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-4 cursor-pointer hover:border-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700 transition`}>
                               <Upload size={16} className="text-gray-400" />
                               <span className="text-gray-600 dark:text-gray-300 text-sm">{t.btnUploadLogo}</span>
                               <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                           </label>
                       </div>
                       {newLogoUrl && (
                           <div className="mt-4 flex justify-center">
                               <img src={newLogoUrl} alt="Preview" className="h-16 object-contain border rounded p-1" />
                           </div>
                       )}
                       <button onClick={handleAdd} disabled={!newLogoName || !newLogoUrl} className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-4 text-sm disabled:opacity-50`}>
                           {t.btnAddLogo}
                       </button>
                  </div>
              )}

              {tab === 'import' && (
                  <div className="space-y-4">
                      {importCandidates.length === 0 ? (
                          <>
                              <div className="flex gap-4">
                                  <button onClick={handleExportAll} className="flex-1 border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2">
                                      <Download size={14} /> {t.btnExportLogos}
                                  </button>
                              </div>

                              <div className="py-4">
                                  <label 
                                      onDragOver={e => e.preventDefault()}
                                      className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-6 text-center text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700 transition cursor-pointer block"
                                  >
                                      <FileJson className="mx-auto h-8 w-8 text-gray-400 mb-2" />
                                      <p className="text-sm font-medium text-gray-700 dark:text-gray-200">Import Logos from JSON File</p>
                                      <p className="text-xs text-gray-400 mt-1">Click to browse or drag file here</p>
                                      <input type="file" accept=".json,application/json" className="hidden" onChange={handleImportFileSelect} />
                                  </label>
                              </div>
                          </>
                      ) : (
                          <div>
                              <div className="flex items-center justify-between mb-4">
                                  <p className="text-xs text-gray-600 dark:text-gray-300">Found <b>{importCandidates.length}</b> logos.</p>
                                  <button onClick={handleClearImport} className="text-[10px] text-red-500 hover:text-red-700 flex items-center gap-1">
                                      <Trash2 size={10} /> Clear Import
                                  </button>
                              </div>
                              <div className="grid grid-cols-5 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-2">
                                  {importCandidates.map(l => {
                                      const isSelected = selectedImportIds.has(l.id);
                                      return (
                                          <div 
                                            key={l.id} 
                                            onClick={() => toggleImportSelect(l.id)}
                                            className={`aspect-square border dark:border-gray-600 rounded-lg p-1 relative group cursor-pointer transition flex flex-col items-center justify-center bg-white dark:bg-gray-700 ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                          >
                                              <div className={`absolute top-1 right-1`}>
                                                   <div className={`w-3 h-3 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 dark:border-gray-500 bg-white dark:bg-gray-600'}`}>
                                                        {isSelected && <Check size={8} />}
                                                   </div>
                                              </div>
                                              <div className="w-6 h-6 sm:w-8 sm:h-8 flex items-center justify-center mb-1">
                                                  <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                              </div>
                                              <p className="text-[8px] text-center font-medium truncate w-full px-1 text-gray-700 dark:text-gray-200">{l.name}</p>
                                          </div>
                                      );
                                  })}
                              </div>
                          </div>
                      )}
                  </div>
              )}
          </div>

          {selectedIds.size > 0 && tab === 'list' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-3 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-3">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 dark:text-gray-200 ml-1 text-sm">{selectedIds.size} {t.selected}</span>
                       </div>
                       <div className="grid grid-cols-2 gap-2 w-full sm:flex sm:w-auto sm:gap-2">
                            <button onClick={handleExportSelected} className="flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-xs font-medium">
                                 <Download size={14} /> {t.exportSelected}
                            </button>
                            <button onClick={handleDeleteSelected} className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-100 dark:bg-red-900/20 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400 px-3 py-2 rounded-lg transition text-xs font-medium">
                                 <Trash2 size={14} /> {t.deleteSelected}
                            </button>
                       </div>
                   </div>
              </div>
          )}

          {importCandidates.length > 0 && tab === 'import' && (
              <div className="fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-3 z-[60] animate-in slide-in-from-bottom duration-300">
                   <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-center gap-3">
                       <div className="w-full sm:w-auto flex justify-between sm:justify-start items-center">
                           <span className="font-semibold text-gray-700 dark:text-gray-200 ml-1 text-sm">{selectedImportIds.size} {t.selected}</span>
                       </div>
                       <div className="flex gap-2 w-full sm:w-auto">
                            <button onClick={handleClearImport} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 px-3 py-2 rounded-lg transition text-xs font-medium">
                                 {t.btnCancel}
                            </button>
                            <button onClick={handleConfirmImport} disabled={selectedImportIds.size === 0} className={`flex-[2] sm:flex-none flex items-center justify-center gap-2 ${theme.btn} text-white px-5 py-2 rounded-lg transition text-xs font-medium disabled:opacity-50`}>
                                 <Download size={14} /> {t.btnImportLogos}
                            </button>
                       </div>
                   </div>
              </div>
          )}
      </div>
  );

  if (inline) {
      return content;
  }

  return (
      <Modal title={t.modalLogoManagerTitle} onClose={onClose} className="max-w-2xl">
          {content}
      </Modal>
  );
};

interface BatchExportModalProps {
  accounts: OTPAccount[];
  onClose: () => void;
  color?: 'blue' | 'orange' | 'emerald';
}

export const BatchExportModal: React.FC<BatchExportModalProps> = ({ accounts, onClose, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'csv' | 'uri' | 'qr'>('csv');
  const [includeLogo, setIncludeLogo] = useState(false);
  const [copied, setCopied] = useState(false);

  const getCSV = () => {
    return accounts.map(acc => {
      // Issuer, Account, Secret, Period, Notes, LogoID
      return `${acc.issuer},${acc.account},${acc.secret},${acc.period},${acc.notes || ''}${includeLogo ? `,${acc.logoId || ''}` : ''}`;
    }).join('\n');
  };

  const getURIs = () => {
    return accounts.map(acc => {
       return `otpauth://totp/${encodeURIComponent(acc.issuer)}:${encodeURIComponent(acc.account)}?secret=${acc.secret}&issuer=${encodeURIComponent(acc.issuer)}&period=${acc.period}`;
    }).join('\n');
  };

  const contentToCopy = tab === 'csv' ? getCSV() : getURIs();

  const handleCopy = () => {
    navigator.clipboard.writeText(contentToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Modal title={`${t.modalExportTitle} (${accounts.length})`} onClose={onClose} className="max-w-4xl">
       <div className="flex gap-4 mb-4 border-b dark:border-gray-700">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'csv' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('csv')}
            >
              {t.tabCSV}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'uri' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('uri')}
            >
              {t.tabURI}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('qr')}
            >
              {t.tabQR}
            </button>
       </div>

       {tab !== 'qr' ? (
         <div className="space-y-4">
            <div className="flex justify-between items-center">
                <p className="text-sm text-gray-500 dark:text-gray-400">
                    {tab === 'csv' ? t.descCSV : t.descURI}
                </p>
                {tab === 'csv' && (
                    <label className="flex items-center gap-2 text-xs text-gray-600 dark:text-gray-300 cursor-pointer">
                        <input type="checkbox" checked={includeLogo} onChange={e => setIncludeLogo(e.target.checked)} className={`rounded ${theme.checkbox}`} />
                        {t.labelIncludeLogo}
                    </label>
                )}
            </div>
            <textarea 
                readOnly
                className={`w-full h-60 p-3 text-xs border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white whitespace-pre`}
                value={contentToCopy}
            />
            <button onClick={handleCopy} className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-2 text-sm flex items-center justify-center gap-2`}>
                {copied ? <Check size={16} /> : <Copy size={16} />}
                {copied ? t.copied : t.btnCopy}
            </button>
         </div>
       ) : (
         <div className="space-y-4 h-[60vh] overflow-y-auto pr-2">
             <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{t.descQR}</p>
             <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                 {accounts.map(acc => {
                     const uri = `otpauth://totp/${encodeURIComponent(acc.issuer)}:${encodeURIComponent(acc.account)}?secret=${acc.secret}&issuer=${encodeURIComponent(acc.issuer)}&period=${acc.period}`;
                     return (
                         <div key={acc.id} className="bg-white p-2 rounded-lg border border-gray-200 shadow-sm flex flex-col items-center">
                             <QRCodeSVG value={uri} size={120} className="mb-2" />
                             <p className="text-xs font-bold text-center w-full truncate">{acc.issuer}</p>
                             <p className="text-[10px] text-gray-500 text-center w-full truncate">{acc.account}</p>
                         </div>
                     );
                 })}
             </div>
         </div>
       )}
    </Modal>
  );
};

interface PasswordSettingsModalProps {
  onClose: () => void;
  hasPassword: boolean;
  onSetPassword: (password: string) => Promise<void | boolean>;
  onRemovePassword: (password: string) => Promise<boolean>;
  onChangePassword?: (oldPass: string, newPass: string) => Promise<boolean>;
  color?: 'blue' | 'orange' | 'emerald';
  isUnlock?: boolean; // If true, only show unlock UI (re-using onSetPassword as unlock handler)
}

export const PasswordSettingsModal: React.FC<PasswordSettingsModalProps> = ({ 
    onClose, hasPassword, onSetPassword, onRemovePassword, onChangePassword, color = 'blue', isUnlock = false 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [view, setView] = useState<'menu' | 'set' | 'remove' | 'change'>(isUnlock ? 'set' : (hasPassword ? 'menu' : 'set'));

  // Form States
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [currentPassword, setCurrentPassword] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
      setPassword('');
      setConfirmPassword('');
      setCurrentPassword('');
      setError('');
  }, [view]);

  const handleSet = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!isUnlock && password !== confirmPassword) {
          setError(t.passwordsNoMatch);
          return;
      }
      try {
          await onSetPassword(password);
          if (isUnlock) {
              // Usually onUnlock doesn't close modal automatically if we want to handle loading state, 
              // but here we assume onSetPassword throws if failed or parent closes modal on success?
              // The App.tsx implementation of handleUnlockFile throws on error, or closes modal on success.
          } else {
             onClose();
          }
      } catch (err) {
          setError(t.wrongPassword);
      }
  };

  const handleRemove = async (e: React.FormEvent) => {
      e.preventDefault();
      const success = await onRemovePassword(currentPassword);
      if (success) onClose();
      else setError(t.wrongPassword);
  };

  const handleChange = async (e: React.FormEvent) => {
      e.preventDefault();
      if (password !== confirmPassword) {
          setError(t.passwordsNoMatch);
          return;
      }
      if (onChangePassword) {
          const success = await onChangePassword(currentPassword, password);
          if (success) onClose();
          else setError(t.wrongPassword);
      }
  };

  const title = isUnlock ? t.unlockFile : (hasPassword ? t.securityTitle : t.setPassword);

  return (
      <Modal title={title} onClose={onClose} className="max-w-md">
          {view === 'menu' && (
              <div className="space-y-3 py-4">
                  <div className="flex items-center justify-center mb-6 text-green-600 dark:text-green-400">
                      <ShieldCheck size={48} />
                  </div>
                  <p className="text-center text-gray-600 dark:text-gray-300 mb-6">{t.securityTitle}</p>

                  <button onClick={() => setView('change')} className={`w-full border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 py-3 rounded-lg font-medium flex items-center justify-center gap-2`}>
                      <KeyRound size={18} /> {t.changePassword}
                  </button>
                  <button onClick={() => setView('remove')} className={`w-full border border-red-200 hover:bg-red-50 dark:border-red-900/30 dark:hover:bg-red-900/20 text-red-600 dark:text-red-400 py-3 rounded-lg font-medium flex items-center justify-center gap-2`}>
                      <ShieldOff size={18} /> {t.removePassword}
                  </button>
              </div>
          )}

          {view === 'set' && (
              <form onSubmit={handleSet} className="space-y-4 py-2">
                  {isUnlock && (
                      <div className="text-center mb-4 text-gray-500 dark:text-gray-400 text-sm">
                          {t.enterFilePassword}
                      </div>
                  )}
                  {!isUnlock && (
                      <div className="bg-blue-50 dark:bg-blue-900/20 text-blue-800 dark:text-blue-300 p-3 rounded-lg text-xs flex items-start gap-2 mb-4">
                          <Info size={16} className="shrink-0 mt-0.5" />
                          <p>Password will encrypt your data. If you lose it, data cannot be recovered.</p>
                      </div>
                  )}

                  <div>
                      <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{isUnlock ? t.enterPassword : t.setPassword}</label>
                      <input 
                        type="password" 
                        autoFocus
                        className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                      />
                  </div>
                  {!isUnlock && (
                      <div>
                          <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.confirmPassword}</label>
                          <input 
                            type="password" 
                            className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                            value={confirmPassword} 
                            onChange={e => setConfirmPassword(e.target.value)} 
                          />
                      </div>
                  )}

                  {error && <p className="text-red-500 text-xs flex items-center gap-1"><AlertTriangle size={12} /> {error}</p>}

                  <button type="submit" className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-2 text-sm`}>
                      {isUnlock ? t.unlock : t.setPassword}
                  </button>
              </form>
          )}

          {view === 'remove' && (
              <form onSubmit={handleRemove} className="space-y-4 py-2">
                  <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-300 p-3 rounded-lg text-xs flex items-start gap-2 mb-4">
                      <AlertTriangle size={16} className="shrink-0 mt-0.5" />
                      <p>Removing password will decrypt your data and store it in plain text.</p>
                  </div>

                  <div>
                      <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.enterPassword}</label>
                      <input 
                        type="password" 
                        autoFocus
                        className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                        value={currentPassword} 
                        onChange={e => setCurrentPassword(e.target.value)} 
                      />
                  </div>

                  {error && <p className="text-red-500 text-xs flex items-center gap-1"><AlertTriangle size={12} /> {error}</p>}

                  <div className="flex gap-2">
                      <button type="button" onClick={() => setView('menu')} className="flex-1 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 py-2 rounded-lg text-sm font-medium">
                          {t.btnCancel}
                      </button>
                      <button type="submit" className="flex-1 bg-red-600 hover:bg-red-700 text-white py-2 rounded-lg font-medium text-sm">
                          {t.removePassword}
                      </button>
                  </div>
              </form>
          )}

          {view === 'change' && (
              <form onSubmit={handleChange} className="space-y-4 py-2">
                  <div>
                      <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Current Password</label>
                      <input 
                        type="password" 
                        autoFocus
                        className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                        value={currentPassword} 
                        onChange={e => setCurrentPassword(e.target.value)} 
                      />
                  </div>

                  <div className="border-t dark:border-gray-700 my-2"></div>

                  <div>
                      <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">New Password</label>
                      <input 
                        type="password" 
                        className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                      />
                  </div>
                  <div>
                      <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.confirmPassword}</label>
                      <input 
                        type="password" 
                        className={`w-full p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                        value={confirmPassword} 
                        onChange={e => setConfirmPassword(e.target.value)} 
                      />
                  </div>

                  {error && <p className="text-red-500 text-xs flex items-center gap-1"><AlertTriangle size={12} /> {error}</p>}

                  <div className="flex gap-2">
                      <button type="button" onClick={() => setView('menu')} className="flex-1 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 py-2 rounded-lg text-sm font-medium">
                          {t.btnCancel}
                      </button>
                      <button type="submit" className={`flex-1 ${theme.btn} text-white py-2 rounded-lg font-medium text-sm`}>
                          {t.changePassword}
                      </button>
                  </div>
              </form>
          )}
      </Modal>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { StorageMode, OTPAccount, ImportCandidate, AppLogo, FileSpace } from './types';
import AccountCard from './components/AccountCard';
import { AccountFormModal, BatchImportModal, BatchExportModal, ImportPreviewModal, LogoManagerModal, BatchEditModal, PasswordSettingsModal } from './components/Modals';
import LockScreen from './components/LockScreen';
import { ToastContainer, ToastMessage, ToastType } from './components/Toast';
import { Plus, Upload, Download, HardDrive, Zap, Lock, ShieldCheck, Languages, Trash2, CheckSquare, Square, Search, Image as ImageIcon, Edit2, ShieldAlert, QrCode, X, FileJson, FolderOpen, Save, FilePlus, PenLine, XCircle, Unlock, AlertTriangle, Sun, Moon, Monitor, StickyNote, Info, Settings } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { LanguageContext, translations, Language } from './utils/i18n';
import { encryptData, decryptData, hashPassword, generateSalt } from './utils/crypto';
import fileSystemClient, { FileSystemFileHandle } from './service/FileSystemClient';
import { handleStore } from './utils/db';

const STORAGE_KEYS = {
  local: 'secure_auth_local_data',
  session: 'secure_auth_session_data',
  customLogos: 'secure_auth_custom_logos',
  lang: 'secure_auth_lang',
  passwordHash: 'secure_auth_password_hash',
  salt: 'secure_auth_salt',
  theme: 'secure_auth_theme',
  fileSpaces: 'secure_auth_file_spaces',
  activeTab: 'secure_auth_active_tab',
  sessionMasterKey: 'secure_auth_temp_master_key',
  sessionFileKeyPrefix: 'secure_auth_temp_file_key_'
};

interface PendingFile {
    space: FileSpace;
    rawEncryptedData: {
        isEncrypted: boolean;
        data: string;
        salt: string;
    }
}

type Theme = 'light' | 'dark' | 'system';

const App: React.FC = () => {
  // Initialize Active Tab from Storage
  const [activeTab, setActiveTab] = useState<StorageMode>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.activeTab) as StorageMode) || 'local';
      } catch {
          return 'local';
      }
  });

  const [accounts, setAccounts] = useState<OTPAccount[]>([]);

  // Security State (App Lock for LocalStorage)
  const [isLocked, setIsLocked] = useState(true); // Default to locked, check session for auto-unlock
  const [hasPassword, setHasPassword] = useState(false);
  const [sessionKey, setSessionKey] = useState<string | null>(null); 
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // File Storage State
  const [openFiles, setOpenFiles] = useState<FileSpace[]>([]);
  const [currentFileId, setCurrentFileId] = useState<string | null>(null);

  // Pending File State (Waiting for decryption)
  const [pendingFile, setPendingFile] = useState<PendingFile | null>(null);
  const [showFileUnlockModal, setShowFileUnlockModal] = useState(false);

  // UI States
  const [showInfo, setShowInfo] = useState(false);
  const [showSettingsDropdown, setShowSettingsDropdown] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const settingsRef = useRef<HTMLDivElement>(null);

  // Theme Color derived from activeTab
  const themeColor = activeTab === 'local' ? 'blue' : (activeTab === 'file' ? 'emerald' : 'orange');

  // Notification State
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Fix: Added missing state variables and their setters for selection, search, modals and editing
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [visibleQRIds, setVisibleQRIds] = useState<Set<string>>(new Set());
  const [editingAccount, setEditingAccount] = useState<OTPAccount | undefined>(undefined);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [showBatchEditModal, setShowBatchEditModal] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showImportPreview, setShowImportPreview] = useState(false);
  const [importCandidates, setImportCandidates] = useState<ImportCandidate[]>([]);

  const showToast = (message: string, type: ToastType = 'info') => {
      const id = uuidv4();
      setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
      setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Initialize Lang from Storage
  const [lang, setLang] = useState<Language>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.lang) as Language) || 'en';
      } catch {
          return 'en';
      }
  });

  // Derived translations based on current language
  const t = translations[lang];

  // Initialize Theme from Storage
  const [theme, setTheme] = useState<Theme>(() => {
      try {
          return (localStorage.getItem(STORAGE_KEYS.theme) as Theme) || 'system';
      } catch {
          return 'system';
      }
  });

  // Close settings on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(event.target as Node)) {
        setShowSettingsDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Persist Active Tab
  useEffect(() => {
      localStorage.setItem(STORAGE_KEYS.activeTab, activeTab);
  }, [activeTab]);

  // Theme Effect
  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    const systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (theme === 'dark' || (theme === 'system' && systemDark)) {
        root.classList.add('dark');
    } else {
        root.classList.add('light');
    }
    localStorage.setItem(STORAGE_KEYS.theme, theme);
  }, [theme]);

  // Persist Language
  useEffect(() => {
      localStorage.setItem(STORAGE_KEYS.lang, lang);
  }, [lang]);

  // Load File Spaces Persistence
  useEffect(() => {
    const loadPersistedFileSpaces = async () => {
        const storedMetadata = localStorage.getItem(STORAGE_KEYS.fileSpaces);
        if (storedMetadata) {
            try {
                const metadata: FileSpace[] = JSON.parse(storedMetadata);
                const restoredSpaces = await Promise.all(metadata.map(async (space) => {
                    if (space.isVirtual) return space;
                    const handle = await handleStore.get(space.id);
                    return {
                        ...space,
                        handle: handle as FileSystemFileHandle,
                        needsPermission: handle !== null 
                    };
                }));
                setOpenFiles(restoredSpaces.filter(s => s.isVirtual || s.handle !== null));
            } catch (e) {
                console.error("Failed to restore file spaces", e);
            }
        }
    };
    loadPersistedFileSpaces();
  }, []);

  // Sync File Spaces to Persistence
  useEffect(() => {
    const metadata = openFiles.map(({ handle, ...meta }) => meta);
    localStorage.setItem(STORAGE_KEYS.fileSpaces, JSON.stringify(metadata));
  }, [openFiles]);

  // Load Custom Logos
  useEffect(() => {
      try {
          const storedLogos = localStorage.getItem(STORAGE_KEYS.customLogos);
          if (storedLogos) setCustomLogos(JSON.parse(storedLogos));
      } catch (e) {}
  }, []);

  // Initial Lock/Auto-Unlock Check
  useEffect(() => {
    const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
    const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
    const sessionMaster = sessionStorage.getItem(STORAGE_KEYS.sessionMasterKey);

    if (storedHash && storedSalt) {
        setHasPassword(true);
        if (sessionMaster) {
            // Attempt auto-unlock
            handleUnlock(sessionMaster).then(success => {
                if (!success) {
                   setIsLocked(true);
                   sessionStorage.removeItem(STORAGE_KEYS.sessionMasterKey);
                }
            });
        } else {
            setIsLocked(true);
        }
    } else {
        setHasPassword(false);
        setIsLocked(false);
        loadData('local', null);
    }
  }, []);

  // Load Data helper function
  const loadData = async (mode: StorageMode, password: string | null) => {
      if (mode === 'file') return;
      const key = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const stored = storage.getItem(key);
      if (!stored) { setAccounts([]); return; }

      if (mode === 'local' && password) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const decrypted = await decryptData(stored, password, salt);
              if (decrypted) setAccounts(JSON.parse(decrypted));
              else setAccounts([]);
          }
      } else {
          try {
              if (stored.trim().startsWith('[') || stored.trim().startsWith('{')) setAccounts(JSON.parse(stored));
              else setAccounts([]);
          } catch (e) { setAccounts([]); }
      }
  };

  // Permission Verification
  const verifyFilePermission = async (file: FileSpace) => {
      if (!file.handle) return false;
      try {
          // @ts-ignore
          let permission = await file.handle.queryPermission({ mode: 'readwrite' });
          if (permission === 'granted') return true;
          // @ts-ignore
          permission = await file.handle.requestPermission({ mode: 'readwrite' });
          return permission === 'granted';
      } catch (e) { return false; }
  };

  // Switching Files + Auto-Unlock for Files
  const handleSwitchFile = async (fileId: string) => {
      const file = openFiles.find(f => f.id === fileId);
      if (!file) return;

      if (file.needsPermission) {
          const granted = await verifyFilePermission(file);
          if (!granted) {
              showToast("Permission denied for file access", 'error');
              return;
          }
          setOpenFiles(prev => prev.map(f => f.id === fileId ? { ...f, needsPermission: false } : f));
      }

      const sessionFileKey = sessionStorage.getItem(STORAGE_KEYS.sessionFileKeyPrefix + fileId);

      if (file.isEncrypted && !file.password) {
          if (sessionFileKey) {
             // Auto-unlock file from session
             try {
                if (file.handle) {
                    const { encryptedData } = await readFileRaw(file.handle as FileSystemFileHandle);
                    const decrypted = await decryptData(encryptedData.data, sessionFileKey, encryptedData.salt);
                    if (decrypted) {
                        setOpenFiles(prev => prev.map(f => f.id === fileId ? { ...f, password: sessionFileKey } : f));
                        setCurrentFileId(fileId);
                        setAccounts(JSON.parse(decrypted));
                        return;
                    }
                }
             } catch(e) { sessionStorage.removeItem(STORAGE_KEYS.sessionFileKeyPrefix + fileId); }
          }

          // Fallback to manual unlock
          try {
              if (file.handle) {
                  const { encryptedData } = await readFileRaw(file.handle as FileSystemFileHandle);
                  setPendingFile({ space: file, rawEncryptedData: encryptedData });
                  setShowFileUnlockModal(true);
              }
          } catch (e) { showToast("Failed to access file", 'error'); }
          return;
      }

      setCurrentFileId(fileId);
      try {
          if (file.handle) {
              // @ts-ignore
              const fileObj = await file.handle.getFile();
              const text = await fileObj.text();
              const parsed = JSON.parse(text);
              if (file.isEncrypted && file.password) {
                 const decrypted = await decryptData(parsed.data, file.password, parsed.salt);
                 if (decrypted) setAccounts(JSON.parse(decrypted));
                 else setAccounts([]); 
              } else {
                 setAccounts(Array.isArray(parsed) ? parsed : []);
              }
          }
      } catch (e) { setAccounts([]); }
  };

  // Reload data when Tab changes (if unlocked)
  useEffect(() => {
      if (!isLocked) {
          if (activeTab === 'file') {
              if (currentFileId) handleSwitchFile(currentFileId);
              else setAccounts([]);
          } else {
              loadData(activeTab, sessionKey);
          }
          setSelectedIds(new Set());
          setSearchQuery('');
          setIsSearchFocused(false);
          setVisibleQRIds(new Set());
      }
  }, [activeTab, isLocked]);

  // Unlock Handler
  const handleUnlock = async (password: string) => {
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      if (!storedHash || !storedSalt) return false;
      const inputHash = await hashPassword(password, storedSalt);
      if (inputHash === storedHash) {
          setSessionKey(password);
          sessionStorage.setItem(STORAGE_KEYS.sessionMasterKey, password);
          setIsLocked(false);
          await loadData('local', password); 
          return true;
      }
      return false;
  };

  const handleResetLock = () => {
      localStorage.removeItem(STORAGE_KEYS.passwordHash);
      localStorage.removeItem(STORAGE_KEYS.salt);
      localStorage.removeItem(STORAGE_KEYS.local); 
      sessionStorage.removeItem(STORAGE_KEYS.sessionMasterKey);
      setHasPassword(false);
      setIsLocked(false);
      setSessionKey(null);
      setAccounts([]);
      showToast('App reset. All local data cleared.', 'info');
  };

  const handleSetPassword = async (password: string) => {
      const salt = generateSalt();
      const hash = await hashPassword(password, salt);
      localStorage.setItem(STORAGE_KEYS.salt, salt);
      localStorage.setItem(STORAGE_KEYS.passwordHash, hash);
      setSessionKey(password);
      sessionStorage.setItem(STORAGE_KEYS.sessionMasterKey, password);
      setHasPassword(true);
      await saveAccountsInternal(accounts, password, 'local');
      showToast(translations[lang].passwordSet, 'success');
  };

  const handleRemovePassword = async (currentPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(currentPassword, storedSalt);
          if (inputHash === storedHash) {
               localStorage.removeItem(STORAGE_KEYS.passwordHash);
               localStorage.removeItem(STORAGE_KEYS.salt);
               sessionStorage.removeItem(STORAGE_KEYS.sessionMasterKey);
               setHasPassword(false);
               setSessionKey(null);
               await saveAccountsInternal(accounts, null, 'local');
               showToast(translations[lang].passwordRemoved, 'success');
               return true;
          }
      }
      return false;
  };

  const handleChangePassword = async (oldPassword: string, newPassword: string) => {
      const storedSalt = localStorage.getItem(STORAGE_KEYS.salt);
      const storedHash = localStorage.getItem(STORAGE_KEYS.passwordHash);
      if (storedSalt && storedHash) {
          const inputHash = await hashPassword(oldPassword, storedSalt);
          if (inputHash === storedHash) {
              const newSalt = generateSalt();
              const newHash = await hashPassword(newPassword, newSalt);
              localStorage.setItem(STORAGE_KEYS.salt, newSalt);
              localStorage.setItem(STORAGE_KEYS.passwordHash, newHash);
              setSessionKey(newPassword);
              sessionStorage.setItem(STORAGE_KEYS.sessionMasterKey, newPassword);
              await saveAccountsInternal(accounts, newPassword, 'local');
              showToast("Password changed successfully", 'success');
              return true;
          }
      }
      return false;
  }

  const saveAccountsInternal = async (newAccounts: OTPAccount[], key: string | null, mode: StorageMode) => {
      if (mode === 'file') {
          if (currentFileId) {
             const file = openFiles.find(f => f.id === currentFileId);
             if (file) await saveToFile(file, newAccounts);
          }
          return;
      }
      const storageKey = STORAGE_KEYS[mode];
      const storage = mode === 'local' ? localStorage : sessionStorage;
      const json = JSON.stringify(newAccounts);
      if (mode === 'local' && key) {
          const salt = localStorage.getItem(STORAGE_KEYS.salt);
          if (salt) {
              const encrypted = await encryptData(json, key, salt);
              storage.setItem(storageKey, encrypted);
          }
      } else storage.setItem(storageKey, json);
  };

  const saveToFile = async (fileSpace: FileSpace, accountsData: OTPAccount[]) => {
      if (fileSpace.handle) {
          try {
              const handle = fileSpace.handle as any;
              const writable = await handle.createWritable();
              const json = JSON.stringify(accountsData);
              if (fileSpace.isEncrypted && fileSpace.password) {
                  const salt = generateSalt();
                  const encrypted = await encryptData(json, fileSpace.password, salt);
                  const fileContent = JSON.stringify({ isEncrypted: true, data: encrypted, salt: salt });
                  await writable.write(fileContent);
              } else await writable.write(json);
              await writable.close();
          } catch (e) { showToast("Failed to save to file.", "error"); }
      } 
      else if (fileSpace.isVirtual) {
          const json = JSON.stringify(accountsData);
          let content = json;
          if (fileSpace.isEncrypted && fileSpace.password) {
              const salt = generateSalt();
              const encrypted = await encryptData(json, fileSpace.password, salt);
              content = JSON.stringify({ isEncrypted: true, data: encrypted, salt: salt });
          }
          const blob = new Blob([content], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = fileSpace.displayName || 'secureauth-accounts.json';
          a.click();
          URL.revokeObjectURL(url);
          showToast("File downloaded", 'info');
      }
  };

  const readFileRaw = async (handle: FileSystemFileHandle) => {
      const fileData = await handle.getFile();
      const text = await fileData.text();
      return parseRawFileContent(text, handle.name, handle);
  };

  const parseRawFileContent = (text: string, name: string, handle: FileSystemFileHandle | null) => {
      let parsed;
      let isEncrypted = false;
      let encryptedData = { isEncrypted: false, data: '', salt: '' };
      try {
          parsed = JSON.parse(text);
          if (parsed && parsed.isEncrypted && parsed.data && parsed.salt) {
              isEncrypted = true;
              encryptedData = parsed;
          }
      } catch(e) { parsed = []; }
      const newFileSpace: FileSpace = { id: uuidv4(), displayName: name, handle: handle, isEncrypted: isEncrypted, isVirtual: handle === null };
      return { newFileSpace, parsed, isEncrypted, encryptedData };
  }

  const handleOpenFile = async () => {
      if (!fileSystemClient.supported) { fileInputRef.current?.click(); return; }
      try {
          const handles = await fileSystemClient.openFile({ types: [{ description: 'JSON File', accept: { 'application/json': ['.json'] } }] });
          if (handles && handles.length > 0) {
              const handle = handles[0];
              const { newFileSpace, parsed, isEncrypted, encryptedData } = await readFileRaw(handle);
              await handleStore.save(newFileSpace.id, handle);
              if (isEncrypted) { setPendingFile({ space: newFileSpace, rawEncryptedData: encryptedData }); setShowFileUnlockModal(true); }
              else { setOpenFiles(prev => [...prev, newFileSpace]); setCurrentFileId(newFileSpace.id); setAccounts(Array.isArray(parsed) ? parsed : []); }
          }
      } catch (e: any) {}
  };

  const handleLegacyFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
          if (ev.target?.result) {
              const text = ev.target.result as string;
              const { newFileSpace, parsed, isEncrypted, encryptedData } = parseRawFileContent(text, file.name, null);
              if (isEncrypted) { setPendingFile({ space: newFileSpace, rawEncryptedData: encryptedData }); setShowFileUnlockModal(true); }
              else { setOpenFiles(prev => [...prev, newFileSpace]); setCurrentFileId(newFileSpace.id); setAccounts(Array.isArray(parsed) ? parsed : []); }
          }
      };
      reader.readAsText(file);
      e.target.value = '';
  };

  const handleOpenFolder = async () => {
     if (!fileSystemClient.supported) { alert("Folder access requires modern browser."); return; }
     try {
         const dirHandle = await fileSystemClient.openDirectory();
         const entries = await fileSystemClient.getDirectoryEntries(dirHandle);
         const jsonFiles = entries.filter(e => e.kind === 'file' && e.name.toLowerCase().endsWith('.json'));
         if (jsonFiles.length === 0) return;
         const newSpaces: FileSpace[] = [];
         for (const entry of jsonFiles) {
             try {
                const fileHandle = entry.handle as FileSystemFileHandle;
                const { newFileSpace } = await readFileRaw(fileHandle);
                if (!openFiles.some(f => f.displayName === newFileSpace.displayName)) {
                    await handleStore.save(newFileSpace.id, fileHandle);
                    newSpaces.push(newFileSpace);
                }
             } catch (err) {}
         }
         if (newSpaces.length > 0) setOpenFiles(prev => [...prev, ...newSpaces]);
     } catch (e: any) {}
  };

  const handleCreateFile = async () => {
      if (!fileSystemClient.supported) {
          const newFileId = uuidv4();
          setOpenFiles(prev => [...prev, { id: newFileId, displayName: 'Untitled.json', handle: null, isEncrypted: false, isVirtual: true }]);
          setCurrentFileId(newFileId);
          setAccounts([]);
          return;
      }
      try {
          const handle = await fileSystemClient.createFile({ suggestedName: '2fa-accounts.json', types: [{ description: 'JSON File', accept: { 'application/json': ['.json'] } }] });
          const newFileId = uuidv4();
          await handleStore.save(newFileId, handle);
          setOpenFiles(prev => [...prev, { id: newFileId, displayName: handle.name, handle: handle, isEncrypted: false }]);
          setCurrentFileId(newFileId);
          setAccounts([]);
          const writable = await (handle as any).createWritable();
          await writable.write("[]");
          await writable.close();
      } catch (e: any) {}
  };

  const handleUnlockFile = async (password: string) => {
      if (!pendingFile) return;
      const { data, salt } = pendingFile.rawEncryptedData;
      const decrypted = await decryptData(data, password, salt);
      if (decrypted) {
          const accountsData = JSON.parse(decrypted);
          sessionStorage.setItem(STORAGE_KEYS.sessionFileKeyPrefix + pendingFile.space.id, password);
          if (!openFiles.some(f => f.id === pendingFile.space.id)) {
             setOpenFiles(prev => [...prev, { ...pendingFile.space, password: password }]);
             setCurrentFileId(pendingFile.space.id);
             setAccounts(accountsData);
          } else {
             setOpenFiles(prev => prev.map(f => f.id === pendingFile.space.id ? { ...f, password: password } : f));
             setCurrentFileId(pendingFile.space.id);
             setAccounts(accountsData);
          }
          setPendingFile(null);
          setShowFileUnlockModal(false);
      } else throw new Error("Wrong Password");
  };

  const handleCancelUnlock = () => {
      if (pendingFile && openFiles.some(f => f.id === pendingFile.space.id)) {
          setOpenFiles(prev => prev.filter(f => f.id !== pendingFile.space.id));
          handleStore.remove(pendingFile.space.id);
      }
      setPendingFile(null);
      setShowFileUnlockModal(false);
  };

  const handleFileRename = (id: string) => {
      const name = prompt(translations[lang].labelRenameFile);
      if (name) setOpenFiles(prev => prev.map(f => f.id === id ? { ...f, displayName: name } : f));
  };

  const handleFileNotes = (id: string) => {
      const space = openFiles.find(f => f.id === id);
      const notes = prompt(t.promptEnterRemarks, space?.notes || "");
      if (notes !== null) setOpenFiles(prev => prev.map(f => f.id === id ? { ...f, notes: notes } : f));
  };

  const handleCloseFile = (id: string) => {
      if (confirm(translations[lang].confirmCloseFile)) {
          setOpenFiles(prev => prev.filter(f => f.id !== id));
          handleStore.remove(id); 
          sessionStorage.removeItem(STORAGE_KEYS.sessionFileKeyPrefix + id);
          if (currentFileId === id) { setCurrentFileId(null); setAccounts([]); }
      }
  };

  const handleSetFilePassword = async (password: string) => {
      if (!currentFileId) return;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file) {
          const updatedFile = { ...file, isEncrypted: true, password: password };
          await saveToFile(updatedFile, accounts);
          sessionStorage.setItem(STORAGE_KEYS.sessionFileKeyPrefix + currentFileId, password);
          setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
          showToast(translations[lang].filePassSet, 'success');
      }
  };

  const handleRemoveFilePassword = async (currPass: string) => {
      if (!currentFileId) return false;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file && file.password === currPass) {
           const updatedFile = { ...file, isEncrypted: false, password: undefined };
           await saveToFile(updatedFile, accounts);
           sessionStorage.removeItem(STORAGE_KEYS.sessionFileKeyPrefix + currentFileId);
           setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
           showToast(translations[lang].filePassRemoved, 'success');
           return true;
      }
      return false;
  };

  const handleChangeFilePassword = async (oldPass: string, newPass: string) => {
      if (!currentFileId) return false;
      const file = openFiles.find(f => f.id === currentFileId);
      if (file && file.password === oldPass) {
          const updatedFile = { ...file, isEncrypted: true, password: newPass };
          await saveToFile(updatedFile, accounts);
          sessionStorage.setItem(STORAGE_KEYS.sessionFileKeyPrefix + currentFileId, newPass);
          setOpenFiles(prev => prev.map(f => f.id === currentFileId ? updatedFile : f));
          showToast("File password changed successfully", 'success');
          return true;
      }
      return false;
  };

  const saveAccounts = (newAccounts: OTPAccount[]) => {
      setAccounts(newAccounts);
      saveAccountsInternal(newAccounts, sessionKey, activeTab);
  };

  const [customLogos, setCustomLogos] = useState<AppLogo[]>([]);
  const [showLogoManager, setShowLogoManager] = useState(false);
  const handleAddLogo = (logo: AppLogo) => { saveCustomLogos([...customLogos, logo]); showToast(translations[lang].logoAdded, 'success'); };
  const saveCustomLogos = (logos: AppLogo[]) => { setCustomLogos(logos); localStorage.setItem(STORAGE_KEYS.customLogos, JSON.stringify(logos)); };
  const handleDeleteLogo = (id: string) => saveCustomLogos(customLogos.filter(l => l.id !== id));
  const handleBatchDeleteLogos = (ids: string[]) => { const idSet = new Set(ids); saveCustomLogos(customLogos.filter(l => !idSet.has(l.id))); };
  const handleImportLogos = (newLogos: AppLogo[]) => { const existingIds = new Set(customLogos.map(l => l.id)); const filteredNew = newLogos.filter(l => !existingIds.has(l.id)); if (filteredNew.length > 0) saveCustomLogos([...customLogos, ...filteredNew]); };

  const handleSaveAccount = (data: Omit<OTPAccount, 'id' | 'createdAt'>) => {
    if (editingAccount) saveAccounts(accounts.map(acc => acc.id === editingAccount.id ? { ...acc, ...data } : acc));
    else saveAccounts([...accounts, { ...data, id: uuidv4(), createdAt: Date.now() }]);
    setEditingAccount(undefined);
  };

  const handleBatchScan = (candidates: ImportCandidate[]) => { setImportCandidates(candidates); setShowAccountModal(false); setShowImportPreview(true); };
  const handleBatchSave = (updates: Partial<OTPAccount>) => { saveAccounts(accounts.map(acc => selectedIds.has(acc.id) ? { ...acc, ...updates } : acc)); setShowBatchEditModal(false); setSelectedIds(new Set()); };
  const handleImportPreview = (candidates: ImportCandidate[]) => { setImportCandidates(candidates); setShowImportModal(false); setShowImportPreview(true); };

  const handleConfirmImport = (selectedCandidates: ImportCandidate[]) => { 
    saveAccounts([...accounts, ...selectedCandidates.map(item => ({ 
      issuer: item.issuer || 'Import', 
      account: item.account || 'Unknown', 
      secret: item.secret, 
      period: item.period || 30, 
      notes: item.notes || '', 
      logoId: item.logoId || '', 
      id: uuidv4(), 
      createdAt: Date.now() 
    }))]); 
    setShowImportPreview(false); 
    setImportCandidates([]); 
  };

  const handleDelete = (id: string) => { if (window.confirm(translations[lang].confirmDelete)) { saveAccounts(accounts.filter(a => a.id !== id)); setSelectedIds(prev => { const next = new Set(prev); next.delete(id); return next; }); } };
  const handleEdit = (account: OTPAccount) => { setEditingAccount(account); setShowAccountModal(true); };
  const handleToggleSelect = (id: string) => { const next = new Set(selectedIds); if (next.has(id)) next.delete(id); else next.add(id); setSelectedIds(next); };
  const handleSelectAll = () => { if (selectedIds.size === filteredAccounts.length) setSelectedIds(new Set()); else setSelectedIds(new Set(filteredAccounts.map(a => a.id))); };
  const handleBulkDelete = () => { if (window.confirm(translations[lang].confirmBulkDelete)) { saveAccounts(accounts.filter(a => !selectedIds.has(a.id))); setSelectedIds(new Set()); } };
  const handleToggleQR = (id: string) => { setVisibleQRIds(prev => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; }); };
  const handleToggleSelectedQR = () => { const selArr = Array.from(selectedIds); const allVis = selArr.every(id => visibleQRIds.has(id)); setVisibleQRIds(prev => { const next = new Set(prev); if (allVis) selArr.forEach(id => next.delete(id)); else selArr.forEach(id => next.add(id)); return next; }); };

  const filteredAccounts = (function() {
    if (!searchQuery.trim()) return accounts;
    const keywords = searchQuery.toLowerCase().split(/\s+/).filter(k => k.length > 0);
    return accounts.filter(acc => {
      const searchString = `${acc.issuer} ${acc.account} ${acc.notes || ''}`.toLowerCase();
      return keywords.every(kw => searchString.includes(kw));
    });
  })();

  const themeClasses = getThemeClasses();
  const selectedAreAllVisible = selectedIds.size > 0 && Array.from(selectedIds).every(id => visibleQRIds.has(id));

  function getThemeClasses() {
     const common = { tabActive: 'bg-white dark:bg-gray-800 shadow-sm' };
     if (activeTab === 'local') return { ...common, primaryBg: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', textGradient: 'from-blue-700 to-blue-500 dark:from-blue-500 dark:to-blue-400', focusRing: 'focus:ring-blue-500', checkboxText: 'text-blue-600', iconBg: 'bg-blue-600', tabActive: `${common.tabActive} text-blue-600 dark:text-blue-400`, lightBg: 'bg-blue-50 dark:bg-blue-900/20', borderColor: 'border-blue-100 dark:border-blue-900/30' };
     if (activeTab === 'file') return { ...common, primaryBg: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', textGradient: 'from-emerald-700 to-emerald-500 dark:from-emerald-500 dark:to-emerald-400', focusRing: 'focus:ring-emerald-500', checkboxText: 'text-emerald-600', iconBg: 'bg-emerald-600', tabActive: `${common.tabActive} text-emerald-600 dark:text-emerald-400`, lightBg: 'bg-emerald-50 dark:bg-emerald-900/20', borderColor: 'border-emerald-100 dark:border-emerald-900/30' };
     return { ...common, primaryBg: 'bg-orange-600', primaryHover: 'hover:bg-orange-700', textGradient: 'from-orange-700 to-orange-500 dark:from-orange-500 dark:to-orange-400', focusRing: 'focus:ring-orange-500', checkboxText: 'text-orange-600', iconBg: 'bg-orange-600', tabActive: `${common.tabActive} text-orange-600 dark:text-orange-400`, lightBg: 'bg-orange-50 dark:bg-orange-900/20', borderColor: 'border-orange-100 dark:border-orange-900/30' };
  }

  if (isLocked) return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
        <LockScreen onUnlock={handleUnlock} onReset={handleResetLock} />
    </LanguageContext.Provider>
  );

  const currentFile = openFiles.find(f => f.id === currentFileId);
  const modeTitle = activeTab === 'local' ? t.bannerLocalTitle : (activeTab === 'file' ? t.bannerFileTitle : t.bannerSessionTitle);
  const modeDesc = activeTab === 'local' ? t.bannerLocalDesc : (activeTab === 'file' ? t.bannerFileDesc : t.bannerSessionDesc);

  return (
    <LanguageContext.Provider value={{ lang, t, setLang }}>
      <ToastContainer toasts={toasts} onClose={removeToast} />
      <input type="file" ref={fileInputRef} className="hidden" accept=".json,application/json" onChange={handleLegacyFileSelect} />

      <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-gray-900 text-gray-800 dark:text-gray-100 font-sans pb-40 sm:pb-24 transition-colors duration-200">
        <header className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-20 transition-colors duration-200">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-14 items-center gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <div className={`${themeClasses.iconBg} p-1.5 rounded-lg transition-colors duration-300`}>
                  <ShieldCheck className="text-white h-5 w-5" />
                </div>
                <h1 className={`text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r ${themeClasses.textGradient} hidden md:block transition-all duration-300`}>
                  {t.appTitle}
                </h1>
              </div>

              <div className={`flex-1 transition-all duration-300 ${isSearchFocused ? 'max-w-full' : 'max-w-md mx-auto'}`}>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className={`h-4 w-4 text-gray-400 group-focus-within:${themeClasses.checkboxText} transition-colors`} />
                    </div>
                    <input type="text" className={`block w-full pl-9 pr-9 py-1.5 border border-gray-300 dark:border-gray-600 rounded-lg leading-5 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:bg-white dark:focus:bg-gray-800 focus:ring-2 ${themeClasses.focusRing} focus:border-transparent transition-all text-sm`} placeholder="Search..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onFocus={() => setIsSearchFocused(true)} onBlur={() => setIsSearchFocused(false)} />
                    {searchQuery && <button onMouseDown={(e) => { e.preventDefault(); setSearchQuery(''); }} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600"><X size={14} /></button>}
                </div>
              </div>

              <div className={`flex items-center gap-2 shrink-0 transition-all duration-300 ${isSearchFocused ? 'w-0 opacity-0 overflow-hidden m-0 p-0' : 'w-auto opacity-100'}`}>
                <div className="flex p-1 bg-gray-100 dark:bg-gray-700 rounded-lg relative">
                  <button onClick={() => setActiveTab('local')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${activeTab === 'local' ? themeClasses.tabActive : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'}`}>
                    <HardDrive size={14} /> <span className="hidden sm:inline">{t.tabLocal}</span>
                  </button>
                  <button onClick={() => setActiveTab('file')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${activeTab === 'file' ? themeClasses.tabActive : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'}`}>
                    <FolderOpen size={14} /> <span className="hidden sm:inline">{t.tabFile}</span>
                  </button>
                  <button onClick={() => setActiveTab('session')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${activeTab === 'session' ? themeClasses.tabActive : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'}`}>
                    <Zap size={14} /> <span className="hidden sm:inline">{t.tabSession}</span>
                  </button>

                  <div className="relative flex items-center ml-1">
                    <button onMouseEnter={() => setShowInfo(true)} onMouseLeave={() => setShowInfo(false)} onClick={() => setShowInfo(!showInfo)} className={`p-1.5 transition-colors ${themeClasses.checkboxText} opacity-60 hover:opacity-100`}><Info size={16} /></button>
                    {showInfo && (
                        <div className={`absolute top-full right-0 mt-2 w-64 p-3 bg-white dark:bg-gray-800 border rounded-lg shadow-xl z-[100] animate-in fade-in zoom-in duration-150 ${themeClasses.borderColor}`}>
                            <h4 className={`font-bold text-sm mb-1 ${themeClasses.checkboxText}`}>{modeTitle}</h4>
                            <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed">{modeDesc}</p>
                        </div>
                    )}
                  </div>
                </div>

                <div className="relative" ref={settingsRef}>
                    <button onClick={() => setShowSettingsDropdown(!showSettingsDropdown)} className={`p-2 text-gray-500 dark:text-gray-400 hover:${themeClasses.checkboxText} hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition flex items-center gap-1`}>
                        <Settings size={20} />
                    </button>

                    {showSettingsDropdown && (
                        <div className="absolute right-0 mt-2 w-56 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-xl shadow-2xl py-2 z-50 animate-in fade-in slide-in-from-top-2 duration-200">
                             <button onClick={() => { setShowPasswordModal(true); setShowSettingsDropdown(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                <Lock size={16} className={hasPassword || (activeTab === 'file' && currentFile?.isEncrypted) ? 'text-green-500' : 'text-gray-400'} />
                                <span className="flex-1 text-left">{activeTab === 'file' ? t.fileSecurityTitle : t.securityTitle}</span>
                                {((activeTab !== 'file' && hasPassword) || (activeTab === 'file' && currentFile?.isEncrypted)) && <div className="w-2 h-2 bg-green-500 rounded-full" />}
                             </button>

                             <button onClick={() => { 
                                 if (theme === 'system') setTheme('light');
                                 else if (theme === 'light') setTheme('dark');
                                 else setTheme('system');
                             }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                {theme === 'light' ? <Sun size={16} /> : (theme === 'dark' ? <Moon size={16} /> : <Monitor size={16} />)}
                                <span className="flex-1 text-left">{t.themeLabel}: {theme === 'light' ? t.themeLight : (theme === 'dark' ? t.themeDark : t.themeSystem)}</span>
                             </button>

                             <button onClick={() => { setLang(lang === 'en' ? 'zh' : 'en'); setShowSettingsDropdown(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                <Languages size={16} className="text-gray-400" />
                                <span className="flex-1 text-left">{t.headerSwitchTo} {lang === 'en' ? '中文' : 'English'}</span>
                             </button>
                        </div>
                    )}
                </div>
              </div>
            </div>
          </div>
        </header>

        {showLogoManager ? (
            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                 <div className="mb-4 flex items-center gap-2">
                    <button onClick={() => setShowLogoManager(false)} className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 font-medium text-sm flex items-center gap-1">&larr; Back to Accounts</button>
                    <h2 className="text-2xl font-bold text-gray-800 dark:text-white ml-2">{t.manageLogos}</h2>
                 </div>
                 <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
                     <LogoManagerModal onClose={() => setShowLogoManager(false)} logos={customLogos} onAddLogo={handleAddLogo} onDeleteLogo={handleDeleteLogo} onBatchDeleteLogo={handleBatchDeleteLogos} onImportLogos={handleImportLogos} inline={true} color={themeColor} />
                 </div>
            </main>
