interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    // Check for Google Auth Migration URI
    if (text.trim().startsWith('otpauth-migration://')) {
        try {
            const migrationAccounts = parseMigrationURI(text.trim());
            const candidates: ImportCandidate[] = migrationAccounts.map(acc => ({
                raw: 'otpauth-migration import',
                issuer: acc.issuer,
                account: acc.name,
                secret: acc.secret,
                period: 30, 
                isValid: true,
                notes: 'Imported via Google Migration'
            }));
            onPreview(candidates);
            return;
        } catch (e) {
            console.error(e);
            alert("Failed to parse migration URI");
            return;
        }
    }

    const lines = text.split('\n');
    const candidates = lines.map(line => parseLine(line, separator)).filter(c => c.raw.trim().length > 0);
    onPreview(candidates);
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            if (qrData.startsWith('otpauth-migration://')) {
                try {
                    const migrationAccounts = parseMigrationURI(qrData);
                    migrationAccounts.forEach(acc => {
                        candidates.push({
                            raw: 'otpauth-migration import',
                            issuer: acc.issuer,
                            account: acc.name,
                            secret: acc.secret,
                            period: 30,
                            isValid: true,
                            notes: 'Imported via Google Migration'
                        });
                    });
                } catch (e) {
                    candidates.push({ raw: file.name, issuer: 'Error', account: 'Migration Parse Error', secret: '', period: 0, isValid: false });
                }
            } else {
                const parsed = parseLine(qrData);
                if (parsed.isValid) {
                     candidates.push(parsed);
                } else {
                     candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
                }
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b dark:border-gray-700">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500 dark:text-gray-400">{t.textPaste} <span className="font-mono bg-gray-100 dark:bg-gray-700 px-1 rounded">Issuer, Account, Secret, Period, Notes, LogoID</span></p>
                <textarea 
                    className={`w-full h-40 p-3 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Google, alice@gmail.com, JBSWY3DPEHPK3PXP, 30, My Notes, 123`}
                />
                 <div>
                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.labelSeparator}</label>
                    <input type="text" className={`w-20 p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none text-center font-mono bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                      value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-2 text-sm`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center">
                     <ImageIcon size={24} className="text-gray-400 dark:text-gray-300" />
                 </div>
                 <div>
                     <p className="text-gray-600 dark:text-gray-300 mb-4 text-sm">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-5 py-2.5 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition text-sm`}>
                         <Upload size={16} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-[10px] text-gray-400">Supported formats: PNG, JPG, WEBP</p>
            </div>
        )}
    </Modal>
  );
};

interface ImportPreviewModalProps {
    isOpen: boolean;
    candidates: ImportCandidate[];
    onClose: () => void;
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewModal: React.FC<ImportPreviewModalProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

    useEffect(() => {
        if (isOpen && candidates.length > 0) {
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        const toImport = candidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(toImport);
    };

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    const getAvatarColor = (name: string) => {
        const colors = ['bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300', 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300', 'bg-violet-100 text-violet-700 dark:bg-violet-900 dark:text-violet-300', 'bg-amber-100 text-amber-700 dark:bg-amber-900 dark:text-amber-300', 'bg-rose-100 text-rose-700 dark:bg-rose-900 dark:text-rose-300', 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900 dark:text-cyan-300'];
        const index = name.length % colors.length;
        return colors[index];
    };

    return (
        <Modal title={`${t.headerImport} (${candidates.length})`} onClose={onClose} className="max-w-2xl">
            <div className="flex flex-col h-full max-h-[70vh]">
                <div className="flex justify-between items-center mb-4 px-1">
                    <p className="text-xs text-gray-500 dark:text-gray-400">{selectedIndices.size} selected</p>
                </div>

                <div className="overflow-y-auto flex-1 bg-gray-50 dark:bg-gray-900/50 rounded-lg border dark:border-gray-700">
                    {candidates.map((c, i) => {
                         // Robust lookup: stringify both sides to catch number vs string mismatch
                         const logo = c.logoId ? logos.find(l => String(l.id) === String(c.logoId)) : null;
                         const avatarClass = getAvatarColor(c.issuer || 'U');
                         return (
                            <div key={i} className={`flex items-start gap-3 p-3 border-b dark:border-gray-700 bg-white dark:bg-gray-800 last:border-b-0 ${!c.isValid ? 'opacity-50' : 'cursor-pointer'}`} onClick={() => c.isValid && toggleSelect(i)}>
                                <div className="pt-1">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedIndices.has(i)} 
                                        onChange={() => {}} 
                                        disabled={!c.isValid}
                                        className={`w-4 h-4 rounded border-gray-300 ${theme.checkbox}`}
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center">
                                        <div className="flex items-center gap-2.5 overflow-hidden min-w-0">
                                            {logo ? (
                                                <div className="w-6 h-6 shrink-0 flex items-center justify-center bg-gray-50 dark:bg-gray-700 rounded p-0.5">
                                                    <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                                                </div>
                                            ) : (
                                                <div className={`w-6 h-6 rounded flex items-center justify-center font-bold text-xs shrink-0 ${avatarClass}`}>
                                                    {(c.issuer || '?').charAt(0).toUpperCase()}
                                                </div>
                                            )}
                                           <span className="font-bold text-sm text-gray-900 dark:text-white truncate">{c.issuer || 'Unknown'}</span>
                                        </div>
                                        <span className="text-[10px] text-gray-400 font-mono shrink-0 ml-2">{c.period}s</span>
                                    </div>
                                    <p className="text-xs text-gray-600 dark:text-gray-400 truncate mt-0.5 ml-8.5">{c.account}</p>
                                    <div className="mt-1 flex items-center gap-2 ml-8.5 overflow-hidden">
                                        <span className="text-[10px] text-gray-400 font-mono truncate max-w-[120px]" title={c.secret}>
                                            {c.secret ? c.secret.substring(0, 4) + '...' + c.secret.substring(c.secret.length-4) : 'NO SECRET'}
                                        </span>
                                        {c.notes && (
                                            <span className="text-[10px] text-blue-500 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 px-1.5 py-0.5 rounded truncate max-w-[150px] border border-blue-100 dark:border-blue-800" title={c.notes}>
                                                {c.notes}
                                            </span>
                                        )}
                                        {c.logoId && !logo && <span className="text-[9px] text-orange-400 border border-orange-100 dark:border-orange-900/50 px-1 rounded">ID: {c.logoId}</span>}
                                        {!c.isValid && <span className="text-[10px] text-red-500 bg-red-50 px-1 rounded">Invalid</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="pt-4 mt-4 border-t dark:border-gray-700 flex justify-end gap-3">
                     <button onClick={onClose} className="px-3 py-2 border dark:border-gray-600 rounded-lg text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 font-medium">
                         {t.btnCancel}
                     </button>
                     <button 
                        onClick={handleConfirm}
                        disabled={selectedIndices.size === 0}
                        className={`${theme.btn} text-white px-5 py-2 rounded-lg text-sm font-medium shadow-sm disabled:opacity-50`}
                     >
                        {t.btnImport} ({selectedIndices.size})
                     </button>
                </div>
            </div>
        </Modal>
    )
}

