interface BatchImportModalProps {
    onClose: () => void;
    onPreview: (candidates: ImportCandidate[]) => void;
    color?: 'blue' | 'orange' | 'emerald';
}

export const BatchImportModal: React.FC<BatchImportModalProps> = ({ onClose, onPreview, color = 'blue' }) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'paste' | 'qr'>('paste');
  const [text, setText] = useState('');
  const [separator, setSeparator] = useState(',');
  const [loading, setLoading] = useState(false);

  const handlePreview = () => {
    // Check for Google Auth Migration URI
    if (text.trim().startsWith('otpauth-migration://')) {
        try {
            const migrationAccounts = parseMigrationURI(text.trim());
            const candidates: ImportCandidate[] = migrationAccounts.map(acc => ({
                raw: 'otpauth-migration import',
                issuer: acc.issuer,
                account: acc.name,
                secret: acc.secret,
                period: 30, 
                isValid: true,
                notes: 'Imported via Migration Package'
            }));
            onPreview(candidates);
            return;
        } catch (e) {
            console.error(e);
            alert("Failed to parse migration URI");
            return;
        }
    }

    const lines = text.split('\n');
    const candidates: ImportCandidate[] = [];

    for (const line of lines) {
        const candidate = parseLine(line, separator);
        if (candidate.secret === 'MIGRATION_BLOB' && candidate.raw.startsWith('otpauth-migration://')) {
             try {
                 const expanded = parseMigrationURI(candidate.raw);
                 expanded.forEach(acc => candidates.push({
                    raw: 'Expanded from Migration URI',
                    issuer: acc.issuer,
                    account: acc.name,
                    secret: acc.secret,
                    period: 30,
                    isValid: true
                 }));
             } catch(err) { candidates.push(candidate); }
        } else {
             candidates.push(candidate);
        }
    }
    onPreview(candidates.filter(c => c.raw.trim().length > 0));
  };

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const candidates: ImportCandidate[] = [];

      for (const file of files) {
        try {
          const qrData = await decodeQRFromImage(file);
          if (qrData) {
            if (qrData.startsWith('otpauth-migration://')) {
                try {
                    const migrationAccounts = parseMigrationURI(qrData);
                    migrationAccounts.forEach(acc => {
                        candidates.push({
                            raw: 'otpauth-migration import',
                            issuer: acc.issuer,
                            account: acc.name,
                            secret: acc.secret,
                            period: 30,
                            isValid: true,
                            notes: 'Imported via Migration Package'
                        });
                    });
                } catch (e) {
                    candidates.push({ raw: file.name, issuer: 'Error', account: 'Migration Parse Error', secret: '', period: 0, isValid: false });
                }
            } else {
                const parsed = parseLine(qrData);
                if (parsed.isValid) {
                     candidates.push(parsed);
                } else {
                     candidates.push({ raw: file.name, issuer: 'Error', account: 'Invalid QR', secret: '', period: 0, isValid: false, notes: 'Could not parse QR data' });
                }
            }
          } else {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'No QR found', secret: '', period: 0, isValid: false });
          }
        } catch (err) {
             candidates.push({ raw: file.name, issuer: 'Error', account: 'Read Error', secret: '', period: 0, isValid: false });
        }
      }
      setLoading(false);
      onPreview(candidates);
    }
  };

  return (
    <Modal title={t.modalImportTitle} onClose={onClose}>
        <div className="flex gap-4 mb-4 border-b dark:border-gray-700">
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'paste' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('paste')}
            >
              {t.textPaste}
            </button>
            <button 
              className={`pb-2 px-1 font-medium text-sm transition ${tab === 'qr' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`}
              onClick={() => setTab('qr')}
            >
              {t.btnUploadQR}
            </button>
        </div>

        {tab === 'paste' ? (
            <div className="space-y-4">
                <p className="text-sm text-gray-500 dark:text-gray-400">{t.textPaste} <span className="font-mono bg-gray-100 dark:bg-gray-700 px-1 rounded">CSV, URI, or Migration URL</span></p>
                <textarea 
                    className={`w-full h-40 p-3 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none font-mono bg-white dark:bg-gray-700 text-gray-900 dark:text-white`}
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder={`Issuer, Account, Secret, Period, Notes, LogoID\notpauth-migration://offline?data=...`}
                />
                 <div className="flex justify-between items-center">
                    <div>
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">{t.labelSeparator}</label>
                        <input type="text" className={`w-20 p-2 text-sm border dark:border-gray-600 rounded-lg focus:ring-2 ${theme.ring} outline-none text-center font-mono bg-white dark:bg-gray-700 text-gray-900 dark:text-white`} 
                        value={separator} onChange={e => setSeparator(e.target.value)} maxLength={1} />
                    </div>
                 </div>
                 <button onClick={handlePreview} disabled={!text.trim()} className={`w-full ${theme.btn} text-white py-2 rounded-lg font-medium mt-2 text-sm`}>
                    {t.btnPreview}
                 </button>
            </div>
        ) : (
            <div className="space-y-8 py-8 text-center">
                 <div className="mx-auto w-12 h-12 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center">
                     <ImageIcon size={24} className="text-gray-400 dark:text-gray-300" />
                 </div>
                 <div>
                     <p className="text-gray-600 dark:text-gray-300 mb-4 text-sm">{t.btnUploadQR}</p>
                     <label className={`${theme.btn} text-white px-5 py-2.5 rounded-lg font-medium cursor-pointer inline-flex items-center gap-2 hover:shadow-lg transition text-sm`}>
                         <Upload size={16} />
                         {loading ? 'Processing...' : 'Select Images'}
                         <input type="file" multiple accept="image/*" className="hidden" onChange={handleQRUpload} disabled={loading} />
                     </label>
                 </div>
                 <p className="text-[10px] text-gray-400">Supports Standard & Migration QRs</p>
            </div>
        )}
    </Modal>
  );
};

interface ImportPreviewModalProps {
    isOpen: boolean;
    candidates: ImportCandidate[];
    onClose: () => void;
    onConfirm: (candidates: ImportCandidate[]) => void;
    logos: AppLogo[];
    color?: 'blue' | 'orange' | 'emerald';
}

export const ImportPreviewModal: React.FC<ImportPreviewModalProps> = ({ isOpen, candidates, onClose, onConfirm, logos, color = 'blue' }) => {
    const { t } = useContext(LanguageContext);
    const theme = getTheme(color);
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

    useEffect(() => {
        if (isOpen && candidates.length > 0) {
            const validIndices = candidates.map((c, i) => c.isValid ? i : -1).filter(i => i !== -1);
            setSelectedIndices(new Set(validIndices));
        }
    }, [isOpen, candidates]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        const toImport = candidates.filter((_, i) => selectedIndices.has(i));
        onConfirm(toImport);
    };

    const toggleSelect = (index: number) => {
        const next = new Set(selectedIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setSelectedIndices(next);
    };

    const getAvatarColor = (name: string) => {
        const colors = ['bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300', 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300', 'bg-violet-100 text-violet-700 dark:bg-violet-900 dark:text-violet-300', 'bg-amber-100 text-amber-700 dark:bg-amber-900 dark:text-amber-300', 'bg-rose-100 text-rose-700 dark:bg-rose-900 dark:text-rose-300', 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900 dark:text-cyan-300'];
        const index = name.length % colors.length;
        return colors[index];
    };

    return (
        <Modal title={`${t.headerImport} (${candidates.length})`} onClose={onClose} className="max-w-2xl">
            <div className="flex flex-col h-full max-h-[70vh]">
                <div className="flex justify-between items-center mb-4 px-1">
                    <p className="text-xs text-gray-500 dark:text-gray-400">{selectedIndices.size} selected</p>
                </div>

                <div className="overflow-y-auto flex-1 bg-gray-50 dark:bg-gray-900/50 rounded-lg border dark:border-gray-700">
                    {candidates.map((c, i) => {
                         // Robust lookup: stringify both sides to catch number vs string mismatch
                         const logo = c.logoId ? logos.find(l => String(l.id) === String(c.logoId)) : null;
                         const avatarClass = getAvatarColor(c.issuer || 'U');
                         return (
                            <div key={i} className={`flex items-start gap-3 p-3 border-b dark:border-gray-700 bg-white dark:bg-gray-800 last:border-b-0 ${!c.isValid ? 'opacity-50' : 'cursor-pointer'}`} onClick={() => c.isValid && toggleSelect(i)}>
                                <div className="pt-1">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedIndices.has(i)} 
                                        onChange={() => {}} 
                                        disabled={!c.isValid}
                                        className={`w-4 h-4 rounded border-gray-300 ${theme.checkbox}`}
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center">
                                        <div className="flex items-center gap-2.5 overflow-hidden min-w-0">
                                            {logo ? (
                                                <div className="w-6 h-6 shrink-0 flex items-center justify-center bg-gray-50 dark:bg-gray-700 rounded p-0.5">
                                                    <img src={logo.data} alt={logo.name} className="w-full h-full object-contain" />
                                                </div>
                                            ) : (
                                                <div className={`w-6 h-6 rounded flex items-center justify-center font-bold text-xs shrink-0 ${avatarClass}`}>
                                                    {(c.issuer || '?').charAt(0).toUpperCase()}
                                                </div>
                                            )}
                                           <span className="font-bold text-sm text-gray-900 dark:text-white truncate">{c.issuer || 'Unknown'}</span>
                                        </div>
                                        <span className="text-[10px] text-gray-400 font-mono shrink-0 ml-2">{c.period}s</span>
                                    </div>
                                    <p className="text-xs text-gray-600 dark:text-gray-400 truncate mt-0.5 ml-8.5">{c.account}</p>
                                    <div className="mt-1 flex items-center gap-2 ml-8.5 overflow-hidden">
                                        <span className="text-[10px] text-gray-400 font-mono truncate max-w-[120px]" title={c.secret}>
                                            {c.secret ? c.secret.substring(0, 4) + '...' + c.secret.substring(c.secret.length-4) : 'NO SECRET'}
                                        </span>
                                        {c.notes && (
                                            <span className="text-[10px] text-blue-500 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 px-1.5 py-0.5 rounded truncate max-w-[150px] border border-blue-100 dark:border-blue-800" title={c.notes}>
                                                {c.notes}
                                            </span>
                                        )}
                                        {c.logoId && !logo && <span className="text-[9px] text-orange-400 border border-orange-100 dark:border-orange-900/50 px-1 rounded">ID: {c.logoId}</span>}
                                        {!c.isValid && <span className="text-[10px] text-red-500 bg-red-50 px-1 rounded">Invalid</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="pt-4 mt-4 border-t dark:border-gray-700 flex justify-end gap-3">
                     <button onClick={onClose} className="px-3 py-2 border dark:border-gray-600 rounded-lg text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 font-medium">
                         {t.btnCancel}
                     </button>
                     <button 
                        onClick={handleConfirm}
                        disabled={selectedIndices.size === 0}
                        className={`${theme.btn} text-white px-5 py-2 rounded-lg text-sm font-medium shadow-sm disabled:opacity-50`}
                     >
                        {t.btnImport} ({selectedIndices.size})
                     </button>
                </div>
            </div>
        </Modal>
    )
}

interface LogoManagerModalProps {
  onClose: () => void;
  logos: AppLogo[];
  onAddLogo: (logo: AppLogo) => void;
  onDeleteLogo: (id: string) => void;
  onBatchDeleteLogo: (ids: string[]) => void;
  onImportLogos: (logos: AppLogo[]) => void;
  inline?: boolean;
  color?: 'blue' | 'orange' | 'emerald';
}

export const LogoManagerModal: React.FC<LogoManagerModalProps> = ({ 
    onClose, logos, onAddLogo, onDeleteLogo, onBatchDeleteLogo, onImportLogos, inline = false, color = 'blue' 
}) => {
  const { t } = useContext(LanguageContext);
  const theme = getTheme(color);
  const [tab, setTab] = useState<'list' | 'add' | 'import'>('list');
  const [newLogoName, setNewLogoName] = useState('');
  const [newLogoUrl, setNewLogoUrl] = useState('');

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [importCandidates, setImportCandidates] = useState<AppLogo[]>([]);
  const [selectedImportIds, setSelectedImportIds] = useState<Set<string>>(new Set());

  useEffect(() => {
      setSelectedIds(new Set());
  }, [tab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (ev) => {
              if (ev.target?.result) {
                  setNewLogoUrl(ev.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAdd = () => {
      if (newLogoName && newLogoUrl) {
          onAddLogo({
              id: uuidv4(),
              name: newLogoName,
              data: newLogoUrl
          });
          setNewLogoName('');
          setNewLogoUrl('');
          setTab('list');
      }
  };

  const handleImportFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (ev.target?.result) {
                try {
                    const parsed = JSON.parse(ev.target.result as string);
                    if (Array.isArray(parsed)) {
                        const valid = parsed.filter(item => item.name && item.data);
                        // Ensure all imported logos have string IDs
                        const candidates = valid.map((l: any) => ({...l, id: l.id ? String(l.id) : uuidv4() }));
                        setImportCandidates(candidates);
                        setSelectedImportIds(new Set(candidates.map((c: any) => String(c.id))));
                    } else {
                        alert("Invalid JSON Format.");
                    }
                } catch (e) {
                    alert("Invalid JSON File.");
                }
            }
        };
        reader.readAsText(file);
        e.target.value = ''; 
    }
  };

  const handleConfirmImport = () => {
      const toImport = importCandidates.filter(c => selectedImportIds.has(String(c.id)));
      if (toImport.length === 0) return;
      onImportLogos(toImport);
      setImportCandidates([]); 
      setTab('list');
  };

  const handleClearImport = () => {
      setImportCandidates([]);
      setSelectedImportIds(new Set());
  };

  const toggleImportSelect = (id: string) => {
      const next = new Set(selectedImportIds);
      const sid = String(id);
      if (next.has(sid)) next.delete(sid);
      else next.add(sid);
      setSelectedImportIds(next);
  };

  const toggleImportSelectAll = () => {
      if (selectedImportIds.size === importCandidates.length) {
          setSelectedImportIds(new Set());
      } else {
          setSelectedImportIds(new Set(importCandidates.map(c => String(c.id))));
      }
  };

  const handleExportSelected = () => {
      if (selectedIds.size === 0) return;
      const selectedLogos = logos.filter(l => selectedIds.has(String(l.id)));
      const json = JSON.stringify(selectedLogos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'logos-export.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Exported");
  };

  const handleExportAll = () => {
      const json = JSON.stringify(logos, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'logos-full.json';
      a.click();
      URL.revokeObjectURL(url);
      alert("Exported");
  };

  const toggleSelect = (id: string) => {
      const next = new Set(selectedIds);
      const sid = String(id);
      if (next.has(sid)) next.delete(sid);
      else next.add(sid);
      setSelectedIds(next);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === logos.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(logos.map(l => String(l.id))));
      }
  };

  const handleDeleteSelected = () => {
      if (confirm(`Delete ${selectedIds.size} selected logos?`)) {
          onBatchDeleteLogo(Array.from(selectedIds));
          setSelectedIds(new Set());
      }
  };

  const content = (
      <div className={`flex flex-col relative ${inline ? '' : 'h-full'}`}>
          <div className="flex gap-4 mb-4 border-b dark:border-gray-700 shrink-0 items-center justify-between">
            <div className="flex gap-4">
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'list' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`} onClick={() => setTab('list')}>
                  {t.tabLogoList}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'add' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`} onClick={() => setTab('add')}>
                  {t.tabAddLogo}
                </button>
                <button className={`pb-2 px-1 font-medium text-sm transition ${tab === 'import' ? `${theme.text} border-b-2 ${theme.border}` : 'text-gray-500 dark:text-gray-400'}`} onClick={() => setTab('import')}>
                  {t.tabImportLogos}
                </button>
            </div>

            {tab === 'list' && logos.length > 0 && (
                 <label className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedIds.size === logos.length} onChange={toggleSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
            {tab === 'import' && importCandidates.length > 0 && (
                 <label className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 cursor-pointer pb-2">
                     <input type="checkbox" checked={selectedImportIds.size === importCandidates.length} onChange={toggleImportSelectAll} className={`rounded ${theme.checkbox}`} />
                     {t.selectAll}
                 </label>
            )}
          </div>

          <div className={`${inline ? '' : 'flex-1 overflow-y-auto min-h-[300px]'} ${(selectedIds.size > 0 && tab === 'list') || (importCandidates.length > 0 && tab === 'import') ? 'pb-20' : 'pb-4'}`}>

              {tab === 'list' && (
                  <div className="space-y-4">
                      {logos.length === 0 && <p className="text-gray-500 text-center py-10">No custom logos.</p>}
                      <div className="grid grid-cols-5 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-2">
                          {logos.map(l => {
                              const sid = String(l.id);
                              const isSelected = selectedIds.has(sid);
                              return (
                                  <div 
                                    key={sid} 
                                    onClick={() => toggleSelect(sid)}
                                    className={`aspect-square border dark:border-gray-600 rounded-lg p-1 relative group cursor-pointer transition flex flex-col items-center justify-center bg-white dark:bg-gray-700 ${isSelected ? `ring-2 ${theme.selectionRing} ${theme.selectionBorder}` : 'hover:shadow-md'}`}
                                  >
                                      <div className={`absolute top-1 right-1 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                           <div className={`w-3 h-3 rounded flex items-center justify-center ${isSelected ? `${theme.checkBg} text-white` : 'border border-gray-300 dark:border-gray-500 bg-white dark:bg-gray-600'}`}>
                                                {isSelected && <Check size={8} />}
                                           </div>
                                      </div>
                                      <div className="w-6 h-6 sm:w-8 sm:h-8 flex items-center justify-center mb-1">
                                          <img src={l.data} alt={l.name} className="max-w-full max-h-full object-contain" />
                                      </div>
                                      <p className="text-[8px] text-center font-medium truncate w-full px-1 text-gray-700 dark:text-gray-200" title={l.name}>{l.name}</p>
                                  </div>
                              );
                          })}
                      </div>
                  </div>
              )}

              {tab === 'add' && (
