        case 'blue':
        default:
            return {
                btn: 'bg-blue-600 hover:bg-blue-700',
                text: 'text-blue-600 dark:text-blue-400',
                border: 'border-blue-500 dark:border-blue-400',
                ring: 'ring-blue-500',
