                    >
                        <ChevronLeft size={16} />
                    </button>
                    <span className="text-xs font-mono font-bold text-gray-600 dark:text-gray-300 bg-white dark:bg-gray-800 px-3 py-1 rounded-md border dark:border-gray-700">
                        {currentPage + 1} / {totalPages}
                    </span>
                    <button 
