             </div>

             <div className="bg-white p-4 rounded-2xl border-[10px] border-gray-100 shadow-2xl">
                 <QRCodeSVG value={currentMigrationURI} size={250} level="M" />
             </div>

             <div className="w-full space-y-2">
                <label className="text-[10px] uppercase tracking-wider font-bold text-gray-400 dark:text-gray-500 ml-1">Migration URL (Page {currentPage + 1})</label>
                <div className="flex gap-2">
                    <div className="flex-1 min-w-0 bg-gray-50 dark:bg-gray-900 border dark:border-gray-700 rounded-lg p-3 font-mono text-[10px] break-all max-h-24 overflow-y-auto text-gray-600 dark:text-gray-300 leading-relaxed scrollbar-thin">
                        {currentMigrationURI}
                    </div>
                    <button 
                        onClick={handleCopy}
