                        title="Copy Current URL"
                    >
                        {copied ? <Check size={18} /> : <Copy size={18} />}
                    </button>
                </div>
                {copied && <p className="text-[10px] text-green-500 font-bold animate-in fade-in slide-in-from-left-1">Copied to clipboard!</p>}
             </div>
         </div>
       )}
