                             <button onClick={handleOpenPasswordModalFromSettings} className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors ${themeClasses.checkboxText}`}>
                                <Lock size={16} className={(activeTab === 'file' && currentFileId ? (openFiles.find(f => f.id === currentFileId)?.isEncrypted) : hasPassword) ? 'text-green-500' : 'text-gray-400'} />
                                <span className="flex-1 text-left font-medium">{(activeTab === 'file' && currentFileId) ? t.fileSecurityTitle : t.securityTitle}</span>
