      });
  };

  const handleOpenPasswordModalFromMenu = (fileId: string) => {
      setPasswordTargetFileId(fileId);
      setContextMenu(null); // 立即关闭菜单
      setShowPasswordModal(true);
  };

  const handleOpenPasswordModalFromSettings = () => {
