                                      {f.needsPermission ? <ShieldAlert size={10} className="text-orange-500" /> : (f.isEncrypted ? <Lock size={10} className={f.password ? "text-green-500" : "text-gray-400"}/> : <FileJson size={10} className="opacity-50"/>)}
